def test_exec_without_a_command_explains_itself(tmp_path, monkeypatch, capsys):
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    assert runprov.__main__.main(["exec"]) == 2
    err = capsys.readouterr().err
    assert "runprov exec needs a command" in err and "--input" in err


def test_exec_defaults_the_name_and_the_sidecar_path(tmp_path, monkeypatch, capsys):
    """No `--name` and no `--provenance`: the program's own name, and a sidecar under the
    project's provenance directory named the way a `Run` in a script would name it.

    THIS TEST USED TO ASSERT THE DEFECT. It globbed `sh_*.json` and its docstring gave the
    reason — "carrying the run id, so two runs do not collide" — which is
    `sidecar_per_run=True` behaviour, decided here, in one entry point, for every project.
    The library default is the opposite and overwrites. Two doors into one decision, opposite
    answers behind them, and a project that had chosen either got the other through one of
    them (L-44). `exec` now names it `{name}.prov.json` and lets `_sidecar_name` apply the
    project's setting, so the collision behaviour is the project's choice from both doors —
    asserted in `test_exec_names_its_sidecar_the_way_the_project_says`."""
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    assert runprov.__main__.main(["exec", "--", "sh", "-c", "true"]) == 0
    capsys.readouterr()
    written = list((tmp_path / "provenance").glob("*.prov.json"))
    assert [p.name for p in written] == ["sh.prov.json"], written
    assert json.loads(written[0].read_text(encoding="utf-8"))["script"] == "sh"
    assert not list((tmp_path / "provenance").glob("sh_*.json")), (
        "the run id must no longer be baked into the name by this entry point alone"
    )


def test_exec_can_tee_the_commands_output_to_a_file(tmp_path, monkeypatch, capsys):
    """The command inherits this process's stdout, so `--capture` -- which works at file
    descriptor level -- sees a SUBPROCESS's output, which Python-level capture cannot."""
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    log = tmp_path / "cmd.log"
    rc = runprov.__main__.main(
        [
            "exec",
            "--provenance",
            str(tmp_path / "p.json"),
            "--capture",
            str(log),
            "--",
            "sh",
            "-c",
            "echo from-a-subprocess",
        ]
    )
    capsys.readouterr()
    assert rc == 0
    assert "from-a-subprocess" in log.read_text(encoding="utf-8")
    rec = json.loads((tmp_path / "p.json").read_text(encoding="utf-8"))
    assert rec["terminal_log"]["path"] == runprov.hashing._posix(log)


# ============================ NFS and Lustre: the filesystems the lock exists for
#: Point this at a directory on a REAL network filesystem and the tests below run there.
#:
#:     RUNPROV_NETWORK_FS_DIR=/mnt/lustre/scratch/you python -m pytest -k network_fs
#:
#: They are skipped otherwise, loudly and by name, because the alternative is a suite that
#: reports success for the one environment it never entered. `flock` on NFS depends on the
#: server, the protocol version and whether lockd is running; none of that can be
#: discovered from a laptop, and asserting it from one would be a claim about a machine
#: that is not the machine that matters.
NETWORK_FS = os.environ.get("RUNPROV_NETWORK_FS_DIR")


def _append_many(target, n, size, tag):
    """One process appending `n` records of about `size` bytes through the real sink."""
    sink = runprov.JsonlSink(pathlib.Path(target))
    for i in range(n):
        sink.append({"tag": tag, "i": i, "pad": "x" * size})


@requires_fcntl
def test_concurrent_appends_survive_when_locking_is_UNAVAILABLE(tmp_path, monkeypatch):
    """The NFS case, forced rather than waited for.

    `flock` on NFS depends on the server, the protocol version and whether lockd is running.
    When it is not there, `fcntl.flock` raises and this package degrades to an unlocked
    `O_APPEND` -- which is exactly the configuration a cluster hands you. So the degraded
    path is tested directly instead of hoping the lock is always available.

    What must hold with NO lock at all: every record still lands, and any line that did tear
    costs ONE record rather than the file. That is the JSONL promise, and it is the reason
    the format was chosen over the YAML it replaces.
    """
    import fcntl

    def no_locks(*_a, **_k):
        raise OSError(errno.ENOLCK, "No locks available")

    monkeypatch.setattr(fcntl, "flock", no_locks)

    target = tmp_path / "runs.jsonl"
    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
        list(pool.map(lambda t: _append_many(target, 20, 4000, t), range(8)))

    rows, bad = runprov.__main__._load(target)
    assert len(rows) + bad == 160, f"records lost outright: {len(rows)} + {bad} torn"
    assert bad == 0 or len(rows) >= 160 - bad, "a torn line must cost one record, never more"


@requires_fcntl
def test_the_downgrade_to_no_locking_is_ANNOUNCED(tmp_path, monkeypatch, capsys):
    """The notice used to sit inside a win32-only branch, so a POSIX `flock` that raised --
    an NFS or CIFS mount, a container without the syscall -- degraded silently. Those
    filesystems are the lock's entire justification, so that was the one case that most
    deserved announcing and the one case that could not."""
    import fcntl

    monkeypatch.setattr(
        fcntl, "flock", lambda *_a, **_k: (_ for _ in ()).throw(OSError(errno.ENOLCK, "nope"))
    )
    runprov.JsonlSink(tmp_path / "h.jsonl").append({"a": 1})
    err = capsys.readouterr().err
    assert "no file locking available" in err
    assert "may interleave" in err, "the consequence, not only the fact"
    assert _lines(tmp_path / "h.jsonl")[-1]["a"] == 1


def test_a_torn_line_costs_one_record_not_the_file(tmp_path):
    """What a network filesystem can actually do to an append, written directly. A YAML
    document that loses a line stops parsing; JSONL loses one record and says so."""
    target = tmp_path / "runs.jsonl"
    sink = runprov.JsonlSink(target)
    sink.append({"i": 0})
    with target.open("a", encoding="utf-8") as fh:
        fh.write('{"i": 1, "trunc')  # an interleaved half-write, no newline
    sink.append({"i": 2})

    rows, bad = runprov.__main__._load(target)
    assert bad == 1, "the torn line is COUNTED, never silently dropped"
    assert [r["i"] for r in rows] == [0, 2], "the records either side are intact"


@pytest.mark.skipif(not NETWORK_FS, reason="set RUNPROV_NETWORK_FS_DIR to a real NFS/Lustre path")
def test_network_fs_concurrent_appends_do_not_lose_records():
    """THE REAL TEST, on the filesystem that matters. Run it on the cluster:

        RUNPROV_NETWORK_FS_DIR=/mnt/lustre/scratch/you python -m pytest -k network_fs

    Processes rather than threads, because on a cluster the writers are separate jobs and
    a thread pool shares one file description -- which is precisely the sharing that hides
    the bug. 8 x 20 records of ~4 KB, which straddles the 4,096-byte bound below which
    POSIX guarantees an atomic O_APPEND and above which it does not.
    """
    root = pathlib.Path(NETWORK_FS)
    root.mkdir(parents=True, exist_ok=True)
    target = root / f"runprov_nfs_{os.getpid()}.jsonl"
    try:
        with concurrent.futures.ProcessPoolExecutor(max_workers=8) as pool:
            list(pool.map(_append_many, [target] * 8, [20] * 8, [4000] * 8, range(8)))

        rows, bad = runprov.__main__._load(target)
        assert bad == 0, f"{bad} torn line(s) on {root} — locking is not holding there"
        assert len(rows) == 160, f"{len(rows)} of 160 records survived on {root}"
        assert len({(r["tag"], r["i"]) for r in rows}) == 160, "and none was duplicated"
    finally:
        target.unlink(missing_ok=True)


@pytest.mark.skipif(not NETWORK_FS, reason="set RUNPROV_NETWORK_FS_DIR to a real NFS/Lustre path")
@requires_fcntl
def test_network_fs_reports_whether_locking_is_actually_available():
    """Not an assertion, a MEASUREMENT: does `flock` work on this mount at all?

    It is allowed to fail -- plenty of NFS exports have no lockd -- and the point is that
    the answer is printed rather than assumed. A run on such a mount degrades to an
    unlocked append and says so, which is the behaviour the tests above pin down.
    """
    import fcntl

    probe = pathlib.Path(NETWORK_FS) / f"runprov_lockprobe_{os.getpid()}"
    probe.write_text("x", encoding="utf-8")
    try:
        with probe.open("a") as fh:
            try:
                fcntl.flock(fh.fileno(), fcntl.LOCK_EX)
                fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
                available = True
                detail = ""
            except OSError as exc:
                available = False
                detail = f"{type(exc).__name__}: {exc}"
        print(f"\nflock on {NETWORK_FS}: {'AVAILABLE' if available else 'UNAVAILABLE'} {detail}")
    finally:
        probe.unlink(missing_ok=True)


# ==================== performance regressions: shapes, never absolute numbers
# Every test here compares TWO measurements of the same operation at different sizes. An
# absolute threshold is a test of the machine that set it -- this suite already learned that
# once, when `peak < size / 4` passed locally and failed in CI by 2% on a 7.4 MB file. A
# ratio cancels the machine out: a linear implementation stays linear on a slow disk too.
def _elapsed(fn, *a, **k):
    start = time.perf_counter()
    fn(*a, **k)
    return time.perf_counter() - start


def test_appending_to_the_history_does_not_get_slower_as_it_grows(tmp_path):
    """The history is appended FOREVER, so an append that reads the file first is a defect
    that only shows up in year two. A 2,000-record history must cost the same per append as
    an empty one."""
    fresh = runprov.JsonlSink(tmp_path / "fresh.jsonl")
    grown = runprov.JsonlSink(tmp_path / "grown.jsonl")
    for i in range(2000):
        grown.append({"i": i, "pad": "x" * 500})

    rec = {"i": -1, "pad": "x" * 500}
    empty_cost = min(_elapsed(fresh.append, rec) for _ in range(20))
    grown_cost = min(_elapsed(grown.append, rec) for _ in range(20))

    assert grown_cost < empty_cost * 8 + 5e-4, (
        f"appending to a 2,000-record history cost {grown_cost * 1e6:.0f}us against "
        f"{empty_cost * 1e6:.0f}us for an empty one — the append is reading the file"
    )


def _big_view(n_artifacts, n_scripts=40):
    return {
        "runs": 100_000,
        "scripts": {
            f"step_{i:02d}": {
                "runs": 100, "ok": 100, "failed": 0, "first": "A", "last": "B",
                "script_file": f"src/step_{i:02d}.py",
                "inputs": {f"data/in_{j}.tsv": ["a" * 16] for j in range(3)},
                "outputs": {f"results/out_{j}.tsv": ["b" * 16] for j in range(3)},
                "note_keys": ["rows"], "parameters": ["mode"],
            }
            for i in range(n_scripts)
        },
        "artifacts": {
            f"results/out_{k:06d}.tsv": {
                "by": f"step_{k % 40:02d}", "digest": "c" * 16,
                "kind": "file", "when": "W", "status": "ok",
            }
            for k in range(n_artifacts)
        },
    }  # fmt: skip


def test_the_project_page_is_never_built_as_one_string(tmp_path):
    """L-39. The page was accumulated as a list of every line and joined at the end, so
    rendering cost about six times the text it produced — 57.7 MB of peak to emit 9.6 MB at
    100,000 artifacts. The waste scales with the artifact count, which is exactly the part
    of this page that grows over the years the history is meant to survive.

    `log` already learned this: `_timeline_entry` was split out so each record could be
    written as it streamed. Same reasoning, and here the unbounded half is the artifacts."""
    import tracemalloc

    view = _big_view(20_000)
    text = runprov.show.render_project(view)

    class Sink(io.TextIOBase):
        def writelines(self, lines):
            for _ in lines:
                pass

    tracemalloc.start()
    Sink().writelines(runprov.show.render_project_lines(view))
    peak = tracemalloc.get_traced_memory()[1]
    tracemalloc.stop()

    assert len(text) > 1_000_000, "the premise: this page is megabytes of text"
    assert peak < len(text) / 4, (
        f"rendering held {peak / 1e6:.1f} MB to write {len(text) / 1e6:.1f} MB of text — "
        f"the page is still being built before any of it is printed"
    )


def test_the_streamed_page_is_byte_for_byte_the_page(tmp_path, monkeypatch):
    """A renderer split for memory must render the same thing, or the fix is a rewrite. The
    string form is kept as a thin wrapper over the generator for exactly this reason: there
    is one implementation, so the two cannot drift."""
    rows = _history(tmp_path, monkeypatch)
    view = runprov.show.project_view(rows)
    states = runprov.show.staleness(rows)
    joined = "".join(runprov.show.render_project_lines(view, states))
    assert joined == runprov.show.render_project(view, states)
    assert joined.endswith("\n") and "project notebook" in joined
    assert all(ln.endswith("\n") for ln in runprov.show.render_project_lines(view, states)), (
        "lines carry their own newline so a caller can writelines() them unchanged"
    )


def test_lineage_counts_each_unreadable_line_once(tmp_path, capsys):
    """`lineage` walks the history TWICE (L-38), and `bad` accumulates across both — so a
    history with two torn lines reported "4 unreadable line(s) skipped". `log` and `show`
    read once and said 2, so the three commands disagreed about the same file.

    A reader who cannot trust the count of what was lost is worse off than one given no
    count at all, because the number looks like evidence. Introduced by the streaming
    rewrite and found by using the tool rather than by a ledger row."""
    p = tmp_path / "runs.jsonl"
    good = lambda i: json.dumps({"script": f"s{i}", "started_utc": f"2026-01-0{i}T00:00:00Z"})  # noqa: E731
    p.write_text(
        "\n".join([good(1), '{"script": "TORN", "pad": "xxx', good(2), "not json at all"]) + "\n",
        encoding="utf-8",
    )

    assert runprov.__main__.main(["lineage", "--log", str(p)]) == 0
    err = capsys.readouterr().err
    assert "2 unreadable line(s) skipped" in err, err
    assert "4 unreadable" not in err, "each damaged line is counted once, not once per pass"

    # And it agrees with the readers that walk the file once.
    assert runprov.__main__.main(["log", "--log", str(p)]) == 0
    assert "2 unreadable line(s) skipped" in capsys.readouterr().err


def test_lineage_does_not_hold_the_records_it_walks(tmp_path):
    """L-38. The comment here said lineage "genuinely needs every record at once ... there is
    nothing to stream past". That was a claim about the RECORDS, and the join is over
    DIGESTS: it needs an index, not a copy of the history. Measured at 40,000 chained runs,
    166 MB against 58 MB, for byte-identical output.

    The confident comment is the reason this survived review — it told the next person not to
    look. Counting reachable records DURING the walk is the same technique L-04 and L-37 use,
    and for the same reason: the list would die with the frame and prove nothing after."""
    import gc
    import weakref

    class Rec(dict):
        pass

    seen: list[weakref.ref] = []
    held: list[int] = []
    n = 200

    def stream():
        prev = None
        for i in range(n):
            d = f"{i:064x}"
            rec = Rec(
                script=f"s{i}",
                run_uid=f"{i:032x}",
                # MONOTONIC, not `i % 60`: rule 2 says a producer must have finished before
                # its consumer started, so a wrapping clock makes some producers look later
                # than the runs that read them and silently drops those edges.
                started_utc=f"2026-08-01T{i // 3600:02d}:{i // 60 % 60:02d}:{i % 60:02d}Z",
                finished_utc=f"2026-08-01T{i // 3600:02d}:{i // 60 % 60:02d}:{i % 60:02d}Z",
                parameters={"pad": "x" * 300},
                inputs=([{"path": "a", "sha256": prev}] if prev else []),
                outputs=[{"path": "a", "sha256": d}],
            )
            prev = d
            seen.append(weakref.ref(rec))
            yield rec
            del rec
            if i == n - 1:
                gc.collect()
                held.append(sum(1 for w in seen if w() is not None))

    # Two passes, so the source must be re-iterable — a generator would give an empty second
    # pass. This shim hands `_lineage` a fresh generator on each `__iter__`, which is exactly
    # the contract `records()` depends on.
    class Reiterable:
        def __iter__(self):
            return stream()

    cli = runprov.__main__
    g = cli._lineage(Reiterable())
    assert g["runs"] == n and g["resolvable"] == n - 1, g
    assert held[0] <= 2, f"{held[0]} of {n} records held to join on digests"


def test_the_lineage_json_gains_no_new_key(tmp_path):
    """`lineage --format json` is a documented output somebody parses. The script-name map
    that replaced the records is an OUT-PARAMETER precisely so it does not land in that
    document — putting it there would trade a memory problem for a bigger file, adding one
    entry per run to the thing a consumer reads."""
    cli = runprov.__main__
    rows = [
        {
            "script": "a",
            "run_uid": "u1",
            "started_utc": "2026-01-01T00:00:00Z",
            "finished_utc": "2026-01-01T00:00:00Z",
            "outputs": [{"path": "x", "sha256": "d1"}],
        },
        {
            "script": "b",
            "run_uid": "u2",
            "started_utc": "2026-01-01T00:00:01Z",
            "inputs": [{"path": "x", "sha256": "d1"}],
        },
    ]
    names: dict[str, str] = {}
    g = cli._lineage(rows, None, names)
    assert set(g) == {"runs", "records_without_uid", "resolvable", "ambiguous", "orphan", "edges"}
    assert g["edges"] == [("u1", "u2")] and g["resolvable"] == 1
    assert names == {"u1": "a", "u2": "b"}, "the names come back beside the graph, not inside it"
    assert "a [u1" in cli._render_lineage(g, names), "and the text view still names the scripts"


def test_appending_to_the_transformation_log_does_not_get_slower_as_it_grows(tmp_path):
    """The same rule as the history beside it, and the reason this file is APPENDED rather
    than regenerated. Rewriting the whole YAML after each run would read the entire history
    to write one entry — O(n) per run and O(n^2) over a project, which is the cost that
    surfaces in year two, on precisely the long-lived record this file is for."""
    fresh = runprov.sinks.YamlLogSink(tmp_path / "fresh.yml")
    grown = runprov.sinks.YamlLogSink(tmp_path / "grown.yml")
    rec = {"script": "s", "started_utc": "2026-01-01T00:00:00Z", "parameters": {"pad": "x" * 400}}
    for i in range(2000):
        grown.append({**rec, "run_id": f"r{i}"})

    empty_cost = min(_elapsed(fresh.append, rec) for _ in range(20))
    grown_cost = min(_elapsed(grown.append, rec) for _ in range(20))

    assert grown_cost < empty_cost * 8 + 5e-4, (
        f"appending to a 2,000-entry transformation log cost {grown_cost * 1e6:.0f}us "
        f"against {empty_cost * 1e6:.0f}us for an empty one — it is rewriting the file"
    )


def test_the_project_page_does_a_fixed_amount_of_work_per_record(tmp_path):
    """L-40. This REPLACES a wall-clock ratio test (`large < small * 9`), which was the only
    timing test in this section with no absolute slack term and the only one that flaked.

    THE SHAPE WAS UNFIXABLE, NOT THE CONSTANTS, and that was established by measurement
    rather than assumed. On 8 cores under 12-way load the original failed twice in eight runs
    at 16.7x and 9.1x. Adding the missing floor, raising the repeats from 3 to 7 and scaling
    the fixtures up did not fix it. Widening the sizes from 4x to 10x made it worse — ratios
    ranged 1.79 to 104.97 — because `min()` over repeats can find a clean run for the SMALL
    measurement, which fits inside a scheduling quantum, and cannot for the large one. The
    ratio then inflates without bound. At 4x sizing linear is 4x and quadratic is 16x, so the
    bound must sit between them, and under contention the noise alone spans that entire gap:
    no threshold separates the two hypotheses. Both reviewers proposed widening to ~12x,
    which would have stopped catching quadratic altogether (16x > 12x).

    A ratio is also blind to a CONSTANT FACTOR by construction: a change that doubles the
    cost at every size leaves it exactly where it was. Simulated during the audit, a 2x
    regression scored 5.58 against a threshold of 9 and passed the whole performance section.
    Reproduced here: a 2x-per-entry regression passes the ratio test and fails this one.

    COUNTING IS DETERMINISTIC. Two counters, and between them they cover what the clock was
    supposed to:

      * `records consumed` catches re-walking the input, which is the classic quadratic —
        the page must touch each record exactly once, however many it is given;
      * `_short`/`_name` calls per record catches extra work per entry — exactly 6.00 at
        every size, because they run once per input and once per output.

    Neither can be moved by CPU load, an allocator or a slow disk, which is what the section
    header has always asked for: shapes, never absolute numbers."""
    per_record = 6  # 3 inputs+outputs x 2 helpers, per record — see the docstring

    def calls(n):
        rows = [
            {
                "script": f"s{i % 20}",
                "status": "ok",
                "started_utc": "2026-01-01T00:00:00Z",
                "inputs": [{"path": f"in/{i % 50}.tsv", "sha256": f"{i:064x}"}],
                "outputs": [{"path": f"out/{i}.tsv", "sha256": f"{i:064x}", "kind": "file"}],
            }
            for i in range(n)
        ]
        counted = [0]
        consumed = [0]

        def once():
            """The records, yielded one at a time and COUNTED. An implementation that walks
            the history twice — or that indexes back into it — consumes more than `n`."""
            for r in rows:
                consumed[0] += 1
                yield r

        real_short, real_name = runprov.show._short, runprov.show._name
        runprov.show._short = lambda e: (counted.__setitem__(0, counted[0] + 1), real_short(e))[1]
        runprov.show._name = lambda e: (counted.__setitem__(0, counted[0] + 1), real_name(e))[1]
        try:
            runprov.show.project_view(once())
        finally:
            runprov.show._short, runprov.show._name = real_short, real_name
        return counted[0], consumed[0]

    for n in (500, 2000, 8000):
        ops, seen = calls(n)
        assert seen == n, (
            f"the page consumed {seen} records to render {n} — it is walking the history "
            f"more than once, which is the classic quadratic"
        )
        assert ops == per_record * n, (
            f"{ops / n:.2f} operations per record at n={n}, not {per_record} — "
            f"the page is doing more work per run than it used to"
        )


def test_reading_a_pin_does_not_read_the_whole_artifact(tmp_path):
    """`verify` opens every candidate file in a tree. It reads a bounded prefix looking for
    the anchor, so a 50 GB BAM costs the same as a 1 KB TSV -- and a regression here turns
    a check into a full-corpus read."""
    small = tmp_path / "small.bin"
    small.write_bytes(b"\x00" * 4096)
    large = tmp_path / "large.bin"
    large.write_bytes(b"\x00" * (64 * 1024 * 1024))

    small_cost = min(_elapsed(runprov.verify.read_pins, small) for _ in range(5))
    large_cost = min(_elapsed(runprov.verify.read_pins, large) for _ in range(5))

    assert large_cost < small_cost * 20 + 5e-3, (
        f"a 64 MB file cost {large_cost * 1e3:.1f}ms against {small_cost * 1e3:.1f}ms for "
        f"4 KB — read_pins is reading past SCAN_BYTES ({runprov.verify.SCAN_BYTES} bytes)"
    )


def test_content_digest_memory_does_not_grow_with_the_file(tmp_path):
    """The property the whole streaming design exists for, guarded as a ratio. Both the line
    COUNT and the line LENGTH are varied, because a block bounded by only one of them looks
    streamed until the other moves -- which is how the byte bound came to be needed."""
    import tracemalloc

    def peak(records, width):
        p = tmp_path / f"f{records}x{width}.txt"
        with open(p, "w", encoding="utf-8") as fh:
            for i in range(records):
                fh.write(f"{i}\t" + "y" * width + "\n")
        tracemalloc.start()
        try:
            assert runprov.content_digest(p)
            return tracemalloc.get_traced_memory()[1]
        finally:
            tracemalloc.stop()

    # ABOVE both block bounds (8,192 lines and 8 MiB), or all three fixtures fit in ONE
    # block and the test measures a single read three times -- 4x the lines took 4.0x the
    # memory, which looked like a regression and was a fixture too small to stream.
    base = peak(20_000, 500)
    more_lines = peak(80_000, 500)
    longer_lines = peak(20_000, 2_000)

    assert more_lines < base * 2, f"4x the LINES took {more_lines / base:.1f}x the memory"
    assert longer_lines < base * 2, f"4x the LINE LENGTH took {longer_lines / base:.1f}x"


def test_constructing_a_run_does_not_scale_with_the_history(tmp_path, monkeypatch):
    """A `Run` reads nothing of the existing history at construction, and must not start:
    the 2,000th step of a pipeline must cost what the first one did."""
    monkeypatch.chdir(tmp_path)
    proj = _project(tmp_path)
    log = tmp_path / "runs.jsonl"
    with log.open("w", encoding="utf-8") as fh:
        for i in range(3000):
            fh.write(json.dumps({"i": i, "pad": "x" * 600}) + "\n")

    grown = min(_elapsed(runprov.Run, "s", project=proj) for _ in range(5))
    log.unlink()
    empty = min(_elapsed(runprov.Run, "s", project=proj) for _ in range(5))

    assert grown < empty * 3 + 5e-3, (
        f"construction cost {grown * 1e3:.1f}ms with a 3,000-record history against "
        f"{empty * 1e3:.1f}ms with none — something is reading it"
    )


def _project_view_peak(runs, artifacts, scripts=20):
    """Peak allocation while aggregating `runs` records naming `artifacts` distinct outputs.

    The two are separated on purpose. `project_view`'s memory is driven by the size of the
    AGGREGATE — distinct scripts and distinct artifact paths — and not by how many records
    streamed past to build it. A fixture that moves both at once cannot tell which.
    """
    import tracemalloc

    def stream():
        for i in range(runs):
            yield {
                "script": f"s{i % scripts}",
                "status": "ok",
                "started_utc": "2026-01-01T00:00:00Z",
                # `run_uid` IS PRESENT, and it is per-run and distinct. Without it the
                # records here were unlike every real record, and a mutation that hoarded
                # one value per run into the aggregate accumulated 20,000 `None`s -- a few
                # bytes each, under the bound, invisible. The fixture has to carry the
                # fields a regression would plausibly hoard.
                "run_uid": f"{i:032x}",
                "inputs": [{"path": f"in/{i % 50}.tsv", "sha256": f"{i:064x}"}],
                "outputs": [{"path": f"out/{i % artifacts}.tsv", "sha256": f"{i:064x}"}],
            }

    tracemalloc.start()
    try:
        view = runprov.show.project_view(stream())
        assert view["runs"] == runs
        return tracemalloc.get_traced_memory()[1]
    finally:
        tracemalloc.stop()


def test_the_project_page_does_not_grow_with_the_number_of_RUNS(tmp_path):
    """L-41. This test was called "does not hold the history in memory", which is a stronger
    claim than it checks — and its fixture pinned artifacts at `i % 100` and scripts at 20,
    so the aggregate was CONSTANT BY CONSTRUCTION and the measurement flat whatever `n` was:
    0.12 MB at 5,000 runs, 0.11 MB at 20,000, 0.11 MB at 80,000. The same numbers would
    appear for an implementation that held everything except the artifact index.

    What it genuinely guards is worth keeping and is now what it is named for: nothing
    proportional to the RUN COUNT survives the aggregation. The artifact count is held fixed
    so that is the only variable, and the growth it cannot see is asserted by the test below
    rather than left to be discovered at 100,000 artifacts.

    Measured on a realistic 100,000-run, 91 MB history: materialising every record cost
    392 MB, streaming it costs 3. `project_view` consumes an ITERABLE and counts as it goes;
    asking for `len(records)` would materialise the history this exists not to hold."""
    small, large = _project_view_peak(5_000, 1_000), _project_view_peak(20_000, 1_000)
    assert large < small * 2, (
        f"4x the runs took {large / small:.1f}x the memory at a FIXED artifact count — "
        f"project_view is keeping something per record"
    )


def test_the_project_page_grows_with_the_ARTIFACT_count_and_only_linearly(tmp_path):
    """The other half, and the one that was invisible. The aggregate IS an index of every
    distinct artifact, so it grows — that is the design, not a defect, and the cost is
    stated here rather than found later: 3.35 MB at 5,000 artifacts, 13.29 MB at 20,000,
    53.59 MB at 80,000, which is linear and is what a project writing one artifact per run
    actually pays.

    Asserting it BOTH grows and grows only linearly is what makes this a test rather than a
    number: a fixture that could not see the growth would satisfy the upper bound trivially,
    which is exactly how the test above came to certify more than it checked."""
    small, large = _project_view_peak(20_000, 5_000), _project_view_peak(80_000, 20_000)
    assert large > small * 2, (
        f"4x the artifacts took only {large / small:.1f}x the memory — the fixture is not "
        f"exercising the artifact index, so the bound below proves nothing"
    )
    assert large < small * 6, (
        f"4x the artifacts took {large / small:.1f}x the memory — the index is growing "
        f"faster than the thing it indexes"
    )


def test_reading_the_history_streams_rather_than_slurping(tmp_path):
    """`_stream` yields a record at a time. The first version did
    `read_text().splitlines()`, holding the whole file AND a list of every line before one
    record was parsed -- two full copies of a file whose design is that it never stops
    growing. Same defect `content_digest` had, in the function that meets the biggest file.
    """
    import tracemalloc

    target = tmp_path / "runs.jsonl"
    with target.open("w", encoding="utf-8") as fh:
        for i in range(20_000):
            fh.write(json.dumps({"i": i, "pad": "x" * 900}) + "\n")
    size = target.stat().st_size
    assert size > 15_000_000, "the fixture must be big enough for slurping to show"

    tracemalloc.start()
    try:
        count = sum(1 for rec in runprov.__main__._stream(target) if rec is not None)
        peak = tracemalloc.get_traced_memory()[1]
    finally:
        tracemalloc.stop()

    assert count == 20_000
    assert peak < size / 4, (
        f"peak {peak / 1e6:.0f} MB against a {size / 1e6:.0f} MB file — it is reading it whole"
    )


def test_the_streaming_peak_is_bounded_by_the_largest_RECORD_not_the_file(tmp_path):
    """L-73. The test above varies the record COUNT at a fixed record size, so it cannot see
    that `_stream`'s peak is bounded by the largest RECORD rather than by a constant — the
    exact blind spot `test_content_digest_streams_files_whose_LINES_are_long` was written to
    close for `content_digest`, left open for the history reader one module over.

    `_stream`'s docstring promises "every line of the history, parsed, one at a time", which
    is true and is NOT the same as bounded. A three-run history containing one enormous note
    costs twice that note, however few runs there are.

    Measured, and the ratio is stable rather than a fixture artefact: 2.01x the largest
    record at 5 MB and 2.01x at 20 MB. The bound asserted here is 3x, which states the real
    guarantee with room for the parse, and would fail a reader that held the whole file."""
    import tracemalloc

    # ONE big record, ISOLATED. A first draft used two adjacent large records to make
    # buffering visible and measured 4.0x rather than 2.0x -- because the consumer still
    # holds the record it is on while the next line is read and parsed, so two large records
    # side by side are both alive at once. That is a true and looser bound; the tight one is
    # per-record, and this test asserts the tight one. See `_stream` for both numbers.
    target = tmp_path / "runs.jsonl"
    with target.open("w", encoding="utf-8") as fh:
        fh.write(json.dumps({"i": 0, "pad": "small"}) + "\n")
        fh.write(json.dumps({"i": 1, "note": "y" * 5_000_000}) + "\n")
        fh.write(json.dumps({"i": 2, "pad": "small"}) + "\n")

    lines = target.read_text(encoding="utf-8").splitlines()
    largest = max(len(ln) for ln in lines)
    assert len(lines) == 3, "the premise: a SHORT history, so record count cannot explain it"

    tracemalloc.start()
    try:
        count = sum(1 for rec in runprov.__main__._stream(target) if rec is not None)
        peak = tracemalloc.get_traced_memory()[1]
    finally:
        tracemalloc.stop()

    assert count == 3
    assert peak < largest * 3, (
        f"peak {peak / 1e6:.1f} MB for a largest record of {largest / 1e6:.1f} MB — the "
        f"reader is holding more than the record it is on"
    )


def test_an_unreadable_line_is_still_counted_when_streaming(tmp_path):
    """The count is what stops a corrupt line from being silently dropped, and it has to
    survive the switch from a list to a generator."""
    target = tmp_path / "runs.jsonl"
    target.write_text('{"i": 0}\nnot json at all\n\n{"i": 1}\n', encoding="utf-8")
    assert list(runprov.__main__._stream(target)) == [{"i": 0}, None, {"i": 1}]
    rows, bad = runprov.__main__._load(target)
    assert [r["i"] for r in rows] == [0, 1] and bad == 1


def test_show_reports_unreadable_lines_it_streamed_past(tmp_path, capsys):
    """`bad` is accumulated as the stream runs, so the summary can still say what it could
    not read — a reader must not be told 'N runs' when it was N plus something broken."""
    target = tmp_path / "runs.jsonl"
    target.write_text(
        json.dumps({"script": "s", "status": "ok", "outputs": [], "inputs": []}) + "\ntorn{\n",
        encoding="utf-8",
    )
    assert runprov.__main__.main(["show", "--log", str(target)]) == 0
    assert "1 unreadable line(s) skipped" in capsys.readouterr().err


def test_log_limit_holds_only_the_limit_not_the_history(tmp_path):
    """`--limit N` keeps a deque of N and nothing else. The 99,900 runs before them do not
    need to be in memory to be skipped.

    A ratio, not a threshold: 4x the history behind the same `--limit` must not cost 4x the
    memory, because what is kept is N either way.
    """
    import tracemalloc

    def peak_for(n):
        target = tmp_path / f"h{n}.jsonl"
        with target.open("w", encoding="utf-8") as fh:
            for i in range(n):
                fh.write(
                    json.dumps(
                        {
                            "script": "s",
                            "status": "ok",
                            "i": i,
                            "pad": "x" * 700,
                            "inputs": [],
                            "outputs": [],
                        }
                    )
                    + "\n"
                )
        # EVERY FLAG `_log` READS, spelled out. A hand-built Namespace is not the parser,
        # so a flag added to the parser and not to this line is an `AttributeError` inside a
        # memory measurement — which is how `--unreadable` announced itself here.
        args = argparse.Namespace(
            log=str(target),
            format="jsonl",
            limit=5,
            script="",
            run_id="",
            failed=False,
            unreadable=False,
        )
        tracemalloc.start()
        try:
            assert runprov.__main__._log(args, target) == 0
            return tracemalloc.get_traced_memory()[1]
        finally:
            tracemalloc.stop()

    small, large = peak_for(5_000), peak_for(20_000)
    assert large < small * 2, (
        f"4x the history cost {large / small:.1f}x the memory behind the same --limit"
    )


def test_log_never_writes_to_the_history(tmp_path, capsys):
    """`--limit` is a VIEW over the history, not a trim of it. `log` reads; it has never
    written. The records it does not show are exactly where they were, and the next command
    without `--limit` shows them again."""
    target = tmp_path / "runs.jsonl"
    with target.open("w", encoding="utf-8") as fh:
        for i in range(50):
            fh.write(
                json.dumps({"script": f"s{i}", "status": "ok", "inputs": [], "outputs": []}) + "\n"
            )
    before, size = hashlib.sha256(target.read_bytes()).hexdigest(), target.stat().st_size

    assert runprov.__main__.main(["log", "--log", str(target), "--limit", "3"]) == 0
    shown = capsys.readouterr()
    assert shown.out.count("run_id") == 3, "three shown"
    assert "3 of 50 run(s)" in shown.err, "and it says what it did not show"

    assert hashlib.sha256(target.read_bytes()).hexdigest() == before
    assert target.stat().st_size == size

    assert runprov.__main__.main(["log", "--log", str(target)]) == 0
    assert capsys.readouterr().out.count("run_id") == 50, "all 50 are still there"


def test_log_streams_every_format_and_the_yaml_header_appears_once(tmp_path, capsys):
    """Streaming means writing each record as it passes, so the banner must be emitted by
    the command rather than by the renderer -- once, not once per run."""
    yaml = pytest.importorskip("yaml")
    target = tmp_path / "runs.jsonl"
    with target.open("w", encoding="utf-8") as fh:
        for i in range(4):
            fh.write(
                json.dumps(
                    {
                        "script": f"s{i}",
                        "status": "ok",
                        "started_utc": "2026-01-01",
                        "command": "c",
                        "inputs": [],
                        "outputs": [],
                    }
                )
                + "\n"
            )

    assert runprov.__main__.main(["log", "--log", str(target), "--format", "yaml"]) == 0
    out = capsys.readouterr().out
    assert out.count("# GENERATED by") == 1, "the banner is not per record"
    assert len(yaml.safe_load(out)) == 4

    assert runprov.__main__.main(["log", "--log", str(target), "--format", "jsonl"]) == 0
    assert len(capsys.readouterr().out.strip().splitlines()) == 4


def test_log_filters_compose_with_limit_while_streaming(tmp_path, capsys):
    """The filters are applied as records stream past, and `--limit` takes the last N of
    what SURVIVED them — not the last N of the file."""
    target = tmp_path / "runs.jsonl"
    with target.open("w", encoding="utf-8") as fh:
        for i in range(30):
            fh.write(
                json.dumps(
                    {
                        "script": "wanted" if i % 3 == 0 else "other",
                        "status": "failed" if i % 2 == 0 else "ok",
                        "run_id": "chain" if i > 20 else "old",
                        "inputs": [],
                        "outputs": [],
                    }
                )
                + "\n"
            )

    assert (
        runprov.__main__.main(
            [
                "log",
                "--log",
                str(target),
                "--script",
                "wanted",
                "--failed",
                "--limit",
                "2",
                "--format",
                "jsonl",
            ]
        )
        == 0
    )
    seen = capsys.readouterr()
    rows = [json.loads(x) for x in seen.out.strip().splitlines()]
    assert len(rows) == 2
    assert all(r["script"] == "wanted" and r["status"] == "failed" for r in rows)
    # J-14 CHANGED THE SECOND NUMBER HERE, from `"2 FAILED"`, and the old one was this row's
    # defect sitting in an assertion: ten records are `wanted`, five of those failed, and
    # `--limit 2` shows two — so `2 FAILED` was the count among the records that fitted in the
    # window. It read as correct only because every shown record happened to be a failure.
    # This test's subject is `--limit` taking the last N of what SURVIVED the filters, which is
    # untouched; the count beside it was incidental, and it is the second existing assertion in
    # this audit found pinning a defect it was not written about.
    assert "2 of 30 run(s)" in seen.err, seen.err
    assert "5 FAILED of 5 matching" in seen.err, (
        "five of the ten `wanted` runs failed and two are shown, so the clause must name the "
        f"denominator rather than report the window's own tally: {seen.err}"
    )


def test_log_counts_a_torn_line_it_streamed_past(tmp_path, capsys):
    """The count is what stops a corrupt line from being silently dropped, and it has to
    survive `log` becoming a stream — a reader must not be told "N runs" when it was N plus
    something unreadable."""
    target = tmp_path / "runs.jsonl"
    target.write_text(
        json.dumps({"script": "a", "status": "ok", "inputs": [], "outputs": []})
        + "\n"
        + "{torn, not json\n"
        + json.dumps({"script": "b", "status": "ok", "inputs": [], "outputs": []})
        + "\n",
        encoding="utf-8",
    )
    assert runprov.__main__.main(["log", "--log", str(target), "--format", "jsonl"]) == 0
    seen = capsys.readouterr()
    assert len(seen.out.strip().splitlines()) == 2, "the two good records still render"
    assert "2 of 2 run(s)" in seen.err
    assert "1 unreadable line(s) skipped" in seen.err


def test_our_own_teardown_is_not_refused_by_the_after_exit_guard(tmp_path, monkeypatch):
    """The after-exit guard fired on `__exit__`'s OWN calls and the record was never written.

    `_in_context` is already False by the time `_finish` runs -- deliberately, because
    `_note_unregistered_reads` relies on it to avoid hashing every first-party file twice --
    so a guard reading `_in_context` alone cannot tell our teardown from a caller reaching in
    after the block. `_finish` -> `write` -> `environment_snapshot` and
    `_record_imported_code` -> `code` are all guarded methods called from `__exit__`.

    Measured: runs.jsonl did not exist at all, and the only trace was a WARNING on stderr.
    The mechanism for refusing a call that reaches no file became the reason nothing reached
    a file.
    """
    monkeypatch.chdir(tmp_path)
    log = tmp_path / "runs.jsonl"
    runprov.configure(root=tmp_path, run_log=log, env_snapshot_dir=tmp_path / "envs")
    with runprov.Run("s", provenance=tmp_path / "p.json"):
        pass

    assert log.is_file(), "the history line was never written"
    line = _lines(log)[-1]
    assert line["environment_snapshot"]["path"].endswith(".txt")
    assert (tmp_path / "p.json").is_file()


# --------------------------------------------------------------------------- prune (A-14b)
def _marker(d: pathlib.Path, name: str, **kw) -> pathlib.Path:
    """One in-flight marker, defaulting to the shape `_mark_in_flight` writes."""
    rec = {
        "run_uid": name,
        "script": "fetch",
        "started_utc": "2020-01-01T00:00:00Z",
        "pid": _never_a_pid(),
        "host": runprov.show.platform.node(),
        **kw,
    }
    d.mkdir(parents=True, exist_ok=True)
    f = d / f"{name}.json"
    f.write_text(json.dumps(rec), encoding="utf-8")
    return f


def test_prune_removes_only_what_it_can_call_interrupted(tmp_path):
    """The safety property the whole command rests on. `rm -r` removes the lot; this removes
    only markers it can positively call INTERRUPTED, because the other two answers are `the
    run is alive` and `I cannot tell from here` — and turning "cannot tell" into a deletion
    is the guess this package exists to refuse.

    It matters most for the shape that appends no history line: a run started without
    `provenance=` has its marker as the ONLY evidence it ever existed."""
    d = tmp_path / ".incomplete"
    dead = _marker(d, "dead")
    alive = _marker(d, "alive", pid=os.getpid())
    far = _marker(d, "far", pid=1, host="a-compute-node")

    p = runprov.prune.plan(d)
    assert p.remove == [dead], f"{[f.name for f in p.remove]}"
    assert (p.running, p.untellable) == (1, 1)

    gone, problems = runprov.prune.apply(p)
    assert (gone, problems) == (1, [])
    assert not dead.exists()
    assert alive.is_file() and far.is_file(), "a live run and another host's keep their marker"


def test_prune_other_hosts_is_the_users_assertion_not_the_commands(tmp_path):
    """A cluster's `.incomplete` is mostly `?`, so refusing them for ever would make the
    command useless where it is most needed. The escape hatch exists — it is just explicit,
    and it never covers a run that is demonstrably alive HERE."""
    d = tmp_path / ".incomplete"
    far = _marker(d, "far", pid=1, host="a-compute-node")
    alive = _marker(d, "alive", pid=os.getpid())

    assert runprov.prune.plan(d, other_hosts=True).remove == [far]
    assert alive.is_file(), "--other-hosts must not reach a live local run"


def test_prune_other_hosts_does_not_reach_a_LOCAL_marker_whose_probe_could_not_answer(
    tmp_path, monkeypatch
):
    """`?` means two things now, and only one of them is the user's assertion to make.

    `_liveness` used to return `?` for exactly one reason — the marker names another host —
    so `plan` could read the STATE and know what `--other-hosts` licensed. T-07 gave it a
    second reason: a probe that could not answer returns `?` rather than guessing RUNNING,
    and that `?` is about a pid on THIS machine. Measured before the repair: a same-host
    marker whose `os.kill` raises `OSError(EINVAL)` came back `?`, and
    `plan(d, other_hosts=True).remove` contained it — `--other-hosts` deleting the marker of
    a run that may be alive right here, on the strength of a flag about somewhere else.

    THE POSITIVE COMPANION IS IN THE SAME TEST: the other-host marker beside it must still
    go, or this passes on a `plan` that has simply stopped removing anything.

    `sys.platform` IS SET, for the reason `test_a_pid_owned_by_someone_else_is_running_not_
    gone` sets it: `_still_running` branches to `_still_running_windows` on Windows and never
    consults `os.kill` at all, so the patch below applied to nothing there, the live pid
    answered for real, and this test failed on its own PREMISE — an unanswerable probe came
    back RUNNING — for a reason with nothing to do with its subject. Measured on the Windows
    leg of run 33573724906: `assert 'RUNNING' == '?'`. Setting the platform makes the POSIX
    branch run and the patched `os.kill` answer on every machine, which is the emulation
    `sinks.py`'s lock tests use in the other direction. The subject is `prune`'s reading of
    `?`, not which system call produced it: the Windows spelling of an unanswerable probe
    (`OpenProcess` failing for a reason that is not "no such process") reaches `_liveness`
    through the same `None` and has its own test.

    THE OTHER-HOST HALF DOES NOT DEPEND ON EITHER PATCH. `far` names a host that is not this
    one, so `_liveness` returns `?` without probing anything at all — which is the point:
    two markers, one state, and only one of them is the user's to assert about."""
    monkeypatch.setattr(sys, "platform", "linux")
    d = tmp_path / ".incomplete"
    mute = _marker(d, "mute", pid=os.getpid())
    far = _marker(d, "far", pid=1, host="a-compute-node")

    def cannot_ask(pid, sig):
        raise OSError(errno.EINVAL, "Invalid argument")

    monkeypatch.setattr(runprov.show.os, "kill", cannot_ask)
    assert runprov.show.liveness(json.loads(mute.read_text(encoding="utf-8"))) == "?", (
        "the premise: an unanswerable probe on this host is `?`, the same string the "
        "other-host case gets"
    )

    p = runprov.prune.plan(d, other_hosts=True)
    assert p.remove == [far], f"{[f.name for f in p.remove]}"
    assert (p.untellable, p.unanswerable) == (0, 1)
    assert "--other-hosts does not cover them" in runprov.prune.render(p, None, d)

    runprov.prune.apply(p)
    assert mute.is_file(), "--other-hosts deleted a marker for a run on THIS host"


def test_prune_will_not_delete_what_it_cannot_date(tmp_path):
    """`--older-than` selects by the marker's own `started_utc`. A marker whose stamp will
    not parse has an unknown age, and "we could not look" is not a licence to delete — the
    same rule the `?` state follows one branch above."""
    d = tmp_path / ".incomplete"
    old = _marker(d, "old")
    young = _marker(d, "young", started_utc="2026-08-21T12:00:00Z")
    bad = _marker(d, "bad", started_utc="not-a-stamp")
    typed = _marker(d, "typed", started_utc=17)

    now = dt.datetime(2026, 8, 21, 12, 0, 30, tzinfo=dt.timezone.utc)
    p = runprov.prune.plan(d, older_than=runprov.prune.parse_age("30d"), now=now)
    assert p.remove == [old]
    assert (p.too_new, p.undateable) == (1, 2)
    assert young.is_file() and bad.is_file() and typed.is_file()


def test_prune_leaves_alone_everything_that_is_not_its_marker(tmp_path):
    """A command that deletes must be NARROWER than the `rm -r` it replaces, or it is not
    worth having. Four ways a `*.json` in that directory is not ours, and all four survive."""
    d = tmp_path / ".incomplete"
    ours = _marker(d, "ours")
    (d / "torn.json").write_text("{not json", encoding="utf-8")
    (d / "list.json").write_text("[1, 2, 3]", encoding="utf-8")
    (d / "other.json").write_text('{"hello": 1}', encoding="utf-8")
    (d / "adir.json").mkdir()
    (d / "notes.txt").write_text("keep me", encoding="utf-8")

    p = runprov.prune.plan(d)
    assert p.remove == [ours] and p.foreign == 4
    runprov.prune.apply(p)
    for name in ("torn.json", "list.json", "other.json", "adir.json", "notes.txt"):
        assert (d / name).exists(), f"{name} was not ours to remove"


@requires_symlinks
def test_prune_will_not_follow_a_symlink_out_of_the_directory(tmp_path):
    """A NAME UNDER A DIRECTORY IS NOT A PATH INSIDE IT. The containment check is per file
    and it is the same rule `verify` applies to a pinned name (A-08). Without it, anything
    that can write to `.incomplete` — a shared scratch directory, a restored archive —
    chooses what a later `runprov prune` unlinks."""
    d = tmp_path / ".incomplete"
    d.mkdir()
    outside = tmp_path / "precious.json"
    outside.write_text(json.dumps({"run_uid": "x", "pid": _never_a_pid()}), encoding="utf-8")
    (d / "sneaky.json").symlink_to(outside)
    ours = _marker(d, "ours")

    p = runprov.prune.plan(d)
    assert p.remove == [ours] and p.foreign == 1
    runprov.prune.apply(p)
    assert outside.is_file() and (d / "sneaky.json").is_symlink()


def test_prune_survives_a_directory_it_cannot_look_at(tmp_path, monkeypatch):
    """An unresolvable or absent directory prunes nothing and says nothing alarming. The
    exception family is `(OSError, RuntimeError)` because a symlink loop raises the SECOND
    one from `resolve()` — the defect class L-98 swept four times and this audit twice more."""
    assert runprov.prune.plan(tmp_path / "never").remove == []
    assert runprov.prune.plan(tmp_path / "never") == runprov.prune.Plan([], 0, 0, 0, 0, 0, 0)

    d = tmp_path / ".incomplete"
    _marker(d, "dead")
    for boom in (OSError("nope"), RuntimeError("symlink loop")):
        monkeypatch.setattr(
            pathlib.Path, "resolve", lambda self, *a, _e=boom, **k: (_ for _ in ()).throw(_e)
        )
        assert runprov.prune.plan(d) == runprov.prune.Plan([], 0, 0, 0, 0, 0, 0)
    monkeypatch.undo()
    assert (d / "dead.json").is_file(), "nothing may be removed on a path that could not look"


def test_prune_reports_the_file_it_could_not_remove_and_keeps_going(tmp_path, monkeypatch):
    """One unremovable file must not stop the other four, and the user must be told WHICH."""
    d = tmp_path / ".incomplete"
    for i in range(5):
        _marker(d, f"dead{i}")
    real = pathlib.Path.unlink

    def refuse(self, *a, **k):
        if self.name == "dead2.json":
            raise PermissionError(13, "Permission denied")
        return real(self, *a, **k)

    monkeypatch.setattr(pathlib.Path, "unlink", refuse)
    gone, problems = runprov.prune.apply(runprov.prune.plan(d))
    assert gone == 4 and len(problems) == 1 and "dead2.json" in problems[0]


def test_parse_age_refuses_a_bare_number(tmp_path):
    """`--older-than 30` is far likelier to mean thirty days than thirty seconds, and the
    difference between those two guesses is deleting nothing and deleting everything."""
    assert runprov.prune.parse_age("30d") == 30 * 86400
    assert runprov.prune.parse_age("90m") == 5400
    assert runprov.prune.parse_age(" 12H ") == 12 * 3600
    for bad in ("30", "d", "", "xd", "-1d"):
        with pytest.raises(ValueError):
            runprov.prune.parse_age(bad)


def test_prune_dry_run_names_the_files_and_removes_none(tmp_path, capsys):
    """A `--dry-run` that says only "would remove 412" is not a preview — nobody can check
    it against anything — and an uncheckable preview is worse than none, because it looks
    like diligence. The listing is capped for the reason the banner is."""
    d = tmp_path / ".incomplete"
    for i in range(runprov.prune.LISTED + 3):
        _marker(d, f"dead{i:02d}")
    log = tmp_path / "runs.jsonl"

    assert cli.main(["prune", "--log", str(log), "--dry-run"]) == 0
    err = capsys.readouterr().err
    assert f"would remove {runprov.prune.LISTED + 3}" in err
    assert err.count("dead") == runprov.prune.LISTED, "the listing must be capped"
    assert "… and 3 more" in err
    assert len(list(d.glob("*.json"))) == runprov.prune.LISTED + 3, "a dry run removed files"

    assert cli.main(["prune", "--log", str(log)]) == 0
    assert f"removed {runprov.prune.LISTED + 3}" in capsys.readouterr().err
    assert list(d.glob("*.json")) == []


def test_prune_says_why_each_survivor_survived(tmp_path, capsys):
    """ "removed 0" with no explanation is the silence this package refuses everywhere else:
    a user staring at it needs to know WHICH of the four reasons it was."""
    d = tmp_path / ".incomplete"
    _marker(d, "alive", pid=os.getpid())
    _marker(d, "far", pid=1, host="a-compute-node")
    _marker(d, "young", started_utc="2999-01-01T00:00:00Z")
    _marker(d, "bad", started_utc="not-a-stamp")
    (d / "other.json").write_text('{"hello": 1}', encoding="utf-8")

    assert cli.main(["prune", "--log", str(tmp_path / "runs.jsonl"), "--older-than", "1d"]) == 0
    err = capsys.readouterr().err
    assert "removed 0" in err
    for why in ("still RUNNING", "another host", "younger than", "started_utc", "not runprov"):
        assert why in err, f"no reason given for {why!r}: {err}"
    assert len(list(d.glob("*.json"))) == 5

    for f in d.glob("*.json"):
        f.unlink()
    assert cli.main(["prune", "--log", str(tmp_path / "runs.jsonl")]) == 0
    assert "nothing to do." in capsys.readouterr().err


def test_prune_reports_a_bad_duration_as_a_usage_error(tmp_path, capsys):
    """Exit 2, like every other usage failure in this CLI, and a message rather than a
    traceback. Distinct from 1, which is a finding about the data."""
    assert cli.main(["prune", "--log", str(tmp_path / "runs.jsonl"), "--older-than", "soon"]) == 2
    assert "expected a number and a unit" in capsys.readouterr().err


def test_prune_exits_1_when_a_marker_would_not_go(tmp_path, capsys, monkeypatch):
    d = tmp_path / ".incomplete"
    _marker(d, "dead")
    monkeypatch.setattr(
        pathlib.Path,
        "unlink",
        lambda self, *a, **k: (_ for _ in ()).throw(PermissionError(13, "denied")),
    )
    assert cli.main(["prune", "--log", str(tmp_path / "runs.jsonl")]) == 1
    assert "could not remove dead.json" in capsys.readouterr().err


def test_show_forget_markers_runs_after_the_page_and_keeps_the_finding(tmp_path, capsys):
    """The flag's two promises. `show` still renders the page it would have rendered — the
    marker is COUNTED on it before it is cleared out from under the reader — and the finding
    survives, because the `started` line is what makes an interruption permanent."""
    log = tmp_path / "runs.jsonl"
    log.write_text(
        json.dumps(
            {
                "schema": runprov.run.START_SCHEMA,
                "run_uid": "killed",
                "run_id": "r",
                "script": "fetch",
                "generation": "g",
                "started_utc": "2020-01-01T00:00:00Z",
                "pid": _never_a_pid(),
                "host": runprov.show.platform.node(),
            }
        )
        + "\n",
        encoding="utf-8",
    )
    d = tmp_path / ".incomplete"
    _marker(d, "killed")

    assert cli.main(["show", "--log", str(log), "--forget-markers"]) == 0
    err = capsys.readouterr().err
    assert "INTERRUPTED" in err, "the page must be rendered BEFORE the markers go"
    assert err.index("INTERRUPTED") < err.index("removed 1"), "the prune must come after"
    assert list(d.glob("*.json")) == []

    assert cli.main(["show", "--log", str(log)]) == 0
    assert "INTERRUPTED" in capsys.readouterr().err, "the finding must outlive the index"


def test_show_forget_markers_works_where_there_is_no_history_at_all(tmp_path, capsys):
    """The path where the directory is most likely to be the only thing left: a deleted
    `runs.jsonl`, a `--log` pointed somewhere never written, a run started with no
    `provenance=`. Accepting the flag and silently doing nothing here would be the silent
    no-op this package refuses everywhere else."""
    d = tmp_path / ".incomplete"
    _marker(d, "orphan")
    log = tmp_path / "never-written.jsonl"

    assert cli.main(["show", "--log", str(log), "--forget-markers"]) == cli.CANNOT_CHECK
    err = capsys.readouterr().err
    assert "no run history" in err and "removed 1" in err
    assert list(d.glob("*.json")) == []


def test_show_forget_markers_never_overwrites_the_exit_code(tmp_path, capsys):
    """`show --stale --exit-code` returning 1 means an artifact is stale. A prune that went
    perfectly cannot turn that into a pass: the exit code is a finding about the DATA, and
    housekeeping has no vote in it."""
    root = tmp_path
    # GONE rather than STALE, because it is the finding this fixture can build without
    # depending on a sidecar or on mtime resolution — A-10's rule, that a test is only as
    # strong as the states its fixture can actually reach. `out.txt` is never written.
    src = root / "in.txt"
    src.write_text("a", encoding="utf-8")
    log = root / "runs.jsonl"
    log.write_text(
        json.dumps(
            {
                "schema": runprov.HISTORY_SCHEMA,
                "run_uid": "u",
                "run_id": "r",
                "script": "s.py",
                "generation": "g",
                "started_utc": "2020-01-01T00:00:00Z",
                "finished_utc": "2020-01-01T00:00:01Z",
                "status": "ok",
                "cwd": str(root),
                "inputs": [{"path": "in.txt", "sha256": "0" * 64}],
                "outputs": [{"path": "out.txt", "sha256": "1" * 64}],
            }
        )
        + "\n",
        encoding="utf-8",
    )
    _marker(root / ".incomplete", "dead")

    code = cli.main(["show", "--log", str(log), "--stale", "--exit-code", "--forget-markers"])
    err = capsys.readouterr().err
    assert "removed 1" in err, "the prune must still have happened"
    assert code == 1, f"a clean prune must not mask a staleness finding (got {code})"


# ------------------------------------------------------- late inputs vs the pin (A-16)
def _late_input_run(tmp_path):
    """A run that registers one input, renders a pin, then registers a second."""
    (tmp_path / "data").mkdir()
    (tmp_path / "data" / "a.tsv").write_text("a\n", encoding="utf-8")
    (tmp_path / "data" / "b.tsv").write_text("b\n", encoding="utf-8")
    # `allow_late_inputs=True`, because refusing is now the DEFAULT (A-16, 2026-08-22) and
    # these tests are about what the record says when a late input is deliberately permitted.
    # The refusal path has its own tests below.
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl", allow_late_inputs=True)
    # RELATIVE, because that is what a script writes and what the record then carries: paths
    # are stored as passed, not rewritten at persist time. Handing absolute ones in made the
    # first draft of these tests assert a spelling the package never produces.
    with runprov.Run("s.py", provenance="s.prov.json") as run:
        run.input("data/a.tsv")
        with run.open_output("out.tsv") as fh:  # renders the pin
            fh.write("x\n")
        run.input("data/b.tsv")  # AFTER it
    return run


def test_an_input_registered_after_the_pin_is_marked_in_the_record(tmp_path, monkeypatch):
    """A-16. `A WARNING IS EPHEMERAL; A FIELD IS PERMANENT` is this package's own sentence,
    written four hundred lines from this branch, about `unregistered_reads` — "a reviewer
    three years later can see that a read was missed". The same class of problem here printed
    to stderr and recorded NOTHING: the sidecar listed 2 inputs, the artifact's pin listed 1,
    and not one of the record's top-level keys said they disagreed.

    The divergence is permanent and unfixable after the fact — the bytes are on disk and a
    pin cannot grow a line — so the record saying so is the whole remedy available."""
    monkeypatch.chdir(tmp_path)
    run = _late_input_run(tmp_path)

    assert [i["path"] for i in run.record["inputs"]] == ["data/a.tsv", "data/b.tsv"]
    pin = (tmp_path / "out.tsv").read_text(encoding="utf-8")
    assert "inputs (1)" in pin and "data/b.tsv" not in pin, "the pin understates, as designed"
    assert run.record["inputs_not_in_pin"] == ["data/b.tsv"], (
        "the record must name what the pin does not list; a stderr line is not a record"
    )

    sidecar = json.loads((tmp_path / "s.prov.json").read_text(encoding="utf-8"))
    assert sidecar["inputs_not_in_pin"] == ["data/b.tsv"]
    # PAST THE TRIM. The history summary reduces each input to path and digests, so a
    # per-entry flag would not reach `show` — which is the only reader that can still check
    # the late input at all.
    line = _lines(tmp_path / "runs.jsonl")[-1]
    assert line["inputs_not_in_pin"] == ["data/b.tsv"], "it must survive the history trim"


def test_a_run_whose_pin_lists_everything_carries_no_such_key(tmp_path, monkeypatch):
    """OMITTED, NOT DEFAULTED — the rule the rest of the record follows, and the one
    `unregistered_reads` follows for this exact reason: a clean run is silent in the file as
    well as on the terminal, so the key's PRESENCE is the finding."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "a.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    with runprov.Run("clean.py", provenance="c.prov.json") as run:
        run.input("a.tsv")
        with run.open_output("out.tsv") as fh:
            fh.write("y\n")

    assert "inputs_not_in_pin" not in run.record
    assert "inputs_not_in_pin" not in json.loads(
        (tmp_path / "c.prov.json").read_text(encoding="utf-8")
    )
    assert "inputs_not_in_pin" not in _lines(tmp_path / "runs.jsonl")[-1]


def test_the_same_late_input_twice_is_named_once(tmp_path, monkeypatch):
    """A list that grows by one entry per CALL would report "2 inputs not in the pin" about
    one file, which is a different and wrong finding."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "a.tsv").write_text("a\n", encoding="utf-8")
    (tmp_path / "b.tsv").write_text("b\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl", allow_late_inputs=True)
    with runprov.Run("s.py", provenance="s.prov.json") as run:
        run.input("a.tsv")
        with run.open_output("out.tsv") as fh:
            fh.write("x\n")
        run.input("b.tsv")
        run.input("b.tsv")

    assert run.record["inputs_not_in_pin"] == ["b.tsv"]


def test_the_late_input_warning_no_longer_claims_nothing_can_detect_it(
    tmp_path, monkeypatch, capsys
):
    """The warning said "nothing downstream can detect it", and that was measurably false:
    `show --stale` reads the record, and the record has every input. Naming the command that
    CAN and the command that CANNOT is the actionable form — and the reason `verify` cannot
    is the same property that makes it work on an artifact with no history beside it."""
    monkeypatch.chdir(tmp_path)
    capsys.readouterr()
    _late_input_run(tmp_path)
    err = capsys.readouterr().err

    assert "input registered AFTER the pin was rendered" in err
    assert "nothing downstream can detect it" not in err, "the false claim is the defect"
    assert "inputs_not_in_pin" in err and "show --stale" in err, "say what still checks it"
    assert "verify" in err and "emailed" in err, "and what does not, and why"


def test_show_still_catches_a_late_input_going_stale_and_verify_still_cannot(
    tmp_path, monkeypatch, capsys
):
    """The two commands genuinely disagree about this artifact, and the README's table now
    has a row saying so. Asserted end to end, with a REVERT CONTROL: without it, "STALE" only
    shows that something was stale, not that the LATE input is what made it so."""
    monkeypatch.chdir(tmp_path)
    _late_input_run(tmp_path)
    log = str(tmp_path / "runs.jsonl")
    stale = ["show", "--log", log, "--stale", "--rehash", "--exit-code"]

    capsys.readouterr()
    assert cli.main(stale) == 0, "the fixture must start clean"

    (tmp_path / "data" / "b.tsv").write_text("CHANGED\n", encoding="utf-8")
    capsys.readouterr()
    assert cli.main(stale) == 1, "show reads the record, which has the late input"
    assert "STALE" in capsys.readouterr().err

    # AND `verify` SAYS OK, which is not a defect in `verify`: it reads the pin in the bytes
    # and nothing else, and that pin never listed this input. The record is the only place
    # the divergence can live.
    capsys.readouterr()
    assert cli.main(["verify", str(tmp_path / "out.tsv"), "--root", str(tmp_path)]) == 0
    assert "OK" in capsys.readouterr().out

    (tmp_path / "data" / "b.tsv").write_text("b\n", encoding="utf-8")
    capsys.readouterr()
    assert cli.main(stale) == 0, "revert control: the STALE came from the unpinned input"


# ------------------------------------------------- conditional transitivity (A-17)
def _three_stage(tmp_path, *, transform: bool):
    """Two pipelines from one script, differing ONLY in whether the middle step copies its
    input through. That is the whole variable, which is what makes the pair a control."""
    for d in ("data", "work", "results"):
        (tmp_path / d).mkdir(exist_ok=True)
    (tmp_path / "data" / "in.tsv").write_text("# a comment\nvalue\t1\nvalue\t2\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")

    def step(name, src, dst):
        with runprov.Run(name, provenance=f"provenance/{name}.prov.json") as run:
            run.input(src)
            text = pathlib.Path(src).read_text(encoding="utf-8")
            if transform:
                # Drops the comment lines — and with them the upstream pin block, which IS
                # the pin. Nothing exotic: every filter, reshape and plot does this.
                text = "".join(ln for ln in text.splitlines(True) if not ln.startswith("#"))
            with run.open_output(dst) as fh:
                fh.write(text)

    step("step1", "data/in.tsv", "work/mid.tsv")
    step("step2", "work/mid.tsv", "results/final.tsv")


def test_verify_is_transitive_only_when_the_step_writes_its_input_through(tmp_path, monkeypatch):
    """A-17. `verify`'s docstring said transitivity holds "because a pin lands in the artifact
    and a downstream step registers that artifact as an input". Registration is NOT the
    mechanism — registering `mid.tsv` pins MID's digest, not the root's. The mechanism is that
    the upstream pin BLOCK survives into the downstream bytes, which only happens for a step
    whose output contains its input.

    Same topology, same change to the same root, one variable."""
    monkeypatch.chdir(tmp_path)
    _three_stage(tmp_path, transform=False)
    final = tmp_path / "results" / "final.tsv"
    assert len(runprov.verify.read_pins(final)) == 2, "write-through carries the upstream pin"

    (tmp_path / "data" / "in.tsv").write_text("# a comment\nvalue\t999\n", encoding="utf-8")
    assert cli.main(["verify", "results/final.tsv", "--root", "."]) == 1, "the root changed"


def test_verify_reports_a_transforming_step_as_OK_after_its_root_changed(tmp_path, monkeypatch):
    """The other half of the control, and the finding. Nothing here is a bug in `verify`: it
    checks what the artifact claims, and this artifact claims one generation because that is
    all its bytes carry. The defect was three documents saying otherwise."""
    monkeypatch.chdir(tmp_path)
    _three_stage(tmp_path, transform=True)
    final = tmp_path / "results" / "final.tsv"
    assert len(runprov.verify.read_pins(final)) == 1, "the transform dropped the upstream pin"

    (tmp_path / "data" / "in.tsv").write_text("# a comment\nvalue\t999\n", encoding="utf-8")
    assert cli.main(["verify", "results/final.tsv", "--root", "."]) == 0, (
        "this is the measured behaviour the docs must describe, not the one they claimed"
    )
    # AND THE REMEDY IS REAL, which is what makes the corrected paragraph actionable rather
    # than merely honest: the intermediate is itself pinned and stale.
    assert cli.main(["verify", ".", "--root", "."]) == 1, (
        "verify . catches what verify results/ misses"
    )


def test_show_stale_is_one_generation_deep_in_BOTH_pipelines(tmp_path, monkeypatch, capsys):
    """The README calls `verify` + `show --stale` a gate, so the natural reading is that the
    second half covers what the first misses. It does not: `show` is one generation deep in
    both pipelines, including the write-through one where `verify` correctly reports STALE.

    The gate does go red — on the INTERMEDIATE. The published artifact is reported OK in
    both, and a reader looking at that row is the one being misled."""
    monkeypatch.chdir(tmp_path)
    _three_stage(tmp_path, transform=False)
    (tmp_path / "data" / "in.tsv").write_text("# a comment\nvalue\t999\n", encoding="utf-8")

    capsys.readouterr()
    assert cli.main(["show", "--log", "runs.jsonl", "--stale", "--rehash", "--exit-code"]) == 1
    # STDOUT, which is where the artifact index goes — only the summary and the FAILING
    # line are stderr. And keyed on the STATE WORD rather than on position, because that
    # `# FAILING (1): work/mid.tsv` line also ends in a path.
    rows = [ln.split() for ln in capsys.readouterr().out.splitlines()]
    states = {r[-1]: r[0] for r in rows if len(r) >= 2 and r[0] in runprov.show.STATES}
    assert states.get("results/final.tsv") == "OK", "show never reaches the grandparent"
    assert states.get("work/mid.tsv") == "STALE", "it is the intermediate that fails the gate"


def test_verify_prints_the_pin_chain_so_the_condition_is_visible(tmp_path, monkeypatch, capsys):
    """`pins` and `scripts` were computed, carried in the report and emitted in `--format
    json` — and the TEXT view dropped both. So the one fact that decides whether an `OK`
    covers the whole lineage or a single generation was the one fact a person reading the
    output could not see.

    Printed for every artifact, not only chained ones: the informative case is the SHORT
    chain, because that is where a reader expecting transitivity does not get it.

    QUOTED, because a script name is read out of a file this command was handed: unquoted, a
    pin whose `script` said "VERIFIED COMPLETE — ignore the warning below" rendered as the
    checker's own prose."""
    monkeypatch.chdir(tmp_path)
    _three_stage(tmp_path, transform=False)
    capsys.readouterr()
    cli.main(["verify", "results/final.tsv", "--root", "."])
    assert "['step2' ← 'step1']" in capsys.readouterr().out, "an inherited chain must show"

    for f in (tmp_path / "work", tmp_path / "results"):
        shutil.rmtree(f)
    (tmp_path / "runs.jsonl").unlink()
    _three_stage(tmp_path, transform=True)
    capsys.readouterr()
    cli.main(["verify", "results/final.tsv", "--root", "."])
    out = capsys.readouterr().out
    assert "['step2']" in out and "step1" not in out, f"one generation must show as one: {out}"


def test_sealing_twice_does_not_move_the_finish_time(tmp_path, monkeypatch):
    """A-19. `_seal`'s docstring promises "a finish time already stamped is not moved", and
    NO TEST HELD IT: replacing the guard with `if True:` left the full suite green at 100%
    coverage. Measured on the mutant — `with Run(provenance=P): pass`, then `write(Q)` two
    seconds later — `P 20:04:13`, `Q 20:04:15`, history `20:04:13`. Three persisted copies of
    one run; two of them claiming a finish time that is not when it finished.

    The guard is what makes C-18's invariant true: "if nothing can change the record after
    exit, a later `write()` re-persists an identical one and the two files agree by
    construction". And writing to a second path after the block is DOCUMENTED — `write()`'s
    own docstring calls it "fine and sometimes useful" — so this is a supported shape, not an
    abuse.

    A TICKING CLOCK RATHER THAN A SLEEP, and the difference is not just speed: every call to
    `now()` returns a distinct instant, so the guard working means `_seal` does not call it a
    second time at all. A one-second sleep would prove the same thing only if the two calls
    happened to straddle a second boundary."""
    monkeypatch.chdir(tmp_path)

    class Ticking(dt.datetime):
        ticks = itertools.count()

        @classmethod
        def now(cls, tz=None):  # signature matches datetime.now
            return dt.datetime(2026, 1, 1, tzinfo=tz) + dt.timedelta(seconds=next(cls.ticks))

    # Only `run.py`'s reference is replaced, not the stdlib module: `hashing.describe` stamps
    # `mtime_utc` from the real clock and has no business being frozen by this.
    monkeypatch.setattr(
        runprov.run, "dt", types.SimpleNamespace(datetime=Ticking, timezone=dt.timezone)
    )

    log = tmp_path / "runs.jsonl"
    runprov.configure(root=tmp_path, run_log=log)
    with runprov.Run("s", provenance="P.json") as run:
        pass
    run.write("Q.json")

    first = json.loads((tmp_path / "P.json").read_text(encoding="utf-8"))["finished_utc"]
    second = json.loads((tmp_path / "Q.json").read_text(encoding="utf-8"))["finished_utc"]
    history = _lines(log)[-1]["finished_utc"]

    assert first == second == history, (
        f"one run, three persisted copies, and they disagree about when it ended: "
        f"P={first} Q={second} history={history}"
    )
    # NOT VACUOUS: a clock that never advanced would make the assertion above true no matter
    # what `_seal` did. The run's own start and finish must be different instants.
    started = json.loads((tmp_path / "P.json").read_text(encoding="utf-8"))["started_utc"]
    assert started != first, "the fixture's clock did not tick, so it proves nothing"


def test_seal_replaces_a_finish_time_that_is_not_a_stamp(tmp_path, monkeypatch):
    """The other half of the same line, and it was undistinguished until this test.

    A-19 asked for the idempotence test, which kills `if True:`. It does NOT kill weakening
    `not isinstance(self.record.get("finished_utc"), str)` to `is None` — both stamp for
    every state `_seal` itself can produce, since the only other writer sets exactly `None`
    (`write()` mid-block). By this repository's standing rule that is either decoration or a
    missing test, so here is the state that tells them apart.

    `run.record` is a documented plain dict — the README passes it to `to_yaml` — so a caller
    assigning the natural wrong type is reachable. Measured: with `isinstance` the record
    gets a real stamp; with `is None` it keeps `'2020-01-01 00:00:00+00:00'`, stringified on
    the way out by `default=str`, which the package's own format cannot parse. That value
    then goes into an APPEND-ONLY history."""
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    run = runprov.Run("s", provenance="P.json")
    run.__enter__()
    run.record["finished_utc"] = dt.datetime(2020, 1, 1, tzinfo=dt.timezone.utc)
    run.__exit__(None, None, None)

    for where, value in (
        ("sidecar", json.loads((tmp_path / "P.json").read_text(encoding="utf-8"))),
        ("history", _lines(tmp_path / "runs.jsonl")[-1]),
    ):
        stamp = value["finished_utc"]
        assert isinstance(stamp, str), f"{where}: {stamp!r}"
        # PARSED, not pattern-matched: the question is whether a reader can use it.
        dt.datetime.strptime(stamp, "%Y-%m-%dT%H:%M:%SZ")
        assert not stamp.startswith("2020"), f"{where} kept the caller's value: {stamp!r}"


def test_the_project_page_reads_the_history_once(tmp_path, monkeypatch, capsys):
    """A-20. The page streamed every record and threw the `started` lines away; then
    `_report_in_flight` read the WHOLE FILE again to recover exactly those lines. Measured on
    a 56 MB, 60,000-run history: 2.63 s for the pass that must happen, 1.61 s for the one
    that need not — **+61%**, on a file that by design only grows.

    COUNTED, NOT TIMED. A timing assertion on a shared machine is a flake; the number of
    times the file is opened is the thing that was wrong and it is exact.

    `--stale` is excluded from the rule ON PURPOSE and asserted separately below: that pass
    is a deliberate trade the code documents — "re-reading 91 MB costs seconds; holding it
    costs hundreds of megabytes, and only one of those grows without bound"."""
    log = tmp_path / "runs.jsonl"
    log.write_text(
        json.dumps(
            {
                "schema": runprov.run.START_SCHEMA,
                "run_uid": "open",
                "run_id": "r",
                "script": "fetch",
                "generation": "g",
                "started_utc": "2020-01-01T00:00:00Z",
                "pid": _never_a_pid(),
                "host": runprov.show.platform.node(),
            }
        )
        + "\n",
        encoding="utf-8",
    )
    passes = [0]
    real = cli._stream

    def counting(p):
        passes[0] += 1
        yield from real(p)

    monkeypatch.setattr(cli, "_stream", counting)

    capsys.readouterr()
    assert cli.main(["show", "--log", str(log)]) == 0
    err = capsys.readouterr().err
    assert passes[0] == 1, f"the history was read {passes[0]} times to render one page"
    # NOT VACUOUS: the one pass must still have produced the finding the second pass used to.
    assert "INTERRUPTED" in err and "fetch" in err, err

    passes[0] = 0
    assert cli.main(["show", "--log", str(log), "--stale"]) == 0
    assert passes[0] == 2, (
        f"`--stale` makes one deliberate extra pass rather than holding the file in memory; "
        f"got {passes[0]}"
    )


def test_an_unreadable_history_line_does_not_hide_an_interrupted_run(tmp_path, capsys):
    """A torn line is what a history HAS after the crash that also left the run unfinished —
    the two arrive together — so the reader that reports interruptions is the last one that
    may fall over on one. A-10 is the same defect class one reader along.

    The reason this test exists rather than the guard alone: nothing exercised the branch.
    Every history reaching `consume` had only readable lines, so `if rec is not None` had one
    side measured, and a `saw(None)` would raise `AttributeError` inside the banner."""
    log = tmp_path / "runs.jsonl"
    log.write_text(
        "{not json at all\n"
        + json.dumps(
            {
                "schema": runprov.run.START_SCHEMA,
                "run_uid": "killed",
                "run_id": "r",
                "script": "fetch",
                "generation": "g",
                "started_utc": "2020-01-01T00:00:00Z",
                "pid": _never_a_pid(),
                "host": runprov.show.platform.node(),
            }
        )
        + "\n[1, 2, 3]\n",
        encoding="utf-8",
    )
    capsys.readouterr()
    cli._report_in_flight(log)
    err = capsys.readouterr().err
    assert "INTERRUPTED" in err and "fetch" in err, f"the torn lines hid the finding: {err}"


def test_only_init_states_how_many_names_the_package_promises():
    """A-22. `test_every_module_declares_its_surface_and_none_of_them_invents_one` checks the
    LISTS and the nine module headers above them are prose, so when the L-84 follow-up cut
    the surface from 22 names to 17 the lists were corrected and every header went on saying
    "22 names". Nine files, all wrong, in the very comment that ADR-0003 makes the ratifying
    record of the surface.

    The remedy is not to write 17 nine more times — that is the same drift rescheduled, and
    this repository has now found four of these. ONE PLACE STATES THE COUNT, `__init__.py`,
    where the list it counts also lives, and this asserts both halves: nobody else states it,
    and the one that does is right."""
    root = _repo_root() / "runprov"
    # THE DIGITS MUST NOT BE PART OF AN IDENTIFIER. `(\d+)\s+names` matched "R-12 names this
    # structure" — taking "12" out of an ADR reference — so ordinary prose citing a numbered
    # requirement tripped a guard about the size of the package surface. Measured: the tight
    # form rejects "R-12 names" and "ADR-0017 R-9 names" and still matches "17 names",
    # "#: 17 names." and "cut it to 22 names".
    #
    # THIS IS A FALSE POSITIVE REMOVED, NOT A SIGNAL SUPPRESSED, and the distinction is I-17's:
    # there, a truncation was noticed and the guard was adjusted so it would pass, which hid a
    # real asymmetry. Here the guard was answering a question nobody asked it — "R-12" is not a
    # statement of how many names this package promises — and the alternative was to forbid
    # citing a requirement by number in a module docstring.
    pat = re.compile(r"(?<![\w-])(\d+)\s+names\b")
    modules = sorted(root.glob("*.py"))
    assert len(modules) > 5, f"the module sweep found {len(modules)} files; the scope broke"

    elsewhere = {
        f.name: pat.findall(f.read_text(encoding="utf-8"))
        for f in modules
        if f.name != "__init__.py" and pat.search(f.read_text(encoding="utf-8"))
    }
    assert not elsewhere, (
        f"a module header states the size of the package surface, which it cannot check and "
        f"which drifted to nine wrong copies once already: {elsewhere}"
    )

    stated = pat.findall((root / "__init__.py").read_text(encoding="utf-8"))
    assert stated, "`__init__.py` no longer says how many names it promises"
    assert {int(s) for s in stated} == {len(runprov.__all__)}, (
        f"`__init__.py` says {stated} names and promises {len(runprov.__all__)}"
    )


def _withdrawn_names() -> list[str]:
    """The ten names `__init__.py` records as withdrawn, read from the record itself.

    From the TABLE COLUMN of the withdrawal blocks, not from loose prose: scanning the whole
    header for tokens that happen to be public attributes also catches `json`, `time`,
    `typing` and `own`, which are ordinary words in that text. And cross-checked both ways —
    every name must still exist on some submodule (a typo in the table fails loudly) and none
    may still be in the package `__all__`.
    """
    init = (_repo_root() / "runprov" / "__init__.py").read_text(encoding="utf-8")
    names = []
    for line in init.split("__all__ = [")[0].splitlines():
        m = re.match(r"^#   ([A-Za-z_][\w, ]*?)(?:\s{2,}.*)?$", line)
        if m:
            names += [n for n in re.split(r",\s*", m.group(1).strip()) if n and " " not in n]
    public = {
        n
        for f in sorted((_repo_root() / "runprov").glob("*.py"))
        if f.stem != "__init__"
        for n in dir(importlib.import_module(f"runprov.{f.stem}"))
        if not n.startswith("_")
    }
    found = sorted(set(names))
    assert found, "the withdrawal record is gone from `__init__.py`; if deliberate, delete this"
    assert set(found) <= public, f"the table names something no module has: {set(found) - public}"
    assert not set(found) & set(runprov.__all__), (
        f"a name is recorded as withdrawn AND still promised: "
        f"{sorted(set(found) & set(runprov.__all__))}"
    )
    return found


def test_no_module_header_argues_for_a_name_it_no_longer_exports():
    """The other half of A-22, and the one a count check cannot reach. `project.py` carried
    five lines arguing that withdrawing `git` "is a package-level decision and is still open;
    this file cannot take it" — directly above an `__all__` with no `git` in it, and after
    ADR-0003's addendum recorded the decision as taken. `environment.py` opened with "Both
    are in the package `__all__`" above an `__all__` that is empty: a sentence that outlived
    its subject.

    A header may NAME a withdrawn export — saying where it went is the point, and `run.py`
    does it well for `PIN_UNSAFE`. What it may not do is discuss one without saying so. The
    population checked is exactly the ten `__init__.py` records as withdrawn, so this cannot
    fire on an internal helper a header legitimately explains.

    BACKTICKS ONLY, AND THAT IS A REAL LIMIT RATHER THAN A DETAIL. Matching the bare word
    catches ordinary English — "what git sees", "a file that git can diff" — so the rule is
    the codebase's own convention that an API name is written in backticks. The consequence
    is that this catches `project.py`'s shape, a named export argued for after withdrawal,
    and NOT `environment.py`'s, which said "Both are in the package `__all__`" and named
    neither name. A sentence whose subject is a pronoun is not reachable from here; that one
    was fixed by reading, and this guard does not pretend otherwise."""
    withdrawn = _withdrawn_names()
    offenders = []
    for f in sorted((_repo_root() / "runprov").glob("*.py")):
        if f.name == "__init__.py":
            continue
        # SPLIT ON THE ASSIGNMENT, not on the first mention. `split("__all__", 1)` cuts at
        # the boilerplate's own "lists it in the package `__all__`" three lines in, so the
        # slice stopped ABOVE the paragraph this test exists to read — and the check passed
        # on a tree where `git` was argued for again. The same scope defect the row reports,
        # in the guard written for it.
        header = re.split(r"^__all__", f.read_text(encoding="utf-8"), maxsplit=1, flags=re.M)[0]
        for name in withdrawn:
            near = [ln for ln in header.splitlines() if f"`{name}`" in ln]
            if near and not any(("WITHDRAWN" in ln or "absent" in ln) for ln in near):
                offenders.append(f"{f.name}: {near[0].strip()}")
    assert not offenders, (
        f"a module header discusses a withdrawn name without saying it was withdrawn — the "
        f"shape that left `git` argued for five lines above an `__all__` that had dropped "
        f"it: {offenders}"
    )


def _configure_kwargs(source: str) -> set[str]:
    """The keyword names passed to `configure(...)` in a block of example code."""
    return {
        kw.arg or "**"
        for node in ast.walk(ast.parse(source))
        if isinstance(node, ast.Call) and getattr(node.func, "id", None) == "configure"
        for kw in node.keywords
    }


def test_the_cli_examples_work_against_the_quickstart_as_written(tmp_path, monkeypatch, capsys):
    """A-23. The README said "if you set `run_log` — as the quickstart above does — every one
    of those commands needs `--log reports/runs.jsonl`". The quickstart does not set
    `run_log`, `reports/runs.jsonl` appeared nowhere in it, and following the instruction
    literally exits 1 while the command it says will not work exits 0. Measured both ways.

    The paragraph was left over from an older quickstart, three sections above a paragraph
    saying "**Leave `run_log` alone unless you have a reason**".

    EXECUTED, NOT READ. The quickstart is already parsed by two tests and neither runs it, so
    a claim about what its CLI commands DO had nothing holding it. This configures a project
    the way the quickstart does, records a run, and runs `log` with no `--log` — which is the
    sentence, tested."""
    assert "run_log" not in _configure_kwargs(_first_python_block(_readme())), (
        "the quickstart now sets run_log, so the paragraph about `--log` has to change with it"
    )

    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path)
    with runprov.Run("summarise", provenance="provenance/s.prov.json"):
        pass

    capsys.readouterr()
    assert cli.main(["log"]) == 0, "the README's own commands must work with no --log"
    assert "summarise" in capsys.readouterr().out


def test_the_shipped_help_example_teaches_the_shape_the_readme_recommends():
    """The other half of A-23, and most likely where the stale sentence came from.

    `runprov/__init__.py`'s docstring is what `help(runprov)` and `pydoc runprov` print, and
    it was the one shipped example setting `run_log=REPO / "reports" / "runs.jsonl"` — the
    shape the README spends a paragraph advising against, with no `--log` caveat beside it.
    A reader following `help()` gets a project whose CLI reports nothing recorded."""
    assert "run_log" not in _configure_kwargs(
        textwrap.dedent(
            "\n".join(
                ln[4:] if ln.startswith("    ") else ln
                for ln in (runprov.__doc__ or "").splitlines()
                if ln.startswith("    ") or not ln.strip()
            )
        )
    ), (
        "`help(runprov)` sets run_log, which the README advises against and which silently "
        "sends the CLI to a path with no history in it"
    )


def test_every_sdist_include_entry_names_something_that_exists():
    """A-24, the half that can be checked without building. `include` is an explicit
    allowlist, so an entry that names a moved or renamed path ships nothing and says nothing
    — which is the same silence the list exists to prevent, running the other way.

    `ci.py build` checks this against the real tarball, which is the authoritative version
    and the one that also catches a file excluded by some other rule. This runs in the fast
    suite, so a stale entry fails in the commit that introduces it rather than at release."""
    pyproject = (_repo_root() / "pyproject.toml").read_text(encoding="utf-8")
    block = pyproject[pyproject.index("[tool.hatch.build.targets.sdist]") :]
    block = block[block.index("include = [") : block.index("]", block.index("include = ["))]
    named = re.findall(r'"([^"]+)"', block)
    assert len(named) > 5, f"the include list parsed to {named}; the reader broke"

    missing = sorted(n for n in named if not (_repo_root() / n).exists())
    assert not missing, (
        f"pyproject's sdist `include` names {missing}, which is not in the repository — "
        f"the entry ships nothing and nothing says so"
    )


def test_the_in_flight_count_equals_the_rows_it_prints(tmp_path, capsys):
    """A-25, and the reason it is a row rather than a nicety: L-99 closed on the argument
    that "a reader who cannot trust the count of what was lost is worse off than one given no
    count at all, because the number looks like evidence". The header count and the rows are
    computed from one list, and `markers.pop` is what keeps a run that has BOTH a start line
    and a marker out of it twice.

    Changing that `.pop` to `.get` — one character, and exactly what a refactor-for-clarity
    does — makes `show` print `# 2 run(s) STARTED` above the identical row twice. Measured.

    THE ASSERTION IS THE INVARIANT, NOT A LITERAL: the count must equal the rows, whatever
    the page holds. A page built of three different shapes at once is what makes that mean
    something — a paired live run, a paired dead one, and a marker the history never heard
    of, which is the one shape that SHOULD add a row."""
    here = runprov.show.platform.node()
    dead = _never_a_pid()
    log = tmp_path / "runs.jsonl"
    d = tmp_path / ".incomplete"
    d.mkdir()

    def start(uid, pid):
        return json.dumps(
            {
                "schema": runprov.run.START_SCHEMA,
                "run_uid": uid,
                "run_id": f"r-{uid}",
                "script": uid,
                "generation": "g",
                "started_utc": f"2026-08-22T09:00:0{len(uid)}Z",
                "host": here,
                "pid": pid,
            }
        )

    def marker(uid, pid):
        (d / f"{uid}.json").write_text(
            json.dumps(
                {
                    "run_uid": uid,
                    "script": uid,
                    "started_utc": f"2026-08-22T09:00:0{len(uid)}Z",
                    "host": here,
                    "pid": pid,
                }
            ),
            encoding="utf-8",
        )

    # paired and alive, paired and dead, and an orphan marker with no start line
    log.write_text(start("alive", os.getpid()) + "\n" + start("killed", dead) + "\n", "utf-8")
    marker("alive", os.getpid())
    marker("killed", dead)
    marker("orphan", dead)

    capsys.readouterr()
    assert cli.main(["show", "--log", str(log)]) == 0
    err = capsys.readouterr().err

    stated = int(re.search(r"# (\d+) run\(s\) STARTED", err).group(1))
    rows = [ln for ln in err.splitlines() if re.match(r"#   (RUNNING|INTERRUPTED|\?) ", ln)]
    assert stated == len(rows) == 3, (
        f"the header says {stated} and {len(rows)} rows were printed; a paired run must "
        f"appear once, and only the orphan marker adds one: {err}"
    )
    assert len([r for r in rows if "alive" in r]) == 1, f"the live run is doubled: {err}"
    assert len([r for r in rows if "killed" in r]) == 1, f"the dead run is doubled: {err}"
    # AND THE FINDING TALLY, which is computed over the same list and would double with it.
    assert "2 of them ran no ending code at all" in err, err

    # `pending()` READS LIKE A QUERY AND MUST BEHAVE LIKE ONE. It pops from a COPY of the
    # marker dict; popping from `self.markers` is indistinguishable today, because `report()`
    # is the only caller and calls it once — which is precisely the shape that traps the next
    # caller, and this class is three days old. Asserted rather than left as a line no
    # mutation can tell from its absence.
    scan = cli._InFlightScan(d)
    scan.consume(log)
    assert [r["run_uid"] for r in scan.pending()] == [r["run_uid"] for r in scan.pending()], (
        "pending() consumed its own state; the second call answers a different question"
    )


def test_a_marker_that_cannot_answer_does_not_outrank_a_start_line_that_can(tmp_path, capsys):
    """Found by mutation while closing A-25: `marker["state"] if marker else liveness(rec)`
    had a branch nothing could distinguish. Both records are written by the same process, so
    their `pid` and `host` agree and either source gives the same state — always, for every
    run this package can produce.

    They diverge when the MARKER is damaged. One that still parses but has lost its `pid`
    reports `?`, and `?` was then printed on a line carrying the start record's own live pid
    and this host — "we could not look" rendered as a verdict with the answer beside it, on
    the same line. Measured before the fix:

        #   ?            align   2026-08-22T09:00:00Z  pid 172377  on corpus-host

    The start line exists to answer exactly this (A-03), so whichever source CAN answer
    wins."""
    here = runprov.show.platform.node()
    log = tmp_path / "runs.jsonl"
    log.write_text(
        json.dumps(
            {
                "schema": runprov.run.START_SCHEMA,
                "run_uid": "damaged",
                "run_id": "r",
                "script": "align",
                "generation": "g",
                "started_utc": "2026-08-22T09:00:00Z",
                "pid": os.getpid(),
                "host": here,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    d = tmp_path / ".incomplete"
    d.mkdir()
    # PARSES, AND CANNOT ANSWER: no `pid`. `in_flight` skips a torn marker, so the shape that
    # reaches here is one that survived being written and lost a field afterwards.
    (d / "damaged.json").write_text(
        json.dumps({"run_uid": "damaged", "script": "align", "host": here}), encoding="utf-8"
    )

    capsys.readouterr()
    assert cli.main(["show", "--log", str(log)]) == 0
    err = capsys.readouterr().err
    assert "RUNNING" in err, f"the start line could answer and was not asked: {err}"
    assert not re.search(r"#   \?\s", err), f"`?` printed beside a live pid on this host: {err}"

    # AND THE SAME DAMAGE THE OTHER WAY ROUND. Nothing privileges either file, so a start
    # line that lost its `pid` beside an intact marker must also report the answer rather
    # than `?`. Both mutations — always take the marker, never take it — left the suite green
    # before these two assertions existed.
    log.write_text(
        json.dumps(
            {
                "schema": runprov.run.START_SCHEMA,
                "run_uid": "damaged",
                "run_id": "r",
                "script": "align",
                "generation": "g",
                "started_utc": "2026-08-22T09:00:00Z",
                "host": here,
            }
        )
        + "\n",
        encoding="utf-8",
    )
    (d / "damaged.json").write_text(
        json.dumps({"run_uid": "damaged", "script": "align", "pid": os.getpid(), "host": here}),
        encoding="utf-8",
    )
    capsys.readouterr()
    assert cli.main(["show", "--log", str(log)]) == 0
    err = capsys.readouterr().err
    assert "RUNNING" in err, f"the marker could answer and was not asked: {err}"

    # AND THE OTHER HOST STILL READS `?`, because there the answer genuinely is not available
    # — `os.kill(pid, 0)` here would report on whichever local process holds that number.
    (d / "damaged.json").write_text(
        json.dumps({"run_uid": "damaged", "script": "align", "pid": 1, "host": "a-compute-node"}),
        encoding="utf-8",
    )
    log.write_text(
        log.read_text(encoding="utf-8").replace(f'"host": "{here}"', '"host": "a-compute-node"'),
        encoding="utf-8",
    )
    capsys.readouterr()
    assert cli.main(["show", "--log", str(log)]) == 0
    assert "?" in capsys.readouterr().err, "a pid on another host still cannot be judged here"


def test_the_marker_names_the_history_the_run_actually_joined(tmp_path):
    """A-26. `_mark_in_flight` wrote `"history": str(resolved_run_log())`. Under a custom
    `sink=`, `resolved_sink()` returns only that sink and the run log is a path NOTHING EVER
    WRITES — so the marker asserted a location that was never observed, in the module whose
    stated rule is that a record must not say more than was observed. Reproduced with a sink
    exposing only `append`: `marker history exists: False`, while both `runprov.start.v1` and
    `runprov.history.v2` reached the sink and the terminal correctly printed
    `history -> DbSink`.

    `history_destination()` is the package's existing single answer — "a sink with no `path`
    (a database, a queue) is named by its type … saying it is better than printing a run log
    the sink ignores" — and the RECORD already used it. The marker was the one place that
    disagreed with it, so this asserts the two AGREE rather than pinning either spelling.

    MEASURED ON THE MARKER WRITTEN MID-RUN, because `_clear_in_flight` removes it at
    `__exit__`; checking afterwards would be checking nothing."""
    sink, proj = _sinked(tmp_path)
    run = runprov.Run("s", project=proj, provenance=tmp_path / "p.json")
    run.__enter__()
    try:
        marker = json.loads(
            next((tmp_path / "provenance" / ".incomplete").glob("*.json")).read_text(
                encoding="utf-8"
            )
        )
        assert marker["history"] == proj.history_destination(), (
            f"the marker says {marker['history']!r}, the run joined {proj.history_destination()!r}"
        )
        assert marker["history"] == run.record["history"]["destination"], (
            "the marker and the record must give one answer, not two"
        )
        # AND IT IS NOT A PATH THAT WILL NEVER EXIST, which is the defect stated directly.
        assert not pathlib.Path(marker["history"]).exists(), (
            "premise: with a sink, the run log is never written — if this fails the fixture "
            "stopped exercising the sink path and the test above proves nothing"
        )
        assert marker["history"] == type(sink).__name__
    finally:
        run.__exit__(None, None, None)


def test_the_marker_still_names_the_file_when_there_is_no_sink(tmp_path, monkeypatch):
    """The other side of A-26: with no `sink=`, `history_destination()` IS the run log, so the
    ordinary case must be unchanged. A fix that made every marker say `JsonlSink` would have
    traded a wrong answer for a useless one."""
    monkeypatch.chdir(tmp_path)
    log = tmp_path / "runs.jsonl"
    runprov.configure(root=tmp_path, run_log=log)
    run = runprov.Run("s", provenance="p.json")
    run.__enter__()
    try:
        marker = json.loads(
            next((tmp_path / ".incomplete").glob("*.json")).read_text(encoding="utf-8")
        )
        assert marker["history"] == str(log)
    finally:
        run.__exit__(None, None, None)


def test_every_pinned_tool_in_a_workflow_matches_the_dev_extra():
    """A-27. `publish.yml` installed `build` and `twine` with `--upgrade` and no constraint —
    in the one job whose output is uploaded to PyPI, where `on: push: tags` fires once and a
    version can never be re-uploaded. Everything around it was careful: every action
    SHA-pinned, `permissions` scoped, trusted publishing, and the backend constrained
    (`hatchling>=1.27,<2`). The front-end tooling was the gap, and it contradicted the policy
    stated two files over for `ruff` and `mypy`.

    THE VERSIONS LIVE IN `pyproject.toml`, because that is the file Dependabot's `pip`
    ecosystem reads — it does not read a workflow's `run:` line, so "Dependabot raises both"
    was only ever true of the tools that were also in the `dev` extra. Which leaves two
    copies of one fact, and this is what keeps them one: a bump in `pyproject.toml` that the
    workflows do not follow fails here rather than silently installing something else in the
    job that builds the artifact.

    DERIVED FROM THE WORKFLOWS, not a list of tool names typed here — the scope defect this
    audit found five times. Any `name==version` a workflow installs is checked."""
    pyproject = (_repo_root() / "pyproject.toml").read_text(encoding="utf-8")
    # `\]\s*$`, because a non-greedy `\]` stops at the one inside `"runprov[test]"` and
    # the extra parses to nothing. Caught by the non-vacuity assertion below.
    dev = re.search(r"^dev = \[(.*?)\]\s*$", pyproject, re.M | re.S)
    assert dev, "the `dev` extra is gone from pyproject.toml"
    pinned = dict(re.findall(r'"([A-Za-z0-9_.\-]+)==([^"]+)"', dev.group(1)))
    assert len(pinned) >= 4, f"the dev extra parsed to {pinned}; the reader broke"

    disagree, unpinned = [], []
    for wf in _workflow_files():
        for line in wf.read_text(encoding="utf-8").splitlines():
            if "pip install" not in line:
                continue
            for name, version in re.findall(r'"([A-Za-z0-9_.\-]+)==([^"]+)"', line):
                if name in pinned and pinned[name] != version:
                    disagree.append(f"{wf.name}: {name}=={version}, pyproject says {pinned[name]}")
            # AND THE OTHER DIRECTION: a tool the dev extra pins, installed unpinned by a
            # workflow, is the defect this row is about — `--upgrade build twine` beside a
            # `dev` extra naming both.
            bare = re.sub(r'"[^"]*"', "", line)
            unpinned += [
                f"{wf.name}: {tool} installed unpinned"
                for tool in pinned
                if re.search(rf"\b{re.escape(tool)}\b", bare)
            ]

    assert not disagree, f"a workflow installs a version pyproject does not name: {disagree}"
    assert not unpinned, (
        f"a workflow installs a tool the `dev` extra pins, without the pin — which is how "
        f"the release job built its artifact with whatever had shipped that morning: "
        f"{unpinned}"
    )


def test_the_yaml_view_stays_one_entry_per_run_when_the_schema_is_bumped(tmp_path, monkeypatch):
    """A-28. `YamlLogSink.append` filtered start lines with the literal `"runprov.start.v1"`
    while `__main__` used the imported `START_SCHEMA` — one sentence in two places, which is
    what `076b770` and ADR-0003 removed for `PIN_ANCHOR`.

    Measured before the fix: bump `START_SCHEMA` to v2, run ONE ordinary run, and
    `transformation_log.yml` gets two `- step:` entries with the first hollow — verbatim the
    outcome the filter exists to prevent, in the file the README positions as the successor
    to the predecessor's manifest, where any `yaml.safe_load` tally would double.

    NOT A TEST THAT THE TWO STRINGS ARE EQUAL. Ledger `9db5b48` settled that: "a test holding
    two constants equal is the defect deferred, not closed" — it passes just as well when both
    copies are wrong together. This bumps the schema and asserts the PROPERTY, which is what
    the literal was silently failing to deliver.

    The suite does go red on a bump today, which is why this is low and not medium — but on
    `len(entries) == 3` in an unrelated history-count test, so the maintainer is pointed at
    the wrong file."""
    monkeypatch.setattr(runprov.run, "START_SCHEMA", "runprov.start.v2")
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "prov" / "runs.jsonl")
    for i in range(2):
        with runprov.Run(f"s{i}", provenance=f"prov/p{i}.json"):
            pass

    yaml_view = (tmp_path / "prov" / "transformation_log.yml").read_text(encoding="utf-8")
    entries = [ln for ln in yaml_view.splitlines() if ln.startswith("- step:")]
    assert len(entries) == 2, (
        f"two completed runs must be two entries in the narrative a person reads; the start "
        f"lines were rendered as well: {entries}"
    )
    # THE PREMISE, asserted rather than assumed: the bump really did reach the records. A
    # monkeypatch that missed would make the count right for the wrong reason.
    starts = [
        r
        for r in (
            json.loads(x) for x in (tmp_path / "prov" / "runs.jsonl").read_text().splitlines()
        )
        if r.get("schema") == "runprov.start.v2"
    ]
    assert len(starts) == 2, f"the schema bump never reached the history: {starts}"


def test_every_document_naming_the_start_schema_names_the_current_one():
    """A-28's other half, and the reason removing the duplicated literals needed a
    replacement rather than just a deletion.

    Before: a real bump failed 42 tests, essentially all of them because the test helper
    `_completed` hardcoded the string — noise that told a maintainer nothing true, and buried
    the one thing that HAD silently broken, the YAML narrative. After: the readers all follow
    the constant, and a bump passes the whole suite. That is correct for the code and wrong
    for the documents: README and CHANGELOG both print `runprov.start.v1` to a reader as the
    shape of a line in their history file, and both would quietly become false.

    So the loudness moves to where it belongs. DERIVED over every Markdown file, not a list of
    two filenames — the scope defect this audit found five times.

    MARKDOWN ONLY, deliberately. Source comments also name the schema, but some of them are
    HISTORICAL — `sinks.py` records what the filter used to compare against, and that sentence
    stays true after a bump. A document showing a reader what their file contains does not."""
    current = runprov.run.START_SCHEMA
    pat = re.compile(r"runprov\.start\.v\d+")
    skip = {".git", ".venv", "__pycache__", ".mypy_cache", ".pytest_cache", "dist", "build"}
    docs = sorted(
        f
        for f in _repo_root().rglob("*.md")
        if not any(p in skip or p.endswith(".egg-info") for p in f.relative_to(_repo_root()).parts)
    )
    assert len(docs) > 3, f"the document sweep found {len(docs)} files; the scope broke"

    stale, cited = [], []
    for f in docs:
        for name in pat.findall(f.read_text(encoding="utf-8")):
            cited.append(f.name)
            if name != current:
                stale.append(f"{f.relative_to(_repo_root())}: {name}")
    assert cited, (
        "no document names the start schema any more; if that is deliberate, delete this test "
        "— it exists because README and CHANGELOG both print it to a reader"
    )
    assert not stale, (
        f"a document shows a reader a schema the package no longer writes, which is exactly "
        f"what a bump makes false and nothing else would now catch: {stale}"
    )


def test_a_promised_name_no_document_mentions_carries_a_recorded_reason():
    """A-31, mechanised. The L-84 follow-up withdrew five names on a measurement — "zero
    references in README, GETTING-STARTED, WHY and every ADR, checked rather than assumed" —
    and the same measurement over the SURVIVORS found `active`, `is_configured` and
    `detect_root` at zero, with `__init__.py`'s block silent about all three while it gave a
    reason for every other quiet name.

    THE SILENCE WAS THE ANOMALY, NOT THE NAMES. Zero references does not disqualify a name
    here: `HISTORY_SCHEMA` and both `DEFAULT_*` tuples score zero and stay, on recorded
    reasons. So the rule is not "delete the quiet ones", it is "a promise nobody was told to
    call has to say why it is a promise" — and that is what this asserts, for every such name
    rather than for the three that happened to be found.

    A name the documents DO use justifies itself by use and needs no line; that is why the
    measurement is the filter and not a list of names typed here."""
    docs = [_repo_root() / n for n in ("README.md", "GETTING-STARTED.md", "WHY.md")]
    docs += sorted((_repo_root() / "docs" / "adr").glob("*.md"))
    docs = [d for d in docs if d.is_file()]
    assert len(docs) > 3, f"the document sweep found {len(docs)} files; the scope broke"
    text = "\n".join(d.read_text(encoding="utf-8") for d in docs)

    reasons = (_repo_root() / "runprov" / "__init__.py").read_text(encoding="utf-8")
    reasons = reasons.split("__all__ = [")[0]
    quiet, loud = [], []
    for name in runprov.__all__:
        (quiet if not re.search(rf"\b{re.escape(name)}\b", text) else loud).append(name)

    # NOT VACUOUS in either direction: some names must be quiet (or the rule checks nothing)
    # and some must be loud (or the reader is broken and everything looks quiet).
    assert quiet and loud, f"quiet={quiet} loud={loud}; the reference measurement broke"

    silent = [n for n in quiet if f"`{n}`" not in reasons]
    assert not silent, (
        f"{silent} are promised, appear in no document, and `__init__.py` does not say why "
        f"they are promised — which is the shape the L-84 withdrawal used to remove five "
        f"other names"
    )


def test_a_late_input_is_refused_by_default_and_the_refusal_is_recorded(tmp_path, monkeypatch):
    """A-16, second half — Taylor's decision, 2026-08-22. `4d37469` made the record say a late
    input happened; this stops it happening.

    WHY REFUSING IS THE ONLY REMEDY, and not merely the strictest: the pin is in the
    artifact's first bytes and those bytes are on disk. The sidecar, the history and
    `show --stale` can all describe the divergence afterwards, but the person holding ONLY the
    artifact runs `verify`, gets OK, and has no way to learn otherwise — measured in the row.
    Stopping the run before the artifact becomes wrong is the one repair that reaches them.

    THE FOURTH RAISE, NOT THE FIRST. `input()` already refuses a missing file, an unreadable
    one and a FIFO. Those three refuse a read that would fail anyway; this refuses one that
    would SUCCEED and be recorded imperfectly, which is why it was Taylor's call and not an
    applier's.

    RECORDED BEFORE IT IS RAISED, so a caller who catches the error cannot erase the fact."""
    monkeypatch.chdir(tmp_path)
    for name in ("a.tsv", "b.tsv"):
        (tmp_path / name).write_text("x\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")

    with pytest.raises(ValueError, match="cannot grow a line"):
        with runprov.Run("s", provenance="p.json") as run:
            run.input("a.tsv")
            with run.open_output("out.tsv") as fh:
                fh.write("x\n")
            run.input("b.tsv")

    record = json.loads((tmp_path / "p.json").read_text(encoding="utf-8"))
    assert record["refused_late_inputs"] == ["b.tsv"]
    assert [i["path"] for i in record["inputs"]] == ["a.tsv"], "the refused input is NOT in it"
    assert "inputs_not_in_pin" not in record, "nothing diverged, because nothing was accepted"
    assert record["status"] == "failed"
    # PAST THE TRIM, like `inputs_not_in_pin`: a caller may catch the ValueError and finish
    # OK, and then the terminal shows nothing at all.
    assert _lines(tmp_path / "runs.jsonl")[-1]["refused_late_inputs"] == ["b.tsv"]

    # THE MESSAGE MUST NAME THE WAY OUT, or a user who genuinely cannot register earlier is
    # left with a refusal and no route.
    with pytest.raises(ValueError, match="allow_late_inputs"):
        with runprov.Run("s2", provenance="p2.json") as run:
            with run.open_output("out2.tsv") as fh:
                fh.write("x\n")
            run.input("b.tsv")


def test_a_caught_refusal_still_leaves_the_fact_in_a_successful_record(tmp_path, monkeypatch):
    """The reason the refusal is a FIELD and not just an exception. A caller can catch the
    ValueError and carry on; the run then ends `ok`, the terminal is silent, and without this
    the record would say nothing at all about the input that was turned away."""
    monkeypatch.chdir(tmp_path)
    for name in ("a.tsv", "b.tsv"):
        (tmp_path / name).write_text("x\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")

    with runprov.Run("s", provenance="p.json") as run:
        run.input("a.tsv")
        with run.open_output("out.tsv") as fh:
            fh.write("x\n")
        for _ in range(3):
            # THREE TIMES, because a caller that swallows the error usually swallows it in a
            # LOOP. One file refused repeatedly is one fact; a list that grew per call would
            # report "3 inputs refused" about one path — the same wrong finding the
            # `inputs_not_in_pin` dedup exists to prevent.
            with contextlib.suppress(ValueError):
                run.input("b.tsv")

    record = json.loads((tmp_path / "p.json").read_text(encoding="utf-8"))
    assert record["status"] == "ok", "the caller swallowed it; the run succeeded"
    assert record["refused_late_inputs"] == ["b.tsv"], "and the record still says so, once"


def test_allow_late_inputs_restores_the_warning_and_the_divergence_field(
    tmp_path, monkeypatch, capsys
):
    """The escape hatch, for the one shape refusing genuinely forbids: an input whose PATH is
    not knowable until something already-open has been read — a config that names its own data
    file. With it on, the pre-A-16 behaviour returns exactly, including `inputs_not_in_pin`,
    so the divergence is still in the record rather than only on the terminal."""
    monkeypatch.chdir(tmp_path)
    for name in ("a.tsv", "b.tsv"):
        (tmp_path / name).write_text("x\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl", allow_late_inputs=True)
    capsys.readouterr()
    with runprov.Run("s", provenance="p.json") as run:
        run.input("a.tsv")
        with run.open_output("out.tsv") as fh:
            fh.write("x\n")
        run.input("b.tsv")

    record = json.loads((tmp_path / "p.json").read_text(encoding="utf-8"))
    assert record["status"] == "ok"
    assert record["inputs_not_in_pin"] == ["b.tsv"]
    assert "refused_late_inputs" not in record
    assert "PROVENANCE WARNING" in capsys.readouterr().err


def test_the_project_type_check_covers_every_bool_and_int_field(tmp_path):
    """A-16 brought a new `Project` field, and the check that refuses `hash_imported_code='no'`
    was a hand-written tuple of six `(name, kind)` pairs — the shape that stops covering what
    it names the moment a field is added, which this audit found five separate times in checks
    elsewhere. It is derived from the annotations now.

    ASSERTED HERE RATHER THAN AT RUNTIME: a sweep matching nothing would validate nothing and
    look identical from inside, but an `assert` in shipped code is removed by `-O`, which is
    the one condition it would be needed in."""
    fields = {f.name: f.type for f in dataclasses.fields(runprov.Project)}
    simple = sorted(n for n, kind in fields.items() if kind in ("bool", "int"))
    assert len(simple) >= 7, f"only {simple} are checkable; the annotation sweep broke"

    for name in simple:
        with pytest.raises(TypeError, match=name):
            runprov.Project(root=tmp_path, **{name: "no"})


def _late_input_artifact(tmp_path, *, allow):
    """One artifact, produced with or without `allow_late_inputs`."""
    for name in ("a.tsv", "b.tsv"):
        (tmp_path / name).write_text("x\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl", allow_late_inputs=allow)
    with runprov.Run("s", provenance="p.json") as run:
        run.input("a.tsv")
        with run.open_output("out.tsv") as fh:
            fh.write("x\n")
        if allow:
            run.input("b.tsv")
    return tmp_path / "out.tsv"


def test_a_pin_that_may_understate_the_run_says_so_in_its_own_bytes(tmp_path, monkeypatch, capsys):
    """A-16's last limit, and it was closed by asking the question at the right MOMENT rather
    than by finding a cleverer place to write.

    I first judged this unfixable: appending a supplementary pin block at close works below
    64 KiB and silently not above it, and a check that works by file size is the failure mode
    this package refuses. That was the wrong end of the problem. The pin is rendered BEFORE
    the artifact is written, and `allow_late_inputs` is known then — so the disclosure goes
    into the first bytes, where every reader already looks, with no size cliff and nothing
    appended to anyone's data.

    THE PERSON THIS REACHES holds ONLY the artifact: no history, no sidecar, no marker. Until
    now `verify` told them OK for ever and there was nothing else to consult."""
    monkeypatch.chdir(tmp_path)
    art = _late_input_artifact(tmp_path, allow=True)

    assert "pin_covers" in art.read_text(encoding="utf-8"), "the disclosure is in the bytes"
    # AND IT IS INSIDE THE PIN BLOCK, not merely somewhere in the file — a reader that cannot
    # parse it is a comment, not a disclosure.
    assert runprov.verify.read_pins(art)[0]["fields"]["pin_covers"]

    capsys.readouterr()
    assert cli.main(["verify", str(art), "--root", str(tmp_path)]) == 0, "nothing is stale"
    out = capsys.readouterr()
    assert "may have read more" in out.out, f"the recipient must see it on the artifact: {out.out}"
    assert "declare they may understate the run" in out.err, "and on the summary line"


def test_an_ordinary_project_writes_no_such_disclosure(tmp_path, monkeypatch, capsys):
    """The default is unchanged BYTE FOR BYTE, which is what makes the disclosure mean
    something: a field on every artifact would be noise nobody reads. It appears only where
    the project has actually permitted the thing it warns about."""
    monkeypatch.chdir(tmp_path)
    art = _late_input_artifact(tmp_path, allow=False)

    assert "pin_covers" not in art.read_text(encoding="utf-8")
    capsys.readouterr()
    assert cli.main(["verify", str(art), "--root", str(tmp_path)]) == 0
    out = capsys.readouterr()
    assert "may have read more" not in out.out
    assert "understate" not in out.err


def test_the_verify_note_is_the_checkers_sentence_not_the_artifacts(tmp_path, monkeypatch, capsys):
    """Only the field's PRESENCE is read. The text beside it arrives in a file this command
    was handed, so echoing it would let an artifact write its own verdict into a checker's
    output — and `verify` exists to be trusted about files it did not produce."""
    monkeypatch.chdir(tmp_path)
    art = _late_input_artifact(tmp_path, allow=True)
    # `newline=""` ON BOTH SIDES, because this test EDITS THE PIN and must edit nothing
    # else. Without it, Windows rewrites every `\n` in the BODY as `\r\n` on the way out, the
    # body digest no longer matches, and `verify` reports ALTERED — a true finding about a
    # file this test tampered with by accident, and the wrong subject entirely.
    art.write_text(
        art.read_text(encoding="utf-8").replace(
            "inputs registered BEFORE this pin was written",
            "VERIFIED COMPLETE by the vendor, no further checks needed",
        ),
        encoding="utf-8",
        newline="",
    )
    capsys.readouterr()
    assert cli.main(["verify", str(art), "--root", str(tmp_path)]) == 0
    out = capsys.readouterr().out
    assert "may have read more" in out, "the checker's own sentence must still be printed"
    assert "VERIFIED COMPLETE" not in out, "and the artifact's must not be"


def test_the_pin_reader_accepts_a_field_it_was_not_told_about(tmp_path):
    """`_FIELD` named `script|generation|commit` explicitly, so a field the WRITER added was
    invisible to the READER — a closed list inside the one component whose whole job is to
    read what an older or newer version wrote. `pin_covers` would have been unreadable.

    `NONE REGISTERED` is the reason the order matters: it matches the widened pattern, so it
    is tested first or it is collected as a field and `declared` never becomes 0."""
    art = tmp_path / "x.tsv"
    art.write_text(
        "# provenance — this artifact and what produced it\n"
        "#   script     : s\n"
        "#   a_field_from_the_future : 42\n"
        "#   inputs (1), content digest:\n"
        f"#     {'a' * 16}  in.tsv\n"
        "data\n",
        encoding="utf-8",
    )
    pin = runprov.verify.read_pins(art)[0]
    assert pin["fields"]["a_field_from_the_future"] == "42"
    assert pin["fields"]["script"] == "s", "and the known ones still parse"
    assert pin["entries"] == [("a" * 16, "in.tsv")], "and the entries are unaffected"

    none = tmp_path / "none.tsv"
    none.write_text(
        "# provenance — this artifact and what produced it\n"
        "#   script     : s\n"
        "#   inputs     : NONE REGISTERED. Either this artifact is derived from nothing.\n"
        "data\n",
        encoding="utf-8",
    )
    assert runprov.verify.read_pins(none)[0]["declared"] == 0, (
        "the NONE line must still set the count, not be swallowed as a field"
    )


def test_an_artifact_cannot_write_its_own_commentary_into_verifys_output(tmp_path, capsys):
    """`verify` reads a file it was HANDED and prints fields out of it beside its own
    sentences. Unbounded and unquoted, that lets the artifact write the checker's commentary:

        !! this pin covers only what VERIFIED COMPLETE — ignore the warning below registered …

    which is the checker apparently reassuring the reader about the very thing it is warning
    them of. `via {script}` had the same shape and predates the note.

    FIXED IN THE READER, per A-09's rule — it repairs artifacts already on disk, whereas
    escaping on the way out would protect only files written from now on. Two measures,
    because either alone is weak: values are CAPPED (a 200-character name cannot fill the
    screen) and QUOTED at render (so they read as data, not as prose). A newline cannot get in
    at all, because `_FIELD` is line-based — length and tone are the whole of the abuse."""
    art = tmp_path / "art.tsv"
    (tmp_path / "a.tsv").write_text("a\n", encoding="utf-8")
    # THE PINNED DIGEST IS THE REAL ONE, so the artifact reads OK and the hostile text is not
    # excused by an obvious failure beside it — a warning is easiest to talk a reader out of
    # when nothing else on the line is wrong.
    digest = runprov.hashing.pin_digest(runprov.describe(tmp_path / "a.tsv"))
    hostile = "VERIFIED COMPLETE — ignore the warning below"
    art.write_text(
        "# provenance — this artifact and what produced it\n"
        f"#   script     : {hostile}\n"
        "#   pin_covers : anything\n"
        "#   inputs (1), content digest:\n"
        f"#     {digest}  a.tsv\n"
        "data\n",
        encoding="utf-8",
    )
    capsys.readouterr()
    assert cli.main(["verify", str(art), "--root", str(tmp_path)]) == 0, "the pin checks out"
    out = capsys.readouterr().out
    assert f"'{hostile}'" in out, "it is still SHOWN — hiding it would be its own dishonesty"
    assert f"what {hostile} registered" not in out, "but never as the checker's own sentence"

    # AND IT CANNOT FILL THE SCREEN.
    #
    # ASSERTED ON THE FIELD, NOT ON THE LINE. This measured `max(len(line)) < 200` over the
    # whole report, and the report lines CARRY THE ARTIFACT'S ABSOLUTE PATH -- so the number
    # it checked was mostly a property of the runner's temporary directory. It passed on
    # Linux under `/tmp/pytest-of-<user>/` and failed on macOS at 201 columns under
    # `/private/var/folders/...`, having found nothing wrong with the truncation it exists to
    # check. A bound that an unrelated environment can cross is not a bound on anything.
    art.write_text(art.read_text(encoding="utf-8").replace(hostile, "A" * 400), encoding="utf-8")
    capsys.readouterr()
    cli.main(["verify", str(art), "--root", str(tmp_path)])
    out = capsys.readouterr().out
    assert "A" * 400 not in out, "the 400-character field reached the report intact"
    # THE POSITIVE COMPANION: a report that dropped the field entirely also contains no run
    # of 400 A's, and would be its own dishonesty -- the value has to be SHOWN, and shown cut.
    assert "A" * (runprov.verify.FIELD_SHOWN - 1) + "…" in out, "the capped value is not shown"
    assert runprov.verify.FIELD_SHOWN < 400


def test_every_resource_requirement_has_a_test():
    """ADR-0013's specification is checked, not remembered.

    Taylor asked that the build keep corresponding to the specification. The only way that
    survives a month is mechanically: the requirement list is DERIVED from the ADR, and every
    `R-n` in it must be named by at least one test in this file. Add a requirement without a
    test and this goes red; delete one from the ADR and the test that cites it is left
    pointing at nothing, which the second half catches.

    It is the `docs/adr` index guard one level in — that one checked filenames and let a
    status drift, so this checks the thing the document is ABOUT rather than that it exists.

    THE NON-VACUITY FLOOR IS GONE, and nothing replaced the number (Audit G, G-11). It read
    `len(required) >= 15` against an ADR that has since grown to 16, so it carried a
    requirement of slack and would carry one more with every requirement added. A floor is a
    hand-written scope, and a hand-written scope is where this codebase keeps finding the
    defect; `== 16` only moves the trap, because the obvious edit when R-17 turns it red is to
    bump the number. `required == cited` needs no number at all: the two directions it folds
    together were already asserted separately here, so this loses no detection — and the
    floor was never what caught a deletion.
    """
    adr = _repo_root() / "docs" / "adr" / "0013-what-a-run-consumed-measured-not-declared.md"
    if not adr.is_file():  # pragma: no cover - docs ship in the sdist, a bare tree may not
        pytest.skip("ADR-0013 not present")
    required = set(re.findall(r"^\*\*(R-\d+[a-z]?)\.\*\*", adr.read_text(encoding="utf-8"), re.M))
    tests = pathlib.Path(__file__).read_text(encoding="utf-8")
    # Cited from a test's own text, not from this file as a whole: the ADR itself is not
    # allowed to satisfy the requirement by mentioning its own number.
    # BRACKETED, and the first version was not. A bare `R-4` matched `R-4.4` in an unrelated
    # test about filename sorting, which silently satisfied a requirement that had no test —
    # a guard with a false positive, which is worse than no guard because it reports green.
    cited = set(
        re.findall(
            r"\[ADR-0013 (R-\d+[a-z]?)\]",
            tests.split("def test_every_resource_requirement")[0],
        )
    )
    assert required == cited, (
        "ADR-0013 and its tests disagree. Requirements the ADR states that no test names: "
        f"{sorted(required - cited, key=lambda s: (len(s), s))}. Requirements the tests cite "
        f"that the ADR no longer states: {sorted(cited - required, key=lambda s: (len(s), s))}"
    )


def test_every_adr_is_listed_in_the_adr_index():
    """`docs/adr/README.md` is an INDEX, and its three relative links are the only route to
    the decisions this project has recorded. A fourth ADR added without a row is a decision
    nobody can find from the place that exists to find them.

    Derived from the directory, because the index and `ci.py`'s tarball check were BOTH
    hand-typed lists of the same three filenames, and adding ADR-0004 would have gone
    unnoticed by both. `ci.py` now reads the directory too."""
    adrs = sorted((_repo_root() / "docs" / "adr").glob("[0-9]*.md"))
    if not adrs:  # pragma: no cover - docs/ is present in the sdist, but a bare tree may not
        pytest.skip("docs/adr not present")
    assert len(adrs) >= 4, f"the ADR sweep found {[f.name for f in adrs]}; the scope broke"

    index = (_repo_root() / "docs" / "adr" / "README.md").read_text(encoding="utf-8")
    missing = [f.name for f in adrs if f.name not in index]
    assert not missing, f"ADR(s) with no row in the index that exists to find them: {missing}"

    # AND THE INDEX NAMES NOTHING THAT IS GONE — a dead relative link is the other half, and
    # the row's own evidence for A-24 was an index whose three links could dead-end.
    linked = set(re.findall(r"\]\((\d{4}-[\w-]+\.md)\)", index))
    assert linked, "the index has no links at all; the reader broke"
    assert not linked - {f.name for f in adrs}, f"the index links a missing file: {linked}"

    # AND THE STATUS COLUMN SAYS WHAT THE ADR SAYS. The check above covers the FILENAME and
    # stopped there, so the index could — and did — carry a status the decision had moved on
    # from: ADR-0010 was listed as Proposed for a day after it was accepted and shipped. An
    # index that is wrong about the thing it summarises is worse than no index, because it is
    # the version a reader trusts without opening the file. The scope pattern, in the guard
    # written to keep this directory honest.
    declared = re.compile(r"Status[:*\s]*([A-Za-z]+)", re.I)
    listed = dict(
        re.findall(r"\]\((\d{4}-[\w-]+\.md)\)\s*\|[^|]*\|\s*\**([A-Za-z]+)\**\s*\|", index)
    )
    for f in adrs:
        m = declared.search(f.read_text(encoding="utf-8"))
        assert m, f"{f.name} declares no Status, so the index cannot be checked against it"
        assert listed.get(f.name, "").lower() == m.group(1).lower(), (
            f"{f.name} says {m.group(1)!r}; the index says {listed.get(f.name)!r}"
        )

    # AND A DECISION THAT HAS SHIPPED IS NOT STILL "PROPOSED". The check above compares the
    # index with the ADR, so when BOTH were wrong it passed: ADR-0013 said proposed for a day
    # after `resources.py` shipped implementing it. It checked the documents against each
    # other and neither against reality.
    #
    # The link already exists in the code and needed no new convention: a module's DOCSTRING
    # names the decision it implements — `resources.py` opens "ADR-0013, T-29". Citing an ADR
    # from the module that implements it is a claim that the ADR is built, so that ADR cannot
    # still be proposing it. Read from the docstring rather than the whole file, so a passing
    # mention of a rejected or future decision in a mid-file comment is not an implementation.
    status_of = {}
    for f in adrs:
        m = declared.search(f.read_text(encoding="utf-8"))
        status_of[f.name[:4]] = m.group(1).lower() if m else "?"

    shipped = {}
    for module in sorted((_repo_root() / "runprov").glob("*.py")):
        doc = ast.get_docstring(ast.parse(module.read_text(encoding="utf-8"))) or ""
        for number in set(re.findall(r"ADR-(\d{4})", doc)):
            shipped.setdefault(number, []).append(module.name)
    assert shipped, "no module cites an ADR; the sweep that links code to decisions broke"

    still_proposed = {n: m for n, m in shipped.items() if status_of.get(n) == "proposed"}
    assert not still_proposed, (
        f"ADR(s) implemented in code but still marked proposed: {still_proposed}"
    )

    # AND NO ADR SAYS ITS FEATURE IS *NOT YET RELEASED* ONCE THE CHANGELOG IS DATED [K-27]. Every
    # check above reads ONE WORD of the status line — `Status[:*\s]*([A-Za-z]+)` — so the rest of
    # it was never read by anything, and ADR-0018's says `Accepted … **not yet released**` with
    # nothing in "Cutting a release, in order" to update it. `docs/adr/` ships in the sdist, so
    # that sentence would be permanent in the release that shipped the feature — which is
    # ADR-0017's 0.7.0 miss on the other half of the same line.
    #
    # THE TRIGGER IS THE HEADING `build` ALREADY READS, so no new convention is needed and the
    # fresh-`[Unreleased]` trap does not bite: CONTRIBUTING step 2 says in bold not to open one
    # yet, so on the tag commit the first heading IS `[<version>] — <day>` and this fires exactly
    # then.
    #: THE SIBLING'S OWN REACH, AND IT IS ONE REGEX [L-12, L-18]. This scan read
    #: `**Status:**` strictly and saw **8 of 21 ADRs** — while `declared` thirty lines above,
    #: which REQUIRES every ADR to have a status, is loose and case-insensitive and reads all
    #: 21. Two instruments for one line, one directory over from K-37. The 13 it could not see
    #: are ADR-0003 … ADR-0015, which use the inline house style
    #: `Date: … · Status: accepted · Ledger: …`, and five spellings the loose check accepts made
    #: this one fail OPEN in silence — including a status with no trailing blank line, which
    #: `\Z` is why the alternation is here.
    #:
    #: L-12's BOUNDING CLAIM WAS WRONG and is recorded rather than repeated: it said the next
    #: ADRs to be built are in the invisible set. 0019, 0020 and 0021 all use the COVERED
    #: spelling, and the 13 invisible are all shipped decisions none of which will need a
    #: release-state status cleared again — so the live exposure is only a NEW ADR written in
    #: the old house style, which is why the severity is low and the fix is still one line.
    #:
    #: NO ADR IS REFORMATTED, which is the half that makes this cheap: the regex moves, the
    #: documents do not. The shared exposure is stated: like its sibling, this anchors on the
    #: first `Status` in the file, and both would read an earlier prose "status" if one appeared
    #: above the line. Measured on all 21 today, every match lands on the real status line.
    def _status_block(text: str) -> str | None:
        found = re.search(r"Status[:*\s]*(.*?)(?:\n[ \t]*\n|\Z)", text, re.S | re.I)
        return found.group(1) if found else None

    def _unreleased_statuses(heading: str, texts: dict[str, str]) -> list[str]:
        if heading == "Unreleased":
            return []
        said = {}
        for filename, text in texts.items():
            block = _status_block(text)
            if block and "not yet released" in block.lower():
                said[filename] = block.strip()[:120]
        return sorted(said)

    changelog = (_repo_root() / "CHANGELOG.md").read_text(encoding="utf-8")
    heading = re.search(r"^## \[([^\]]+)\]", changelog, re.M)
    assert heading, "CHANGELOG.md carries no version heading, so this check reads nothing"
    texts = {f.name: f.read_text(encoding="utf-8") for f in adrs}
    assert not _unreleased_statuses(heading.group(1), texts), (
        "[K-27] the CHANGELOG's first heading is dated, so this tree is a release — and these "
        "ADR statuses still say their feature is *not yet released*. `docs/adr/` ships in the "
        "sdist, so the sentence is permanent in that release. CONTRIBUTING step 2 is where this "
        f"is cleared, in the same commit that dates the heading: "
        f"{_unreleased_statuses(heading.group(1), texts)}"
    )
    # POSITIVE CONTROL, THROUGH THE SAME FUNCTION, AND ON A SYNTHETIC ADR. Today's first heading
    # is `[Unreleased]`, so the clause above returns early and its silence would mean nothing —
    # and a control built on the REAL ADRs would start failing on the day step 2 does its job,
    # which is the one day this guard must survive.
    #: AND THE SCAN'S OWN SCOPE IS ASSERTED [L-18]: the set of ADRs it can read a status from
    #: must be ALL of them. As L-18 filed it this was a lone assertion and it is `8 != 21` —
    #: **red on day one** — which is why it lands in the same edit as the regex above and not
    #: before it. With the sibling's reach it is 21/21, and it is what makes the control below
    #: mean something: a positive control says *the scan can see A SUBJECT*, and this says *it
    #: can see EVERY subject*.
    unreadable = sorted(name for name, text in texts.items() if _status_block(text) is None)
    assert not unreadable, (
        f"[L-18] the release-state scan cannot read a status from {unreadable}, so it fails OPEN "
        f"on them — an ADR whose status it cannot parse is one whose *not yet released* sentence "
        f"would ship permanently in the sdist with this guard green"
    )

    # POSITIVE CONTROL, THROUGH THE SAME FUNCTION, AND ON A SYNTHETIC ADR. Today's first heading
    # is `[Unreleased]`, so the clause above returns early and its silence would mean nothing —
    # and a control built on the REAL ADRs would start failing on the day step 2 does its job,
    # which is the one day this guard must survive.
    #
    # TWO SPELLINGS, AND THE SECOND ONE IS THE POINT [L-18]. The original control was a single
    # synthetic file in the ONE spelling the strict scan already handled, so its green said
    # nothing whatever about coverage of the real subject — a control in the covered spelling is
    # a tautology. The second is this repository's own inline house style, the one 13 shipped
    # ADRs use and the one the strict scan was blind to.
    probe = {
        "0099-probe.md": "# 99. p\n\n**Status:** Accepted — built, **not yet released**.\n\n",
        "0098-inline.md": "# 98. p\n\nDate: 2026-10-04 · Status: accepted, **not yet released**",
    }
    assert _unreleased_statuses("0.9.9", probe) == ["0098-inline.md", "0099-probe.md"], (
        "the release-state scan cannot see its own subject in both spellings, so its silence "
        "proves nothing — and the inline one is the spelling 13 real ADRs are written in"
    )
    assert _unreleased_statuses("Unreleased", probe) == [], (
        "and it must say nothing while the CHANGELOG is still open, or no release could be cut"
    )


def _orphan_marker(tmp_path, **extra):
    """A marker beside a history file that does not exist — what a killed run leaves."""
    d = tmp_path / ".incomplete"
    d.mkdir(parents=True, exist_ok=True)
    (d / "killed.json").write_text(
        json.dumps(
            {
                "run_uid": "killed",
                "script": "ingest",
                "started_utc": "2026-09-01T08:00:00Z",
                "pid": _never_a_pid(),
                "host": runprov.show.platform.node(),
                **extra,
            }
        ),
        encoding="utf-8",
    )
    return tmp_path / "runs.jsonl"


def test_no_run_history_says_where_the_records_went_when_a_marker_knows(tmp_path, capsys):
    """A-26's remaining half. Beside a missing history, this branch printed two things that
    are FALSE for a project with a custom `sink=`: "nothing has been recorded here yet", when
    a great deal was recorded — into a database — and "pass --log that path", when a sink has
    no path to pass. The operator was sent looking for a file that will never exist, by the
    command holding the answer: every marker carries the `history_destination()` of the run
    that wrote it, and beside a missing history that is the one piece of evidence in the room.

    NAMED, NOT INTERPRETED. Whether the destination is a file to pass to `--log` or a sink
    with nothing to read is a distinction the reader can make from the string and this command
    cannot make safely — `JsonlSink(/x/y.jsonl)` and a bare `DbSink` are both possible, and
    guessing wrong sends them looking a second time."""
    log = _orphan_marker(tmp_path, history="DbSink")
    capsys.readouterr()
    assert cli.main(["show", "--log", str(log)]) == cli.CANNOT_CHECK, "could not check"
    err = capsys.readouterr().err

    assert "DbSink" in err, "the command knew where the records went and did not say"
    assert "Nothing has been recorded here yet" not in err, "false for a sink project"
    assert "pass --log that path" not in err, "there is no path to pass"


def test_no_run_history_keeps_its_ordinary_advice_when_no_marker_knows_better(tmp_path, capsys):
    """The other branch, and the reason the new one is conditional: for an ordinary project
    the `--log` advice is right and is the likeliest cause — a `configure(run_log=...)` the
    CLI cannot see. Replacing it unconditionally would trade one wrong message for another."""
    capsys.readouterr()
    assert cli.main(["show", "--log", str(tmp_path / "nowhere.jsonl")]) == cli.CANNOT_CHECK
    err = capsys.readouterr().err
    assert "Nothing has been recorded here yet" in err
    assert "pass --log that path" in err
    assert "SAYS OTHERWISE" not in err


def test_a_marker_naming_the_path_already_being_read_is_not_a_contradiction(tmp_path, capsys):
    """The ordinary killed-first-run case: the marker names THIS history, which simply does
    not exist yet. Reporting that as "a marker says otherwise" would manufacture a
    disagreement out of two records that agree."""
    log = _orphan_marker(tmp_path, history=str(tmp_path / "runs.jsonl"))
    capsys.readouterr()
    assert cli.main(["show", "--log", str(log)]) == cli.CANNOT_CHECK
    err = capsys.readouterr().err
    assert "SAYS OTHERWISE" not in err, f"the marker agrees with the path being read: {err}"
    assert "Nothing has been recorded here yet" in err


def test_the_three_exit_codes_mean_one_thing_each(tmp_path, monkeypatch, capsys):
    """at_log-81, decided by Taylor 2026-09-01. Exit `1` meant four different things across the
    subcommands — "no match", "stale artifacts", "nothing was checked" and "no history file" —
    so a CI job could not tell **your artifacts are stale** from **I could not look**. Both a
    green gate over nothing and a red one are worse than no gate, and exit codes are the CLI's
    real API for automation: they cannot be changed in 1.x without breaking pipelines.

        0  checked, nothing wrong
        1  checked, something IS wrong
        2  could not check, or the invocation did not describe one

    grep's and diff's convention, so it costs a reader nothing to learn.

    ONE TEST FOR THE WHOLE CONTRACT, not a line in each command's own test, because the defect
    was never in one command — it was that the commands disagreed. A table is the only shape
    that can fail for that."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "data").mkdir()
    (tmp_path / "data" / "in.tsv").write_text("a\n", encoding="utf-8")
    log = tmp_path / "runs.jsonl"
    runprov.configure(root=tmp_path, run_log=log)
    with runprov.Run("build", provenance="b.prov.json") as run:
        run.input("data/in.tsv")
        with run.open_output("out.tsv") as fh:
            fh.write("x\n")

    at_log = ["--log", str(log)]
    checked_clean = [
        ["log", *at_log],
        ["log", *at_log, "--script", "build"],
        [
            "log",
            *at_log,
            "--script",
            "build",
            "--failed",
        ],  # a CLASS filter: empty is the good answer
        ["show", *at_log],
        ["show", *at_log, "--stale", "--exit-code"],
        ["verify", str(tmp_path / "out.tsv"), "--root", str(tmp_path)],
    ]
    could_not_check = [
        ["log", "--log", str(tmp_path / "gone.jsonl")],
        ["show", "--log", str(tmp_path / "gone.jsonl")],
        ["verify", str(tmp_path / "data"), "--root", str(tmp_path)],  # nothing carries a pin
        ["show", *at_log, "--exit-code"],  # nothing to gate on
        ["prune", *at_log, "--older-than", "soon"],
    ]
    for argv in checked_clean:
        capsys.readouterr()
        assert cli.main(argv) == 0, f"{argv} is a clean check and must exit 0"
    for argv in could_not_check:
        capsys.readouterr()
        assert cli.main(argv) == cli.CANNOT_CHECK, f"{argv} could not check and must exit 2"

    # AND NOW SOMETHING IS ACTUALLY WRONG.
    (tmp_path / "data" / "in.tsv").write_text("CHANGED\n", encoding="utf-8")
    wrong = [
        ["verify", str(tmp_path / "out.tsv"), "--root", str(tmp_path)],
        ["show", *at_log, "--stale", "--exit-code"],
        ["show", *at_log, "nosuchtarget"],
        ["log", *at_log, "--script", "buidl"],  # a NAME that matched nothing: probably a typo
        ["log", *at_log, "--run-id", "nosuchid"],
    ]
    for argv in wrong:
        capsys.readouterr()
        assert cli.main(argv) == 1, f"{argv} found something wrong and must exit 1"

    # THE THREE CODES ARE DISTINCT, asserted so a future "simplification" that collapses two
    # of them fails here rather than in somebody's pipeline.
    assert len({0, 1, cli.CANNOT_CHECK}) == 3


def test_a_class_filter_matching_nothing_is_not_a_missing_name(tmp_path, monkeypatch, capsys):
    """The distinction the contract rests on, and the one that is easy to get wrong: `--script`
    and `--run-id` NAME a record, so matching nothing means the name was wrong; `--failed`
    selects a CLASS, and "no failed runs" is the good answer rather than an absent one.

    The first version of this fix tested them together, so `--script build --failed` over a
    project whose `build` never failed reported "nothing matched 'build'" and exited 1 — false
    twice over: the name was right, and no failures is success."""
    monkeypatch.chdir(tmp_path)
    log = tmp_path / "runs.jsonl"
    runprov.configure(root=tmp_path, run_log=log)
    with runprov.Run("build", provenance="b.prov.json"):
        pass

    at_log = ["--log", str(log)]
    capsys.readouterr()
    assert cli.main(["log", *at_log, "--failed"]) == 0, "no failures is the good answer"
    assert cli.main(["log", *at_log, "--script", "build", "--failed"]) == 0, (
        "the name matched; the class filter then found nothing, which is success"
    )
    assert cli.main(["log", *at_log, "--script", "buidl", "--failed"]) == 1, (
        "but a wrong NAME is still a wrong name, whatever else was asked for"
    )
    assert "nothing matched" in capsys.readouterr().err

    # AN EMPTY HISTORY IS THE CASE THAT SEPARATES THEM. A project whose `runs.jsonl` exists
    # but holds no completed run — only start lines, or nothing yet — must still answer 0 to
    # `--failed`: there are no failures, which is the good answer. Treating `--failed` as a
    # NAME is indistinguishable everywhere else, and this is where it shows.
    empty = tmp_path / "empty.jsonl"
    empty.write_text("", encoding="utf-8")
    capsys.readouterr()
    assert cli.main(["log", "--log", str(empty), "--failed"]) == 0, (
        "no runs at all still means no FAILED runs, which is not a missing name"
    )


def test_the_commits_the_ci_section_names_are_real_and_in_this_history():
    """L-105. "What has actually been run" exists because every platform claim in this README
    once rested on "CI covers it", and CI had not run — and the FIRST version of that section
    was itself wrong, because `gh run list --limit 60` returned a window and it was reported
    as the whole history.

    So the section now names COMMITS rather than dates or counts-since. A count is stale the
    next time anyone pushes; a commit is a fact that can be checked, and this checks it: every
    sha the section cites must exist in this repository and be an ancestor of HEAD. A typo, a
    rebase, or a sha copied from another project fails here.

    WHAT THIS CANNOT CHECK, stated rather than implied: whether those runs were green, and how
    many runs there have been. Both live on GitHub, and a test that needed the network would
    be skipped in exactly the environments this section exists to be honest about. The run
    tally carries an explicit "as of" date for that reason."""
    if not (_repo_root() / ".git").exists():  # pragma: no cover - not shipped in the sdist
        pytest.skip("not a git checkout")
    # A SHALLOW CLONE CANNOT ANSWER THIS, and saying so is better than failing as though the
    # shas were wrong. `actions/checkout` clones at depth 1 by default, so this test passed on
    # every developer machine and FAILED IN CI on all four interpreters — found by dispatching
    # the self-hosted runner, not by reading. The workflows now set `fetch-depth: 0`, and
    # `test_every_checkout_that_runs_the_suite_fetches_the_full_history` keeps them that way,
    # so this skip is for a human's `--depth 1` clone rather than a hole in CI.
    shallow = subprocess.run(
        ["git", "rev-parse", "--is-shallow-repository"],
        cwd=_repo_root(),
        capture_output=True,
        text=True,
    )
    if shallow.stdout.strip() == "true":  # pragma: no cover - CI fetches the full history
        pytest.skip("shallow clone: the history needed to check these commits is not here")
    section = _readme().split("## What has actually been run", 1)[1].split("\n## ", 1)[0]
    # AT LEAST ONE HEX LETTER, because the section also cites a GitHub RUN ID — `31592997325`
    # — and a decimal run id is a valid hex string, so a naive sha pattern swallows it and
    # then reports that this repository has no such commit. A real all-digit sha is possible
    # and astronomically unlikely; a run id is neither.
    shas = sorted(set(re.findall(r"`([0-9a-f]{7,40})`", section)))
    shas = [s for s in shas if re.search(r"[a-f]", s)]
    assert len(shas) >= 2, f"the CI section names {shas}; it is supposed to cite commits"

    for sha in shas:
        found = subprocess.run(
            ["git", "cat-file", "-t", sha], cwd=_repo_root(), capture_output=True, text=True
        )
        assert found.stdout.strip() == "commit", f"{sha} is not a commit in this repository"
        ancestor = subprocess.run(
            ["git", "merge-base", "--is-ancestor", sha, "HEAD"], cwd=_repo_root()
        )
        assert ancestor.returncode == 0, f"{sha} is not an ancestor of HEAD"


def test_the_ci_section_claims_no_more_than_the_self_hosted_workflow_runs():
    """The other half of L-105, and the reason this section keeps going stale: it describes a
    thing that changes underneath it. `932a0f3` wired `lint` and `build` onto the self-hosted
    runner, which makes "the whole gate" true — and would have made it a lie if the wiring were
    ever undone.

    Derived from the workflow rather than trusted: whatever `ci.py` steps that file actually
    runs are what the README may claim for it."""
    wf = _repo_root() / ".github/workflows/selfhosted.yml"
    if not wf.is_file():  # pragma: no cover - workflows are not in the sdist
        pytest.skip("selfhosted.yml not present")
    section = _readme().split("## What has actually been run", 1)[1].split("\n## ", 1)[0]
    assert "self-hosted" in section, "the runner that answers for today's tree is unmentioned"

    runs = set(re.findall(r"ci\.py (\w+)", wf.read_text(encoding="utf-8")))
    claimed = set(re.findall(r"`ci\.py (\w+)`", section))
    assert claimed, "the section names no gate step for the self-hosted runner"
    assert claimed <= runs, f"the README claims {sorted(claimed - runs)}, which it does not run"

    # AND IT MUST NOT CLAIM THE TWO PLATFORMS THAT RUNNER CANNOT REACH.
    linux_only = section.split("self-hosted Linux runner", 1)[-1]
    for platform_ in ("macOS", "Windows"):
        assert platform_ not in linux_only, (
            f"the paragraph about the Linux runner mentions {platform_}, which it cannot run"
        )


def test_every_checkout_that_runs_the_suite_fetches_the_full_history():
    """`actions/checkout` clones at DEPTH 1 unless told otherwise, and the suite asks git
    questions: whether each commit the README's CI section cites is an ancestor of HEAD. A
    shallow clone cannot answer, so that check passed on every developer machine and failed in
    CI on all four interpreters — and it would have failed the hosted matrix too, the moment
    billing was fixed. Found by dispatching the runner rather than by reading the YAML.

    The suite is allowed to SKIP that check in a shallow clone, which is why this test has to
    exist: without it, dropping `fetch-depth` would silently turn a green CI leg into one that
    is no longer checking anything, and a check that goes quiet is the failure this repository
    keeps finding.

    Derived — every workflow that invokes `ci.py test` must deepen every checkout it has."""
    for wf in _workflow_files():
        doc = _yaml().safe_load(wf.read_text(encoding="utf-8")) or {}
        jobs = (doc.get("jobs") or {}).values()
        if not any("ci.py test" in str(j) for j in jobs):
            continue
        for job_name, job in (doc.get("jobs") or {}).items():
            for step in job.get("steps") or []:
                if "actions/checkout" not in str(step.get("uses", "")):
                    continue
                depth = (step.get("with") or {}).get("fetch-depth")
                assert depth == 0, (
                    f"{wf.name}:{job_name} checks out at depth {depth!r}; this workflow runs "
                    f"the suite, which asks git for history a shallow clone does not have"
                )


def _live_surface() -> list[str]:
    """The surface, from `ci.py` — the one definition that `ci.py surface` also writes from.

    Not recomputed here. A checker with its own copy of the generator agrees with itself and
    with nothing else, which is the defect this whole file keeps finding.
    """
    import ci

    return ci.public_surface()


def test_the_public_surface_matches_what_is_written_down():
    """Reported from downstream: an upgrade broke a project, and a survey of this history for
    `feat!` and `BREAKING` found nothing — because the three commits responsible were typed
    `refactor:`. Verified here against the history rather than taken on trust:

        25fd221  refactor  withdrew 5 names from the package __all__
        8a7452e  refactor  withdrew 5 more
        f9b5a74  refactor  renamed `Run.write_json` to `Run.output_json`

    **A CONVENTION THAT RECORDS INTENT CANNOT SEE A BREAKAGE THE AUTHOR DID NOT INTEND.** Each
    of those was deliberate and none was thought of as breaking, because each was framed as
    "this was never really promised" — true of the decision, and false for the person who was
    importing the name. `__all__` discipline decides what the project *means* to promise; it
    cannot decide what somebody already depends on.

    So this test does not check intent, and it does not check the commit message. It checks
    the SURFACE, against a file. Removing or renaming anything forces an edit to
    `docs/public-surface.txt`, which appears in the diff — and that is the moment to type the
    commit `feat!` and write the removal in the CHANGELOG.

    IT COVERS MORE THAN `__all__`, because `__all__` is where the reported breakage was NOT:
    a promised class carries its public methods, properties and dataclass fields, and
    `Project` is configured entirely through fields."""
    recorded = _repo_root() / "docs" / "public-surface.txt"
    if not recorded.is_file():  # pragma: no cover - docs/ ships, but a bare tree may not
        pytest.skip("docs/public-surface.txt not present")
    want = [
        ln
        for ln in recorded.read_text(encoding="utf-8").splitlines()
        if ln.strip() and not ln.startswith("#")
    ]
    have = _live_surface()
    assert len(want) > 20, f"the recorded surface parsed to {len(want)} lines; the reader broke"

    gone = [ln for ln in want if ln not in have]
    new = [ln for ln in have if ln not in want]
    assert not gone, (
        f"THIS IS A BREAKING CHANGE. {gone} was promised and is not there any more. If that is "
        f"intended: remove those lines from docs/public-surface.txt, type the commit `feat!`, "
        f"and record it in the CHANGELOG so a downstream reader can find it."
    )
    assert not new, (
        f"{new} is public and not written down. Add it to docs/public-surface.txt — a promise "
        f"nobody recorded is one nobody can be held to, and one nobody knows they may rely on."
    )


def test_the_surface_file_can_be_regenerated_from_nothing(tmp_path, monkeypatch):
    """`ci.py surface` used to read the header back out of the file it was rewriting, so
    deleting that file made it raise `FileNotFoundError` — a regenerate command that cannot
    regenerate, taking the explanation with it. The header lives in `ci.py` now and the whole
    file is derived.

    Asserted by actually deleting it, because "it should work" is what the previous version
    also looked like."""
    import ci

    monkeypatch.setattr(ci, "SURFACE_FILE", tmp_path / "docs" / "public-surface.txt")
    ci.surface()

    written = (tmp_path / "docs" / "public-surface.txt").read_text(encoding="utf-8")
    assert written.startswith("# THE PUBLIC SURFACE"), "the explanation must come back too"
    body = [ln for ln in written.splitlines() if ln.strip() and not ln.startswith("#")]
    assert body == ci.public_surface(), "and the body must be the surface, not a stale copy"


def test_a_promised_static_or_class_method_is_part_of_the_surface():
    """`vars()` hands back the DESCRIPTOR, and `inspect.isfunction` is False for both
    `staticmethod` and `classmethod` — so a promised `@staticmethod` would have been invisible
    to a check whose entire job is not to miss things. None exists on a promised class today,
    which is exactly why the hole would have opened silently the first time one did."""
    import ci

    class Promised:
        @staticmethod
        def a_static() -> None: ...

        @classmethod
        def a_class(cls) -> None: ...

        @property
        def a_prop(self) -> None: ...

        def a_method(self) -> None: ...

    monkeypatch = pytest.MonkeyPatch()
    try:
        monkeypatch.setattr(runprov, "__all__", ["Promised"], raising=False)
        monkeypatch.setattr(runprov, "Promised", Promised, raising=False)
        got = ci.public_surface()
    finally:
        monkeypatch.undo()
    assert got == [
        "Promised  [class]",
        "Promised.a_class",
        "Promised.a_method",
        "Promised.a_prop",
        "Promised.a_static",
    ], got


# ------------------------------------------- a record is written whole or not at all (ADR-0005)


def test_a_write_that_fails_leaves_the_previous_record_untouched(tmp_path, monkeypatch):
    """THE WHOLE POINT. `write_text` truncates and then fills, so a crash in between costs
    the record that WAS there — not only the one being written. Nothing recovers that.

    Simulated at the one instant where it matters: after the temporary file exists and
    before the rename. A test that made the OPEN fail would pass against the old
    implementation too, and prove nothing about this one."""
    p = tmp_path / "s.prov.json"
    p.write_text('{"status": "the record that was already here"}\n', encoding="utf-8")
    before = p.read_bytes()

    def die(*a, **k):
        raise OSError("the machine stopped")

    monkeypatch.setattr(runprov._atomic.os, "replace", die)
    with pytest.raises(OSError, match="the machine stopped"):
        runprov._atomic.atomic_write_text(p, "the new one, never finished")
    assert p.read_bytes() == before, "the crash took the new record, not the old one"


def test_a_write_that_fails_leaves_no_debris_behind(tmp_path, monkeypatch):
    """A temporary file that outlives its write is a file every reader then has to be
    taught to ignore. Cleaned up on the way out, including for `KeyboardInterrupt` — which
    is not an `OSError` and would otherwise walk straight past an `except OSError`."""
    p = tmp_path / "s.prov.json"

    def interrupt(*a, **k):
        raise KeyboardInterrupt

    monkeypatch.setattr(runprov._atomic.os, "replace", interrupt)
    with pytest.raises(KeyboardInterrupt):
        runprov._atomic.atomic_write_text(p, "x")
    assert sorted(q.name for q in tmp_path.iterdir()) == [], "the temporary file was left"


def test_a_completed_write_leaves_no_debris_either(tmp_path):
    """The ordinary path. Named separately because "no debris after a failure" passes on an
    implementation that leaks one on every SUCCESS, and that is the common case."""
    p = tmp_path / "s.prov.json"
    runprov._atomic.atomic_write_text(p, "whole\n")
    assert p.read_text(encoding="utf-8") == "whole\n"
    assert [q.name for q in tmp_path.iterdir()] == ["s.prov.json"]


@requires_real_file_modes
def test_the_replacement_keeps_the_permissions_the_record_already_had(tmp_path):
    """A rename brings the temporary file's mode with it, so a record somebody had
    restricted would quietly re-open on the next run. `write_text` truncated in place and
    kept them, and that behaviour has to survive the change to how it is written."""
    p = tmp_path / "s.prov.json"
    p.write_text("first\n", encoding="utf-8")
    p.chmod(0o600)
    runprov._atomic.atomic_write_text(p, "second\n")
    assert p.stat().st_mode & 0o777 == 0o600, oct(p.stat().st_mode)


@requires_real_file_modes
def test_the_temporary_file_IS_NARROW_WHILE_IT_HOLDS_THE_RECORD(tmp_path, monkeypatch):
    """The mode after the call is not the question. The question is the mode DURING it.

    The test above checks `p.stat()` once the write has returned, and it passed on an
    implementation that created the temporary file at `0o666 & ~umask` — world- or
    group-readable — filled it with the complete record, `fsync`ed it, and only THEN
    narrowed it. Measured under umask 0002 against a `0o600` destination: at fsync time the
    temporary file was 0o664 and already held every byte. `fsync` is not a fast call, and
    the file it is syncing sits in the results directory under a predictable name.

    `write_text` truncated the destination in place and never widened the mode for any
    instant, so this was a REGRESSION introduced by ADR-0005 against the guarantee stated in
    the comment three lines above the chmod that was meant to provide it.

    THE SPY IS ON `fsync` BECAUSE THAT IS THE MOMENT: the content is complete (it was just
    flushed) and the rename has not happened, so the file is at its most exposed and its
    most interesting. Anything sampled after the call cannot see the window at all."""
    p = tmp_path / "s.prov.json"
    p.write_text("first\n", encoding="utf-8")
    p.chmod(0o600)
    record = "SECRET RECORD v2\n"
    real_fsync = runprov._atomic.os.fsync
    seen: list[tuple[int, int]] = []

    def spy(fd):
        for q in tmp_path.iterdir():
            if q.name != p.name:
                seen.append((q.stat().st_mode & 0o777, q.stat().st_size))
        return real_fsync(fd)

    was = os.umask(0o002)
    try:
        monkeypatch.setattr(runprov._atomic.os, "fsync", spy)
        runprov._atomic.atomic_write_text(p, record)
    finally:
        os.umask(was)

    assert seen, "no temporary file existed at any fsync, so this observed nothing"
    mode, size = seen[0]
    assert size == len(record), (
        f"the sample was taken before the record was complete ({size} B), so a wide mode "
        f"here would not yet have exposed anything"
    )
    assert mode == 0o600, (
        f"the temporary file held the whole record at {oct(mode)} under a 0o600 destination"
    )
    assert p.stat().st_mode & 0o777 == 0o600, oct(p.stat().st_mode)


def test_a_destination_REMOVED_while_its_mode_is_read_does_not_lose_the_write(
    tmp_path, monkeypatch
):
    """A permission-preserving nicety must not be able to destroy the record.

    The narrowing used to be `if dest.is_file(): os.chmod(tmp, dest.stat().st_mode & 0o7777)`
    — two questions to the filesystem about one file. A concurrent `unlink` landing between
    them raised `FileNotFoundError` from inside the helper, the `except BaseException`
    cleanup removed the temporary file, and NEITHER the old record nor the new one was left
    on disk. The identical removal one syscall later, between the `stat` and the
    `os.replace`, is harmless — `os.replace` does not care whether the destination is there.
    A window that loses a write depending on which of two adjacent syscalls it falls between
    is not a policy, so the mode lookup now answers "I do not know" and the write goes on.

    The spy asserts it FIRED: a race nobody ran looks exactly like a race that was survived."""
    p = tmp_path / "s.prov.json"
    p.write_text("first\n", encoding="utf-8")
    real_stat = runprov._atomic.os.stat
    raced: list[object] = []

    def vanishing(target, *a, **k):
        # `follow_symlinks` TELLS THE TWO CALLERS APART. `runprov._atomic.os` is the `os`
        # module itself, so this patch is global, and `path.is_symlink()` at the top of the
        # helper reaches `os.stat(..., follow_symlinks=False)` on Python 3.12. Racing THAT
        # call proves nothing: `is_symlink` swallows the error, the real mode lookup then
        # succeeds, and the test passes on the unrepaired helper -- measured, which is how
        # this line came to be here.
        if pathlib.Path(target) == p and k.get("follow_symlinks", True) and not raced:
            raced.append(target)
            raise FileNotFoundError(errno.ENOENT, "No such file or directory")
        return real_stat(target, *a, **k)

    monkeypatch.setattr(runprov._atomic.os, "stat", vanishing)
    runprov._atomic.atomic_write_text(p, "second\n")
    monkeypatch.undo()

    assert raced, "the destination's mode was never read, so nothing was raced"
    assert p.read_text(encoding="utf-8") == "second\n", "the write was lost to the race"
    assert [q.name for q in tmp_path.iterdir()] == ["s.prov.json"], "debris beside the target"


@requires_symlinks
def test_a_record_is_written_THROUGH_a_symlink_and_not_over_it(tmp_path):
    """`open(path, "w")` follows a symlink; `os.replace` would destroy it and leave a real
    file where the user had put a deliberate pointer. The record has to land where they
    aimed it."""
    real = tmp_path / "elsewhere" / "s.prov.json"
    real.parent.mkdir()
    real.write_text("first\n", encoding="utf-8")
    link = tmp_path / "s.prov.json"
    link.symlink_to(real)
    runprov._atomic.atomic_write_text(link, "second\n")
    assert link.is_symlink(), "the link was replaced by a file"
    assert real.read_text(encoding="utf-8") == "second\n"
    assert [q.name for q in real.parent.iterdir()] == ["s.prov.json"], "debris beside the target"


def test_a_directory_that_cannot_be_OPENED_does_not_fail_a_write_that_succeeded(
    tmp_path, monkeypatch
):
    """Windows cannot open a directory as a file at all — that is its ORDINARY path here, not
    an edge case — and it is no reason to raise over a record already on disk. The atomicity
    holds either way; only the rename's survival of a power cut is at stake."""
    p = tmp_path / "s.prov.json"
    real_open = runprov._atomic.os.open

    def no_dir_handle(path, *a, **k):
        if pathlib.Path(path).is_dir():
            raise OSError("cannot open a directory here")
        return real_open(path, *a, **k)

    monkeypatch.setattr(runprov._atomic.os, "open", no_dir_handle)
    runprov._atomic.atomic_write_text(p, "one\n")
    assert p.read_text(encoding="utf-8") == "one\n"


@requires_directory_handles
def test_a_directory_sync_that_is_REFUSED_does_not_fail_a_write_that_succeeded(
    tmp_path, monkeypatch
):
    """The other refusal, and a different line: the handle exists and the filesystem rejects
    the `fsync`, as some network filesystems do.

    ITS OWN TEST, and gated, because it needs a directory handle to drive and Windows never
    supplies one. Folded in with the case above, it asserted "the sync was attempted" on the
    one platform where it never can be — and failed there for the opposite of the reason it
    exists.
    """
    p = tmp_path / "s.prov.json"
    real_fsync = runprov._atomic.os.fsync
    seen = []

    def refuse_dir_sync(fd):
        if os.fstat(fd).st_mode & 0o170000 == 0o040000:
            seen.append(fd)
            raise OSError("fsync is not supported on this filesystem")
        return real_fsync(fd)

    monkeypatch.setattr(runprov._atomic.os, "fsync", refuse_dir_sync)
    runprov._atomic.atomic_write_text(p, "two\n")
    assert p.read_text(encoding="utf-8") == "two\n"
    assert seen, "the directory sync was never attempted, so its refusal proves nothing"


def test_every_provenance_write_in_the_package_goes_through_the_atomic_helper():
    """DERIVED, NOT LISTED. The six sites were found by measurement, and a hand-typed list of
    six filenames is the defect this repository has repaired eight times: it is right on the
    day it is written and silently stops covering the seventh site.

    PARSED, NOT GREPPED. The first version of this test read lines and matched
    `".write_text("`, and it fired on two DOCSTRINGS -- `__init__.py`'s worked example and a
    comment in `run.py` quoting it. A guard that cannot tell code from prose about code
    would have been switched off or narrowed by whoever met it next, which is how a check
    stops covering what it names.

    BOTH SPELLINGS, and the second one is a repair. This matched `write_text` alone, and
    `environment.archive_lockfiles` copied a lock file with `target.write_bytes(...)` — a
    seventh non-atomic site, sitting in front of a guard written precisely so there could
    not be a seventh. "Derived, not listed" was true of the FILES and false of the METHOD
    NAME: one hand-typed string inside the check was the whole of its scope.

    Each exemption carries its reason here, beside the name, because an exemption whose
    reason lives somewhere else is one nobody can re-examine."""
    exempt = {
        "sinks.py": (
            "appends under an exclusive lock with its own torn-line repair, and is already "
            "fsynced; rewriting a forever-growing history to add one line is the wrong shape"
        ),
        "_atomic.py": "is the helper",
    }
    torn = ("write_text", "write_bytes")

    # ONE MATCHER, CALLED TWICE — on the package and on the probe below. Two copies of it
    # is how the sibling `_posix` guard came to have a non-vacuity probe that agreed with a
    # matcher the real scan did not use, and passed while the real scan matched nothing.
    def offenders_in(source: str, name: str) -> dict[str, str]:
        found = {}
        for node in ast.walk(ast.parse(source, filename=name)):
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr in torn
            ):
                found[f"{name}:{node.lineno}"] = ast.unparse(node.func)
        return found

    offenders = {}
    for mod in sorted(pathlib.Path(runprov.__file__).parent.glob("*.py")):
        if mod.name in exempt:
            continue
        offenders |= offenders_in(mod.read_text(encoding="utf-8"), mod.name)
    assert not offenders, (
        f"these write a file the old way, which a crash tears in half: {offenders}. "
        f"Use `atomic_write_text` / `atomic_write_bytes` (ADR-0005), or add the file to "
        f"`exempt` WITH its reason."
    )
    # NON-VACUITY. Every module could stop containing a `write_text` call and this would
    # still pass -- "nothing found" and "nothing looked at" are the same green, and the
    # version of this test that read lines instead of parsing them would have gone quiet the
    # day someone wrapped a call across two of them. So make the scan find one it must find.
    #
    # ONE PER ARM, and the count is asserted rather than "is not empty": with `write_bytes`
    # dropped from `torn` a probe that only had to be non-empty would go on passing on the
    # strength of the `write_text` line, which is exactly how the seventh site got in.
    hits = offenders_in(
        "import pathlib\npathlib.Path('x').write_text('y')\npathlib.Path('x').write_bytes(b'y')\n",
        "<probe>",
    )
    assert hits == {
        "<probe>:2": "pathlib.Path('x').write_text",
        "<probe>:3": "pathlib.Path('x').write_bytes",
    }, f"the scan cannot see its own subject in both spellings: {hits}"
    # AND A STALE EXEMPTION IS A LIE. A file renamed out from under this dict would sit here
    # excusing something that no longer exists, while the file under its new name went
    # unchecked -- the exemption outliving its subject.
    for name in exempt:
        assert (pathlib.Path(runprov.__file__).parent / name).is_file(), name
    helper = pathlib.Path(runprov._atomic.__file__).read_text(encoding="utf-8")
    assert "os.replace(" in helper, "the helper the others were pointed at no longer renames"


def test_the_debris_count_reaches_the_person_reading_the_command(tmp_path, capsys):
    """Counting it and not saying it is the failure this package refuses everywhere else.
    Debris is the only visible trace that a run died while writing a record, and an
    unexplained dotfile in a results directory is exactly what someone needs told."""
    runprov.configure(root=tmp_path, run_log=tmp_path / "provenance" / "runs.jsonl")
    (tmp_path / "in.tsv").write_text("id\n1\n", encoding="utf-8")
    with runprov.Run("s", {}, provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        with run.open_output(tmp_path / "out.tsv") as fh:
            fh.write("id\n1\n")
    capsys.readouterr()

    rc = runprov.__main__.main(["verify", str(tmp_path), "--root", str(tmp_path)])
    assert runprov._atomic.TEMP_SUFFIX not in capsys.readouterr().err, (
        "a clean tree must not mention debris, or the message is noise the next reader "
        "learns to skip"
    )
    assert rc == 0

    left = tmp_path / f".out.tsv.abcdef123456{runprov._atomic.TEMP_SUFFIX}"
    left.write_text((tmp_path / "out.tsv").read_text(encoding="utf-8"), encoding="utf-8")
    runprov.__main__.main(["verify", str(tmp_path), "--root", str(tmp_path)])
    err = capsys.readouterr().err
    assert "1 file(s) left behind by a run that died while writing a record" in err, err
    assert runprov._atomic.TEMP_SUFFIX in err, "it does not say what to look for"


def test_verify_counts_write_debris_and_does_not_read_it_as_an_artifact(tmp_path):
    """Debris carries a pin — it is a half-written artifact — so a checker that walked it
    would report an artifact under a name nobody wrote. Counted and said, not dropped: it
    is also the only visible trace that a run died mid-write."""
    monkeypatch = pytest.MonkeyPatch()
    try:
        monkeypatch.chdir(tmp_path)
        (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
        proj = _project(tmp_path)
        with runprov.Run("s", project=proj, provenance=tmp_path / "s.prov.json") as run:
            run.input(tmp_path / "in.tsv")
            fh = run.open_output(tmp_path / "out.tsv")
            fh.write("b\n")
            fh.close()
    finally:
        monkeypatch.undo()
    art = (tmp_path / "out.tsv").read_text(encoding="utf-8")
    clean = runprov.verify.verify([tmp_path], tmp_path)

    debris = tmp_path / f".out.tsv.deadbeef1234{runprov._atomic.TEMP_SUFFIX}"
    debris.write_text(art, encoding="utf-8")
    after = runprov.verify.verify([tmp_path], tmp_path)
    assert after["write_debris"] == 1, after
    assert after["artifacts_pinned"] == clean["artifacts_pinned"], (
        "the half-written copy was counted as a second artifact"
    )
    assert after["artifacts_seen"] == clean["artifacts_seen"], after
    assert clean["write_debris"] == 0, "a clean tree must report none, or the count is noise"


# ------------------------------------- is that pid alive? (T-07: os.kill is not that question)


def _fake_ctypes(*, handle=7, last_error=0, waited=None, raises=None):
    """A stand-in for the Windows half of `ctypes`, which does not exist on this platform.

    Same device as `test_the_windows_lock_path_is_exercised` uses for `msvcrt`: it does not
    test Windows — CI does that on a real runner — but it proves this code asks the right
    question and reads the three answers apart. The numbers are the ones measured ON the
    runner, 2026-09-01, not ones copied out of a header file.
    """
    from runprov.show import _WAIT_TIMEOUT

    closed = []

    class Kernel32:
        @staticmethod
        def OpenProcess(access, inherit, pid):
            if raises is not None:
                raise raises
            return handle

        @staticmethod
        def WaitForSingleObject(h, ms):
            return _WAIT_TIMEOUT if waited is None else waited

        @staticmethod
        def CloseHandle(h):
            closed.append(h)

    class FakeCtypes:
        WinDLL = staticmethod(lambda name, use_last_error=False: Kernel32())
        get_last_error = staticmethod(lambda: last_error)

    return FakeCtypes, closed


def _as_windows(monkeypatch, fake):
    monkeypatch.setattr(sys, "platform", "win32")
    monkeypatch.setitem(sys.modules, "ctypes", fake)


def test_show_NEVER_signals_a_process_when_asking_whether_it_is_alive(monkeypatch):
    """THE SAFETY HALF, and the reason this was a defect and not a wrong answer.

    `signal.CTRL_C_EVENT` is 0, and CPython's `os.kill` special-cases it — so
    `os.kill(pid, 0)` on Windows is `GenerateConsoleCtrlEvent(CTRL_C_EVENT, pid)`, which
    sends a Ctrl-C to a console process group. `runprov show`, reading a marker left by a
    job that died last week, would interrupt whatever live process now holds that number.

    Asserted as "os.kill is not called at all" rather than as an outcome, because an
    outcome-only test passes on any implementation that signals the process and then
    happens to return the right answer."""
    fake, _ = _fake_ctypes(waited=runprov.show._WAIT_OBJECT_0)
    _as_windows(monkeypatch, fake)

    def refuse(*a, **k):
        raise AssertionError("os.kill was called to ask whether a process is alive")

    monkeypatch.setattr(runprov.show.os, "kill", refuse)
    assert runprov.show._still_running(4321) is False


def test_the_three_windows_answers_are_read_apart(monkeypatch):
    """Measured on the runner: self -> WAIT_TIMEOUT (258), a reaped pid -> WAIT_OBJECT_0 (0),
    an absurd pid -> no handle, error 87. Three questions, three different right answers —
    and the old code gave the same one to all three."""
    for waited, expect in (
        (runprov.show._WAIT_TIMEOUT, True),
        (runprov.show._WAIT_OBJECT_0, False),
    ):
        fake, closed = _fake_ctypes(waited=waited)
        _as_windows(monkeypatch, fake)
        assert runprov.show._still_running(11) is expect, waited
        assert closed == [7], "the handle must be closed whatever the answer"

    fake, _ = _fake_ctypes(handle=0, last_error=runprov.show._ERROR_INVALID_PARAMETER)
    _as_windows(monkeypatch, fake)
    assert runprov.show._still_running(12) is False, "error 87 IS 'there is no such process'"

    fake, _ = _fake_ctypes(handle=0, last_error=runprov.show._ERROR_ACCESS_DENIED)
    _as_windows(monkeypatch, fake)
    assert runprov.show._still_running(13) is True, (
        "a process we may not open is a process that EXISTS -- Windows for EPERM, and the "
        "same answer POSIX gives for the same fact"
    )

    fake, _ = _fake_ctypes(handle=0, last_error=1450)  # ERROR_NO_SYSTEM_RESOURCES
    _as_windows(monkeypatch, fake)
    assert runprov.show._still_running(18) is None, "a failure to ask is not an answer"

    fake, _ = _fake_ctypes(waited=0xFFFFFFFF)  # WAIT_FAILED
    _as_windows(monkeypatch, fake)
    assert runprov.show._still_running(14) is None, "an unrecognised wait result is not an answer"

    fake, _ = _fake_ctypes(raises=OSError("the call itself failed"))
    _as_windows(monkeypatch, fake)
    assert runprov.show._still_running(15) is None


def test_the_windows_helper_declines_when_it_is_not_on_windows(monkeypatch):
    """It is normally reached through a platform test, so this can only happen by calling it
    directly — which is exactly what a later refactor might do. `None` is the honest answer
    from a function that cannot ask the question here.

    `sys.platform` IS SET RATHER THAN ASSUMED, so the test asserts the same thing on every
    machine. Written without it, it asserted "this is not Windows" and duly failed on
    Windows — a test whose outcome depended on where it ran, in a change whose entire
    subject is code whose outcome depends on where it runs."""
    monkeypatch.setattr(sys, "platform", "linux")
    assert runprov.show._still_running_windows(os.getpid()) is None


def test_a_process_we_may_not_signal_is_alive_and_one_we_cannot_ask_about_is_not_an_answer(
    monkeypatch,
):
    """`EPERM` genuinely means the process exists — that reasoning was sound and is kept.
    It was extended to EVERY `OSError`, which is what made a failure to ask look like an
    answer, and is the sentence the Windows bug hid behind."""
    monkeypatch.setattr(sys, "platform", "linux")

    def perm(*a, **k):
        raise PermissionError(1, "Operation not permitted")

    monkeypatch.setattr(runprov.show.os, "kill", perm)
    assert runprov.show._still_running(16) is True

    def other(*a, **k):
        raise OSError(22, "Invalid argument")

    monkeypatch.setattr(runprov.show.os, "kill", other)
    assert runprov.show._still_running(17) is None
    assert runprov.show._liveness({"host": "h", "pid": 17}, "h") == runprov.show.UNTELLABLE, (
        "'I could not look' must not be printed as 'it is running'"
    )


def test_open_output_writes_exactly_the_bytes_it_is_given(tmp_path, monkeypatch):
    """`csv` writes its own `\\r\\n`, so a handle that also translates `\\n` produces `\\r\\r\\n`
    and a blank line after every row. The README's front-page block writes through this
    handle with `csv.DictWriter`; measured on the Windows runner 2026-09-01, its artifact
    came out with 13 lines where the test expected 10.

    THE CALL SHAPE IS ASSERTED, not only the result, and that is the point of this test.
    On Linux `newline=None` and `newline=""` produce identical bytes — so a result-only test
    passes here on the broken version and can never guard the platform it was written for.

    The bytes are asserted too: a call-shape test alone would pass on an implementation that
    opened the file correctly and then mangled the text itself."""
    seen = {}
    real = builtins.open

    def watched(file, *a, **k):
        # THE TEMPORARY FILE, not the destination. Since ADR-0006 the body is written into
        # `.out.tsv.<hex>.runprov-tmp` and renamed, so matching on the final name would
        # watch a file this call never opens — a spy that sees nothing and asserts nothing.
        if "out.tsv" in str(file):
            seen.update(k)
        return real(file, *a, **k)

    monkeypatch.setattr(builtins, "open", watched)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        with run.open_output(tmp_path / "out.tsv") as fh:
            w = csv.writer(fh, delimiter="\t")
            w.writerow(["sample", "value"])
            w.writerow(["a", "9"])
    monkeypatch.undo()

    assert seen.get("newline") == "", f"open_output must not translate line endings: {seen}"
    raw = (tmp_path / "out.tsv").read_bytes()
    assert b"\r\r\n" not in raw, "csv's own CRLF was translated a second time"
    assert raw.count(b"\r\n") == 2, "one per csv row, and none in the pin"
    assert raw.split(b"\r\n")[0].endswith(b"sample\tvalue"), raw[:200]


def test_every_recorded_path_is_spelled_one_way_on_every_platform():
    """A RECORD IS READ ON A DIFFERENT MACHINE FROM THE ONE THAT WROTE IT, and until this
    the format was consistent everywhere except the field it is mostly made of. Measured on
    the Windows leg 2026-09-01: `record["inputs"][i]["path"]` came back `data\\a.tsv`,
    `provenance_path` as `out\\mid.prov.json`, and `show --stale` keyed its answers
    `{'results\\final.tsv': 'OK'}` for a reader asking about `results/final.tsv`.

    EMULATED, because on this platform `str()` and `as_posix()` agree and a test that cannot
    fail here would be no guard at all. `PurePath` is made Windows-flavoured, which is
    exactly what it is there.

    The pin and the directory hash had each already made this choice, with their own note
    saying why. `describe` is the funnel every input and output passes through, so the rule
    lives there rather than in a list of call sites somebody has to keep extending."""
    win = pathlib.PureWindowsPath
    assert runprov.hashing._posix(win("data\\a.tsv")) == "data/a.tsv"
    assert runprov.hashing._posix(win("C:\\x\\y.tsv")) == "C:/x/y.tsv", (
        "an absolute path too — pathlib parses that back to the same file on Windows"
    )
    assert runprov.hashing._posix("data/a.tsv") == "data/a.tsv", "already-posix stays put"
    assert runprov.hashing._posix(tmp := pathlib.Path("a") / "b") == "a/b", (
        f"and a native path is unchanged here: {tmp}"
    )


#: THE RECORDED-PATH NAMES THIS PACKAGE SPELLS `_posix` THAT DO NOT END IN `path` [L-05].
#:
#: THE GUARD BELOW SCOPED ITSELF BY A SUFFIX, and `history` was deliberately named without the
#: word — `policy.py` records that naming decision — so the field sat OUTSIDE the check that
#: exists to enforce its spelling. All three of its sites reverted to `str()` with the suite
#: green. `df4964b` is the proof the class escapes: it took a Windows CI leg to find one
#: instance, and L-06 then found four more (`artifact` three times and `root`) with L-07 adding
#: `cwd` and `project_root`. A suffix test is a one-item list wearing a derivation's clothes.
#:
#: AND THIS DECLARATION IS HELD BY EQUALITY AGAINST A SIDE DERIVED WITHOUT IT: the names the
#: package ALREADY spells `_posix`, found by the same AST walk, minus the ones the suffix
#: already covers. That is the form L-19 earns the rule for — *a declared table is only held by
#: equality when something else can compute its right-hand side* — and here something can.
#:
#: SO WHY DECLARE IT AT ALL, if it is derived? Because the derivation alone is not enough, and
#: the measurement is the reason. Revert ONE of a name's `_posix` sites to `str()` and the
#: derivation still carries the name, so the offender arm names the line. Revert ALL of them and
#: the name vanishes from the derived side — the scan would lose its own subject silently. The
#: declared set keeps the name in scope, so the offender arm still fires, AND the equality below
#: fires too, naming the name that stopped being spelled at all. Measured: one-site revert RED
#: on one arm, all-sites revert RED on BOTH.
#:
#: ONE EXEMPTION, RECORDED HERE SO IT IS NOT READ AS AN OVERSIGHT. `history_destination` — and
#: the `history.destination` field it fills — is deliberately NOT `_posix`-spelled, and its own
#: docstring carries the reason: it is a field that is SOMETIMES A TYPE NAME (a sink with no
#: path answers with its class), and a field that is sometimes a type name cannot be a path. The
#: same docstring states what to do if that ever stops being enough: *if a reader ever needs to
#: join on where the history went, the repair is a second machine-readable field, not a spelling
#: change.* It is not in the set below because the derivation never found it there.
#: `cwd` IS ABSENT AND THAT IS A MEASUREMENT, NOT AN OMISSION [L-27]. L-07 `_posix`-spelled the
#: record's `cwd` and 15 tests went red on the Windows leg alone, because `Run._anchor` compares
#: that field with `str(pathlib.Path.cwd())` as a string. The spelling of `cwd` is one side of an
#: equality, so it is not free; `project_root` has no reader and stays.
#: `script_file` JOINED THIS SET WITH THE REPAIR THAT PUT IT IN SCOPE [M/guard-1, guard-2]. It is
#: `run.py`'s `"script_file": _posix(sp) if sp else None` — a recorded absolute path that was
#: spelled `str()` for its whole life, twenty-two lines below the `project_root` L-07 fixed in the
#: same `"code"` dict, and in nobody's list. It is a `_posix` site so the derived side below
#: carries it, and it is declared here so the name survives losing that site; both halves and the
#: branch-aware walk had to land in ONE commit, because every two-of-three combination is RED.
#: The ground for the repair is `_posix`'s own docstring — *THE ONE SPELLING EVERY RECORDED PATH
#: USES* — and the permanence of a history line, NOT a consumer: there is no `ast.Compare` in the
#: package mentioning `script_file`, so by L-27's rule the spelling was free to change.
_ALSO_PATHS = frozenset(
    #: `symlink_target` JOINED WITH THE M-01 REPAIR: `hashing.describe` records
    #: `os.readlink`'s answer, which is the native spelling on Windows, and it is now
    #: `_posix(link_target)`. It is derivable on the right-hand side for the same reason
    #: every other member is — something spells it `_posix` — which is the condition L-19
    #: states for a declared table to stay held by equality.
    {"artifact", "history", "project_root", "root", "script_file", "symlink_target"}
)


def test_no_docstring_in_the_tree_holds_a_character_python_cannot_compile():
    """A LONE SURROGATE IN A DOCSTRING IS A MODULE PYTHON 3.13 WILL NOT COMPILE.

    Measured, and this guard exists because it shipped: `4b2ac25` wrote
    `"\\ud83e\\uddac"` into `show._q`'s docstring as a live escape rather than as text,
    while explaining that a surrogate escape is legal JSON and illegal YAML. Python read the
    two escapes as two real lone surrogates, and 3.13 refuses to compile a module whose
    docstring cannot be encoded to UTF-8:

        py_compile.compile("runprov/show.py", doraise=True)
        PyCompileError: UnicodeEncodeError: 'utf-8' codec can't encode characters in
        position 795-796: surrogates not allowed

    So `from .show import render_yaml` raised at IMPORT, the whole test module failed to
    COLLECT, and the leg reported one error and zero tests. **The local gate could not see it
    and did not need the matrix to:** `ci.py` runs 3.12, where this compiles, and a 3.13
    interpreter was on the host the whole time. The CHEAPEST instrument was never asked.

    **A docstring ABOUT an escape has to show the text, not contain the character** — the same
    confusion as a comment that quotes a regex without raw-stringing it, and the same class as
    [L-13], where a document taught the opposite of the contract it described.

    Scoped to DOCSTRINGS, not to every constant, and that is derived rather than cautious: a
    lone surrogate in a function body compiles fine on 3.13 (measured, by compiling every file
    in the tree), and this suite legitimately holds several — `_safe_for_pin` is tested with
    `"x\\ud800y.tsv"` because a filesystem can hand the package exactly that. Widening this to
    all constants would turn those into offenders, which is a guard that cannot pass.

    **WHAT HOLDS THE SWEEP'S HONESTY, AND IT IS NOT A FLOOR ANY MORE** [Audit O, guards-3]. A
    per-file floor stood here -- *every swept file must contribute at least one docstring* -- and
    it was satisfied by the 32 MODULE docstrings alone, 1.9% of the 1 686 in the tree, with an
    EMPTY module docstring qualifying because `ast.get_docstring` returns `''` and not `None`. So
    the sweep could stop reading 1 654 of 1 686 docstrings and still report a clean tree, and a
    live lone surrogate in a FUNCTION docstring was green here while 3.13 and 3.14 refused to
    compile the file. Both halves of that are gone: the node-kind list is deleted in favour of
    what the language means by a docstring, and the floor is deleted with it rather than raised.
    What remains is the roots EQUALITY -- which is about FILES and names the one that went
    missing -- and a walk with no list left in it to narrow.

    **AND THE ROOTS WERE NOT A SWEEP EITHER, UNTIL THIS COMMIT** [Audit Q, assertion-4]. They
    were three non-recursive globs plus two literal paths (`tests/test_runprov.py` and `ci.py`),
    and a `.py` added beside either literal was both unswept AND unable to move the count. They
    are now recursive within the four trees the sdist ships, plus a non-recursive glob of the
    repository root, and the count assertion sits AFTER the offender scan -- because count-first
    never names the surrogate, which is the defect `guards-10` already filed once.

    **THIS GUARD'S FIRST CATCH WAS ITS OWN DOCSTRING**, which is the whole argument for it:
    the paragraph above named the surrogate as a live escape while explaining that a
    docstring must show the text. It went red naming this line before it had ever run
    against the tree, and the care taken writing the sentence substituted for nothing.
    """
    import ast

    #: RECURSIVE WITHIN THE FOUR SDIST TREES, PLUS THE REPOSITORY ROOT [Audit Q, assertion-4].
    #: This read `glob("*.py")` over three directories plus TWO LITERAL PATHS
    #: (`tests/test_runprov.py` and `ci.py`), and the comment below called them *"the four
    #: explicit globs"*, which they were not. The literals are exactly where a new file is both
    #: unswept AND unable to move `len(roots)`: measured with a planted `tests/test_second.py`
    #: carrying a `\ud800` ESCAPE in its module docstring, 3.10/3.11/3.12 compile it and 3.13 and
    #: 3.14 REFUSE -- the failure this guard exists for -- while `len(roots)` was still 32, the
    #: file was not in `roots`, and both this guard and the whole suite were RC=0.
    #:
    #: THE NON-RECURSION IS CLOSED IN ALL FOUR DIRECTORIES, not only in the two that were
    #: literals. Measured as a drop-in on 3.10 / 3.11 / 3.12 / 3.13 / 3.14: 32 == 32, element for
    #: element identical to the set the three globs and two literals produced today.
    #:
    #: AND THE RECORDED REFUTATION OF `rglob` IS TRUE OF A DIFFERENT EXPRESSION. It read
    #: *"`rglob("*.py")` is worse, not better: 1 796 files in this checkout, 1 764 of them inside
    #: `.venv`"*. That is `rglob` FROM THE REPOSITORY ROOT, and it reproduces exactly -- but
    #: `.venv` is inside NONE of the four trees: measured, 0 of the files these four `rglob`s
    #: return lie in `.venv`. The root-level source is `glob("*.py")`, which is not recursive, so
    #: the dependency tree is not reachable from here at all.
    #:
    #: THE ONE DERIVATION STILL REFUTED: `git ls-files '*.py'` CANNOT RUN WHERE THIS SUITE IS
    #: MOST NEEDED. `ci.py build` runs the suite from an unpacked sdist, which is not a git
    #: checkout: measured in the built tarball, `fatal: not a git repository`, exit 128. A sweep
    #: that derives its own scope from git is empty for the packager, which is the one audience
    #: the sdist check exists for.
    #:
    #: `examples` WAS THE HOLE BEFORE THE LITERALS WERE [Audit N, guards-4]. The sweep read 30
    #: files and the repository tracks 32; the two outside it were `examples/summarise.py` and
    #: `examples/format_compatibility.py`, both shipped in the sdist -- `pyproject`'s
    #: `[tool.hatch.build.targets.sdist] include` lists `examples` beside `tools` and `ci.py`,
    #: verified in the built tarball -- and both in `ci.py`'s own `want` set.
    #:
    #: `__pycache__` IS EXCLUDED AND IT REMOVES NOTHING TODAY, measured: 0 of the files these
    #: four `rglob`s return lie in one, because a cache holds `.pyc` and `*.py` does not match
    #: those. It is here because the subject is SOURCE, and a stray `.py` written into a cache
    #: directory is not a module of anything; it is not load-bearing and the next reader should
    #: not read it as if it were.
    roots = sorted(
        found
        for directory in ("runprov", "tests", "examples", "tools")
        for found in pathlib.Path(directory).rglob("*.py")
        if "__pycache__" not in found.parts
    )
    roots += sorted(pathlib.Path(".").glob("*.py"))
    roots = [p for p in roots if p.is_file()]
    offenders: dict[str, str] = {}
    #: A DOCSTRING IS THE FIRST STATEMENT OF ANY BODY WHEN IT IS A STRING CONSTANT, AND THERE IS
    #: NO LIST OF NODE KINDS HERE ANY MORE [Audit O, guards-3]. The walk used to filter on
    #: `(Module, ClassDef, FunctionDef, AsyncFunctionDef)` and ask `ast.get_docstring`, and that
    #: list is a subject that can be NARROWED: drop `ClassDef` and 65 class docstrings go unread
    #: behind a green sweep, which is how every floor in this family has been defeated. Audit O's
    #: generalisation, which is the reason this is shaped the way it is:
    #:
    #:     Every FLOOR in this family has been defeated by narrowing the subject, and no
    #:     exhaustiveness assertion has been. The repair is not to extend the list: it is to
    #:     delete the list and compute the thing itself.
    #:
    #: This IS the thing itself -- it is what the language means by a docstring -- so there is no
    #: kind to forget. Measured as a drop-in: 1 692 docstrings collected either way, byte for
    #: byte the same set, and ZERO nodes outside those four kinds in the whole swept tree,
    #: identical on all five interpreters on this host. `isinstance(body, list)` is what keeps
    #: `Lambda` and `IfExp` out, whose `body` is a single expression rather than a block.
    #:
    #: AND THE PER-FILE FLOOR IS DELETED WITH THE LIST, not kept beside it. It read *every file
    #: must contribute at least one docstring*, and it was satisfied by 32 of 1 686 -- 1.9% --
    #: so the sweep could stop reading 98% of its subject and still report a clean tree. It was
    #: a floor on HOW MUCH of the subject was read, which is the thing that has never held. What
    #: holds this sweep now is the roots floor above, which is about the FILES, plus the fact
    #: that the walk has no narrowable list left in it. A `checked >= N` total is refused for the
    #: separate reason it always was: it rots on every docstring edit in the repository, which is
    #: the K-37/L-08 defect and the reason `pyproject`'s coverage figures were DELETED rather
    #: than corrected.
    for path in roots:
        tree = ast.parse(path.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            body = getattr(node, "body", None)
            if not (isinstance(body, list) and body and isinstance(body[0], ast.Expr)):
                continue
            const = body[0].value
            if not (isinstance(const, ast.Constant) and isinstance(const.value, str)):
                continue
            try:
                const.value.encode("utf-8")
            except UnicodeEncodeError as exc:
                #: `getattr`, BECAUSE `ast.Module` HAS NO `lineno` [Audit N, guards-7]. All 32
                #: swept files have a module docstring, which is the commonest docstring in the
                #: tree, and for that one the f-string raised `AttributeError` INSIDE this
                #: `except UnicodeEncodeError` handler — so the guard went red with a type error
                #: and NO PATH WAS NAMED ANYWHERE in the report. The reader got coverage's
                #: "position 1677" and no file. The guard's whole value is naming the site.
                offenders[f"{path}:{getattr(node, 'lineno', 1)}"] = str(exc)

    assert not offenders, (
        f"these docstrings hold a character Python 3.13 cannot compile, so the module will not "
        f"IMPORT there and every test in it reports as a collection error: {offenders}. A "
        f"docstring about an escape must show the text -- double the backslashes"
    )

    #: AND THE COUNT COMES AFTER THE OFFENDERS, WHICH IS HALF OF THIS ROW AND NOT A DETAIL
    #: [Audit Q, assertion-4]. Count-first RE-CREATES `guards-10`'s defect, measured: with this
    #: equality ahead of the scan, a planted surrogate reports `assert 33 == (24 + 8)` and
    #: *"a file was added ... bump `_PACKAGE_MODULES`"*. The file appears in the census this
    #: message prints, but the ACCUSATION is the count and the ADVICE IS WRONG -- bumping the
    #: constant makes the guard green over a module 3.13 and 3.14 cannot compile. Nothing says
    #: "surrogate" anywhere. The named defect is asserted first now, and this equality is the
    #: census behind it.
    #:
    #: IT IS AN EQUALITY, BECAUSE THE COMMENT ABOVE SAID SO WHILE THE ASSERTION SAID `>= 32`
    #: [Audit P, exhaustive-9]. A floor is slack by one the moment a package module is added, and
    #: nothing said so: 24 + 2 + 1 + 6 + 2 is 35 today, and with a 25th package module a floor
    #: of 32 reads 33 and stays green over a file it may well not have read.
    #:
    #: THE PACKAGE HALF READS `_PACKAGE_MODULES` RATHER THAN RESTATING IT, so one bump moves one
    #: number [Audit O, guards-12]. The rest are what the four trees and the repository root hold
    #: OUTSIDE the package -- `tests/*.py` 2, `ci.py` 1, `tools/*.py` 6, `examples/*.py` 2 -- and
    #: they live in `_NON_PACKAGE_SOURCES` so that this side and the `open_output` sweep read ONE
    #: number between them. This is NOT circular -- `_PACKAGE_MODULES` is a
    #: hand-written constant that a human must re-read when adding a module, and `len(roots)` is
    #: read off the disk, so the two sides have different sources and the equality has something
    #: to say.
    #:
    #: ONE LIMIT, MEASURED RATHER THAN LEFT TO BE DISCOVERED: this holds the TOTAL, so it cannot
    #: say WHICH half moved, and bumping either half silences either cause. Measured: a planted
    #: `examples/planted.py` makes this red, and bumping `_PACKAGE_MODULES` to 25 makes it green
    #: again over a file that is not a package module at all. That is why the message below names
    #: both causes and says which number answers which; the `_PACKAGE_MODULES - 1` census in the
    #: layer test is what holds the package half on its own.
    assert len(roots) == _PACKAGE_MODULES + _NON_PACKAGE_SOURCES, (
        f"the sweep found {len(roots)} source files and the repository tracks "
        f"{_PACKAGE_MODULES + _NON_PACKAGE_SOURCES} -- {_PACKAGE_MODULES} in `runprov/` plus "
        f"{_NON_PACKAGE_SOURCES} outside it "
        f"(2 in `tests/`, `ci.py`, 6 in `tools/`, 2 in `examples/`). Either a sweep has stopped "
        f"matching, or a file was added: if a PACKAGE module was added, bump "
        f"`_PACKAGE_MODULES`, which is the one number for it; if it was added outside the "
        f"package, the 8 above is what to re-read. NOT every root ships in the sdist, and this "
        f"assertion does not claim they do: the sdist's `include` lists `examples`, `tools` and "
        f"`ci.py` BY NAME, so a second `.py` at the repository root is swept here and packaged "
        f"nowhere -- which is the right way round, because an unswept file is the failure and an "
        f"unpackaged one is not. Found: {[str(p) for p in roots]}"
    )


def test_no_recorded_path_is_spelled_with_a_bare_str():
    """DERIVED, NOT LISTED — the ninth and tenth instance of the pattern this repository
    keeps finding, and the reason this test exists rather than seven fixed lines.

    `describe()` had spelled the path correctly for the whole of its life, and then
    `described["path"] = str(q)` twelve lines later overwrote it, so every INPUT went into
    the record POSIX and every OUTPUT went in the platform's way. Two more sites were in
    `terminal.py`, one in `environment.py`, one more in `run.py`. Nobody would have found
    the seventh by reading, and a list of six filenames is the same defect rescheduled.

    PARSED, NOT GREPPED, for the reason the atomic-write guard is: a line-matching version
    of this fires on docstrings that quote the code.

    THREE SHAPES, AND THE KEY IS A SUFFIX — both of those are repairs to this test, and both
    were found by mutating the package rather than by reading the check:

    * the key was matched as the literal `"path"`, so `run.py`'s
      `"provenance_path": _posix(prov_path)` was outside the scan entirely. Reverting that
      one line to `str(...)` left the whole file green — and `provenance_path` is a field
      the sibling test's own docstring names as one of the breakages this rule exists for.
      It is `.endswith("path")` now, which was measured to be false-positive-free here.
    * a keyword ARGUMENT was not a shape at all, and `path=str(target)` inside a
      `dict(rec, ...)` call is how the lock-file record spelled its path — one line below
      the snapshot path that had been converted, in the same commit, by somebody reading.

    ONE MATCHER, CALLED TWICE. The non-vacuity probe below used to walk a hand-copied,
    LOOSER version of this scan: it keyed on `"path"` and omitted the two `func.id == "str"`
    conditions the real one turns on. Measured: changing `== "str"` to `== "srt"` in the
    test body left it at `1 passed`, so the real matcher could have matched nothing at all
    and the probe would still have said the scan could see its subject. A probe that does
    not run the code under test is a second implementation agreeing with itself."""

    #: ONE WALK, TWO CALLEES [L-05]. The scan for `str(` and the derivation of `_posix(`-spelled
    #: names are the SAME function with a different callee, for the reason the probe below
    #: exists: two walks are two chances for the derived side to see shapes the offender side
    #: does not, and the two sides are then not about the same thing.
    def keyed_calls(source: str, name: str, callee: str) -> list[tuple[str, str, str]]:
        """Every `<callee>(...)` that is KEYED BY A NAME, in all three recorded shapes."""

        def is_the_call(v: ast.expr | None) -> bool:
            if not isinstance(v, ast.Call):
                return False
            # `str(...)` is a bare name; `_posix(...)` is spelled both bare (`run.py`,
            # `verify.py`, which import it) and qualified (`hashing._posix(...)` in
            # `__main__.py`, `policy.py` and `report.py`). Both have to count or the derived
            # side is short by whichever modules happen to use the other form.
            return (isinstance(v.func, ast.Name) and v.func.id == callee) or (
                isinstance(v.func, ast.Attribute) and v.func.attr == callee
            )

        def key_of(x: ast.expr | None) -> str | None:
            if isinstance(x, ast.Constant) and isinstance(x.value, str):
                return x.value
            return None

        #: BRANCH-AWARE, AND DELIBERATELY NO DEEPER [M/guard-2]. The three shapes above test the
        #: TOP node of a keyed value, so the same revert wrapped in a conditional expression was
        #: invisible: measured, `verify.py`'s `_posix(path)` reverted to `str(path)` is RED naming
        #: the site, and that same revert written `str(path) if path else ""` left the WHOLE SUITE
        #: at RC=0 — the scope-pattern defect, found again inside a guard written to stop it.
        #:
        #: A DEEP `ast.walk` OF THE VALUE IS THE WRONG WIDENING, and it was measured rather than
        #: argued: it gains `code`, `onerror` and `terminal_log` on the derived side, which breaks
        #: the equality below, and it reports the legitimate `_posix(str(...))` in `hashing.py`'s
        #: `onerror` as an offender together with `run.py`'s `script_file` keyed as `code` — a
        #: report that misnames its own finding. So: `IfExp` arms and `BoolOp` operands, nothing
        #: else. The package has 24 keyed values of those two shapes and exactly one of them is a
        #: path, so the absence of false positives here is structural rather than luck.
        def branches(v: ast.expr) -> list[ast.expr]:
            """The arms a keyed value can hide the call in — and no other descent."""
            if isinstance(v, ast.IfExp):
                return [*branches(v.body), *branches(v.orelse)]
            if isinstance(v, ast.BoolOp):
                return [b for x in v.values for b in branches(x)]
            return [v]

        out: list[tuple[str, str, str]] = []
        for node in ast.walk(ast.parse(source, filename=name)):
            if isinstance(node, ast.Dict):
                for k, v in zip(node.keys, node.values, strict=False):
                    key = key_of(k)
                    if key is None:
                        continue
                    for arm in branches(v):
                        if is_the_call(arm):
                            out.append((key, f"{name}:{arm.lineno}", ast.unparse(arm)))
            elif isinstance(node, ast.Assign):
                for arm in branches(node.value):
                    if not is_the_call(arm):
                        continue
                    for t in node.targets:
                        if isinstance(t, ast.Subscript):
                            key = key_of(t.slice)
                            if key is not None:
                                out.append((key, f"{name}:{node.lineno}", ast.unparse(node)))
            elif isinstance(node, ast.keyword) and node.arg:
                for arm in branches(node.value):
                    if is_the_call(arm):
                        out.append((node.arg, f"{name}:{arm.lineno}", ast.unparse(node)))
        return out

    sources = {
        mod.name: mod.read_text(encoding="utf-8")
        for mod in sorted(pathlib.Path(runprov.__file__).parent.glob("*.py"))
    }
    assert len(sources) == _PACKAGE_MODULES, (
        f"the walk read {len(sources)} of the package's {_PACKAGE_MODULES} modules: "
        f"{sorted(sources)}"
    )

    #: THE SECOND SIDE, DERIVED WITHOUT CONSULTING `_ALSO_PATHS`: the names this package already
    #: spells `_posix`. This is what makes the declaration falsifiable rather than circular —
    #: *held by equality both ways* names no second side, and a set compared only against itself
    #: is RC=0 with a row deleted.
    posix_spelled = {
        key
        for name, src in sources.items()
        for key, _site, _src in keyed_calls(src, name, "_posix")
    }
    assert set(_ALSO_PATHS) == {n for n in posix_spelled if not n.endswith("path")}, (
        f"[L-05] `_ALSO_PATHS` and the names this package actually spells `_posix` disagree. "
        f"Declared {sorted(_ALSO_PATHS)}; derived (minus the ones the suffix already covers) "
        f"{sorted(n for n in posix_spelled if not n.endswith('path'))}. A name that stopped "
        f"being `_posix`-spelled ANYWHERE falls out of the derived side, and the scan would "
        f"lose its own subject silently — which is what `history` did for three commits."
    )

    #: THE SCOPE: the suffix, plus what is derived, plus what is declared. The declared half is
    #: the only one that survives a name losing every `_posix` site it had.
    scope = set(_ALSO_PATHS) | posix_spelled

    def offenders_in(source: str, name: str) -> dict[str, str]:
        return {
            site: src
            for key, site, src in keyed_calls(source, name, "str")
            if key.endswith("path") or key in scope
        }

    #: THE OFFENDER ARM BELOW IS STRUCTURALLY UNREACHABLE FOR A SINGLE-SITE FIELD, AND THAT IS
    #: WHY THE REPAIRS IN SCOPE HERE HAVE NO NORMAL DEMONSTRATION [M]. `scope` is
    #: `_ALSO_PATHS | posix_spelled`, and the equality above holds
    #: `_ALSO_PATHS == {derived minus *path}` — so a name that does not end in `path` is in scope
    #: only while something still spells it `_posix`. Revert the ONE site a single-site field has
    #: and the name leaves the DERIVED side in the same stroke: the equality fails, and that
    #: assert precedes this one. Measured at HEAD on the field L-27 cleared, nothing else changed
    #: — `"script_file"`'s neighbour `"project_root": _posix(root)` put back to `str(root)` is RED
    #: at the equality above, accusing `_ALSO_PATHS` itself, and it NEVER names the line in
    #: `run.py`. The same is true of `script_file` from the commit that added it onward.
    #: `artifact` has THREE `_posix` sites, so reverting one of them leaves the name on the
    #: derived side and this arm does fire — which is why L-05's own measurement looked
    #: informative and does not generalise. Writing "RED unfixed: the guard names the line" for a
    #: one-site field would be false; what holds those fields is the EQUALITY, and what holds the
    #: matcher is the probe below.
    offenders = {}
    for name, src in sources.items():
        offenders |= offenders_in(src, name)
    assert not offenders, (
        f"a recorded path spelled the platform's way: {offenders}. Use `hashing._posix`, so "
        f"a record written on Windows can be read on Linux and vice versa."
    )
    # NON-VACUITY, THROUGH THE SAME FUNCTION. "Nothing found" and "nothing looked at" are
    # the same green. One line per arm, and each arm twice -- once with the bare key and
    # once with a suffixed one -- so narrowing the key back to `== "path"` fails here rather
    # than quietly halving the scan's reach, and so does losing either `str` condition.
    #: AND EACH ARM AGAIN FOR A NAME THAT DOES NOT END IN `path` [L-05], so the widened scope
    #: is probed in all three shapes too. Without these three lines the widening could be a
    #: no-op — the suffix half would answer every probe line and the new half would never be
    #: exercised, which is the "green because it is uninformed" shape this row is about.
    hits = offenders_in(
        'rec = {"path": str(p)}\n'
        'rec = {"provenance_path": str(p)}\n'
        'rec["path"] = str(p)\n'
        'rec["provenance_path"] = str(p)\n'
        "f(path=str(p))\n"
        "f(script_path=str(p))\n"
        'rec = {"artifact": str(p)}\n'
        'rec["cwd"] = str(p)\n'
        "f(history=str(p))\n"
        #: AND ONE LINE PER BRANCH ARM [M/guard-2], for the same reason the three shapes each get
        #: two: without these the branch-aware walk could be a no-op — the top-node half would
        #: answer every probe line and the new half would never be exercised, which is the
        #: "green because it is uninformed" shape the widening was filed against.
        'rec = {"root": str(p) if p else None}\n'
        'rec["artifact"] = None if p is None else str(p)\n'
        'f(history=str(p) or "")\n',
        "<probe>",
    )
    assert hits == {
        "<probe>:1": "str(p)",
        "<probe>:2": "str(p)",
        "<probe>:3": "rec['path'] = str(p)",
        "<probe>:4": "rec['provenance_path'] = str(p)",
        "<probe>:5": "path=str(p)",
        "<probe>:6": "script_path=str(p)",
        "<probe>:7": "str(p)",
        #: `<probe>:8` IS `rec["cwd"] = str(p)` AND IT IS DELIBERATELY NOT HERE [L-27]. The probe
        #: still writes that line, so its absence from `hits` proves the scan IGNORES a name
        #: outside its scope rather than proving the scan is blind — a control in the other
        #: direction, free. `cwd` left the scope because `Run._anchor` compares that field with
        #: `str(pathlib.Path.cwd())` as a string, so its spelling is one side of an equality and
        #: `_posix` broke 15 tests on the Windows leg.
        "<probe>:9": "history=str(p)",
        #: THE THREE BRANCH ARMS [M/guard-2]: an `IfExp` body, an `IfExp` orelse and a `BoolOp`
        #: operand. `<probe>:10` is the exact shape `run.py`'s `script_file` had while it was
        #: spelled `str()` and this scan could not see it.
        "<probe>:10": "str(p)",
        "<probe>:11": "rec['artifact'] = None if p is None else str(p)",
        "<probe>:12": "history=str(p) or ''",
    }, f"the scan cannot see its own subject in all three shapes: {hits}"


def test_inside_describe_every_str_is_wrapped_in_posix():
    """THE FUNNEL'S OWN RULE, MADE CHECKABLE. `describe`'s docstring calls `_posix` "THE ONE
    SPELLING EVERY RECORDED PATH USES ... one funnel, one rule, and no list of call sites to
    keep extending" — and then three lists inside that same function were built with `str()`:
    `unreadable_dirs`, `symlinked_dirs_not_followed` and `skipped_nonregular`, which are
    precisely the fields a reader on the other platform consults when a tree hash does not
    match and they want to know what was left out of it.

    SCOPED TO THE INVARIANT, NOT TO A SYNTAX SHAPE, which is why this is a second guard and
    not a fourth arm on the one above. That one enumerates the shapes a path can be recorded
    in — a dict value, a subscript assignment, a keyword argument — and a shape list is the
    thing this repository has had to widen nine times. This one asks a question with no
    shapes in it: inside this one function, is there any `str(...)` that is not handed
    straight to `_posix`? It catches `list.append(str(p))`, a comprehension element, an
    f-string's operand, a return value — anything, because it does not look at where the
    call sits.

    IT NEEDS NO EXEMPTIONS, and that is what makes it worth having rather than a rule with a
    list of excuses beside it. Measured on this tree: `describe` contains exactly ONE `str(`
    call, `_posix(str(getattr(e, "filename", e)))`, and the `str` there is not redundant —
    `onerror` is handed an exception whose `filename` can be `None` and whose fallback is
    the exception itself, and `_posix` of either raises `TypeError` out of the guard that
    exists so an unreadable directory does not stop the walk.

    IT IS ALSO THE ONLY WAY THIS FIX CAN FAIL HERE. On Linux `str(PosixPath(p))` and
    `_posix(PosixPath(p))` are byte-identical, so no assertion about a record's CONTENT can
    tell the repaired function from the unrepaired one on the platform this suite runs on.
    A line no mutation can distinguish is decoration; this is the mutation.

    AND THE EXACT SHAPE IT CANNOT SEE, NAMED HERE BECAUSE THE SENTENCE ABOVE IS WHY [M-01].
    *`describe` contains exactly ONE `str(` call* is true, and it is precisely what makes this
    blind to a recorded path that arrives WITHOUT a `str()`: `link_target = os.readlink(path)`
    is already a string, so `"symlink_target": link_target` had no `str(` for this to find and
    no `Call` node for the scope guard to test. The question *is there a bare `str`* is the
    wrong question for that family, and asking it harder cannot fix it.
    `test_inside_describe_every_recorded_path_arrives_through_posix` asks a different one — did
    the VALUE come through `_posix`, whatever produced it — and that is the guard this pair
    needs. Both stay: this one is an AST property that needs no fixture, and that one needs a
    real symlink on disk and skips where the platform has none."""

    def scan(source: str, name: str) -> tuple[dict[str, str], dict[str, str]]:
        """Every `str(...)` inside `describe`, split into wrapped and bare."""
        tree = ast.parse(source, filename=name)
        fn = next(
            (n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name == "describe"),
            None,
        )
        # NOT `assert fn`: a scan that located no function must be a LOUD failure, not a
        # quiet empty result that reads exactly like a clean tree.
        assert fn is not None, f"{name}: there is no `describe` here, so this looked at nothing"

        def is_str_call(n: ast.AST) -> bool:
            return isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "str"

        wrapped_ids = {
            id(a)
            for c in ast.walk(fn)
            if isinstance(c, ast.Call) and isinstance(c.func, ast.Name) and c.func.id == "_posix"
            for a in c.args
            if is_str_call(a)
        }
        bare, wrapped = {}, {}
        for n in ast.walk(fn):
            if is_str_call(n):
                (wrapped if id(n) in wrapped_ids else bare)[f"{name}:{n.lineno}"] = ast.unparse(n)
        return bare, wrapped

    source = pathlib.Path(runprov.hashing.__file__).read_text(encoding="utf-8")
    bare, wrapped = scan(source, "hashing.py")
    assert not bare, (
        f"a path inside `describe` is spelled the platform's way: {bare}. Every `str(...)` in "
        f"the funnel must be the argument of `_posix(...)`, or a record written on Windows "
        f"cannot be read on Linux — and this is the function whose docstring promises it."
    )
    # NON-VACUITY, ON THE REAL FILE: `describe` could lose its last `str` call and this would
    # go on passing for ever while the rule it enforces stopped having a subject. Keyed on
    # what was matched rather than on a line number, so moving the function does not lie.
    assert sorted(wrapped.values()) == ["str(getattr(e, 'filename', e))"], (
        f"the one legitimate wrapped `str` in `describe` is not where this thinks: {wrapped}"
    )
    # AND THE SCAN MUST BE ABLE TO REPORT ONE. The assertion above is a negative; a matcher
    # that had stopped recognising `str` at all would satisfy it and the one above equally.
    probe = scan(
        "def describe(path):\n"
        "    out = []\n"
        "    out.append(_posix(str(path)))\n"
        "    out.append(str(path))\n"
        "    return out\n",
        "<probe>",
    )
    assert probe == (
        {"<probe>:4": "str(path)"},
        {"<probe>:3": "str(path)"},
    ), f"the scan cannot tell a wrapped `str` from a bare one: {probe}"
    # AND LOSING THE FUNCTION MUST BE LOUD. This arm cannot be reached by mutating the
    # package -- `runprov/__init__.py` imports `describe` by name, so a rename fails at
    # import long before it reaches here -- so it is driven directly. Without it, a scan
    # renamed out from under this guard would report zero offenders for ever, which is the
    # "nothing found and nothing looked at are the same green" failure in its purest form.
    with pytest.raises(AssertionError, match="looked at nothing"):
        scan("def something_else(path):\n    return str(path)\n", "<no-describe>")


@requires_symlinks
def test_inside_describe_every_recorded_path_arrives_through_posix(tmp_path, monkeypatch):
    """THE SAME INVARIANT ASKED ABOUT THE VALUE, BECAUSE THE SYNTAX QUESTION HAS A BLIND SPOT
    AND M-01 WAS IN IT. `link_target = os.readlink(path)` is ALREADY a string, so
    `"symlink_target": link_target` carried the native spelling into the record with no `str(`
    for the sibling guard to find and no `Call` node at all for the scope guard to test — the
    fourth undocumented recorded path, six lines below `"path": _posix(path)`, inside the one
    function this package calls the funnel. Two guards, two different reasons to be blind, and
    the field was in nobody's list.

    DERIVED, NOT LISTED, AND THE DERIVATION IS THE FILESYSTEM'S. The tempting repair is a set
    of path-producing functions — `os.readlink`, `os.path.realpath`, `os.readlink`'s next
    sibling — and that is the list-of-sites shape this repository has had to widen nine times;
    the eighth path-producer would arrive outside it exactly as `os.readlink` arrived outside
    the other two. So the question here has no function names in it: **`_posix` is replaced by
    a marking version, `describe` is run over a real tree, and every recorded string that NAMES
    SOMETHING ON DISK must carry the mark.** What counts as a path is decided by the operating
    system, not by this file, so a value that arrives from a call nobody here has heard of is
    caught on the day it is recorded.

    IT IS ALSO THE DEMONSTRATION THE SPELLING REPAIRS OTHERWISE CANNOT HAVE. On Linux
    `str(PosixPath(p))` and `_posix(p)` are byte-identical, so no assertion about a record's
    content distinguishes either state; the mark is not a separator, so this one does. Measured:
    dropping `_posix` from `symlink_target` is RED here naming `symlink_target`, where the two
    existing guards stay green.

    WHY NOT AN AST GUARD TOO: because the AST sibling above is kept and this is the other half.
    That one needs no fixture and holds on every platform; this one needs a real symlink and
    skips where the platform cannot make one. Neither subsumes the other.
    """
    monkeypatch.chdir(tmp_path)
    mark = "<posix>"
    spelled = runprov.hashing._posix
    monkeypatch.setattr(runprov.hashing, "_posix", lambda p: mark + spelled(p))

    #: ONE WALK, TWO USES, for the reason the scope guard's `keyed_calls` is one function: the
    #: side that reports an offender and the side that proves the walk saw anything at all must
    #: be about the same leaves, or a green means nothing.
    def strings_in(obj: object, where: str = "") -> list[tuple[str, str]]:
        """Every string leaf of a record, keyed by its own path through the structure."""
        if isinstance(obj, dict):
            return [
                leaf
                for k, v in obj.items()
                for leaf in strings_in(v, f"{where}.{k}" if where else str(k))
            ]
        if isinstance(obj, list):
            return [leaf for i, v in enumerate(obj) for leaf in strings_in(v, f"{where}[{i}]")]
        return [(where, obj)] if isinstance(obj, str) else []

    def unspelled_in(rec: object) -> dict[str, str]:
        """Those leaves that NAME SOMETHING ON DISK and did not come through `_posix`.

        `os.path.lexists`, NOT `exists`, AND THE REASON IS THE LINK AND NOT ITS TARGET [Audit N,
        guards-9]. The two differ for a DANGLING LINK — `exists` is False and `lexists` is True —
        and they never differ for that link's TARGET, where both are False. An earlier wording
        here had it the other way round. The reason to use `lexists` is that a recorded path may
        BE a link whose target is gone, and that is still a path that was recorded.

        AND THE SCOPE IS THE TEST'S CWD, WHICH IS A KNOWN LIMIT, NOT A CLOSED ONE. A relative
        `symlink_target` inside a subdirectory — `../real.tsv` for `sub/link.tsv` — does not
        `lexists` from the test's cwd, so a regression confined to that shape is outside this
        half of the guard. The repair proposed for it was to resolve candidates against
        `dirname(rec["path"])` as a UNION, and that is MEASURED DEAD HERE: `path` is the one
        field guaranteed to carry the mark, so the base is `<posix>sub` and the join is
        `<posix>sub/../real.tsv`, which exists nowhere. Measured side by side in this fixture:
        the bare value False, the union False, and only a mark-STRIPPED base True. Resolving
        against the record's own `path` without stripping widens nothing, and stripping the mark
        inside the detector would make the detector depend on the sentinel it is detecting. So
        the limit is recorded rather than closed, and the AST sibling above — which needs no
        fixture and holds on every platform — is what covers the spelling of that field today.
        """
        return {
            where: value
            for where, value in strings_in(rec)
            if value and mark not in value and os.path.lexists(value)
        }

    real = tmp_path / "real.tsv"
    real.write_text("id\tv\nx\t1\n", encoding="utf-8")
    link = tmp_path / "link.tsv"
    link.symlink_to(real)
    tree = tmp_path / "t"
    (tree / "sub").mkdir(parents=True)
    (tree / "sub" / "a.tsv").write_text("a\n", encoding="utf-8")
    (tree / "to_sub").symlink_to(tree / "sub", target_is_directory=True)

    #: A FILE, A LINK AND A DIRECTORY, so the three arms of `describe` are all exercised: the
    #: link is the one that carries M-01's field, and the directory is the one that carries the
    #: three lists L-05 found. A record with no symlink in it cannot fail this.
    names = ("real.tsv", "link.tsv", "t")
    records = {name: runprov.hashing.describe(pathlib.Path(name)) for name in names}
    for name, rec in records.items():
        bad = unspelled_in(rec)
        assert not bad, (
            f"`describe({name})` recorded a path that never went through `_posix`: {bad}. Every "
            f"recorded path is spelled the one way whatever produced it, and `os.readlink`'s "
            f"answer is the platform's — that is M-01."
        )
        # NON-VACUITY ON THE REAL RECORD: "no unspelled path" and "no path at all" are the same
        # green, and only the record says which one happened.
        assert [w for w, v in strings_in(rec) if mark in v], (
            f"`describe({name})` recorded no path through the funnel at all: {rec}"
        )

    #: AND THE PREMISE OF THE WHOLE TEST, ASSERTED RATHER THAN ASSUMED: the link's record
    #: actually carries M-01's field, and it carries it SPELLED. Without this the loop above is
    #: satisfied by `path` alone and the field this guard exists for need not be present.
    #: `.get`, NOT A SUBSCRIPT [Audit N, guards-8]. This line subscripted before it asserted,
    #: so a `describe` that stopped recording the field died here with a bare `KeyError` instead
    #: of its own *the subject is missing* message — an error rather than an assertion, the same
    #: shape as the `ast.Module` `lineno` above. The row that filed it said this was the only
    #: guard holding M-01; that is WRONG and the correction matters, because it is what makes
    #: this a diagnostics defect rather than a hole: deleting the field fails THREE tests, two of
    #: which name it with a full explanation — the behavioural symlink test and `_ALSO_PATHS`'s
    #: static equality, which is held on EVERY leg, Windows included.
    assert mark in records["link.tsv"].get("symlink_target", ""), (
        f"the subject is missing: `describe` recorded no `symlink_target` for a real symlink, so "
        f"the loop above is satisfied by `path` alone and the field this guard exists for need "
        f"not be present: {records['link.tsv']}"
    )

    # AND THE DETECTOR MUST BE ABLE TO REPORT ONE, through the same walk and at depth. A
    # matcher that had stopped recognising a path would satisfy the negative above in silence.
    probe = unspelled_in(
        {
            "path": mark + "real.tsv",
            "symlink_target": "real.tsv",
            "kind": "file",
            "mtime_utc": "2026-01-01T00:00:00Z",
            "sha256": "0" * 64,
            "nested": [{"skipped_nonregular": "t/sub"}],
        }
    )
    assert probe == {
        "symlink_target": "real.tsv",
        "nested[0].skipped_nonregular": "t/sub",
    }, f"the detector cannot tell a spelled path from a bare one, at any depth: {probe}"


# ------------------------------------- the gate others can adopt: pre-commit and an Action


def _repo_file(name):
    """The file at the repository root, or a skip when running from an installed wheel."""
    p = _repo_root() / name
    if not p.is_file():
        pytest.skip(f"{name} is not packaged in the installed distribution")
    return p


def test_every_pre_commit_hook_runs_a_command_this_package_actually_accepts():
    """A hook whose flags do not exist is worse than no hook: `pre-commit` reports it as a
    failure, and the first thing anybody does with a gate that cries wolf is remove it.

    RUN, NOT PARSED. The commands are executed in an empty directory, which is the state a
    fresh clone is in — so this also pins that the gate SAYS SOMETHING USEFUL rather than
    crashing when there is no history yet. Exit 2 is the right answer there ("could not
    check"), and it is in the contract; a traceback or an argparse complaint is not."""
    import yaml

    hooks = yaml.safe_load(_repo_file(".pre-commit-hooks.yaml").read_text(encoding="utf-8"))
    assert len(hooks) >= 2, f"expected the hooks this repository offers, found {hooks}"
    with tempfile.TemporaryDirectory() as empty:
        for hook in hooks:
            entry = hook["entry"].split()
            assert entry[:3] == ["python", "-m", "runprov"], (
                f"{hook['id']}: a hook must invoke this package, not {entry[:3]}"
            )
            out = subprocess.run(
                [sys.executable, "-m", "runprov", *entry[3:]],
                capture_output=True,
                text=True,
                cwd=empty,
                env={**os.environ, "PYTHONPATH": str(REPO)},
                check=False,
            )
            said = out.stdout + out.stderr
            assert "unrecognized arguments" not in said, f"{hook['id']}: {said.strip()[:200]}"
            assert "invalid choice" not in said, f"{hook['id']}: {said.strip()[:200]}"
            assert "Traceback" not in said, f"{hook['id']}: {said.strip()[:300]}"
            assert out.returncode in {0, 1, 2}, (
                f"{hook['id']}: exit {out.returncode} is outside the contract — see "
                f"CANNOT_CHECK in __main__.py"
            )


def test_the_action_only_names_subcommands_that_exist_and_options_it_handles():
    """The Action's script is shell inside YAML, which no type checker reads. Two ways it can
    lie and both are silent until somebody's build breaks: naming a subcommand this package
    does not have, and documenting a `check:` value its own `case` statement does not branch
    on."""
    import yaml

    text = _repo_file("action.yml").read_text(encoding="utf-8")
    action = yaml.safe_load(text)

    # DERIVED FROM THE PARSER, not from a list typed here — the point of the whole exercise.
    out = subprocess.run(
        [sys.executable, "-m", "runprov", "--help"],
        capture_output=True,
        text=True,
        env={**os.environ, "PYTHONPATH": str(REPO)},
        check=False,
    )
    real = {w.strip(" ,") for w in re.findall(r"\{([a-z,]+)\}", out.stdout)[0].split(",")}
    assert {"show", "verify"} <= real, f"the parser no longer offers these: {real}"

    named = set(re.findall(r"python -m runprov ([a-z]+)", text))
    assert named, "the Action runs no runprov command at all"
    assert named <= real, f"the Action names subcommands that do not exist: {named - real}"

    # THE DOCUMENTED VALUES AND THE BRANCHED VALUES MUST BE THE SAME SET, and BOTH SIDES ARE
    # DERIVED. The first version of this matched ``(stale|verify|both)`` — a hand-typed
    # alternation, so the "documented" set could only ever contain the three words already in
    # it. Adding a fourth documented value went undetected: mutation-checked, it survived.
    # That is the scope pattern this repository keeps finding, in the test written to prevent
    # a documentation drift.
    documented = set(re.findall(r"`([a-z]+)`", action["inputs"]["check"]["description"]))
    branched = {
        w
        for line in re.findall(r"^\s*([a-z|]+)\)$", text, re.M)
        for w in line.split("|")
        if w != "esac"
    }
    assert documented, "the `check:` input documents no values at all"
    assert branched, "the Action's script branches on nothing — the case statement is gone"
    assert documented == branched, (
        f"`check:` documents {sorted(documented)} and the script branches on "
        f"{sorted(branched)} — a value in one and not the other is a build that fails for a "
        f"reason nobody wrote down"
    )


# ------------------------------------- the artifact answers for itself (ADR-0006)


def _pinned(tmp_path, body="sample\tvalue\na\t9\n"):
    """A real pinned artifact, written the documented way."""
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        with run.open_output(tmp_path / "out.tsv") as fh:
            fh.write(body)
    return tmp_path / "out.tsv"


def test_an_edited_artifact_is_ALTERED_and_a_stale_one_is_not(tmp_path, monkeypatch):
    """The two findings are different repairs and must not collapse into one another.

    A STALE artifact is REBUILT — its inputs moved. An ALTERED one was edited by somebody
    after it was written, and rebuilding it is exactly the wrong move: it destroys whatever
    the edit was. Reporting either as the other sends a person to do the opposite of what
    the situation needs, which is why they are separate states and not one."""
    monkeypatch.chdir(tmp_path)
    art = _pinned(tmp_path)
    assert runprov.verify.verify_artifact(art, tmp_path)["status"] == "OK"

    # THE ROUND TRIP MUST PRESERVE BYTES EVERYWHERE BUT THE EDIT. `Path.read_text` takes no
    # `newline` before 3.13, so the byte-for-byte guarantee is made on the WRITE: without it,
    # Windows rewrites every `\n` on the way out and the restore below is not a restore.
    art.write_text(
        art.read_text(encoding="utf-8").replace("a\t9", "a\t999"),
        encoding="utf-8",
        newline="",
    )
    assert runprov.verify.verify_artifact(art, tmp_path)["status"] == runprov.verify.ALTERED

    # THE OTHER DIRECTION, so the test cannot pass by calling everything ALTERED: restore the
    # artifact byte for byte and move the INPUT instead. Same file, opposite verdict.
    art.write_text(
        art.read_text(encoding="utf-8").replace("a\t999", "a\t9"),
        encoding="utf-8",
        newline="",
    )
    (tmp_path / "in.tsv").write_text("MOVED\n", encoding="utf-8")
    assert runprov.verify.verify_artifact(art, tmp_path)["status"] == "STALE"


def test_the_body_digest_covers_the_body_and_not_the_pin(tmp_path, monkeypatch):
    """The digest is of everything AFTER the pin block, and it has to be: a digest that
    covered the pin could never be written into it.

    So an artifact whose pin block is edited is not reported ALTERED by this check — that is
    a real limit and it is asserted rather than left to be discovered. What catches THAT is
    the pin no longer parsing, or its digests no longer matching the inputs."""
    monkeypatch.chdir(tmp_path)
    art = _pinned(tmp_path)
    raw = art.read_bytes()
    pin = runprov.verify.read_pins(art)[0]
    assert raw[pin["body_at"] :] == b"sample\tvalue\na\t9\n", "the offset is the body's start"
    assert hashlib.sha256(raw[pin["body_at"] :]).hexdigest()[:16] == pin["fields"]["body"]


def test_an_artifact_with_no_body_digest_is_not_reported_as_altered(tmp_path, monkeypatch):
    """Every artifact this package wrote before ADR-0006 carries no `body` field, and so does
    every artifact anybody produced another way. "I cannot tell" is the honest answer for
    them — reporting them ALTERED would condemn the entire existing corpus on the day this
    shipped, which is the loudest possible false positive."""
    monkeypatch.chdir(tmp_path)
    art = _pinned(tmp_path)
    stripped = "\n".join(
        ln for ln in art.read_text(encoding="utf-8").splitlines() if "  body " not in ln
    )
    art.write_text(stripped + "\n", encoding="utf-8")
    result = runprov.verify.verify_artifact(art, tmp_path)
    assert result["status"] == "OK", result
    assert not result.get("body_checked"), "and it must not claim to have checked"


def test_the_report_says_how_many_artifacts_could_be_asked_at_all(tmp_path, monkeypatch, capsys):
    """ "0 ALTERED" over artifacts that carry no digest says nothing, and looks exactly like
    "nothing was tampered with" — the negative assertion this repository keeps having to give
    a positive companion. The count of how many COULD be asked is that companion."""
    monkeypatch.chdir(tmp_path)
    _pinned(tmp_path)
    capsys.readouterr()
    assert cli.main(["verify", str(tmp_path), "--root", str(tmp_path)]) == 0
    err = capsys.readouterr().err
    assert "1 of 1 could be asked" in err, err


def test_a_pinned_artifact_appears_once_and_complete_never_half_written(tmp_path, monkeypatch):
    """ADR-0006. The body streams into a temporary file and one rename publishes it, so the
    destination never exists holding a pin whose own digest is still the placeholder.

    Asserted DURING the write, which is the only moment it could be false."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    out = tmp_path / "out.tsv"
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        with run.open_output(out) as fh:
            fh.write("sample\tvalue\n")
            assert not out.exists(), (
                "the artifact must not exist while it is still being written — a reader "
                "would find a pin whose body digest is a placeholder"
            )
            temps = [q for q in tmp_path.iterdir() if q.name.endswith(runprov._atomic.TEMP_SUFFIX)]
            assert len(temps) == 1, f"the body should be in exactly one temporary file: {temps}"
        assert out.exists(), "and it must exist as soon as the handle closes"
    assert runprov.hashing.PIN_BODY_PENDING not in out.read_text(encoding="utf-8")
    assert [q for q in tmp_path.iterdir() if q.name.endswith(runprov._atomic.TEMP_SUFFIX)] == []


def test_a_writer_the_caller_forgot_to_close_is_published_by_the_seal(tmp_path, monkeypatch):
    """Forgetting `close()` must cost the pin's accuracy at worst, never the file. Because
    the body lives in a temporary file until close renames it, a caller who forgets would
    otherwise find NO artifact — which is a far worse failure than the partial one the old
    implementation left."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    out = tmp_path / "out.tsv"
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        fh = run.open_output(out)
        fh.write("sample\tvalue\na\t9\n")  # and never closed
    assert out.is_file(), "the seal must publish what the caller left open"
    assert runprov.verify.verify_artifact(out, tmp_path)["status"] == "OK", (
        "and the digest must be right, not merely present"
    )


def test_a_pin_that_cannot_be_written_leaves_no_temporary_file(tmp_path, monkeypatch):
    """The header is the first thing written into the temporary file. If that write fails —
    a full disk, a directory that vanished — the handle closes and the temporary file goes,
    so a failure to start an artifact does not leave debris beside the one it never made."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        real = builtins.open

        def refuse_the_header(*a, **k):
            fh = real(*a, **k)
            fh.write = lambda *_a, **_k: (_ for _ in ()).throw(OSError("no space left"))
            return fh

        monkeypatch.setattr(runprov.run, "open", refuse_the_header, raising=False)
        with pytest.raises(OSError, match="no space left"):
            run.open_output(tmp_path / "out.tsv")
        monkeypatch.undo()
    assert not (tmp_path / "out.tsv").exists()
    assert [
        q.name for q in tmp_path.iterdir() if q.name.endswith(runprov._atomic.TEMP_SUFFIX)
    ] == []


def test_a_publish_that_fails_leaves_no_artifact_and_no_debris(tmp_path, monkeypatch):
    """The rename is the moment the artifact becomes real. If it cannot happen, the honest
    outcome is NO file — a run that could not finish writing its result did not produce one —
    and the temporary file must not be left where `verify` would meet it."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        fh = run.open_output(tmp_path / "out.tsv")
        fh.write("x\n")
        # ONLY THE ARTIFACT'S RENAME. `os` is one module object, so a blanket patch also
        # breaks the sidecar's own atomic write and the test then fails for the wrong reason
        # — measured: `p.json` was never published.
        real_replace = os.replace
        monkeypatch.setattr(
            runprov.run.os,
            "replace",
            lambda src, dst: (
                (_ for _ in ()).throw(OSError("cannot rename"))
                if str(dst).endswith("out.tsv")
                else real_replace(src, dst)
            ),
        )
        with pytest.raises(OSError, match="cannot rename"):
            fh.close()
        monkeypatch.undo()
    assert not (tmp_path / "out.tsv").exists()
    assert [
        q.name for q in tmp_path.iterdir() if q.name.endswith(runprov._atomic.TEMP_SUFFIX)
    ] == []


def test_the_seal_reports_a_publish_it_could_not_do_and_does_not_end_the_run(
    tmp_path, monkeypatch, capsys
):
    """The rule this module follows everywhere: describing a run may not be what ends one.
    A writer the caller left open that cannot be published is a warning and a lost artifact,
    never an exception out of `__exit__` over work that already succeeded."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        fh = run.open_output(tmp_path / "out.tsv")
        fh.write("x\n")
        real_replace = os.replace  # only the artifact's rename — see the test above
        monkeypatch.setattr(
            runprov.run.os,
            "replace",
            lambda src, dst: (
                (_ for _ in ()).throw(OSError("read-only"))
                if str(dst).endswith("out.tsv")
                else real_replace(src, dst)
            ),
        )
    monkeypatch.undo()
    assert "could not publish out.tsv" in capsys.readouterr().err
    assert json.loads((tmp_path / "p.json").read_text(encoding="utf-8"))["status"] == "ok", (
        "the run finished; only an artifact was lost, and the record says so"
    )


def test_writelines_and_a_second_close_and_a_delegated_attribute_all_behave(tmp_path, monkeypatch):
    """The three parts of the handle's surface that are not `write`.

    `writelines` must feed the hash exactly as `write` does — a body written that way and one
    written line by line are the same bytes and must get the same digest. `close` is
    idempotent, because `with` closes and a caller may close again. And anything the wrapper
    does not define delegates, which is why it wraps rather than subclasses."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    with runprov.Run("s", provenance=tmp_path / "p.json") as run:
        run.input(tmp_path / "in.tsv")
        fh = run.open_output(tmp_path / "out.tsv")
        assert fh.encoding == "utf-8", "an attribute this class does not define must delegate"
        fh.writelines(["sample\tvalue\n", "a\t9\n"])
        fh.close()
        fh.close()  # idempotent: `with` would have done this too
    art = tmp_path / "out.tsv"
    assert art.read_text(encoding="utf-8").endswith("sample\tvalue\na\t9\n")
    assert runprov.verify.verify_artifact(art, tmp_path)["status"] == "OK", (
        "writelines must feed the hash exactly as write does, or the digest is wrong"
    )


def test_an_artifact_that_cannot_be_READ_is_not_reported_as_altered(tmp_path, monkeypatch):
    """ "I could not open it" is not "somebody edited it". The same rule as everywhere else in
    this checker: a failure to ask is never reported as an answer."""
    monkeypatch.chdir(tmp_path)
    art = _pinned(tmp_path)
    # THE PIN IS READ FIRST. Patching `Path.open` before this would break `read_pins` too,
    # and the test would pass on an IndexError rather than on the branch it names.
    pin = runprov.verify.read_pins(art)[0]
    monkeypatch.setattr(
        pathlib.Path, "open", lambda *a, **k: (_ for _ in ()).throw(OSError("unreadable"))
    )
    assert runprov.verify._body_verdict(art, pin) is None


# ------------------------------------- recording a script nobody changed (ADR-0008)


def _capture_project(tmp_path, body, name="summarise.py"):
    """A project with one unmodified script in it, ready for `runprov capture`."""
    (tmp_path / "data").mkdir(exist_ok=True)
    (tmp_path / "results").mkdir(exist_ok=True)
    (tmp_path / "data" / "in.tsv").write_text("sample\tvalue\na\t9\nb\t2\n", encoding="utf-8")
    (tmp_path / name).write_text(body, encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    return tmp_path / name


def test_capture_records_an_unmodified_script(tmp_path, monkeypatch):
    """THE ADOPTION COST, REMOVED. The script contains no `import runprov`, no `run.input`,
    nothing — and the record still names what it read and what it wrote, because the audit
    hook saw the interpreter do it."""
    monkeypatch.chdir(tmp_path)
    _capture_project(
        tmp_path,
        "rows = open('data/in.tsv').read().splitlines()\n"
        "open('results/out.tsv', 'w').write(rows[0] + '\\n')\n",
    )
    assert cli.main(["capture", "summarise.py"]) == 0
    rec = json.loads((tmp_path / "summarise.prov.json").read_text(encoding="utf-8"))
    assert [pathlib.Path(i["path"]).name for i in rec["inputs"]] == ["in.tsv"]
    assert [pathlib.Path(o["path"]).name for o in rec["outputs"]] == ["out.tsv"]
    assert rec["inputs"][0]["sha256"], "an observed input is hashed like any other"
    # NON-VACUITY IN THE OTHER DIRECTION: the script itself is a `.py` and must NOT be
    # recorded as data. A capture that swept up every file the interpreter touched would
    # list the script, the stdlib and site-packages, and be useless rather than wrong.
    names = [pathlib.Path(i["path"]).name for i in rec["inputs"]]
    assert "summarise.py" not in names, names


def test_capture_calls_a_file_it_wrote_an_output_even_if_it_also_read_it(tmp_path, monkeypatch):
    """A script that appends to a table has not taken that table as an INPUT. Recording it as
    both would draw a lineage edge from the file to itself — a cycle in the one graph this
    package exists to keep straight."""
    monkeypatch.chdir(tmp_path)
    (tmp_path / "results").mkdir(exist_ok=True)
    (tmp_path / "results" / "log.tsv").write_text("a\n", encoding="utf-8")
    _capture_project(
        tmp_path,
        "prev = open('results/log.tsv').read()\nopen('results/log.tsv', 'a').write('b\\n')\n",
    )
    assert cli.main(["capture", "summarise.py"]) == 0
    rec = json.loads((tmp_path / "summarise.prov.json").read_text(encoding="utf-8"))
    assert [pathlib.Path(o["path"]).name for o in rec["outputs"]] == ["log.tsv"]
    assert [pathlib.Path(i["path"]).name for i in rec["inputs"]] == [], rec["inputs"]


def test_capture_returns_the_scripts_own_exit_code_and_argv(tmp_path, monkeypatch, capsys):
    """It has to compose in a Makefile exactly as `exec` does, so the wrapped script's exit
    code is the command's exit code — and the script must see the arguments it was given, not
    runprov's."""
    monkeypatch.chdir(tmp_path)
    _capture_project(
        tmp_path, "import sys\nprint('argv', sys.argv[1:])\nsys.exit(int(sys.argv[1]))\n"
    )
    assert cli.main(["capture", "summarise.py", "7"]) == 7
    assert "argv ['7']" in capsys.readouterr().out
    assert sys.argv[0] != "summarise.py", "argv must be restored afterwards"


def test_capture_records_a_script_that_raises_as_a_failed_run(tmp_path, monkeypatch):
    """The failure mode this package exists for: a run that died still has to be on record,
    with what it had read before it died."""
    monkeypatch.chdir(tmp_path)
    _capture_project(
        tmp_path, "open('data/in.tsv').read()\nraise ValueError('the analysis broke')\n"
    )
    with pytest.raises(ValueError, match="the analysis broke"):
        cli.main(["capture", "summarise.py"])
    rec = json.loads((tmp_path / "summarise.prov.json").read_text(encoding="utf-8"))
    assert rec["status"] == "failed" and rec["failure"]["type"] == "ValueError"


def test_capture_writes_the_sidecar_where_it_is_told_to(tmp_path, monkeypatch):
    """`--provenance` names the sidecar; without it the record goes beside the history, named
    for the script. Both are asserted because the default is the one nobody types and so the
    one that goes wrong unnoticed."""
    monkeypatch.chdir(tmp_path)
    _capture_project(tmp_path, "open('data/in.tsv').read()\n")
    # BEFORE THE SCRIPT, and that is the contract rather than an accident: `rest` is
    # `argparse.REMAINDER`, so everything after the script name belongs to the SCRIPT. A flag
    # written afterwards is passed through to it — which is what you want, and worth pinning,
    # because the alternative would have runprov quietly eat a script's own `--provenance`.
    assert cli.main(["capture", "--provenance", str(tmp_path / "sc.json"), "summarise.py"]) == 0
    assert (tmp_path / "sc.json").is_file()
    assert not (tmp_path / "summarise.prov.json").exists(), "the default must not also fire"


def test_capture_says_so_when_there_is_no_such_script(tmp_path, monkeypatch, capsys):
    """Exit 2, `CANNOT_CHECK`: the invocation did not describe a run. Not 1, which would say
    a run happened and something was wrong with it."""
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    assert cli.main(["capture", "nope.py"]) == 2
    assert "no such script" in capsys.readouterr().err


# ------------------------------------- the record in other people's vocabularies (ADR-0009)


def _two_stage(tmp_path):
    """Two runs joined by a real file, so there is a lineage edge to look for."""
    (tmp_path / "data").mkdir(exist_ok=True)
    (tmp_path / "out").mkdir(exist_ok=True)
    (tmp_path / "data" / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    with runprov.Run("step1", provenance=tmp_path / "out/step1.prov.json") as run:
        run.input("data/in.tsv")
        with run.open_output("out/mid.tsv") as fh:
            fh.write("b\n")
    with runprov.Run("step2", provenance=tmp_path / "out/step2.prov.json") as run:
        run.input("out/mid.tsv")
        with run.open_output("out/final.tsv") as fh:
            fh.write("c\n")


def test_export_writes_nothing_the_package_owns(tmp_path, monkeypatch, capsys):
    """THE REQUIREMENT, ASSERTED. Export is a derived view; `runs.jsonl`, the sidecars, the
    YAML twins and `transformation_log.yml` remain the record of truth. A derived view that
    could rewrite its source would be a strange thing for a provenance tool to ship."""
    monkeypatch.chdir(tmp_path)
    _two_stage(tmp_path)
    before = {p: p.read_bytes() for p in sorted(tmp_path.rglob("*")) if p.is_file()}
    assert any(p.name == "transformation_log.yml" for p in before), "the premise: it exists"
    capsys.readouterr()
    assert cli.main(["export", "--format", "ro-crate"]) == 0
    after = {p: p.read_bytes() for p in sorted(tmp_path.rglob("*")) if p.is_file()}
    assert after == before, "export must not touch, add or rewrite a single file"
    assert capsys.readouterr().out.startswith("{"), "and it goes to stdout by default"


@pytest.mark.parametrize("fmt", ["ro-crate", "prov"])
def test_export_joins_the_lineage_across_runs(tmp_path, monkeypatch, capsys, fmt):
    """`out/mid.tsv` is step1's output and step2's input. It must be ONE node in the export,
    or the graph says two files with the same name and the lineage does not join.

    This is where T-08 pays: the key is the recorded path, and every recorded path is spelled
    one way on every platform."""
    monkeypatch.chdir(tmp_path)
    _two_stage(tmp_path)
    capsys.readouterr()
    assert cli.main(["export", "--format", fmt]) == 0
    doc = json.loads(capsys.readouterr().out)
    text = json.dumps(doc)
    assert text.count('"out/mid.tsv"') >= 1, "the joined file must be named"
    if fmt == "ro-crate":
        ids = [n["@id"] for n in doc["@graph"]]
        assert len(ids) == len(set(ids)), f"a repeated @id makes the crate invalid: {ids}"
        assert ids.count("out/mid.tsv") == 1, "one file, one node"
        assert {"ro-crate-metadata.json", "./"} <= set(ids), "both required descriptors"
        actions = [n for n in doc["@graph"] if n.get("@type") == "CreateAction"]
        assert len(actions) == 2, actions
        assert {"@id": "out/mid.tsv"} in actions[0]["result"]
        assert {"@id": "out/mid.tsv"} in actions[1]["object"]
    else:
        assert set(doc["prefix"]) == {"prov", "runprov"}
        assert len(doc["activity"]) == 2 and len(doc["entity"]) == 3, doc
        assert len(doc["wasDerivedFrom"]) == 2, "one derivation per (output, input) per run"
        assert doc["used"] and doc["wasGeneratedBy"] and doc["wasAssociatedWith"]


@pytest.mark.parametrize("fmt", ["ro-crate", "prov"])
def test_export_of_one_run_needs_only_its_sidecar(tmp_path, monkeypatch, capsys, fmt):
    """The scope that matters for a file somebody sent you: no history, no database, one
    sidecar. It is also the scope you attach to a submitted artifact."""
    monkeypatch.chdir(tmp_path)
    _two_stage(tmp_path)
    (tmp_path / "runs.jsonl").unlink()  # the history is GONE; the sidecar is not
    capsys.readouterr()
    assert cli.main(["export", "out/step2.prov.json", "--format", fmt]) == 0
    text = capsys.readouterr().out
    assert "out/final.tsv" in text and "out/mid.tsv" in text
    assert "data/in.tsv" not in text, "one run means one run — step1's input is not in it"


def test_export_says_what_to_do_when_there_is_no_history(tmp_path, monkeypatch, capsys):
    """Exit 2 — could not check — and it must name the scope that WOULD work, because the
    person meeting this most often is holding a sidecar and no history."""
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    assert cli.main(["export"]) == 2
    err = capsys.readouterr().err
    assert "no run history" in err and "runprov export out/step.prov.json" in err


def test_export_to_a_directory_uses_the_formats_own_filename(tmp_path, monkeypatch, capsys):
    """`ro-crate-metadata.json` is not a preference: a crate is RECOGNISED by that filename
    sitting beside the data, so writing it as anything else produces a file no tool looks
    for."""
    monkeypatch.chdir(tmp_path)
    _two_stage(tmp_path)
    (tmp_path / "crate").mkdir()
    assert cli.main(["export", "-o", str(tmp_path / "crate")]) == 0
    assert (tmp_path / "crate" / "ro-crate-metadata.json").is_file()
    assert cli.main(["export", "--format", "prov", "-o", str(tmp_path / "crate")]) == 0
    assert (tmp_path / "crate" / "prov.json").is_file()


def test_export_leaves_out_a_run_that_only_started(tmp_path, monkeypatch, capsys):
    """A `runprov.start.v1` line is a run that has begun and says nothing yet about inputs or
    outputs. In a crate it would assert an activity that produced nothing, which is not what
    a reader would understand by it."""
    monkeypatch.chdir(tmp_path)
    _two_stage(tmp_path)
    log = tmp_path / "runs.jsonl"
    log.write_text(
        log.read_text(encoding="utf-8")
        + json.dumps({"schema": runprov.run.START_SCHEMA, "run_uid": "begun", "script": "step3"})
        + "\n",
        encoding="utf-8",
    )
    capsys.readouterr()
    assert cli.main(["export"]) == 0
    assert "step3" not in capsys.readouterr().out


def test_an_unknown_export_format_is_refused_by_name(tmp_path):
    """The CLI's `choices` catches it first; the function must too, because it is importable
    and a caller who reaches it directly deserves the same answer."""
    with pytest.raises(ValueError, match="unknown export format"):
        runprov.export.render([], "turtle")


def test_export_reports_a_sidecar_it_cannot_read(tmp_path, monkeypatch, capsys):
    """Two ways it is not a sidecar — unreadable, and readable but not an object — and both
    are `could not check` rather than an empty export that looks like a run with nothing in
    it."""
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "runs.jsonl")
    assert cli.main(["export", "nope.prov.json"]) == 2
    assert "cannot read" in capsys.readouterr().err
    (tmp_path / "list.json").write_text("[1, 2]", encoding="utf-8")
    assert cli.main(["export", "list.json"]) == 2
    assert "is not a runprov sidecar" in capsys.readouterr().err


def test_export_reports_a_destination_it_cannot_write(tmp_path, monkeypatch, capsys):
    """Writing the export is the one thing this command does that can fail, and it must fail
    as `could not check` rather than by traceback."""
    monkeypatch.chdir(tmp_path)
    _two_stage(tmp_path)
    monkeypatch.setattr(
        runprov.__main__,
        "atomic_write_text",
        lambda *a, **k: (_ for _ in ()).throw(OSError("read-only")),
    )
    assert cli.main(["export", "-o", str(tmp_path / "c.json")]) == 2
    assert "cannot write" in capsys.readouterr().err


def test_export_describes_a_thin_record_without_inventing_anything():
    """Records are not uniform and the export must not pretend they are.

    A history line trims an input to path and digests; a MISSING output has no digest at all
    and no size; an entry with no `path` cannot be a node in either graph. Each of those is a
    real shape on disk, and the honest response to a missing field is to OMIT it rather than
    emit a null that a validator reads as "known to be nothing"."""
    thin = [
        {
            "run_uid": "u1",
            "script": "s",
            "status": "failed",
            "inputs": [{"path": "a.tsv"}, {"note": "no path at all"}],
            "outputs": [{"path": "b.tsv", "kind": "MISSING"}],
        }
    ]
    crate = runprov.export.to_ro_crate(thin)
    files = {n["@id"]: n for n in crate["@graph"] if n.get("@type") == "File"}
    assert set(files) == {"a.tsv", "b.tsv"}, "the entry with no path is not a node"
    assert "sha256" not in files["a.tsv"] and "contentSize" not in files["a.tsv"]
    assert files["b.tsv"]["description"] == "runprov: MISSING", (
        "a finding must survive into the crate; a tidier description would be of a worse situation"
    )
    action = next(n for n in crate["@graph"] if n.get("@type") == "CreateAction")
    assert action["actionStatus"].endswith("FailedActionStatus")

    doc = runprov.export.to_prov_json(thin)
    assert set(doc["entity"]) == {"runprov:file/a.tsv", "runprov:file/b.tsv"}
    assert "runprov:sha256" not in doc["entity"]["runprov:file/a.tsv"]

    # AN EMPTY DOCUMENT DECLARES NOTHING. A PROV document that says it has entities and lists
    # none means something different from one that does not mention them.
    empty = runprov.export.to_prov_json([])
    assert set(empty) == {"prefix"}, empty


# --------------------------------------------------------------------------- Audit C (2026-09-17)
def test_a_checkpointed_sidecar_is_not_stamped_twice_and_is_not_left_running(tmp_path, capsys):
    """Audit C, C-05. The scope pattern in a third place.

    `write()` refused to re-stamp exactly ONE name — `self.provenance_path`, the constructor's,
    stamped in `__init__` — and that was the complete set until A-01 made `_finish` rebuild the
    record through `write()` for every shape of run. `_finish` then handed back
    `_written_paths[0]`, a name a previous `write()` had ALREADY stamped, and it was stamped a
    second time.

    The consequence is not cosmetic. The rebuilt record landed in the phantom
    `s.<t>.<uid>.<t>.<uid>.prov.json`, and the skip guard below the rebuild then compared the
    original stamped path against the un-stamped `rebuild` value, found them equal, and skipped
    the re-persist — so the sidecar the caller named, the one `write()` HANDED BACK for logging
    or archiving, kept the checkpoint's `status: "running"` and empty `outputs` permanently, on
    a run that succeeded.

    The remedy is the one this project keeps relearning: DERIVE the exclusion (any name this
    run has already written) rather than extend a list of one.
    """
    runprov.configure(
        root=tmp_path, run_log=tmp_path / "h.jsonl", auto_steps="off", sidecar_per_run=True
    )
    with runprov.Run("demo", {}) as run:
        returned = run.write(tmp_path / "s.prov.json")  # the documented mid-run checkpoint
        (tmp_path / "late.tsv").write_text("a\n", encoding="utf-8")
        run.output(tmp_path / "late.tsv")

    written = sorted(p.name for p in tmp_path.glob("*.prov.json"))
    assert len(written) == 1, f"one sidecar, not a phantom twin beside it: {written}"
    assert returned.name == written[0], "and it is the path write() handed back"
    assert written[0].count("Z.") == 1, f"stamped once: {written[0]}"

    sealed = json.loads(returned.read_text(encoding="utf-8"))
    assert sealed["status"] == "ok", "the caller's own sidecar carries the terminal status"
    assert sealed["finished_utc"], "not a checkpoint's null"
    assert [pathlib.Path(o["path"]).name for o in sealed["outputs"]] == ["late.tsv"], (
        "and the late artifact, which the pre-fix record dropped entirely"
    )
    capsys.readouterr()


def test_the_dropped_watch_count_is_distinct_paths_and_reaches_the_record(tmp_path, monkeypatch):
    """Audit C, C-06 and C-10 — the two halves A-11 left.

    C-06: `+= 1` fired per audit EVENT, and a dropped path never enters `_opened`, so a loop
    re-reading one reference file 1 000 times past the cap recorded
    `unregistered_watch_truncated: 1000` for a single lost file. The field's own docstring, the
    commit that added it and the test beside it all say DISTINCT paths. An overstatement
    written into the permanent record is the worst class of defect this package has.

    C-10: A-11's regression test drove a local stub and stopped at the private counter, so the
    record field the whole row exists to produce survived being deleted outright — mutating
    `if self._opened_dropped:` to `if False:` left the suite green. It is asserted on a REAL
    run here, in the history line, which is where a reader three years later finds it.
    """
    monkeypatch.setattr(runprov.watch, "WATCH_MAX_PATHS", 3)  # INJECTED: the bound is the
    cap = runprov.watch.WATCH_MAX_PATHS  # subject, not this host's open-file behaviour
    watcher = runprov.watch._Watcher()

    class _Run:
        def __init__(self):
            self._opened, self._opened_write = set(), set()

    run = _Run()
    watcher._active.append(run)
    for i in range(cap + 1):
        watcher._hook("open", (str(tmp_path / f"{i}.tsv"), "r"))
    assert len(run._opened) == cap and run._opened_dropped == 1, "one distinct path over it"

    for _ in range(1000):  # the ordinary shape: a loop re-reading one reference file
        watcher._hook("open", (str(tmp_path / "reference.fa"), "r"))
    assert run._opened_dropped == 2, (
        "a thousand opens of ONE further path is one further path — this read 1001 before C-06"
    )

    watcher._hook("open", (str(tmp_path / "second.fa"), "r"))
    assert run._opened_dropped == cap, "and a genuinely distinct one does count"

    # AND IT IS A FLOOR, DECLARED AS ONE. The set of dropped paths is bounded by the SAME cap
    # as `_opened`, so the memory this bound exists to protect is at most doubled and never
    # unbounded. Past that the count stops rising — which is why every reader says "at least",
    # a saturated count that reads as exact being the same lie in the other direction.
    for i in range(20):
        watcher._hook("open", (str(tmp_path / f"extra{i}.tsv"), "r"))
    assert run._opened_dropped == cap, "saturated, and honest about being a floor"
    assert len(run._opened_dropped_paths) == cap


def test_the_truncated_watch_is_recorded_and_every_reader_says_so(tmp_path, monkeypatch, capsys):
    """Audit C, C-06 (second half) and C-10. The field was written by one line and read by
    nothing: `grep -rn unregistered_watch_truncated runprov/` returned only the write site.

    Every reader that exists to say "this absence is not evidence" still keyed on
    `unregistered_reads` alone — so two runs that both hit the cap both record an EMPTY list,
    `runprov diff` printed `inputs unchanged (3 vs 3)` and exited 0 over a census both runs
    knew was incomplete, `runprov report` printed its observation block with no qualification,
    and `runprov impact` omitted the largest thing it had not seen.
    """
    monkeypatch.chdir(tmp_path)
    monkeypatch.setattr(runprov.watch, "WATCH_MAX_PATHS", 1)  # INJECTED, not this host's load
    (tmp_path / "data").mkdir()
    for name in ("in.tsv", "lookup.csv", "other.csv"):
        (tmp_path / "data" / name).write_text("a\n", encoding="utf-8")
    runprov.configure(root=tmp_path, run_log=tmp_path / "h.jsonl", auto_steps="off")

    with runprov.Run("misses", provenance=tmp_path / "p.json") as run:
        with open(run.input(tmp_path / "data" / "in.tsv"), encoding="utf-8") as fh:
            fh.read()
        for name in ("lookup.csv", "other.csv"):
            with open(tmp_path / "data" / name, encoding="utf-8") as fh:
                fh.read()
        with run.open_output(tmp_path / "out.tsv") as fh:
            fh.write("x\n")
    capsys.readouterr()

    record = _lines(tmp_path / "h.jsonl")[-1]
    dropped = record["observation"]["unregistered_watch_truncated"]
    assert dropped >= 1, "the cap bit, and the record says so — in the history, not in a stub"

    # `runprov report` — the page a reader consults to judge ONE artifact.
    page = runprov.report.page(tmp_path / "out.tsv", tmp_path, [record])
    assert any("WATCH TRUNCATED" in line for line in page.lines), page.lines

    # `runprov diff` — the gate. Two records that both hit the cap must not compare clean.
    dimension = next(d for d in runprov.diff.compare(record, record) if d.name == "inputs")
    assert dimension.blocked and "partial census" in dimension.blocked
    assert not dimension.settled, "a gate may not go green over a census known to be partial"

    # `runprov impact` — the blind-spot tally, which counted only the reads a run MANAGED to
    # report and was silent about the ones dropped before they could be.
    #
    # THROUGH THE COMMAND, not by constructing a `Chain` by hand. The first version of this
    # assertion built one with the count already in it, which tested `render` and left the
    # wiring that FILLS the field unguarded — mutating the sum in `_impact` to `+= 0` kept the
    # suite green. A line can be covered without being tested; the seam has to be the real one.
    runprov.__main__.main(
        ["impact", str(tmp_path / "data" / "in.tsv"), "--log", str(tmp_path / "h.jsonl")]
    )
    assert "dropped by the watch itself" in capsys.readouterr().out


def test_a_truncated_impact_walk_cannot_check_rather_than_passing(tmp_path, capsys):
    """Audit C, C-07. A-09 named two halves and only the sentence was fixed.

    `--depth 0` empties `steps` while `seeds` stays non-empty, and the command returned 0 —
    the code that means "checked, and nothing is wrong", identical to the code for a file
    nothing ever read. A pre-overwrite guard written as `runprov impact ref.fa --depth 0 ||
    abort` goes green and the reference is overwritten with derived artifacts in the history.
    `--depth 0` is the natural spelling for "just the direct readers", and for "no limit" in
    many tools.

    2 is COULD NOT CHECK (`__main__.py`'s own convention), which is exactly what a walk cut off
    before it reached a single consumer is. A-09's test asserted only the new message, so the
    exit code could have stayed 0 forever without the suite noticing — it is asserted here.
    """
    runprov.configure(root=tmp_path, run_log=tmp_path / "h.jsonl", auto_steps="off")
    (tmp_path / "ref.fa").write_text(">r\nACGT\n", encoding="utf-8")
    with runprov.Run("align", provenance=tmp_path / "a.prov.json") as run:
        run.input(tmp_path / "ref.fa")
        with run.open_output(tmp_path / "aligned.tsv") as fh:
            fh.write("x\n")
    capsys.readouterr()

    argv = ["impact", str(tmp_path / "ref.fa"), "--log", str(tmp_path / "h.jsonl")]
    assert runprov.__main__.main(argv) == 1, "something derives from it: checked, and it matters"
    assert "artifact(s) derive" in capsys.readouterr().out

    assert runprov.__main__.main([*argv, "--depth", "0"]) == 2, (
        "truncated is COULD NOT CHECK, not a clean bill of health"
    )
    assert "TRUNCATED" in capsys.readouterr().out


def test_a_pinned_sidecars_temporary_file_is_not_world_readable_while_it_is_written(tmp_path):
    """Audit C, C-08. A-13 tightened the PUBLISHED mode and left the temp file at the umask
    default for the whole write block — so a result deliberately restricted to 0600 sat beside
    its own destination as a group-readable `.name.<hex>.runprov-tmp` for as long as the run
    took to produce it, which on an eight-hour job is eight hours. The window A-13 closed at
    the end was open at the start.

    The mode is applied immediately after creation rather than passed to `os.open`: two tests
    inspect the `open()` call this class makes, because `newline=""` is load-bearing, and
    bypassing `open` broke that seam. The residual exposure is microseconds against hours, and
    it is not zero.
    """
    # A `.tsv`, because the pin goes INSIDE the artifact for a format that holds a comment —
    # which is what makes `_PinnedWriter` the handle, and the temp file the subject here.
    dest = tmp_path / "restricted.tsv"
    dest.write_text("old\n", encoding="utf-8")
    dest.chmod(0o600)
    # THE DESTINATION'S OWN MODE, READ BACK, not the literal 0o600 that was asked for —
    # eighth instance this session of a test leaning on what the HOST supplies. Windows has
    # no POSIX mode bits: `chmod` there toggles the read-only attribute and nothing else, so
    # `stat()` reports 0o666 for the same call and the literal failed on that leg alone. The
    # invariant this row is about is "the temp file carries the DESTINATION's mode", which is
    # true on both and is what is asserted.
    restricted = stat.S_IMODE(dest.stat().st_mode)
    if os.name == "posix":  # and where the mode means something, it still means 0o600
        assert restricted == 0o600

    runprov.configure(root=tmp_path, run_log=tmp_path / "h.jsonl", auto_steps="off")
    seen = []
    with runprov.Run("tight", provenance=tmp_path / "p.json") as run:
        with run.open_output(dest) as fh:
            # MID-WRITE, which is the whole window: the mode is asserted while the body is
            # still streaming, not after `os.replace` has published it.
            seen.append(stat.S_IMODE(pathlib.Path(fh._tmp).stat().st_mode))
            fh.write("x\n")

    assert seen == [restricted], f"the temp file carries the destination's mode from birth: {seen}"
    assert stat.S_IMODE(dest.stat().st_mode) == restricted, "and the published file still does"


def test_a_snapshot_whose_bytes_do_not_match_its_name_is_rewritten(tmp_path, monkeypatch):
    """Audit C, C-11. A-15 fixed the bytes NEW snapshots are written with and left every
    pre-fix one wrong forever.

    The name is derived from the digest, so a snapshot written by an older version on Windows
    — CRLF, hashing to something other than the `d` its own name asserts — sits at exactly the
    path `write_snapshot` would reuse. Deciding by NAME alone reported it `reused: true`, which
    is the record's way of saying "the environment has not moved", over a file whose recorded
    sha256 does not describe it. `sha256sum -c` on that line fails for a file nobody touched.
    """
    store = tmp_path / "env"
    first = runprov.environment.write_snapshot(store)
    assert first["reused"] is False
    path = pathlib.Path(first["path"])

    assert runprov.environment.write_snapshot(store)["reused"] is True, "identical: reused"

    # The pre-fix Windows shape, reproduced exactly: the right name, the wrong bytes.
    good = path.read_bytes()
    path.write_bytes(good.replace(b"\n", b"\r\n"))
    again = runprov.environment.write_snapshot(store)
    assert again["reused"] is False, "content that does not hash to its own name is not reusable"
    assert path.read_bytes() == good, "and it is rewritten, not left wrong forever"
    assert runprov.environment.digest(path.read_text(encoding="utf-8")) == again["sha256"]

    # UNREADABLE IS NOT REUSABLE EITHER, and the read must not end the run. Injected rather
    # than chmod'ed, so this is the same assertion on every platform and as every user.
    def _refuse(self):
        raise OSError("EACCES")

    monkeypatch.setattr(pathlib.Path, "read_bytes", _refuse)
    assert runprov.environment.write_snapshot(store)["reused"] is False


def test_the_pypi_readme_names_every_command_the_cli_offers(capsys):
    """The gap that shipped at 0.3.0, at 0.4.0 and again at 0.5.0 — caught each time by a
    person looking, which is not a gate.

    `README-pypi.md` is frozen into the wheel at upload and is the ONLY page most people who
    install this ever read; the repository README is not on PyPI. Three releases in a row added
    a command and left that page describing the previous release.

    DERIVED FROM THE PARSER, never a list beside one: a list is exactly what fell out of date.
    The omissions are the part that is stated by hand, because they are decisions — and a
    decision that has to be written down is one somebody has to defend when it changes.
    """

    def _commands(capsys):
        with contextlib.suppress(SystemExit):
            runprov.__main__.main(["--help"])
        found = re.search(r"\{([a-z,]+)\}", capsys.readouterr().out)
        assert found, "the help text no longer lists its subcommands; this test reads nothing"
        return found.group(1).split(",")

    #: Deliberately not on the PyPI page. `exec` and `prune` are operational rather than
    #: analytical — one runs a foreign script, the other trims a history — and the page is an
    #: argument for adopting the package, not its manual. `lineage` is the DAG that `diff` and
    #: `impact` are the two useful questions about; both of those ARE on the page.
    not_on_the_pypi_page = {"exec", "prune", "lineage"}

    page = pathlib.Path(runprov.__file__).resolve().parent.parent / "README-pypi.md"
    if not page.is_file():  # pragma: no cover - an installed wheel, not a checkout
        pytest.skip("not a source checkout")
    text = page.read_text(encoding="utf-8")
    commands = _commands(capsys)
    assert len(commands) > 5, "the parser shape moved; this test is reading nothing"
    missing = [c for c in commands if c not in not_on_the_pypi_page and f"runprov {c}" not in text]
    assert not missing, (
        f"README-pypi.md is frozen into the wheel and does not name: {missing}. Add them to "
        f"the page, or add them to not_on_the_pypi_page with the reason."
    )


# ----------------------------------------------------- the cross-version record corpus
# `tools/corpus.py` and `tools/corpus_scenario.py` build these trees by installing each
# RELEASED wheel from PyPI and running one fixed scenario under it. What follows holds today's
# package to records today's package did not write — the only hole the rest of this file
# structurally cannot cover, because every other test builds a record with the code that reads
# it. Audit C's C-03 lived in that hole: `sha256_tree` silently moved on Linux and macOS inside
# a fix meant to stop it depending on the machine, every directory input pinned by 0.1.0-0.4.0
# would have verified STALE with nothing touched, and the suite was green throughout.
from tools import corpus as corpus_tool  # noqa: E402 - after the fixtures it shares

CORPUS_VERSIONS = corpus_tool.corpus_versions()

#: How to point each command at a materialised tree, from inside it. DERIVED against the
#: parser below, so a new subcommand fails this file until it is either given a recipe or
#: named as a deliberate omission WITH ITS REASON — the shape that stopped `README-pypi.md`
#: shipping a release behind for the fourth time.
CORPUS_RECIPES: dict[str, list[str]] = {
    "log": ["log", "--log", "prov/history.jsonl"],
    "show": ["show", "--log", "prov/history.jsonl"],
    "lineage": ["lineage", "--log", "prov/history.jsonl"],
    "verify": ["verify", "out/align.tsv"],
    "report": ["report", "out/summarise.tsv", "--log", "prov/history.jsonl"],
    "impact": ["impact", "data/m.tsv", "--log", "prov/history.jsonl"],
    "resources": ["resources", "--log", "prov/history.jsonl"],
    "diff": ["diff", "align", "genotype", "--log", "prov/history.jsonl"],
    "export": ["export", "prov/align.prov.json"],
    "check": ["check", "."],
    "chain": ["chain", "prov/history.jsonl"],
    # T-34. THE ONE RECIPE THAT NEEDS A SECOND FILE, written into the materialised tree by the
    # test below. This is the most interesting row in the table: today's rules against records
    # written by every released wheel, where `observation` did not exist at all in the earliest of
    # them — so `environment_captured` must answer CANNOT_CHECK for those rather than accusing a
    # year-old run of recording nothing.
    #: `--format json` IS PART OF THE RECIPE [K-40]. The whole assertion used to be
    #: `code in (0, 1, 2)`, and the comment above claimed a behaviour the exit code cannot
    #: carry. PROVED: a derived policy naming ZERO rules sends `load()` down its refusal path,
    #: exit 2 with **0 bytes on stdout** — inside the legal set — and all seven parametrised
    #: versions stayed green. With every rule it also exits 2, with a 3 274-byte page, and the
    #: assertion could not tell the two apart. The payload is what distinguishes them.
    "gate": ["gate", "--policy", "policy.json", "--log", "prov/history.jsonl", "--format", "json"],
}

#: Not pointed at the corpus, with the reason. `exec` and `capture` CREATE a run rather than
#: reading one, so they would write into the fixture rather than interrogate it; `prune`
#: deletes in-flight markers, and a test that mutates the corpus is a test that changes its
#: own subject between runs.
#:
#: AND THAT REASON IS ABOUT THE CORPUS, NOT ABOUT `prune` [Audit Q, decision-1]. It was read for
#: six audits as *no behavioural leg may ever reach `prune`*, and a live forgery in
#: `prune.apply` sat behind that reading with every structural check silent. A leg that stubs
#: `plan` touches no filesystem and deletes nothing:
#: `test_prune_does_not_forge_a_line_from_a_marker_filename` is that leg, it is
#: platform-neutral, and it is what holds the five shapes the AST derivation cannot see.
CORPUS_NOT_READERS = {"exec", "capture", "prune"}


def _corpus_commands(capsys) -> list[str]:
    with contextlib.suppress(SystemExit):
        runprov.__main__.main(["--help"])
    found = re.search(r"\{([a-z,]+)\}", capsys.readouterr().out)
    assert found, "the help text no longer lists its subcommands; this test reads nothing"
    return found.group(1).split(",")


@pytest.mark.skipif(not CORPUS_VERSIONS, reason="no corpus — tools/corpus.py generate --all")
@pytest.mark.parametrize("version", CORPUS_VERSIONS)
def test_a_record_written_by_a_released_version_still_verifies(version, tmp_path, monkeypatch):
    """THE ORACLE. Every artifact every released wheel ever wrote must still verify OK.

    This is the assertion the whole harness exists for, and it is cheap only because the
    expensive half — installing four wheels from PyPI and running a fixed scenario under each
    — was paid once and committed. `verify` re-derives the pinned digests from the artifact
    alone, so a green here means today's hashing agrees with 0.1.0's, 0.2.0's, 0.3.0's and
    0.4.0's, byte for byte, including `sha256_tree` over a nested directory.

    VERIFIED AS A POSITIVE CONTROL, which is the only reason to believe it: reinstating C-03's
    sort key in a copied tree turns the `align` artifact STALE in all four versions at once.
    The other two artifacts stay OK because only `align` pins the directory, and that is the
    correct answer rather than a weakness — a control that reddened everything would not
    distinguish this defect from a broken harness.
    """
    tree = corpus_tool.materialise(version, tmp_path / "tree")
    monkeypatch.chdir(tree)
    runprov.configure(root=".", run_log="prov/history.jsonl")

    artifacts = sorted(p.name for p in (tree / "out").glob("*.tsv"))
    assert artifacts, f"{version} materialised no artifacts — an empty tree passes everything"

    for name in artifacts:
        result = runprov.verify.verify_artifact(pathlib.Path("out") / name, pathlib.Path("."))
        assert result["status"] == runprov.verify.OK, (
            f"{version} wrote out/{name} and this version no longer agrees with its pin: "
            f"{result.get('status')} {result.get('reason', '')}"
        )
        # OK IS NOT ENOUGH ON ITS OWN, and a mutation proved it rather than a review: renaming
        # `PIN_BODY_FIELD` from `body` makes the reader find no body digest in these older
        # artifacts, skip the check entirely — which is CORRECT for an artifact written before
        # that field existed — and still report OK. The status then means "nothing was found
        # wrong with what I looked at", and what it looked at had quietly become nothing.
        # `body_checked` is the positive companion, and these artifacts all carry a body.
        assert result["body_checked"] is True, (
            f"out/{name}: the artifact's own bytes were NOT re-derived, so OK means nothing"
        )
        assert result["pins"] >= 1, f"out/{name}: no pin block was read"
        statuses = {i.get("name"): i.get("status") for i in result["inputs"]}
        assert statuses, f"out/{name}: the pin names no inputs, so no digest was re-derived"
        assert set(statuses.values()) == {runprov.verify.OK}, f"out/{name}: {statuses}"


@pytest.mark.skipif(not CORPUS_VERSIONS, reason="no corpus — tools/corpus.py generate --all")
@pytest.mark.parametrize("version", CORPUS_VERSIONS)
def test_every_command_reads_a_history_written_by_a_released_version(
    version, tmp_path, monkeypatch, capsys
):
    """No command may traceback on an old record, and none may invent a verdict for one.

    The exit-code contract (`__main__.py`) is the whole assertion: 0 checked-and-clean, 1
    checked-and-something-is-wrong, 2 could-not-check. A traceback is none of the three, and
    it is what a reader of a year-old history actually meets when a field has quietly changed
    shape. Audit B's A-03 was exactly this — `runprov diff` raised `TypeError: 'int' object is
    not iterable` for any project that had ever used `@run.step`, because the history stores a
    COUNT of steps and the sidecar stores the list.
    """
    tree = corpus_tool.materialise(version, tmp_path / "tree")
    monkeypatch.chdir(tree)
    # `gate` NEEDS A POLICY AS WELL AS A HISTORY, and the corpus contains none: the trees are what
    # each released wheel WROTE, and a policy is what a project writes about them. Written into the
    # materialised copy — which is a tmp tree, not the committed corpus — and naming EVERY
    # registered rule, derived, so a rule added later is pointed at old records on the day it
    # exists. The assertion is the exit-code contract below: no rule may traceback on a record
    # written before it was conceived, and none may invent a verdict for one.
    (tree / "policy.json").write_text(
        json.dumps(
            {
                "rules": [
                    {"rule": name, "why": "exercised against a released version's records"}
                    for name in sorted(runprov.policy.rules())
                ]
            }
        ),
        encoding="utf-8",
    )

    commands = _corpus_commands(capsys)
    unrecipe = [c for c in commands if c not in CORPUS_RECIPES and c not in CORPUS_NOT_READERS]
    assert not unrecipe, (
        f"new subcommand(s) {unrecipe} are not exercised against the corpus. Add a recipe to "
        f"CORPUS_RECIPES, or name them in CORPUS_NOT_READERS with the reason."
    )

    #: THE TREE'S OWN RECORD COUNT, read from the history this version wrote rather than
    #: assumed, because it is what `gate`'s payload is held to below [K-40].
    lines = [
        json.loads(line)
        for line in (tree / "prov" / "history.jsonl").read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    written = [r for r in lines if r.get("schema") != runprov.run.START_SCHEMA]
    assert len(written) >= 3, f"{version}: the tree holds {len(written)} record(s); the premise"

    checked = 0
    for name, argv in CORPUS_RECIPES.items():
        if name not in commands:  # pragma: no cover - a command was removed, not added
            continue
        runprov.configure(root=".", run_log="prov/history.jsonl")
        try:
            code = runprov.__main__.main(list(argv))
        except SystemExit as exc:  # argparse's own exits are still exits, not tracebacks
            code = exc.code if isinstance(exc.code, int) else 2
        except Exception as exc:  # the thing under test is that this never happens
            pytest.fail(f"{version}: `runprov {' '.join(argv)}` raised {type(exc).__name__}: {exc}")
        shown = capsys.readouterr()
        out = shown.out
        assert code in (0, 1, 2), f"{version}: `runprov {name}` exited {code}"
        #: AND THE PROPERTY L-03 IS HELD BY, MEASURED AGAINST EVERY RELEASED WHEEL'S RECORDS.
        #: The escaping guard asserts *no character a terminal acts on* over a FORGED history;
        #: this is the other half, and the half that makes the property a universal rather than
        #: a rule with exemptions beside it: over the real records of all seven released
        #: versions it is already true, so nothing legitimate is escaped away. Measured when
        #: this was written: 2 098 lines across twelve recipes and seven histories, zero
        #: characters a terminal acts on.
        assert _acted_on(out + shown.err) == [], (
            f"{version}: `runprov {name}` printed {_acted_on(out + shown.err)} over a RELEASED "
            f"wheel's own records — so the escaping property has a false positive, and a page "
            f"is being mangled rather than protected"
        )
        if name == "gate":
            #: AND THE GATE REALLY RAN TODAY'S RULES AGAINST THIS VERSION'S RECORDS [K-40]. This
            #: is the only check in the suite that points today's rules at an earlier release's
            #: history, and until now it could not tell *the gate answered* from *the gate
            #: refused to start*. `json.loads` is the first half: the zero-rule refusal that
            #: proved the hole emits nothing at all, so it fails here before any assertion.
            body = json.loads(out)
            assert body["schema"] == runprov.policy.SCHEMA, body.get("schema")
            assert [row["rule"] for row in body["rules"]] == sorted(runprov.policy.rules()), (
                f"{version}: the policy written above names every registered rule, so the answer "
                f"must carry a row for each: {[row['rule'] for row in body['rules']]}"
            )
            assert body["runs"] == len(written), (
                f"{version}: the gate examined {body['runs']} of the {len(written)} record(s) "
                f"this version wrote"
            )
            for row in body["rules"]:
                assert row["evaluated"] == len(written), (
                    f"{version}: `{row['rule']}` was evaluated against {row['evaluated']} of "
                    f"{len(written)} record(s), so this recipe's green is partly vacuous: {row}"
                )

            #: AND THE OUTCOME IS RE-DERIVED FROM THE PAYLOAD'S OWN TALLIES [L-17]. This recipe
            #: asserted the schema, the rule-row set, `runs` and each rule's `evaluated` — and
            #: **NO OUTCOME AT ALL**, which is the one thing a corpus oracle exists to be an
            #: oracle for. Mutating `assess`'s fold so a MET majority outranks a single
            #: inability flipped `inputs_verify` from CANNOT_CHECK to **MET on all seven
            #: released histories** — `GATE: MET (exit 0)` printed above its own page line
            #: reading `1 not checked` — and this recipe stayed RC=0. ADR-0018 R-3's central
            #: claim broken at the fold, over every released history, with the oracle green.
            #:
            #: **AND THE CAUSE WAS A PROCESS ERROR RATHER THAN AN OVERSIGHT**, which is why the
            #: paragraph this replaces is quoted below instead of deleted: K-40's remedy
            #: correctly refuted the clause it was handed — *every rule's `outcome !=
            #: VIOLATED`*, which is red on day one because `tools/corpus_scenario.py` reads
            #: `data/lookup.csv` **unregistered on purpose**, so `no_unregistered_reads` answers
            #: VIOLATED on six of the seven histories and CANNOT_CHECK on 0.1.0, correctly —
            #: **and wrote no substitute.** The refutation closed the proposed FORM of the
            #: assertion and was read as closing the REQUIREMENT. A refuted remedy leaves its
            #: requirement open.
            #:
            #: **AND THE REMEDY FILED FOR *THIS* ROW WAS REFUTED TOO, measured.** A declared
            #: `CORPUS_VERDICTS` table asserted by equality is green today and raises a bare
            #: `KeyError` the first time an eighth wheel is captured — **red on correct code, on
            #: the one act `corpus_versions()` was written to make free.** So the second side is
            #: DERIVED from the payload itself: each row's own `violated` / `not_checked` /
            #: `evaluated` counts must fold to the `outcome` the row states, and the row set
            #: must fold to the top-level one. **Version-free and scenario-free**: it says
            #: nothing about which rule answers what on which release, so a new wheel and a
            #: changed scenario both cost nothing, and a fold that stops respecting R-3's
            #: precedence is red on every history at once.
            def folded(violated: int, not_checked: int, evaluated: int) -> str:
                #: R-3's PRECEDENCE, in the order the ADR states it: a violation outranks an
                #: inability, because knowing part of a list is knowing a breach; an inability
                #: outranks a pass, because an unexamined run is never one; and a rule asked of
                #: nothing could not answer either.
                if violated:
                    return runprov.policy.VIOLATED
                if not_checked or not evaluated:
                    return runprov.policy.CANNOT_CHECK
                return runprov.policy.MET

            for row in body["rules"]:
                want = folded(row["violated"], row["not_checked"], row["evaluated"])
                assert row["outcome"] == want, (
                    f"[ADR-0018 R-3] [L-17] {version}: `{row['rule']}` states outcome "
                    f"{row['outcome']} while its own counts are violated={row['violated']}, "
                    f"not_checked={row['not_checked']}, evaluated={row['evaluated']}, which fold "
                    f"to {want}. A rule that calls an unexamined run a pass is R-3's whole "
                    f"subject, and this is the only check in the suite that sees it over a "
                    f"released wheel's records"
                )
            outcomes = {row["outcome"] for row in body["rules"]}
            top = next(
                outcome
                for outcome in (
                    runprov.policy.VIOLATED,
                    runprov.policy.CANNOT_CHECK,
                    runprov.policy.MET,
                )
                if outcome in outcomes
            )
            assert body["outcome"] == top, (
                f"[ADR-0018 R-3] [L-17] {version}: the gate answered {body['outcome']} over rows "
                f"answering {sorted(outcomes)}; the top of that set is {top}"
            )

            #: AND THE TEXT PAGE, OVER THE SAME TREE [L-22]. Widening this recipe to assert the
            #: payload switched it off the DEFAULT renderer, so `gate`'s page became the only
            #: one of twelve recipes never rendered against any released wheel's history — the
            #: other eleven all still run the default. What that lost is this branch's own
            #: `except Exception -> pytest.fail` over the gate's TEXT renderer for records
            #: written by every released wheel, **including 0.1.0, which has no `observation`
            #: block at all** — and the text page is exactly where K-21 found a defect two
            #: commits later. It also puts K-21's territory under the corpus for the first time.
            runprov.configure(root=".", run_log="prov/history.jsonl")
            try:
                shown_code = runprov.__main__.main(
                    [arg for arg in argv if arg not in ("--format", "json")]
                )
            except SystemExit as exc:
                shown_code = exc.code if isinstance(exc.code, int) else 2
            except Exception as exc:
                pytest.fail(
                    f"{version}: `runprov gate` rendered as TEXT raised {type(exc).__name__}: {exc}"
                )
            page = capsys.readouterr().out
            assert shown_code == body["exit_code"], (
                f"[ADR-0017 R-1] {version}: the page exited {shown_code} and the payload says "
                f"{body['exit_code']} — one answer, two renderings"
            )
            assert page.strip(), f"{version}: the gate rendered an empty page"
            assert page.count("GATE: ") == 1, (
                f"[K-21] {version}: the page carries {page.count('GATE: ')} verdict lines, and "
                f"exactly one of them can be the real one:\n{page}"
            )
        checked += 1
    assert checked >= 8, f"only {checked} commands were run against {version}"


@pytest.mark.skipif(not CORPUS_VERSIONS, reason="no corpus — tools/corpus.py generate --all")
def test_the_corpus_describes_the_scenario_that_actually_exists(tmp_path):
    """A corpus is only meaningful as *what version X did with scenario S*.

    Edit the scenario without rebuilding the trees and every assertion above still passes while
    describing a scenario that no longer exists — a green over nothing, which is the failure
    this harness was built to stop and therefore the one it may not introduce. The scenario's
    digest is recorded at generation and compared here.

    Also asserted: the corpus carries no absolute path from the machine that built it, with a
    PLANTED one to prove the scanner works. "No leaks found" and "nothing was scanned" are the
    same green.
    """
    manifest = json.loads((corpus_tool.CORPUS / "MANIFEST.json").read_text(encoding="utf-8"))
    assert manifest["scenario_sha256"] == corpus_tool.scenario_digest(), (
        "tools/corpus_scenario.py has changed since the corpus was built. Regenerate it with "
        "`python tools/corpus.py generate --all`, or the trees describe a scenario that is gone."
    )
    assert sorted(manifest["versions"]) == sorted(CORPUS_VERSIONS)

    for version in CORPUS_VERSIONS:
        tree = corpus_tool.CORPUS / version / "tree"
        assert not corpus_tool.leaks(tree), f"{version} carries paths from the build machine"

    planted = corpus_tool.materialise(CORPUS_VERSIONS[0], tmp_path / "planted")
    (planted / "prov" / "planted.json").write_text('{"cwd": "/home/someone/x"}', encoding="utf-8")
    assert corpus_tool.leaks(planted), (
        "the leak scanner does not work, so its silence means nothing"
    )


@pytest.mark.skipif(len(CORPUS_VERSIONS) < 2, reason="needs two released versions")
def test_identical_bytes_produced_identical_digests_in_every_released_version():
    """The sharpest thing the corpus makes sayable, and it needs no re-derivation at all.

    Every version ran the same scenario over byte-identical inputs, so every version should
    have PINNED the same digests. Comparing the recorded values directly — 0.1.0's against
    0.4.0's — states "the digest has not moved" as a fact about what was written, rather than
    inferring it from today's reader agreeing with today's re-derivation.

    `data/refs` is the one that matters and it is asserted by name: it is a DIRECTORY, so its
    entry is a `sha256_tree` over nested paths whose separator competes with `.` and `-`, and
    that is the exact quantity C-03 moved. A test that happened to cover only flat files would
    read as covering this and would not.
    """
    pinned: dict[str, dict[str, str]] = {}
    for version in CORPUS_VERSIONS:
        tree = corpus_tool.CORPUS / version / "tree"
        blocks = runprov.verify.read_pins(tree / "out" / "align.tsv")
        assert blocks, f"{version}: align.tsv carries no pin"
        pinned[version] = {name: digest for digest, name in blocks[0]["entries"]}
        assert "data/refs" in pinned[version], (
            f"{version} pinned {sorted(pinned[version])} — the DIRECTORY input is missing, so "
            f"sha256_tree is not under test and C-03 could recur unseen"
        )

    reference = pinned[CORPUS_VERSIONS[0]]
    for version, entries in pinned.items():
        assert entries == reference, (
            f"{version} recorded different digests from {CORPUS_VERSIONS[0]} for byte-identical "
            f"inputs. A digest that moves between releases re-pins every artifact at once — "
            f"the failure the record-format promise in README.md exists to forbid.\n"
            f"  {CORPUS_VERSIONS[0]}: {reference}\n  {version}: {entries}"
        )


@pytest.mark.skipif(len(CORPUS_VERSIONS) < 2, reason="needs two released versions")
def test_the_record_schema_has_not_moved_across_any_released_version():
    """`schema` is the field a future reader keys compatibility off, so it is not free to drift.

    If this ever fails the answer is not to update the constant: it is that a record-format
    change happened, and the README's record-format promise says that is the one kind of
    change this package documents rather than absorbs. The corpus is what makes the question
    answerable at all — before it, nothing in the suite had ever seen last year's `schema`.
    """
    seen: dict[str, set[str]] = {}
    for version in CORPUS_VERSIONS:
        history = corpus_tool.CORPUS / version / "tree" / "prov" / "history.jsonl"
        records = [
            json.loads(line)
            for line in history.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        assert records, f"{version}: an empty history proves nothing"
        seen[version] = {r.get("schema", "MISSING") for r in records}

    everything = set().union(*seen.values())
    assert everything <= {runprov.HISTORY_SCHEMA, runprov.START_SCHEMA}, (
        f"a released version wrote a schema this one does not name: {everything}"
    )
    assert len(set(map(frozenset, seen.values()))) == 1, (
        f"the schema set moved between releases: {seen}"
    )


def test_a_captured_history_from_a_chaining_release_verifies(tmp_path):
    """A corpus tree from a release that writes `prev` must chain. DERIVED FROM THE RECORDS.

    Found on release day for 0.6.0, the first version that chains: every edge of the captured
    tree was `BROKEN`, and correctly. `_normalise` rewrites the record bytes to take this
    machine's paths, venv and hostname out of them, and the chain is over the bytes AS WRITTEN
    (R-1, R-2) — so the scrub invalidated every digest it had signed. The harness and the
    feature had been built in different worlds and only met when a chaining release was first
    captured.

    The corpus cannot keep both properties: it exists to be published, so the scrub is not
    optional, and no scrub can be invisible to a chain over bytes. So `_rechain` rebuilds the
    links over the records as published and the manifest records that it did. What this asserts
    is the property that survives — a shipped fixture is internally consistent — and NOT that
    the bytes are what some run emitted, which the scrub already made untrue.

    WHICH VERSIONS ARE CHECKED IS DERIVED, never listed: a tree is expected to chain exactly
    when its own records carry `prev`. Add a release and it is covered with nothing to
    remember; the pre-chain trees stay `CANNOT_CHECK`, which is the right answer for them.
    """
    if not CORPUS_VERSIONS:  # pragma: no cover - a bare tree has no corpus
        pytest.skip("no corpus")
    manifest = json.loads((corpus_tool.CORPUS / "MANIFEST.json").read_text(encoding="utf-8"))
    chaining, checked = [], 0
    for version in CORPUS_VERSIONS:
        history = corpus_tool.CORPUS / version / "tree" / "prov" / "history.jsonl"
        if not history.is_file():  # pragma: no cover - every tree has one today
            continue
        checked += 1
        claims = [
            "prev" in json.loads(line)
            for line in history.read_text(encoding="utf-8").splitlines()
            if line
        ]
        report = runprov.chain.verify(history)
        if any(claims):
            chaining.append(version)
            assert report.status == runprov.chain.INTACT, (
                f"{version} writes `prev` but its captured history is {report.status}. The scrub "
                f"rewrites the bytes the chain signed, so `_rechain` must rebuild the links over "
                f"what is published: {[ln.detail for ln in report.of(runprov.chain.BROKEN)][:2]}"
            )
            assert manifest["versions"][version].get("rechained"), (
                f"{version} chains but the manifest does not record that it was re-chained; a "
                f"reader would take a corpus tree for a forensic one"
            )
        else:
            assert report.status == runprov.chain.CANNOT_CHECK, (
                f"{version} predates the chain, so nothing in it is chained and the honest "
                f"verdict is CANNOT_CHECK, not {report.status}"
            )
    assert checked == len(CORPUS_VERSIONS), "a corpus tree has no history; the sweep is partial"
    assert chaining, (
        "no corpus tree carries `prev`, so this asserts nothing — the corpus has stopped "
        "covering the chain and a regression in it would be invisible here"
    )


def test_the_corpus_keeps_up_with_the_releases_by_itself():
    """A corpus that has to be REMEMBERED after each release is a corpus that stops growing.

    This project's own record on remembered rules is seven misses for the scope pattern and
    three for `README-pypi.md`, so the harness may not depend on one. Every released tag must
    have a captured tree — with a grace period of exactly one release, because the wheel has
    to exist on PyPI before it can be installed and captured, and `main` going red the instant
    a tag is pushed would punish the release rather than the omission.

    So: tag 0.5.0 and nothing happens. Tag 0.6.0 without having captured 0.5.0 and this fails,
    naming the one command that fixes it. The window is a whole release cycle, and the failure
    is unmissable when it arrives.

    THE SKIP IS LOUD ON PURPOSE. Without tags — a shallow clone, or an sdist with no `.git` —
    "every tag is covered" is true of the empty set, which is the vacuous pass this file was
    written to stop. It says it looked at nothing rather than reporting green.
    """
    try:
        released = corpus_tool.released_versions()
    except (OSError, subprocess.CalledProcessError):  # pragma: no cover - no git here
        pytest.skip("no git tags visible; this check needs a full clone")
    if not released:  # pragma: no cover - a shallow clone or an unpacked sdist
        pytest.skip("no released tags found — nothing to compare the corpus against")

    owed = set(released[:-1]) - set(CORPUS_VERSIONS)
    assert not owed, (
        f"released but never captured: {sorted(owed)}. The cross-version gate cannot see a "
        f"version it has no record from. Run `python tools/corpus.py generate "
        + " ".join(f"--version {v}" for v in sorted(owed))
        + "` and commit the trees."
    )


def _text_attr_under_tests() -> dict[str, str] | None:
    """What GIT says about `text` for every file under `tests/`, or None if git cannot answer.

    SHARED BY TWO TESTS DELIBERATELY. One asks whether the byte-asserted directories are safe
    from git's own LF->CRLF translation on checkout; the other asks whether they are safe from
    the pre-commit hooks that rewrite files on commit. **They are one rule in two directions**,
    and two copies of this derivation would be free to disagree about which files it covers --
    which is the failure both tests exist to prevent, one level up.

    Paths are POSIX-spelled because that is how `pre-commit` matches an `exclude` regex, and git
    accepts forward slashes on every platform. Spelling them with `os.sep` would have made the
    second test pass everywhere and fail on Windows only.
    """
    roots = [d for d in (REPO / "tests").iterdir() if d.is_dir() and d.name != "__pycache__"]
    assert roots, "no fixture directories found; this is reading nothing"
    files = [p for d in roots for p in d.rglob("*") if p.is_file() and "__pycache__" not in p.parts]
    assert len(files) > 20, f"only {len(files)} fixture files seen; expected the corpus and more"

    asked = subprocess.run(
        ["git", "check-attr", "text", "--", *[p.relative_to(REPO).as_posix() for p in files]],
        cwd=REPO,
        capture_output=True,
        text=True,
    )
    if asked.returncode:  # pragma: no cover - no git here (an unpacked sdist)
        return None
    return {
        line.rsplit(": text: ", 1)[0]: line.rsplit(": text: ", 1)[1]
        for line in asked.stdout.splitlines()
        if line
    }


def test_every_byte_asserted_fixture_is_protected_from_line_ending_translation():
    """Git's default on Windows is `core.autocrlf=true`, which rewrites LF to CRLF ON CHECKOUT.

    For a directory whose whole purpose is that its BYTES are pinned, that is fatal and silent:
    the corpus artifacts carry pins `verify` re-derives, and the environment snapshot's
    filename IS the digest of its body, so a translated checkout makes every artifact report
    STALE and every snapshot report a digest that does not describe it — on one platform only,
    which is the kind of failure that reaches a user before it reaches a developer.

    `.gitattributes` already carried `tests/fixtures/** -text` with a comment saying Windows CI
    had caught exactly this. Then `tests/corpus/` arrived and the list did not grow: THE SCOPE
    PATTERN, in the file that documents the scope pattern, for the eighth time in this project.

    So this derives the directories from disk rather than naming them, and asks git itself.
    """
    attrs = _text_attr_under_tests()
    if attrs is None:  # pragma: no cover - no git here (an unpacked sdist)
        pytest.skip("git is not available to answer")

    unprotected = [path for path, value in attrs.items() if value != "unset"]
    assert not unprotected, (
        "these fixture files can be rewritten LF->CRLF by a Windows checkout, which changes "
        "bytes whose digests are asserted:\n  " + "\n  ".join(unprotected[:10]) + "\n"
        "Add the directory to .gitattributes with `-text`."
    )


#: WHETHER EACH PRE-COMMIT HOOK REWRITES A FILE -- the human judgement in the check below, and
#: the only list in it. The POPULATION is derived from `.pre-commit-config.yaml` itself and held
#: to these keys by an EQUALITY, so a ninth hook cannot arrive unclassified and a removed one
#: cannot leave a dead entry behind. Same split as `tests/conftest.py`'s tiers and
#: `tools/claims.py`'s bindings: the registry holds the PAIR, never the value.
_HOOKS_THAT_REWRITE_FILES = {
    "ruff-check": "`args: [--fix]` edits the file in place",
    "ruff-format": "a formatter writes the file it formats",
    "end-of-file-fixer": "appends a newline to any file lacking one -- the hook that did this",
    "trailing-whitespace": "strips trailing whitespace from every line it finds it on",
}
_HOOKS_THAT_ONLY_READ = {
    "check-yaml": "parses and reports; writes nothing",
    "check-toml": "parses and reports; writes nothing",
    "check-added-large-files": "refuses a large file without changing it",
    "check-merge-conflict": "greps for conflict markers",
}


def test_every_byte_asserted_directory_is_excluded_from_every_hook_that_rewrites_files():
    """THE SAME RULE AS ABOVE, IN THE DIRECTION NOBODY GUARDED. `.gitattributes` stops git
    rewriting these bytes on CHECKOUT. Nothing stopped a hook rewriting them on COMMIT.

    Found 2026-10-09 by running `pre-commit run --all-files` rather than by reading the config.
    `end-of-file-fixer` appended a newline to **21 files**: every `tests/corpus/**/prov/*.prov.json`
    record, which are the only files of the corpus's 149 without one -- because that is how every
    released wheel wrote the sidecar, confirmed against today's package, whose record still ends
    `}`. So the corpus was FAITHFUL and the hook would have made it assert a byte no version ever
    wrote; `tools/corpus.py` has the sentence for it -- *a corpus that had to be edited to be moved
    would be measuring the editor*.

    AND IT WAS SILENT, which is why a comment would not have been enough. With all 21 records
    rewritten the suite reported **1 247 passed, 5 skipped** -- identical to the baseline, same five
    named skips. No assertion anywhere reads those bytes. The exposure is not hypothetical either:
    `ci.py setup` runs `pre_commit install`, `CONTRIBUTING.md` tells every contributor to run it,
    nothing in CI or this suite runs the hooks, and the corpus is regenerated BY HAND at a release
    -- exactly when those files are staged. The next captured version would have carried a newline
    the wheel never wrote and read as a record-format change in the package, which is the one thing
    the corpus exists to detect.

    WHAT IS DERIVED AND WHAT IS DECIDED. The hooks are read from the config and the protected
    directories are asked of GIT, so neither is a list here. The decision is the eight-line
    registry above saying which hooks WRITE, and it is held to the config by an equality rather
    than a subset: an unclassified hook is one nobody asked the question about, and an entry for a
    hook the config no longer runs is a rule declared and not in effect.

    WHAT THIS ONE CANNOT DO, AND WHICH TEST DOES IT. Its subject is derived from
    `.gitattributes`, so **moving `.gitattributes` moves the subject**: delete the
    `tests/corpus/** -text` line and the corpus stops being byte-asserted, `asserted` shrinks to
    the fixtures, and this assertion goes quietly green. Demonstrated, not assumed. The test above
    is what refuses that -- it quantifies over *every file under `tests/`* rather than over the
    protected ones, and in the same tree it fails naming `tests/corpus/MANIFEST.json` and the rest.
    **Neither is total alone; the pair is**, and that is the only reason this one is allowed to ask
    git instead of naming the directories.

    THE RUFF HOOKS ARE INCLUDED THOUGH NO `.py` LIVES UNDER EITHER DIRECTORY TODAY, and that is
    the point: the requirement follows the rule, not today's file list. A digest-asserted `.py`
    fixture must not be reformatted either, and the exclusion has to be here BEFORE that file
    arrives -- the scope pattern this project has now hit nine times is always a rule that was
    right and a list that did not grow.
    """
    root = _repo_root()
    config = root / ".pre-commit-config.yaml"
    if not config.is_file():  # pragma: no cover - a bare tree
        pytest.skip(".pre-commit-config.yaml not present")

    import yaml

    cfg = yaml.safe_load(config.read_text(encoding="utf-8"))
    hooks = {hook["id"]: hook for repo in cfg["repos"] for hook in repo["hooks"]}
    assert hooks, "the config declares no hooks, so this test is reading nothing"

    classified = set(_HOOKS_THAT_REWRITE_FILES) | set(_HOOKS_THAT_ONLY_READ)
    assert set(hooks) == classified, (
        f"unclassified in this file: {sorted(set(hooks) - classified)}; named here but no longer "
        f"in the config: {sorted(classified - set(hooks))}. Say of each hook whether it REWRITES "
        f"files, with the reason"
    )

    attrs = _text_attr_under_tests()
    if attrs is None:  # pragma: no cover - no git here (an unpacked sdist)
        pytest.skip("git is not available to answer")
    asserted = sorted(path for path, value in attrs.items() if value == "unset")
    assert asserted, "git reports no `-text` file under tests/, so there is nothing to protect"

    writers = sorted(set(hooks) & set(_HOOKS_THAT_REWRITE_FILES))
    assert writers, "no file-rewriting hook is configured, so this check would pass on anything"

    #: `pre-commit` skips a file when the TOP-LEVEL `exclude` matches it or the hook's own does,
    #: so both are read. An absent pattern excludes nothing -- and `re.search("", path)` matches
    #: everything, so an empty one must not reach the regex.
    shared = cfg.get("exclude")
    reachable: dict[str, list[str]] = {}
    for hook_id in writers:
        patterns = [pat for pat in (shared, hooks[hook_id].get("exclude")) if pat]
        missed = [path for path in asserted if not any(re.search(p, path) for p in patterns)]
        if missed:
            reachable[hook_id] = missed[:3]
    assert not reachable, (
        "these hooks can rewrite files whose BYTES are asserted: "
        + "; ".join(f"{hook} -> {paths}" for hook, paths in sorted(reachable.items()))
        + ". Each is listed in _HOOKS_THAT_REWRITE_FILES for the reason given there. Add an "
        "`exclude:` covering every directory `.gitattributes` marks `-text`"
    )


# ------------------------------------------------------------------- Audit D (2026-09-17)
def _mixed_case_tree(root: pathlib.Path) -> pathlib.Path:
    """A directory whose names order DIFFERENTLY under the two conventions.

    `Panel/` and `README.md` are capitalised and `annotations.tsv`/`data/` are not, so the
    case-folded key (what `PurePath.__lt__` uses on Windows, and only there) and the unfolded
    `.parts` key disagree. An all-lowercase fixture cannot show any of this — which is exactly
    why the cross-version corpus missed D-08 despite being built for this class of defect.
    """
    refs = root / "refs"
    for rel, text in (
        ("Panel/a.fa", ">p\nAAAA\n"),
        ("README.md", "# refs\n"),
        ("annotations.tsv", "a\tb\n"),
        ("data/x.csv", "x,y\n"),
    ):
        (refs / rel).parent.mkdir(parents=True, exist_ok=True)
        (refs / rel).write_text(text, encoding="utf-8", newline="\n")
    return refs


def test_the_tree_digest_is_the_unfolded_order_and_keeps_the_folded_one_only_when_it_differs():
    """Audit D, D-08. Making `sha256_tree` machine-independent NECESSARILY moves one platform.

    There is no sort key that equals both the case-folded and the unfolded order, so A-14 was
    always a record-format change; the comment here claimed the opposite ("platform
    independence bought without moving a single existing digest") and C-03 inherited it. What
    actually happened: A-14 moved Windows, C-03 restored POSIX and left Windows moved.

    The legacy order is kept ONLY where it differs, so ~80 % of trees gain no field at all and
    its presence says something true about the tree rather than about this package's history.
    """
    root = pathlib.Path(tempfile.mkdtemp())
    described = runprov.hashing.describe(_mixed_case_tree(root))
    folded = described["sha256_tree_casefolded"]
    assert folded != described["sha256_tree"], "the fixture must actually distinguish the keys"

    # THE FOLDED VALUE IS WHAT WINDOWS ACTUALLY PRODUCED, not an invented second hash. Built
    # here from `PureWindowsPath`'s own ordering over the same (name, digest) pairs.
    pairs = [
        (
            p.relative_to(described["path"] if False else root / "refs").as_posix(),
            runprov.hashing.sha256(p),
        )
        for p in sorted((root / "refs").rglob("*"))
        if p.is_file()
    ]
    # THE PUBLIC COMPARISON, not a private attribute. `PurePath.__lt__` IS the key the released
    # versions sorted by — that is the whole point — and its internals are versioned: 3.10 and
    # 3.11 use `_cparts` / `casefold_parts`, 3.12+ uses a different private name. The first
    # draft of this line reached inside for one of them and went red on the two oldest legs
    # while being right about the behaviour — this project's own "probe, never reach inside"
    # rule, earned again, one turn after a reviewer had told me that attribute moved between
    # versions. Sorting the paths themselves is correct on every version by construction.
    native_windows = sorted(pairs, key=lambda kv: pathlib.PureWindowsPath(kv[0]))
    stream = hashlib.sha256()
    for name, digest in native_windows:
        stream.update(name.encode() + b"\0")
        stream.update(digest.encode() + b"\0")
    assert folded == stream.hexdigest(), "the migration aid must recognise what 0.1.0-0.4.0 wrote"

    # An all-lowercase tree orders identically under both keys and carries no extra field.
    low = root / "low"
    (low / "panel").mkdir(parents=True)
    (low / "panel" / "a.fa").write_text(">p\n", encoding="utf-8", newline="\n")
    (low / "readme.md").write_text("x\n", encoding="utf-8", newline="\n")
    assert "sha256_tree_casefolded" not in runprov.hashing.describe(low)


def test_a_directory_pinned_by_a_pre_0_5_0_windows_run_is_told_why_it_is_stale():
    """Audit D, D-08 — the migration aid, and the two things it must NOT do.

    A Windows user of 0.1.0-0.4.0 with `run.input("refs/")` upgrades and every directory pin
    goes STALE with nothing on disk touched. Measured over this project's own domain tree, 69
    of 339 directories order differently under the two keys. The C-11 precedent says migrate
    such a population rather than document it away.

    STILL STALE: the pin no longer identifies this tree under the digest this version computes
    and the user must re-pin, so OK would be a green over a record that needs action, and a
    fifth status would move README.md's exit-code table for a one-time migration. What changes
    is that the page names the cause instead of reporting an unexplained mismatch.
    """
    root = pathlib.Path(tempfile.mkdtemp())
    refs = _mixed_case_tree(root)
    legacy = runprov.hashing.describe(refs)["sha256_tree_casefolded"][
        : runprov.hashing.PIN_DIGEST_CHARS
    ]

    result = runprov.verify.check_input(legacy, "refs", root)
    assert result["status"] == runprov.verify.STALE, "re-pinning is required, so it is not OK"
    assert "ON WINDOWS" in result["reason"] and "re-pin" in result["reason"]

    # AND A REAL CHANGE STILL GETS A BARE STALE. The migration aid must not explain away a
    # directory whose contents actually moved — that would be the worst possible false green,
    # since it reads as "nothing is wrong, just an old pin".
    (refs / "data" / "x.csv").write_text("x,y\n9,9\n", encoding="utf-8", newline="\n")
    changed = runprov.verify.check_input(legacy, "refs", root)
    assert changed["status"] == runprov.verify.STALE
    assert "reason" not in changed, f"a genuinely changed tree must not be excused: {changed}"


def test_the_verify_cache_carries_both_digests_so_the_tree_is_walked_once(monkeypatch):
    """Audit D, D-08. The legacy comparison may not cost a second walk.

    `verify` fans out over many artifacts sharing inputs, and the inputs a scientific artifact
    pins are the expensive ones — a reference genome, a 40 GB matrix. Answering "was this
    pinned in the old order?" by calling `describe` again would re-read the whole tree on the
    already-failing path. Both digests come from one walk and are memoised together.
    """
    root = pathlib.Path(tempfile.mkdtemp())
    _mixed_case_tree(root)

    # COUNTED, NOT INFERRED. The first version of this test removed the tree and expected the
    # cache to answer anyway — but `check_input` tests `exists()` before it reaches the cache,
    # deliberately, so it returned GONE and proved nothing about walking. The walk itself is
    # what has to be counted.
    walks = []
    real = runprov.hashing.describe

    def counting(path, *a, **k):
        walks.append(pathlib.Path(path))
        return real(path, *a, **k)

    monkeypatch.setattr(runprov.verify, "describe", counting)

    cache: dict[pathlib.Path, tuple[str, str] | Exception] = {}
    first = runprov.verify.check_input("0" * runprov.hashing.PIN_DIGEST_CHARS, "refs", root, cache)
    assert first["status"] == runprov.verify.STALE
    assert list(cache) == [root / "refs"]
    current, legacy = cache[root / "refs"]
    assert current and legacy and current != legacy, cache

    again = runprov.verify.check_input(legacy, "refs", root, cache)
    assert again["status"] == runprov.verify.STALE and "ON WINDOWS" in again["reason"]
    assert len(walks) == 1, (
        f"the tree was walked {len(walks)} times for two checks; the legacy digest must come "
        f"from the same walk as the current one, not from a second `describe`"
    )


def test_diff_says_when_a_run_did_not_finish(tmp_path):
    """Audit D, D-02. Seven dimensions and not one of them read `status`.

    A script that writes its table and THEN raises — a post-processing step blowing up after
    the output is on disk — records identical inputs, outputs, parameters, packages and commit
    to its successful predecessor. `runprov diff` reported every dimension `unchanged` and
    exited 0, while the traceback sat in the same history line it had just read, and `runprov
    log` printed `FAILED RuntimeError: …` from that very line.

    A BARE INEQUALITY IS NOT THE FIX, which is the part the finding itself missed: when BOTH
    runs crash identically the statuses agree, so `!=` settles and the command reports a clean
    green comparison forever. The per-side evidence lines are what close that.
    """
    ok = _hrec(status="ok")
    crashed = _hrec(status="failed", failure={"type": "RuntimeError", "message": "blew up\nline2"})

    d = _dim(runprov.diff.compare(ok, crashed), "status")
    assert d.verdict == "changed" and not d.settled
    assert "status  ok -> failed" in d.differences
    assert any("B failed: RuntimeError: blew up" in line for line in d.differences)
    assert not any("line2" in line for line in d.differences), "one line of the message, not all"

    # BOTH CRASHED: the statuses agree and it is still a finding.
    both = _dim(runprov.diff.compare(crashed, crashed), "status")
    assert both.verdict == "changed" and not both.settled, "two failures are not 'unchanged'"
    assert len(both.differences) == 2, both.differences

    # AND AN ORDINARY PAIR STAYS GREEN, or the gate is unusable — A-07's lesson.
    clean = _dim(runprov.diff.compare(ok, ok), "status")
    assert clean.verdict == "unchanged" and clean.settled and clean.examined == "ok vs ok"

    # A failed run with no failure block is still a finding; `status` is what the history
    # projection guarantees, `failure` is only the evidence and can be truncated away.
    bare = _dim(runprov.diff.compare(ok, _hrec(status="failed")), "status")
    assert any("no failure block recorded" in line for line in bare.differences)


def test_diff_refuses_to_compare_a_run_that_has_not_finished():
    """Audit D, D-02 — the two shapes that must BLOCK rather than compare.

    `compare()` is pure and public and is fed hand-built mappings by callers and by this file,
    so `status` can be absent; and `running` reaches a mid-run sidecar, where it describes a
    run that has not finished rather than one that failed. Reporting either as a difference
    would be a confident wrong answer, which is worse than refusing.
    """
    ok = _hrec(status="ok")
    for other, why in (
        (_hrec(status="running"), "has not finished"),
        ({k: v for k, v in ok.items() if k != "status"}, "does not say whether"),
    ):
        d = _dim(runprov.diff.compare(ok, other), "status")
        assert d.verdict == "not comparable", f"{other.get('status')!r} -> {d.verdict}"
        assert why in (d.blocked or ""), d.blocked
        assert not d.settled, "a gate may not go green over a run that may still be going"


def test_diff_marks_a_failed_run_on_the_header_line_too(tmp_path, capsys):
    """Audit D, D-02. When BOTH runs failed the `status` row reads as agreement at a glance.

    A reader scanning the table sees `unchanged` down the column; the fact that neither run
    finished has to be where the runs are named. `show` already puts the state in exactly that
    position, so this is the package agreeing with itself rather than a new convention.
    """
    crashed = _hrec(status="failed", failure={"type": "RuntimeError", "message": "x"})
    lines = runprov.diff.render(runprov.diff.build(crashed, crashed))
    assert lines[0].startswith("A ") and lines[0].endswith("[failed]"), lines[0]
    assert lines[1].endswith("[failed]"), lines[1]

    ok = _hrec(status="ok")
    clean = runprov.diff.render(runprov.diff.build(ok, ok))
    assert "[" not in clean[0], f"an ordinary run carries no marker: {clean[0]}"


def test_a_zero_step_comparison_still_carries_its_truncation_reason():
    """Audit D, D-10. C-02's `0 vs 0 declared` fast path is the one exit from `_steps` whose
    `blocked` propagation nothing asserted — and suppressing it was green.

    Two runs that both declared no steps agree, which is what that branch is for. But a run
    whose step observation was CUT OFF also reports zero, and those two are not the same fact.
    Drop the reason on the way out and `steps` reads `unchanged`, settles, and the gate passes
    over a census both runs know is partial — A-07 and C-02's own defect in mirror image,
    arriving through the branch that fixed them.

    The existing guard could not see it: its `steps` cases go through `_hrec()`, which carries
    a step LIST, so they never reach the count branch at all.
    """
    for mark in ("steps_truncated", "observed_truncated", "auto_stopped_after_calls"):
        a = {"observation": {mark: 3, "auto_available": True}}
        b = {"observation": {"auto_available": True}}
        d = _dim(runprov.diff.compare(a, b), "steps")
        assert d.examined == "0 vs 0 declared", d.examined
        assert d.blocked and mark in d.blocked, f"{mark} did not survive the zero-step branch"
        assert d.verdict == "not comparable" and not d.settled

    # A differing `auto_available` is the other way a zero can mean two things.
    d = _dim(
        runprov.diff.compare(
            {"observation": {"auto_available": True}}, {"observation": {"auto_available": False}}
        ),
        "steps",
    )
    assert d.blocked and "different amounts" in d.blocked
    assert not d.settled

    # AND TWO GENUINELY STEPLESS RUNS STILL AGREE, or the branch is pointless.
    clean = _dim(
        runprov.diff.compare(
            {"observation": {"auto_available": True}}, {"observation": {"auto_available": True}}
        ),
        "steps",
    )
    assert clean.verdict == "unchanged" and clean.settled and clean.blocked is None


def test_diff_compares_the_code_that_ran_not_only_the_commit():
    """Audit D, D-04. `git status` reports neither a gitignored module nor a script outside
    the repository, so `git_code_dirty` is False, the commits match, and `code` said
    `unchanged` — while the same history line carried a different `imported_code.digest`.

    `run.code()` on an out-of-repo script is the documented purpose of that API, README.md says
    this digest "answers *did any first-party code change between these two runs*", and
    ADR-0014's own precondition table already named `imported_code.omitted`. The ADR
    contemplated the field; the implementation was handed it and did not look.

    Reproduced end to end before this: edit a `run.code()` script between two runs of a clean
    git tree and `runprov diff` exited 0. It exits 1 and names the digests.
    """

    def rec(digest, **over):
        return _hrec(git_commit="abc1234", imported_code={"count": 2, "digest": digest, **over})

    changed = _dim(runprov.diff.compare(rec("aa" * 32), rec("bb" * 32)), "code")
    assert changed.differences == [f"first-party code  {'aa' * 8} -> {'bb' * 8}"]
    assert not changed.settled, "a changed analysis script must be able to fail a gate"

    same = _dim(runprov.diff.compare(rec("aa" * 32), rec("aa" * 32)), "code")
    assert same.verdict == "unchanged" and same.settled
    assert "code aaaaaaaa / aaaaaaaa" in same.examined, same.examined

    # THE COMMIT IS STILL COMPARED. The digest is an addition, not a replacement.
    moved = _dim(
        runprov.diff.compare(
            _hrec(git_commit="abc1234", imported_code={"digest": "aa" * 32, "count": 1}),
            _hrec(git_commit="def5678", imported_code={"digest": "aa" * 32, "count": 1}),
        ),
        "code",
    )
    assert moved.differences == ["commit  abc1234 -> def5678"]


def test_diff_refuses_to_compare_code_when_only_one_run_recorded_a_digest():
    """Audit D, D-04. `imported_code` entered the history WITHOUT a `HISTORY_SCHEMA` bump.

    So two records legitimately share `runprov.history.v2` and disagree about whether the field
    exists — this repository's own `provenance/runs.jsonl` holds such a line — and
    `hash_imported_code` can be off on one machine and on elsewhere. Comparing there would
    report a code change for every pair straddling 2026-08-13: a confident wrong answer, which
    is worse than a refusal.
    """
    with_digest = _hrec(git_commit="abc1234", imported_code={"count": 2, "digest": "aa" * 32})
    without = _hrec(git_commit="abc1234")

    d = _dim(runprov.diff.compare(with_digest, without), "code")
    assert d.verdict == "not comparable" and not d.settled
    assert "only A recorded a digest" in d.blocked, d.blocked

    # NEITHER SIDE IS NOT A REFUSAL. Two runs that both predate the field, or both have the
    # feature off, agree about first-party code in the only sense available — the same
    # reasoning as two runs that both declared no steps, and as two that both measured no cost.
    both_absent = _dim(runprov.diff.compare(without, without), "code")
    assert both_absent.verdict == "unchanged" and both_absent.settled
    assert both_absent.blocked is None
    assert "code" not in both_absent.examined.split(",")[-1] or "only" not in both_absent.examined


def test_a_truncated_code_digest_is_noted_and_does_not_block():
    """Audit D, D-04 — Taylor's decision, 2026-09-17.

    Past `imported_code_max` the digest covers only the kept prefix of the sorted file list, so
    equality means the first N files agree. ADR-0014's table asks for a truncated field to
    block the dimension — applied literally that would stop any project with more than 200
    first-party modules from EVER exiting 0, which is the gate-that-cannot-pass this package
    has now built three times.

    So it is a NOTE, in `examined`, where the scope of a comparison belongs. Anyone who wants
    strictness has `configure(imported_code_max=…)`.
    """
    capped = _hrec(
        git_commit="abc1234", imported_code={"count": 200, "digest": "aa" * 32, "omitted": 100}
    )
    whole = _hrec(git_commit="abc1234", imported_code={"count": 200, "digest": "aa" * 32})

    d = _dim(runprov.diff.compare(capped, whole), "code")
    assert d.settled, "a capped digest must not make the gate unpassable"
    assert d.blocked is None
    assert "A's code digest covers 200 of 300 files" in d.examined, d.examined


def test_diff_reads_the_code_digest_from_either_record_shape():
    """Audit D, D-04. The history FLATTENS this field and the sidecar does not.

    `run.py` writes a top-level `imported_code`; the live record keeps `code.imported`. Reading
    only one shape is how A-04 made `packages` compare `{}` against `{}` on every real history
    and how A-03 crashed `steps` — twice in one audit, in this function's own neighbours. The
    suite builds sidecar-shaped records and the command is fed history ones, so a reader that
    handles one shape is self-consistent and wrong.
    """
    flat = {"git_commit": "abc1234", "imported_code": {"count": 1, "digest": "aa" * 32}}
    nested = {"git_commit": "abc1234", "code": {"imported": {"count": 1, "digest": "bb" * 32}}}

    d = _dim(runprov.diff.compare(flat, nested), "code")
    assert d.differences == [f"first-party code  {'aa' * 8} -> {'bb' * 8}"], d.differences
    assert runprov.diff._imported_of(flat)["digest"] == "aa" * 32
    assert runprov.diff._imported_of(nested)["digest"] == "bb" * 32
    assert runprov.diff._imported_of({"imported_code": None}) == {}


def _out_record(script, path, digest, cwd="/proj", **over):
    """A history record that wrote one output, for `find_run`'s ranking."""
    return {
        "script": script,
        "run_id": f"r_{script}",
        "cwd": cwd,
        "status": "ok",
        "outputs": [{"path": path, "sha256": digest}],
        **over,
    }


def test_an_exact_path_beats_a_byte_identical_file_somewhere_else():
    """Audit D, D-09 — the guard C-01 never got, and the reason coverage is not one.

    C-01 was the highest-severity row of its audit: `report` had begun matching on digest
    before path, so a byte-identical file written later at a DIFFERENT path did not merely win,
    it destroyed a correct exact-path match. The repair ranked path above digest and shipped
    with no test of that ranking.

    Measured afterwards: `report.py` sits at 100% statement AND branch coverage, and reversing
    the ranking passes 976 of 976 tests. Every branch of `find_run` executes; the priority
    those branches exist to encode was asserted by nobody. Coverage is a measure of execution.
    """
    history = [
        _out_record("summarise_s01", "s01/summary.csv", "aa" * 32),
        _out_record("summarise_s99", "s99/summary.csv", "aa" * 32),  # byte-identical, later
    ]
    # THE READER NAMED s01, and s99's identical bytes must not take the page away from it.
    assert runprov.report.find_run(history, "/proj/s01/summary.csv", "aa" * 32)["script"] == (
        "summarise_s01"
    ), "an exact recorded path is the strongest identity available and must win outright"

    # AND THE DIGEST IS STILL THE FALLBACK for an artifact that has since been MOVED, which is
    # the case it was added for — a path comparison cannot answer it.
    moved = runprov.report.find_run(history, "/archive/kept.csv", "bb" * 32)
    assert moved is None, "no path, no unique digest: 'not found' is the honest answer"
    one_only = [_out_record("only", "out/x.csv", "cc" * 32)]
    assert runprov.report.find_run(one_only, "/archive/kept.csv", "cc" * 32)["script"] == "only"

    # TWO PATHS, ONE DIGEST identifies no single run, so it names none of them.
    assert runprov.report.find_run(history, "/archive/kept.csv", "aa" * 32) is None


def test_the_page_says_when_the_bytes_are_not_the_bytes_that_run_recorded(tmp_path, capsys):
    """Audit D, D-03. The path branch assigned unconditionally, so when the path-matching
    record's OWN digest for that path contradicted the bytes on disk, `find_run` held proof it
    did not describe them and returned it anyway — discarding an unambiguous digest match.

    The page then paired one run's script, command and commit with ANOTHER run's inputs (those
    come from the artifact's own pin), reported OK and exited 0. Three commands gave three
    answers for one file: `report` named v1, `verify` named v2, `show --stale` said MODIFIED.

    Reached by publish-by-copy — a staged result copied to a stable name, which is `publishDir`
    in Nextflow and a `cp` in a Makefile — or by restoring a good copy over a bad run.
    """
    history = [
        _out_record("v1_pipeline", "results/summary.csv", "aa" * 32),
        _out_record("v2_pipeline", "staging/summary.csv", "bb" * 32),
    ]
    match = runprov.report.find_match(history, "/proj/results/summary.csv", "bb" * 32)

    assert match.record["script"] == "v1_pipeline", "the path match stays the named run"
    assert match.also_elsewhere
    assert match.recorded == ("aa" * 32)[: runprov.hashing.PIN_DIGEST_CHARS]
    assert match.elsewhere["script"] == "v2_pipeline"
    # DERIVED, NOT SPELLED. The ninth host-dependent test of this session: `_resolve` returns
    # the platform's own spelling, so a hard-coded `/proj/staging/summary.csv` was right on
    # POSIX and `D:\proj\staging\summary.csv` on Windows, and the assertion failed on the one
    # leg while the code was correct on both. Ask the same function the code asks.
    assert match.elsewhere_path == runprov.report._resolve("staging/summary.csv", "/proj")

    # EDITED IN PLACE IS A DIFFERENT FACT, and I-02 is that the two used to be one. There the
    # record IS the producer, the page correctly reports ALTERED, and no other run's output
    # matches — so there is no twin to name. The DIGEST disagreement is still real, and is now
    # reported by `_differs` rather than being suppressed for want of a twin: that suppression
    # was the false negative half of I-02.
    edited = runprov.report.find_match([history[0]], "/proj/results/summary.csv", "ff" * 32)
    assert edited.record["script"] == "v1_pipeline", "an edited artifact still names who wrote it"
    assert not edited.also_elsewhere, "and no other run holds those bytes"

    # TWO OTHER RUNS HOLDING THOSE BYTES IDENTIFY NONE OF THEM, so the page must not offer one.
    # The same uniqueness rule the digest FALLBACK uses, applied to the hand-off — offering the
    # last-appended of several would be C-01's defect wearing the new line as a disguise.
    ambiguous = runprov.report.find_match(
        [*history, _out_record("v3_pipeline", "other/summary.csv", "bb" * 32)],
        "/proj/results/summary.csv",
        "bb" * 32,
    )
    assert ambiguous.record["script"] == "v1_pipeline"
    assert not ambiguous.also_elsewhere, "two candidates identify no single run"
    assert ambiguous.elsewhere is None

    # AND THE RECORDED DIGEST COMES FROM `pin_digest`, not a fourth re-derivation of its
    # precedence: a checker that recomputes it independently can disagree with the pin it is
    # checking, and that disagreement reads to a user as a stale artifact.
    content_shaped = [
        _out_record("v1_pipeline", "results/summary.csv", "aa" * 32),
        history[1],
    ]
    content_shaped[0]["outputs"][0]["content_sha256"] = "dd" * 32
    from_pin = runprov.report.find_match(content_shaped, "/proj/results/summary.csv", "bb" * 32)
    assert from_pin.recorded == ("dd" * 32)[: runprov.hashing.PIN_DIGEST_CHARS], (
        "`content_sha256` wins over `sha256` in a pin, so it must win here too"
    )

    # AND THE PAGE PRINTS IT. Asserting only on `find_match` leaves the block that renders it
    # unguarded — the D-10 shape, where the fact reached the data and no reader said it.
    artifact = tmp_path / "results" / "summary.csv"
    artifact.parent.mkdir(parents=True)
    artifact.write_text("col\nv2\n", encoding="utf-8")
    disk = runprov.hashing.sha256(artifact)
    page = runprov.report.page(
        artifact,
        tmp_path,
        [
            _out_record("v1_pipeline", "results/summary.csv", "aa" * 32, cwd=str(tmp_path)),
            _out_record("v2_pipeline", "staging/summary.csv", disk, cwd=str(tmp_path)),
        ],
    )
    text = "\n".join(page.lines)
    assert "BYTES DIFFER" in text, text
    assert "v2_pipeline" in text and "v1_pipeline" in text
    assert pathlib.Path("staging/summary.csv").name in text
    #: COMPARED IN THE PAGE'S OWN SPELLING. `render_page` prints
    #: `hashing._posix(match.elsewhere_path)`, so asserting the platform's spelling passes on
    #: POSIX and fails on Windows, where `_resolve` gives `C:\\...\\staging\\summary.csv`
    #: and the page prints forward slashes. Red on the Windows leg from 2026-09-30; the fact
    #: being asserted is unchanged.
    assert (
        runprov.hashing._posix(runprov.report._resolve("staging/summary.csv", str(tmp_path)))
        in text
    )


def test_find_run_keeps_its_name_and_returns_the_record(tmp_path):
    """Audit D, D-03. `find_match` carries the extra answer; `find_run` is what callers use.

    The prototype passed the new facts through a module-level global. Two readers of one
    artifact would then have raced, and a second caller would have seen the first one's answer
    — a wrong record produced by the code that exists to prevent wrong records.
    """
    history = [_out_record("only", "out/x.csv", "cc" * 32)]
    assert runprov.report.find_run(history, "/proj/out/x.csv") == history[0]
    assert runprov.report.find_match(history, "/proj/out/x.csv").record == history[0]
    assert runprov.report.find_run([], "/proj/out/x.csv") is None
    assert runprov.report.find_match([], "/proj/out/x.csv").record is None
    assert not runprov.report.Match(None).also_elsewhere


def test_an_archived_lockfile_that_does_not_hash_to_its_own_name_is_rewritten(
    tmp_path, monkeypatch
):
    """Audit D, D-05 — C-11's sibling, one function along, with the remedy already next door.

    Both functions name a file after a prefix of a digest and publish `sha256` beside `reused`,
    and C-11's argument applies unchanged: the name is DERIVED from the digest, so an existing
    file at that name is not evidence about its bytes. A torn write from before
    `atomic_write_bytes` — the state `_atomic.py`'s own comment describes — leaves a prefix
    under a name claiming a digest it does not have; every later run sees the name, sets
    `reused: true`, and never writes it again. The record then asserts a `sha256` that does not
    describe the file it points at, for ever, and `reused: true` reads to a reader as
    corroboration that the environment's declaration has not moved.
    """
    root, store = tmp_path / "proj", tmp_path / "arch"
    root.mkdir()
    (root / "requirements.txt").write_text("numpy==2.1.0\npandas==2.2.0\n", encoding="utf-8")

    first = runprov.environment.archive_lockfiles(root, store)[0]
    assert first["reused"] is False and first["archived"] is True
    copy = pathlib.Path(first["path"])
    assert hashlib.sha256(copy.read_bytes()).hexdigest() == first["sha256"]

    assert runprov.environment.archive_lockfiles(root, store)[0]["reused"] is True, "unchanged"

    # THE TORN WRITE: the right name, a prefix of the bytes.
    copy.write_bytes(copy.read_bytes()[:16])
    again = runprov.environment.archive_lockfiles(root, store)[0]
    assert again["reused"] is False, "a copy that does not hash to its own name is not reusable"
    assert hashlib.sha256(copy.read_bytes()).hexdigest() == again["sha256"], "and it is rewritten"

    # UNREADABLE IS NOT REUSABLE EITHER, and the read must not end the run. Injected rather
    # than chmod'ed, so this asserts the same thing on every platform and as every user.
    def _refuse(self):
        raise OSError("EACCES")

    monkeypatch.setattr(pathlib.Path, "read_bytes", _refuse)
    assert runprov.environment._holds(copy, again["sha256"]) is False


def test_the_digest_fallback_counts_distinct_runs_not_distinct_paths():
    """Audit D, D-06. Keying the ambiguity guard on the PATH got it wrong in both directions.

    Two runs that wrote byte-identical bytes to the SAME recorded path — which is every re-run
    of a deterministic pipeline — collapsed to one key, so the guard passed and the
    LAST-appended run was named, with its command and its commit, for an artifact the reader
    had found somewhere else entirely. And one run that wrote identical bytes to TWO paths
    counted as two, so a moved artifact that a single run plainly produced was reported NOT
    FOUND. The question is "which run", so runs are what must be counted.
    """
    twice = [
        _out_record("summarise", "out/summary.csv", "aa" * 32, run_uid="u1", run_id="r1"),
        _out_record("summarise", "out/summary.csv", "aa" * 32, run_uid="u2", run_id="r2"),
    ]
    assert runprov.report.find_run(twice, "/archive/2026-05/summary.csv", "aa" * 32) is None, (
        "two runs wrote those bytes; naming the newest is a guess dressed as an answer"
    )

    # ONE RUN, TWO PATHS is not ambiguous — it is one answer, and the old rule refused it.
    one_run = [
        {
            "script": "emit",
            "run_uid": "u9",
            "cwd": "/proj",
            "outputs": [
                {"path": "out/a.csv", "sha256": "bb" * 32},
                {"path": "out/b.csv", "sha256": "bb" * 32},
            ],
        }
    ]
    found = runprov.report.find_run(one_run, "/archive/moved.csv", "bb" * 32)
    assert found is not None and found["script"] == "emit"

    # And a record with no identity at all still works, because tests build such mappings.
    bare = [{"outputs": [{"path": "out/x.csv", "sha256": "cc" * 32}]}]
    assert runprov.report.find_run(bare, "/archive/x.csv", "cc" * 32) is not None


def test_impact_does_not_call_a_sum_of_per_run_counts_a_floor_on_paths(capsys):
    """Audit D, D-07. C-06 made the watch count DISTINCT paths per run, then the reader written
    for it summed those across runs and printed "at least N path(s) were dropped".

    A sum of per-run distinct counts is a count of (run, path) drop EVENTS. It is neither
    distinct across the history nor a floor on distinct paths: a hundred runs that each dropped
    the same 2 000 system paths sum to 200 000 for 2 000 files. That is the same overstatement
    C-06 removed per-run — "the value can exceed the number of files on the disk" — arriving
    through the reader added to fix it. It overstates a blind spot rather than hiding one, so
    it is not a false green; it is a wrong sentence about a permanent record, which this
    package ranks highly enough to fix.
    """
    chain = runprov.impact.Chain("abc123", [], [], 0, 100, 200_000)
    text = "\n".join(runprov.impact.render(chain))
    assert "200000 read(s) were dropped" in text, text
    assert "across the 100 run(s)" in text
    assert "may repeat between runs" in text, "the reader is told what the number is not"
    assert "at least" not in text, "a sum over runs is not a floor on distinct paths"

    assert runprov.impact.Chain("abc123", [], [], 0, 1).watch_drops == 0
    quiet = "\n".join(runprov.impact.render(runprov.impact.Chain("abc123", [], [], 0, 1)))
    assert "dropped by the watch" not in quiet, "silent when nothing was dropped"


# ------------------------------------------------------------------ T-32 / ADR-0016: the chain
# Rewritten 2026-09-18 after Audit E. The first version of this block asserted behaviour the
# audit showed to be wrong — one test PINNED the false green it was supposed to prevent — so
# these are written against the amended specification rather than patched toward it.
CHAIN_TOOL = {"version": "0.6.0"}


def _chain_history(path: pathlib.Path, count: int = 4, version: str = "0.6.0") -> list[bytes]:
    """`count` records appended through the real sink, so the chain is the one runprov writes."""
    sink = runprov.JsonlSink(path)
    for i in range(count):
        sink.append(
            {
                "schema": "runprov.history.v2",
                "run_id": f"r{i}",
                "status": "ok",
                "tool": {"version": version},
            }
        )
    return path.read_bytes().rstrip(b"\n").split(b"\n")


def _chain_exit(path: pathlib.Path) -> int:
    report = runprov.chain.verify(path)
    if report.status == runprov.chain.BROKEN:
        return 1
    return 0 if report.status == runprov.chain.INTACT else 2


def test_each_history_line_carries_the_digest_of_the_one_before_it(tmp_path):
    """ADR-0016 [ADR-0016 R-1] [ADR-0016 R-2] [ADR-0016 R-3] [ADR-0016 R-4] [ADR-0016 R-19].

    Nothing detected a retroactive edit before this: change line 40 and `log`, `show`, `diff`,
    `impact` and `report` all repeat the new value with no sign anything moved.

    [ADR-0016 R-19] is the placement, and it is not cosmetic. `prev` used to be serialised LAST —
    measured at 46 % into the line with 75 bytes of digest trailing it — so the one field whose
    job is to survive a truncation sat where a tear destroys it first. That single choice is
    what made two of Audit E's findings look like an unavoidable trade.
    """
    p = tmp_path / "h.jsonl"
    lines = _chain_history(p, 3)

    assert json.loads(lines[0])["prev"] == runprov.chain.GENESIS, "[ADR-0016 R-3] the first line"
    for i in (1, 2):
        # [ADR-0016 R-1] [ADR-0016 R-2] the digest is of the PRECEDING LINE'S BYTES AS WRITTEN —
        # no canonicalisation, no re-serialisation. A verifier hashes what it reads.
        assert json.loads(lines[i])["prev"] == hashlib.sha256(lines[i - 1]).hexdigest()
    assert len(json.loads(lines[1])["prev"]) == 64, "[ADR-0016 R-1] full lower-case hex"
    for line in lines:
        assert line.startswith(b'{"prev": "'), f"[ADR-0016 R-19] prev must lead the line: {line}"

    # [ADR-0016 R-4] a history that predates the chain is ANCHORED by the next append, not left
    # as a fresh island — the difference between protecting existing histories and only new ones.
    old = tmp_path / "old.jsonl"
    old.write_bytes(b'{"schema": "runprov.history.v2", "run_id": "before"}\n')
    runprov.JsonlSink(old).append({"schema": "runprov.history.v2", "run_id": "after"})
    grown = old.read_bytes().rstrip(b"\n").split(b"\n")
    assert "prev" not in json.loads(grown[0]), "the pre-existing line is not rewritten"
    assert json.loads(grown[1])["prev"] == hashlib.sha256(grown[0]).hexdigest()
    assert _chain_exit(old) == 0, "[ADR-0016 R-4] an anchored history is not a finding"


def test_the_chain_is_computed_inside_the_lock_and_after_the_torn_line_repair(tmp_path):
    """ADR-0016 [ADR-0016 R-6] [ADR-0016 R-7] [ADR-0016 R-22]. Where the digest is read.

    [ADR-0016 R-6] Outside the lock, two concurrent runs chain to the same predecessor and the
    second silently orphans the first. [ADR-0016 R-7] Before the repair, a fragment left by a
    killed process is not yet the last line. [ADR-0016 R-22] And when no lock could be taken at
    all, no claim is made — a degraded mode that used to lose nothing must not be promoted into
    one that manufactures a tamper verdict.
    """
    p = tmp_path / "h.jsonl"
    runprov.JsonlSink(p).append({"n": 1})
    with p.open("ab") as fh:  # what a SIGKILL mid-append leaves
        fh.write(b'{"n": 2, "torn"')
    runprov.JsonlSink(p).append({"n": 3})

    lines = p.read_bytes().rstrip(b"\n").split(b"\n")
    assert len(lines) == 3, lines
    assert json.loads(lines[2])["prev"] == hashlib.sha256(lines[1]).hexdigest(), (
        "[ADR-0016 R-7] the fragment the repair closed IS the predecessor"
    )
    source = inspect.getsource(runprov.sinks.JsonlSink.append)
    assert source.index("_exclusive") < source.index("chain.previous_digest")
    assert source.index("chain.previous_digest") < source.index("json.dumps")

    # [ADR-0016 R-6] eight writers, twenty-four appends, and the chain must still be a chain.
    busy = tmp_path / "many.jsonl"

    def one(i):
        runprov.JsonlSink(busy).append({"n": i})

    with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
        list(pool.map(one, range(24)))
    got = busy.read_bytes().rstrip(b"\n").split(b"\n")
    assert len(got) == 24, f"{len(got)} of 24 records survived"
    assert runprov.chain.verify(busy).status == runprov.chain.INTACT


def test_no_lock_means_no_chain_claim_rather_than_a_false_accusation(tmp_path, monkeypatch):
    """ADR-0016 [ADR-0016 R-22] [ADR-0016 R-32]. Audit E, E-03 — and Audit G, G-01, which this
    test is the reason nobody saw coming.

    `_exclusive` documents an unlocked fallback for NFS, CIFS and containers, and its own
    measurement records that 8 processes x 20 appends produced 160/160 intact records there.
    Chaining under it lets two writers claim the same predecessor, so a file in which every
    record landed correctly gets reported as tampered — reproduced with ENOLCK: 80/80 records
    present, four accusations naming untouched lines.

    THIS TEST WAS VACUOUS WITH RESPECT TO THE RULE IT GUARDS, and that is why G-01 escaped
    every reader who checked that R-22 had a test. Its fixture appended the unlocked records
    to an EMPTY file, so no line was ever chained, `started` never became true, and all four
    edges fell to rule 3b/4 — `UNCHAINED` — before rule 7 was reached. Measured on the fixture
    as it stood: `[UNCHAINED, UNCHAINED, UNCHAINED, UNCHAINED]`, `chained_from = None`. The
    exit 2 it asserted came from *nothing in this file is chained*, not from any judgement
    about the unlocked lines at all; and restoring rule 7's `BROKEN` in place left this test
    PASSING. The guard a reader would point at could not fire.

    A CHAINED PREFIX IS THE SITUATION R-22 IS ACTUALLY ABOUT: a project already recording
    normally, which then runs somewhere `flock` is unavailable — a colleague on an NFS home, a
    container without it. That is when an unlocked append lands after a chained line, and it is
    the only arrangement in which the rule can be reached. So the fixture now begins with two
    ordinary locked appends, and the assertion is the [ADR-0016 R-32] outcome: `UNCLAIMED`,
    exit 2, disclosed by name, and no line accused.
    """
    # BOTH MECHANISMS, because `_exclusive` uses `fcntl` on POSIX and `msvcrt` on Windows.
    # Blocking only `fcntl` left Windows fully locked, so this asserted the UNLOCKED behaviour
    # of a LOCKED append and failed on that leg alone — the eleventh test of this session to
    # lean on what the host supplies. Name what the CODE depends on, not what this machine has.
    # `test_no_locking_available_says_so` already had it right, four thousand lines up.
    real = __import__
    mechanisms = ("fcntl", "msvcrt")

    def without_locking(name, *a, **k):
        if name in mechanisms:
            raise ImportError(name)
        return real(name, *a, **k)

    p = tmp_path / "h.jsonl"
    # THE CHAINED PREFIX, written normally, before locking goes away. Without it the rule this
    # test exists for is unreachable and the assertions below hold for the wrong reason.
    for i in range(2):
        runprov.JsonlSink(p).append({"schema": "runprov.history.v2", "run_id": f"ok{i}"})

    monkeypatch.setattr(builtins, "__import__", without_locking)
    for i in range(4):
        runprov.JsonlSink(p).append({"schema": "runprov.history.v2", "run_id": f"r{i}"})
    monkeypatch.undo()

    lines = p.read_bytes().rstrip(b"\n").split(b"\n")
    assert len(lines) == 6, "the degraded path still keeps every record"
    assert [("prev" in json.loads(line)) for line in lines] == [True, True, *[False] * 4], (
        "an unlocked append makes NO claim; a claim it cannot stand behind is worse than none"
    )

    report = runprov.chain.verify(p)
    assert report.chained_from == 1, (
        "the prefix really is chained — without this the walk never reaches rule 7 and every "
        "assertion below passes for a reason that has nothing to do with R-22"
    )
    assert [e.line for e in report.of(runprov.chain.UNCLAIMED)] == [3, 4, 5, 6], (
        "[ADR-0016 R-32] the four unlocked lines are the rule-7 cell, and it is reached"
    )
    assert not report.of(runprov.chain.BROKEN), (
        "every record landed and no byte moved: G-01's four accusations over a correct file"
    )
    assert _chain_exit(p) == 2, "unverifiable, and never an accusation"


def test_a_torn_line_never_accuses_and_never_absolves(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-11] [ADR-0016 R-20]. Audit E, E-05 and E-06 — BOTH directions.

    The first build violated this requirement twice over, and the two errors cancelled in the
    only case the suite exercised, which is why 17 of 17 mutations passed over them:

    * a mid-file torn line was reported COULD NOT CHECK *and* accused — "LINE 3 IS WHAT
      CHANGED… the history was edited after it was written" — so a bad disk sector accused the
      user, the one thing [ADR-0016 R-11] forbids;
    * an end-of-file torn line CONCEALED an edit to its predecessor, reporting INTACT and exit
      0 — an attack needing a text editor and no hashing, strictly easier than the re-chaining
      this ADR already concedes.

    [ADR-0016 R-20] is what makes both halves hold at once: with `prev` first, the fragment
    usually still carries a verifiable claim, so the ordinary crash costs nothing AND an edit
    hidden behind a truncation is upgraded to a detection.
    """
    # An ordinary crash: a tear halfway through a line. Costs NOTHING, permanently.
    crash = tmp_path / "crash.jsonl"
    _chain_history(crash, 4)
    raw = crash.read_bytes()
    cut = raw.rfind(b"\n", 0, len(raw) - 1)
    crash.write_bytes(raw[: cut + 1] + raw[cut + 1 :][: len(raw[cut + 1 :]) // 2])
    report = runprov.chain.verify(crash)
    assert not report.of(runprov.chain.BROKEN), "[ADR-0016 R-11] it accuses nobody"
    assert not report.of(runprov.chain.UNCHECKABLE), (
        "[ADR-0016 R-20] the fragment kept its claim, so line 3 is still attested"
    )
    assert _chain_exit(crash) == 0, "a crash must not cost a project its gate, for ever"

    # Audit G, G-17 and G-08 — RESTORED. This assertion stood at `3dded76` and was replaced by
    # the negation above rather than joined to it, and with it went the only statement anywhere
    # that the newest line's own bytes are gone. The edge model cannot hold that fact: an edge
    # judges the LINK between two lines, and the newest line is the predecessor of no edge, so
    # `json.loads` refused it, `log`, `show` and `report` could not read it, and the page said
    # INTACT with no mention of it.
    #
    # DISCLOSURE, AND IT MUST CHANGE NO VERDICT — which is why it sits UNDER the exit-code
    # assertion above rather than replacing it. Making it decisive was measured and refused: it
    # moves the ordinary crash off exit 0 and contradicts "a crash must not cost a project its
    # gate, for ever" on the line above.
    assert report.unreadable == (4,), "the fragment is reported"
    page = runprov.chain.render(report, crash)
    assert [line for line in page if line.lstrip().startswith("UNREADABLE  line 4")], page
    assert "Truncation of the tail cannot be seen from this file alone" not in "\n".join(page), (
        "[ADR-0016 R-23]'s sentence is about whole lines REMOVED — nothing in a file says how "
        "long it used to be. It is FALSE over a file whose last line the parser has just "
        "refused, where the truncation is exactly what IS visible from this file alone."
    )
    assert runprov.__main__.main(["chain", str(crash), "--format", "json"]) == 0
    payload = json.loads(capsys.readouterr().out)
    assert payload["unreadable"] == [4], payload
    assert payload["status"] == "INTACT", "the machine reader is told BOTH, and the verdict held"

    # G-08's other half: the same tear ONE BYTE further, side by side. The verdicts differ and
    # they are RIGHT to differ — R-20's recovery of the claim genuinely is more evidence — so
    # what this asserts is that the two answers are now legible next to each other, which is
    # the thing that was missing. The line is unreadable in both, and both say so.
    further = tmp_path / "further.jsonl"
    _chain_history(further, 4)
    raw = further.read_bytes()
    cut = raw.rfind(b"\n", 0, len(raw) - 1)
    further.write_bytes(raw[: cut + 1] + raw[cut + 1 :][:74] + b"\n")
    beyond = runprov.chain.verify(further)
    assert beyond.status == runprov.chain.CANNOT_CHECK and _chain_exit(further) == 2, (
        '74 bytes is one short of `{"prev": "` plus 64 hex plus its quote, so [ADR-0016 '
        "R-20] recovers nothing and the edge is UNCHECKABLE"
    )
    assert beyond.unreadable == (4,) and report.unreadable == beyond.unreadable, (
        "the SAME line is unreadable on both sides of the 75-byte anchor; only the recovered "
        "claim differs, and the report now states the shared fact in both"
    )

    # A mid-file tear: still no accusation, and the line it can no longer vouch for is named.
    mid = tmp_path / "mid.jsonl"
    lines = _chain_history(mid, 5)
    mid.write_bytes(b"\n".join([*lines[:2], lines[2][:20], *lines[3:]]) + b"\n")
    report = runprov.chain.verify(mid)
    assert not report.of(runprov.chain.BROKEN), (
        "[ADR-0016 R-11] a torn line is a fact about a disk, not about a person"
    )
    # BOTH edges around a torn line: the one it makes (its claim is unreadable) and the one
    # above it (its bytes cannot be compared). My first expectation here was [3] — a torn
    # line costs TWO edges, not one, and the model says so where intuition did not.
    assert [e.line for e in report.of(runprov.chain.UNCHECKABLE)] == [3, 4]
    assert _chain_exit(mid) == 2, "unverifiable is not intact"
    # G-17: the disclosure SUBTRACTS what the edges have already said. Line 3 is unreadable and
    # two sentences above name it — rule 6 at its own edge and rule 9 at the edge below — so a
    # third wording of the same fact would be the confusion this row exists to remove.
    assert report.unreadable == (3,) and not [
        line for line in runprov.chain.render(report, mid) if "UNREADABLE  line" in line
    ], runprov.chain.render(report, mid)

    # The concealment attempt: edit a line, truncate the line that would have accused it.
    hidden = tmp_path / "hidden.jsonl"
    lines = _chain_history(hidden, 6)
    edited = lines[4].replace(b'"status": "ok"', b'"status": "FORGED"')
    hidden.write_bytes(b"\n".join([*lines[:4], edited, lines[5][:90]]) + b"\n")
    assert _chain_exit(hidden) == 1, (
        "[ADR-0016 R-20] the fragment kept its claim, and the claim disagrees with the forgery"
    )


def test_the_verdict_is_broken_then_unverifiable_then_intact(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-8]. Audit E, E-05 and E-10.

    The first version consulted only `broken`, so a file in which ONE link of six could be
    checked printed INTACT and exited 0 — the vacuous pass, delivered as a green gate, by the
    command built to detect exactly that. `--format json` carried it to machines, where no
    `COULD NOT CHECK` row can be read as mitigation.
    """
    p = tmp_path / "h.jsonl"
    _chain_history(p, 4)
    assert runprov.__main__.main(["chain", str(p)]) == 0
    assert "INTACT" in capsys.readouterr().out

    shredded = tmp_path / "shredded.jsonl"
    lines = _chain_history(shredded, 6)
    shredded.write_bytes(lines[0] + b"\n" + b"\n".join(b"{ not json" for _ in lines[1:]) + b"\n")
    assert runprov.__main__.main(["chain", str(shredded)]) == 2, (
        "one checkable link of six is not a clean bill of health"
    )
    out = capsys.readouterr().out
    assert "INTACT" not in out, out

    # The JSON payload carries the same verdict. Its only test used to be a clean two-line
    # history in which every field equalled its correct value, so three mutations of it survived.
    assert runprov.__main__.main(["chain", str(shredded), "--format", "json"]) == 2
    payload = json.loads(capsys.readouterr().out)
    assert payload["status"] == "CANNOT_CHECK"
    assert payload["attested"] == 0 and payload["lines"] == 6
    assert [e["line"] for e in payload["edges"] if e["status"] == "UNCHECKABLE"] == [2, 3, 4, 5, 6]


def test_a_break_says_only_what_is_true_of_the_break_it_found(tmp_path):
    """ADR-0016 [ADR-0016 R-10] [ADR-0016 R-32]. Audit E, E-07.

    One sentence was formatted for every break, so it produced three false statements: "LINE 0
    IS WHAT CHANGED" for a deleted first line, naming a line that does not exist; "line 0 hashes
    to GENESIS", presenting the sentinel as a digest; and "LINE N-1 IS WHAT CHANGED" for a line
    that made no claim at all, where this requirement's own reasoning does not hold.

    THE VERDICT ON THE THIRD CASE CHANGED UNDER [ADR-0016 R-32], and this test asserted the old
    one. E-07 fixed the SENTENCE printed for a line that made no claim; Audit G found that the
    verdict behind the sentence was wrong too. A tail-appended line with no `prev` is what a
    forger who did not compute the digest leaves — and equally what an append that could not
    take the lock (G-01) and a start line whose run is still in flight (G-05) leave, over files
    in which every record is present and every byte is original. Rule 7 therefore answers
    `UNCLAIMED`, not `BROKEN`, and this case now belongs to the UNCLAIMED rows rather than the
    BROKEN ones. R-10's own scope shrinks with it: BROKEN can now arise only from rules 0, 2
    and 11, all of which have a claim, so `Link.detail`'s claimless arm was deleted as
    unreachable. What this test still guards is that the two remaining breaks say only what is
    true of themselves.
    """
    p = tmp_path / "h.jsonl"
    lines = _chain_history(p, 4)

    edited = tmp_path / "edited.jsonl"
    edited.write_bytes(
        b"\n".join([*lines[:1], lines[1].replace(b'"ok"', b'"NO"'), *lines[2:]]) + b"\n"
    )
    detail = runprov.chain.verify(edited).of(runprov.chain.BROKEN)[0].detail
    assert "line 3 claims" in detail and "LOOK BETWEEN LINES 2 AND 3" in detail, detail
    assert "line 2 was edited in place" in detail, (
        "Audit H, H1-4: an in-place edit is still NAMED as a possible cause — the sentence "
        "stopped naming it as the only one, it did not stop naming it"
    )

    # H1-4. THE TWO SHAPES NO TEST IN THIS SUITE EVER CONSTRUCTED, which is how "LINE N-1 IS
    # WHAT CHANGED" came to be printed over lines that are byte-for-byte what the original
    # held. Deletion and reordering are two of the three threats this module's docstring names,
    # and both take the same DIFFERS path an edit takes, so no mutation distinguishes them.
    for name, rebuilt in (
        ("deleted", [*lines[:1], *lines[2:]]),
        ("reordered", [lines[0], lines[2], lines[1], lines[3]]),
    ):
        victim = tmp_path / f"{name}.jsonl"
        victim.write_bytes(b"\n".join(rebuilt) + b"\n")
        breaks = runprov.chain.verify(victim).of(runprov.chain.BROKEN)
        assert breaks, f"{name} must still be a break; that verdict was never in doubt"
        first = breaks[0]
        untouched = victim.read_bytes().rstrip(b"\n").split(b"\n")[first.line - 2]
        assert untouched in lines, (
            f"{name}: line {first.line - 1} is byte-for-byte a line of the original — this is "
            f"the file over which the capitalised accusation was false"
        )
        assert f"LINE {first.line - 1} IS WHAT CHANGED" not in first.detail, first.detail
        assert f"LOOK BETWEEN LINES {first.line - 1} AND {first.line}" in first.detail
        assert "deleted, reordered, or pushed aside by an insertion" in first.detail, (
            "the disjunction, with no cause picked — rule 0's reasoning, applied to rule 11"
        )
        assert first.claimed in first.detail and first.computed in first.detail, (
            "[ADR-0016 R-10] [ADR-0016 R-12]: both digests stay whole, whatever the wording"
        )

    beheaded = tmp_path / "beheaded.jsonl"
    beheaded.write_bytes(b"\n".join(lines[1:]) + b"\n")
    detail = runprov.chain.verify(beheaded).of(runprov.chain.BROKEN)[0].detail
    assert "LINE 0" not in detail and "GENESIS" not in detail, detail
    assert "removed from the front" in detail, detail

    # G-09: THE FOURTH SHAPE, and the only one reachable with no forger at all. Two histories
    # rotated under [ADR-0016 R-14] and concatenated — `cat old.jsonl new.jsonl > merged.jsonl`
    # — put a line whose `prev` is the GENESIS sentinel behind two other lines. Rule 0 breaks
    # that edge, and the VERDICT is right: the file really is two chains spliced. The sentence
    # was rule 11's, and it read "line 3 claims its predecessor was GENESIS but line 2 hashes
    # to c7cd… — LINE 2 IS WHAT CHANGED" over a line 2 that is byte-for-byte what the old file
    # held. Both halves verify INTACT alone, so a reader was sent to an untouched line in an
    # untouched file — E-07's own failure, at the one break shape E-07 did not enumerate.
    old_file = tmp_path / "old.jsonl"
    new_file = tmp_path / "new.jsonl"
    old_lines = _chain_history(old_file, 2)
    new_lines = _chain_history(new_file, 2)
    assert runprov.chain.verify(old_file).status == runprov.chain.INTACT
    assert runprov.chain.verify(new_file).status == runprov.chain.INTACT, (
        "each half is a complete, correct history; nothing was edited to reach this state"
    )
    merged = tmp_path / "merged.jsonl"
    merged.write_bytes(b"\n".join([*old_lines, *new_lines]) + b"\n")
    joined = runprov.chain.verify(merged)
    assert [e.line for e in joined.of(runprov.chain.BROKEN)] == [3]
    assert merged.read_bytes().split(b"\n")[1] == old_lines[1], "line 2 was never touched"
    detail = joined.of(runprov.chain.BROKEN)[0].detail
    assert "LINE 2 IS WHAT CHANGED" not in detail, detail
    assert "line 2 hashes to" not in detail, detail
    assert hashlib.sha256(old_lines[1]).hexdigest() not in detail, (
        "and no digest of the untouched line is offered as a comparand. That clause was "
        "wrong in FORM rather than in fact — inviting a comparison between a sentinel and a "
        "64-hex digest — where 'LINE 2 IS WHAT CHANGED' was flatly false"
    )
    assert "line 3 declares itself the first line of a chain" in detail, detail
    assert "sentinel, not a digest" in detail, detail
    assert "2 line(s) precede it" in detail, detail
    assert "or a line inserted that was never chained here" in detail, (
        "and the cause stays OPEN. Two histories joined and a line inserted by hand that was "
        "never chained here leave the same bytes, and this file cannot tell them apart"
    )

    # The line that made no claim: STILL not accused of moving its predecessor, and now not
    # accused at all. [ADR-0016 R-32] — the same bytes are what an unlocked append and an
    # in-flight run leave behind, so the claimless arm of `Link.detail` is gone with the
    # verdict that reached it, and there is no BROKEN edge here to ask for a detail.
    spliced = tmp_path / "spliced.jsonl"
    forged = json.dumps({"run_id": "x", "tool": {"version": "0.6.0"}}).encode()
    spliced.write_bytes(b"\n".join([*lines, forged]) + b"\n")
    report = runprov.chain.verify(spliced)
    assert not report.of(runprov.chain.BROKEN), "a line that made no claim accuses nobody"
    assert [e.line for e in report.of(runprov.chain.UNCLAIMED)] == [5]
    assert report.status == runprov.chain.CANNOT_CHECK, "disclosed, decisive, and not an edit"

    # And every sentence `Link.detail` can still produce comes from a break that HAS a claim.
    for link in (*runprov.chain.verify(edited).edges, *runprov.chain.verify(beheaded).edges):
        assert link.status != runprov.chain.BROKEN or link.claimed is not None


def test_an_unchained_line_is_judged_by_the_version_that_wrote_it(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-5] [ADR-0016 R-32]. Audit E, E-02 — the row that made the original
    unimplementable.

    R-5 first said a line with no `prev` after the chain began is a break, because that is what
    splicing an old-format line in looks like. It is also exactly what A COLLEAGUE RUNNING A
    SUPPORTED RELEASE looks like: 0.1.0 through 0.5.0 are on PyPI, none writes `prev`, and from
    the file alone the two are byte-identical. Reproduced during the audit with a real 0.5.0
    wheel — one ordinary run marked the history tampered permanently.

    Taylor's decision (2026-09-18) was to keep it strict rather than tolerate mixed versions,
    because a rule that shrugs is a rule nobody acts on. A human acknowledgement was proposed
    and rejected on the right grounds — "most people will just open it and say okay without
    really verifying" — so the judgement is made from evidence already in the record.

    WHAT CHANGED UNDER [ADR-0016 R-32], and it is the other half of the same argument. E-02
    rescued the PRE_CHAIN case by reading `tool.version`; Audit G found the CAPABLE and
    UNSTATED cases needed the same rescue for the same reason, and could not get it from the
    record because there is nothing in the record to read. The exit code for the chain-capable
    unclaimed line therefore moves from 1 to 2. R-5's strictness is untouched and this test
    still asserts it: a 0.5.0 line is a GAP, it is decisive, and the report names the machine.
    That sentence — "upgrade that machine" — belongs to rule 5 ALONE, and rule 7's own sentence
    must never borrow it, because the machine is unnamed and an in-flight run needs no upgrade.
    """
    old = tmp_path / "old.jsonl"
    _chain_history(old, 3)
    with old.open("ab") as fh:
        fh.write(
            json.dumps(
                {"schema": "runprov.history.v2", "run_id": "x", "tool": {"version": "0.5.0"}}
            ).encode()
            + b"\n"
        )
    report = runprov.chain.verify(old)
    assert not report.of(runprov.chain.BROKEN), "a supported release is not a forger"
    assert [e.wrote for e in report.of(runprov.chain.GAP)] == ["0.5.0"]
    assert runprov.__main__.main(["chain", str(old)]) == 2, (
        "but it IS unverifiable, and it is FIXABLE — which is what gives the strict reading teeth"
    )
    out = capsys.readouterr().out
    assert "1 line(s) written by runprov 0.5.0" in out and "upgrade that machine" in out, out

    # A CHAIN-CAPABLE release that wrote no `prev` is DISCLOSED, not accused — [ADR-0016 R-32].
    # Exit 2, not 1: it is the same shape as an unlocked append and an in-flight start line.
    forged = tmp_path / "forged.jsonl"
    _chain_history(forged, 3)
    with forged.open("ab") as fh:
        fh.write(json.dumps({"run_id": "x", "tool": {"version": "0.6.0"}}).encode() + b"\n")
    assert runprov.__main__.main(["chain", str(forged)]) == 2
    unclaimed = capsys.readouterr().out
    assert "carries no chain claim" in unclaimed and "UNCLAIMED" in unclaimed, unclaimed
    assert "upgrade that machine" not in unclaimed, (
        "rule 5's advice, on a line that names no machine and may need no upgrade at all"
    )

    # And the PRE-CHAIN prefix is disclosed and never decisive: no upgrade can retroactively
    # chain a line that was already written, so making it decisive would mean no project that
    # predates the feature could ever exit 0.
    upgraded = tmp_path / "upgraded.jsonl"
    upgraded.write_bytes(b'{"schema": "runprov.history.v2", "run_id": "before"}\n' * 3)
    runprov.JsonlSink(upgraded).append({"schema": "runprov.history.v2", "run_id": "after"})
    assert runprov.__main__.main(["chain", str(upgraded)]) == 0
    assert "3 line(s) predate the chain" in capsys.readouterr().out


def test_the_version_a_gap_names_is_the_one_it_was_judged_by(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-5] [ADR-0016 R-29]. Audit H, H1-6.

    THE MESSAGE READ THE LINE AND THE JUDGEMENT READ THE RUN, and they are not the same value.
    `_writer_of` resolves a version from the line's own `tool.version` and, failing that, from
    the completed record sharing its `run_uid` (R-29); the sentence resolved it again, inline,
    from the raw `tool.get("version")` alone. So a line whose own version field is not a string
    was JUDGED on the version its run states and REPORTED with the raw field:

        1 line(s) written by runprov 12345, which cannot chain — upgrade that machine

    and `Link.wrote`, annotated `str | None`, held an int that `--format json` emitted as a
    number. That is F-09's shape — two expressions for one fact are two places a later edit can
    move apart — and it is what makes a reader distrust a page: the machine named is not the
    machine the tool decided about.

    Both GAP lines below belong to the same run and the same 0.5.0 machine, so the report has
    one sentence to make about them. Before the fix it made two, and one named a number.
    """
    p = tmp_path / "h.jsonl"
    _chain_history(p, 2)
    uid = "u" * 32
    with p.open("ab") as fh:
        for tool in (
            {"name": "runprov", "version": "0.5.0"},
            {"name": "runprov", "version": 12345},
        ):
            fh.write(
                json.dumps(
                    {"schema": "runprov.history.v2", "run_id": "old", "run_uid": uid, "tool": tool}
                ).encode()
                + b"\n"
            )

    report = runprov.chain.verify(p)
    gaps = report.of(runprov.chain.GAP)
    assert [e.line for e in gaps] == [3, 4], (
        "both are judged PRE_CHAIN — the second only through its run, which is R-29's whole "
        "point and the half the message did not use"
    )
    assert [e.wrote for e in gaps] == ["0.5.0", "0.5.0"], [e.wrote for e in gaps]
    assert all(isinstance(e.wrote, str) or e.wrote is None for e in report.edges), (
        "`Link.wrote` is annotated `str | None`, and `--format json` publishes it"
    )

    assert runprov.__main__.main(["chain", str(p)]) == 2
    page = capsys.readouterr().out
    assert "2 line(s) written by runprov 0.5.0, which cannot chain" in page, page
    assert "12345" not in page, "the raw field, printed as though it were a release"

    assert runprov.__main__.main(["chain", str(p), "--format", "json"]) == 2
    payload = json.loads(capsys.readouterr().out)
    assert [e["wrote"] for e in payload["edges"] if e["status"] == "GAP"] == ["0.5.0", "0.5.0"]


def test_a_translated_checkout_is_named_rather_than_called_tampering(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-21]. Audit E, E-01 — the maximal false accusation.

    Reproduced during the audit with a real `git clone --config core.autocrlf=true`, git's
    Windows default, on a history committed with LF: EVERY line from the second onward reported
    BROKEN, each naming a specific innocent line. `README.md` recommends tracking `provenance/`
    in git, and this project's `.gitattributes` protects its own test data and nothing a user
    would have.

    The bytes genuinely did change, so INTACT would be false. What is false is calling it
    tampering — so the report names the cause and the one-line fix.
    """
    p = tmp_path / "h.jsonl"
    _chain_history(p, 4)
    p.write_bytes(p.read_bytes().replace(b"\n", b"\r\n"))

    report = runprov.chain.verify(p)
    assert report.translated == 4 and not report.of(runprov.chain.BROKEN), (
        "nobody edited this file, and the count is per LINE rather than a verdict"
    )
    assert runprov.__main__.main(["chain", str(p)]) == 2
    out = capsys.readouterr().out
    assert "translated" in out and "-text" in out, out
    assert "edited after it was written" not in out, "no accusation anywhere on the page"


def test_the_report_counts_attested_lines_and_says_the_newest_is_not_one(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-9] [ADR-0016 R-23]. Audit E, E-04 and E-09.

    The count was of COMPARISONS, which is wrong by one in every history born after this
    feature: line 1's comparison is against the `GENESIS` sentinel, which attests no bytes —
    any forger writes it for free. Six comparisons, five attested lines, and the report said
    six of six. `N of N` asserts coverage the mechanism cannot have.

    [ADR-0016 R-23] is the standing disclosure: line N's bytes are attested only by line N+1, so
    the newest line is attested by nothing and a tail truncation cannot be seen from this file
    alone. Both are genuinely undetectable — a line cannot contain its own digest — so the fix
    is to say so, which is this package's character everywhere else.
    """
    p = tmp_path / "h.jsonl"
    _chain_history(p, 6)
    report = runprov.chain.verify(p)
    assert report.lines == 6
    assert report.attested == 5, "six lines, five edges; the sentinel attests nothing"
    assert report.attested >= 0, "and the arithmetic can no longer go negative"

    assert runprov.__main__.main(["chain", str(p)]) == 0
    out = capsys.readouterr().out
    assert "5 line(s) attested of 6" in out, out
    assert "line 6 is the newest and nothing attests it yet" in out, out
    assert "Truncation of the tail cannot be seen from this file alone" in out, out

    # A history with pre-chain lines: the two numbers are far apart and both are printed.
    mixed = tmp_path / "mixed.jsonl"
    mixed.write_bytes(b'{"schema": "runprov.history.v2", "run_id": "old"}\n' * 5)
    runprov.JsonlSink(mixed).append({"schema": "runprov.history.v2", "run_id": "a"})
    runprov.JsonlSink(mixed).append({"schema": "runprov.history.v2", "run_id": "b"})
    got = runprov.chain.verify(mixed)
    # Seven lines, two claims, two attested — and note WHICH two: line 6's claim attests line 5,
    # which is a PRE-CHAIN line. That is [ADR-0016 R-4] anchoring doing its work, and it is why
    # one run is enough to make editing the last pre-chain line detectable.
    assert (got.lines, got.attested) == (7, 2), (got.lines, got.attested)
    assert got.chained_from == 6 and len(got.of(runprov.chain.UNCHAINED)) == 5


def test_a_line_that_is_json_but_not_an_object_cannot_raise(tmp_path):
    """ADR-0016 [ADR-0016 R-24]. Audit E, E-11.

    `json.loads(b"[1, 2, 3]")` succeeds and has no `.get`. Every fixture written for R-11 fed
    syntactically INVALID JSON, so the half of the guard handling "or not an object" was
    asserted by nothing and a mutation removing it survived the whole suite. `verify`'s own
    docstring promises it never raises, and a verifier that raises is one nobody runs twice.
    """
    assert runprov.chain.claimed_by(b"[1, 2, 3]") is None
    assert runprov.chain.claimed_by(b'"just a string"') is None
    assert runprov.chain.claimed_by(b"null") is None
    assert runprov.chain.claimed_by(b'{"prev": 12345}') is None, "a non-string claim is no claim"

    p = tmp_path / "h.jsonl"
    p.write_bytes(b"[1, 2, 3]\n")
    runprov.JsonlSink(p).append({"schema": "runprov.history.v2", "run_id": "after"})
    report = runprov.chain.verify(p)  # must not raise
    assert report.lines == 2 and not report.of(runprov.chain.BROKEN)


def test_the_chain_survives_the_shapes_a_real_history_file_reaches(tmp_path, monkeypatch, capsys):
    """ADR-0016, the edges. Each is a state a long-lived history actually reaches.

    A history is appended to by crashing processes on shared filesystems for years. A verifier
    that raises, or divides by zero, or reports a number it cannot justify, on any one of these
    is a verifier nobody runs twice.
    """
    # A version string the record states but this package cannot parse.
    assert runprov.chain._version_of({"tool": {"version": "nightly"}}) is None
    assert runprov.chain._version_of({"tool": "0.5.0"}) is None
    assert runprov.chain._version_of({}) is None

    # A file that is one bare newline: an empty last line, which is still a line with a digest.
    lone = tmp_path / "lone.jsonl"
    lone.write_bytes(b"\n")
    runprov.JsonlSink(lone).append({"n": 1})
    grown = lone.read_bytes().rstrip(b"\n").split(b"\n")
    assert json.loads(grown[1])["prev"] == hashlib.sha256(b"").hexdigest()

    # A first line longer than the tail block, so the backwards read must loop.
    big = tmp_path / "big.jsonl"
    runprov.JsonlSink(big).append({"pad": "x" * (runprov.chain._TAIL_BLOCK * 3)})
    runprov.JsonlSink(big).append({"n": 2})
    lines = big.read_bytes().rstrip(b"\n").split(b"\n")
    assert json.loads(lines[1])["prev"] == hashlib.sha256(lines[0]).hexdigest()

    # An unreadable file is CANNOT_CHECK, never an accusation, and never an exception.
    def _refuse(self):
        raise OSError("EACCES")

    monkeypatch.setattr(pathlib.Path, "read_bytes", _refuse)
    blocked = runprov.chain.verify(tmp_path / "anything.jsonl")
    assert blocked.status == runprov.chain.CANNOT_CHECK and blocked.attested == 0
    monkeypatch.undo()

    # A missing history, and a project with none configured at all.
    assert runprov.__main__.main(["chain", str(tmp_path / "absent.jsonl")]) == 2
    assert "no history to read" in capsys.readouterr().out
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=".", run_log=None)
    assert runprov.__main__.main(["chain"]) == 2
    assert "no history to read" in capsys.readouterr().out, (
        "G-06. A project with no explicit `run_log` is the DEFAULT project, not a project with "
        "no history: the path resolves to `provenance/runs.jsonl` and it is simply not there. "
        "One answer for one state — the same sentence `chain <absent path>` gives above."
    )

    # Two torn lines in a row: the second's predecessor is already reported unreadable, so it
    # is not ALSO reported unattested — one finding, not two.
    doubled = tmp_path / "doubled.jsonl"
    lines = _chain_history(doubled, 5)
    doubled.write_bytes(b"\n".join([*lines[:2], lines[2][:15], lines[3][:15], lines[4]]) + b"\n")
    report = runprov.chain.verify(doubled)
    assert [e.line for e in report.of(runprov.chain.UNCHECKABLE)] == [3, 4, 5], (
        "two adjacent torn lines cost three edges: the two they make and the one above them"
    )

    # A torn line BEFORE the chain begins has no attested predecessor to lose — there is no
    # line 0, and nothing before `chained_from` was ever attested by anything. The walk must
    # not reach back past the start of the file looking for one.
    headless = tmp_path / "headless.jsonl"
    headless.write_bytes(b"{ torn from an older crash\n")
    runprov.JsonlSink(headless).append({"schema": "runprov.history.v2", "run_id": "after"})
    report = runprov.chain.verify(headless)
    assert report.edges[0].status == runprov.chain.UNCHECKABLE, (
        "a torn FIRST line did not predate the chain — we cannot read what it said"
    )
    assert report.chained_from == 2
    # Audit G, G-21. THE WHOLE REPORT, restored. Two whole-report assertions stood here and
    # were replaced by the single field above, which watches one status of one edge and leaves
    # the digests unwatched — so letting the walk reach `lines[index - 2]` for index 1 passed
    # THIS test, the one whose docstring sets the standard ("reports a number it cannot
    # justify"). Measured on the mutant: this test RETURN CODE 0.
    #
    # `lines[-1]` is the file's LAST line, so the first edge reported ITS digest as line 0's,
    # and `__main__` emits `computed` for every edge in the `--format json` payload — a machine
    # reader told that a line which does not exist hashes to a specific value.
    assert report.edges[0].computed is None, (
        "there is no line 0, so the first edge can hold no computed digest — and the digest it "
        "held was the file's LAST line, reached by walking backwards off the front"
    )
    assert [e.status for e in report.edges] == [
        runprov.chain.UNCHECKABLE,
        runprov.chain.HOLDS,
    ], [e.status for e in report.edges]


def test_the_chain_is_verifiable_with_sha256sum_and_nothing_else(tmp_path):
    """ADR-0016 [ADR-0016 R-12]. The claim the README leads with, applied to the chain.

    A chain that needed this package to check it would be worth less than no chain, because it
    would be believed. This runs the recipe printed in the ADR — `sha256sum`, `sed`, a shell
    loop — over a fully chained file, with the package's own module not involved at all.

    THE RECIPE IS FOR A FULLY CHAINED FILE and says so in the ADR. On a history with an
    unchained prefix it reports those lines as breaks, which is the honest limit of a nine-line
    shell loop: it is a second opinion, not a second implementation, and the safe direction for
    a second opinion to err in is toward shouting.
    """
    if not shutil.which("sha256sum"):  # pragma: no cover - not on this leg
        pytest.skip("sha256sum is not available here")
    p = tmp_path / "h.jsonl"
    _chain_history(p, 5)
    recipe = tmp_path / "check.sh"
    recipe.write_text(
        'n=0; prev="GENESIS"; bad=0\n'
        "while IFS= read -r line; do\n"
        "  n=$((n+1))\n"
        '  claimed=$(printf \'%s\' "$line" | sed -n \'s/.*"prev": *"\\([^"]*\\)".*/\\1/p\')\n'
        '  [ "$claimed" = "$prev" ] || { echo "BREAK $n"; bad=1; }\n'
        "  prev=$(printf '%s' \"$line\" | sha256sum | cut -d' ' -f1)\n"
        # THE BARE FILENAME, with the script run from its directory. A Windows path
        # (`C:\\Users\\…`) interpolated into a shell redirect has its backslashes eaten
        # as escapes, so the loop read nothing, `bad` stayed 0, and this reported that the
        # recipe had missed an edit it was never shown. Twelfth host-dependent test today.
        "done < " + p.name + "\n"
        'echo "bad=$bad"\n',
        encoding="utf-8",
    )
    clean = subprocess.run(
        ["sh", recipe.name], cwd=tmp_path, capture_output=True, text=True, check=False
    )
    assert "bad=0" in clean.stdout, clean.stdout

    lines = p.read_text(encoding="utf-8").splitlines()
    lines[2] = lines[2].replace('"run_id": "r2"', '"run_id": "rX"')
    # NEWLINE="" so the platform does not translate LF to CRLF on the way out: every digest
    # here was taken over LF bytes, and letting the rewrite change them would exercise R-21 by
    # accident instead of the edit this case is about.
    p.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="")
    edited = subprocess.run(
        ["sh", recipe.name], cwd=tmp_path, capture_output=True, text=True, check=False
    )
    assert "BREAK 4" in edited.stdout, f"the shell must catch it too: {edited.stdout}"
    assert runprov.chain.verify(p).status == runprov.chain.BROKEN, "and so must the package"


def test_nothing_in_the_package_removes_a_history_line(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-13]. Audit E, E-15 — and the first test for this was vacuous.

    R-13 was written believing `prune` removes history lines and would therefore need a rebuild
    marker. It does not: it unlinks in-flight MARKER files inside `.incomplete`, and its own
    docstring says in capitals that the history is what it is NOT ALLOWED to touch. So the
    requirement inverted — there is no legitimate discontinuity, and any break is a finding.

    The assertion that stood here was `assert "prune" not in out` — a word absent from a report
    that never contained it, which is true of almost any string and proves nothing. This runs
    `prune` against a real history and checks the bytes.
    """
    monkeypatch_root = tmp_path / "proj"
    (monkeypatch_root / ".incomplete").mkdir(parents=True)
    history = monkeypatch_root / "h.jsonl"
    _chain_history(history, 4)
    before = history.read_bytes()
    (monkeypatch_root / ".incomplete" / "dead.json").write_text(
        json.dumps({"run_id": "gone", "started_utc": "2020-01-01T00:00:00Z"}), encoding="utf-8"
    )

    runprov.configure(root=monkeypatch_root, run_log=history)
    assert runprov.__main__.main(["prune", "--older-than", "1s"]) in (0, 1, 2)
    capsys.readouterr()

    assert history.read_bytes() == before, "prune must not touch one byte of the history"
    assert runprov.chain.verify(history).status == runprov.chain.INTACT


def test_a_rotated_history_needs_no_support_from_the_chain(tmp_path):
    """ADR-0016 [ADR-0016 R-14]. A new file starts at GENESIS; the old one still verifies.

    A chain spanning files would need an index, which is a store, which is the thing this
    package does not build. Rotation therefore costs nothing and needs no procedure — which is
    also why a head-anchor sibling file was rejected during Audit E: it would have made a
    legitimate rotation look like tampering.
    """
    live = tmp_path / "h.jsonl"
    _chain_history(live, 4)
    live.rename(tmp_path / "h.1.jsonl")
    runprov.JsonlSink(live).append({"schema": "runprov.history.v2", "run_id": "fresh"})

    assert json.loads(live.read_text(encoding="utf-8"))["prev"] == runprov.chain.GENESIS
    assert runprov.chain.verify(tmp_path / "h.1.jsonl").status == runprov.chain.INTACT
    assert runprov.chain.verify(live).status == runprov.chain.INTACT


def test_prev_is_a_property_of_the_file_and_reaches_nothing_else(tmp_path, monkeypatch):
    """ADR-0016 [ADR-0016 R-15] [ADR-0016 R-16] [ADR-0016 R-17] [ADR-0016 R-18].

    [ADR-0016 R-15] is the one that would have bitten: `prev` differs between any two lines by
    construction, so a `diff` that compared it would report a change on every pair ever
    compared — A-07's gate-that-cannot-pass, arriving through a field added for another purpose.
    """
    monkeypatch.chdir(tmp_path)
    (tmp_path / "in.tsv").write_text("a\n", encoding="utf-8")
    runprov.configure(root=".", run_log="h.jsonl", auto_steps="off")
    with runprov.Run("s", {}, provenance="p.json") as run:
        run.input("in.tsv")
        with run.open_output("out.tsv") as fh:
            fh.write("x\n")

    history = [json.loads(x) for x in (tmp_path / "h.jsonl").read_text().splitlines() if x]
    done = [r for r in history if r.get("schema") == runprov.HISTORY_SCHEMA][-1]
    assert "prev" in done, "the history line carries it"

    # [ADR-0016 R-18] the sidecar stands alone and has no predecessor
    assert "prev" not in json.loads((tmp_path / "p.json").read_text(encoding="utf-8"))
    # [ADR-0016 R-17] the pin answers whether a result follows from its inputs
    assert "prev" not in (tmp_path / "out.tsv").read_text(encoding="utf-8")
    # [ADR-0016 R-16] RO-Crate and PROV are provenance vocabularies; this is one file's storage
    for shape in (runprov.export.to_ro_crate([done]), runprov.export.to_prov_json([done])):
        assert "prev" not in json.dumps(shape)
    # [ADR-0016 R-15] and no dimension may compare it
    assert not any(d.differences for d in runprov.diff.compare(done, dict(done, prev="f" * 64))), (
        "a field that differs by construction must never decide a gate"
    )


CHAIN_CELLS = list(
    itertools.product(
        runprov.chain.CLAIMS,
        runprov.chain.PREDECESSORS,
        runprov.chain.AGREEMENTS,
        runprov.chain.WRITERS,
        (False, True),
    )
)

#: ADR-0016 R-25's table, TRANSCRIBED FROM THE DOCUMENT AND NOT FROM `classify` — the condition
#: column of the ADR, in the precedence order the ADR states, as a flat first-match list rather
#: than the nested branches the module uses. Two independent statements of one specification,
#: which is the only way a test of a decision table can fail for the right reason: a check
#: derived from the code it checks agrees with the code by construction.
#:
#: Audit G, G-04. What stood here asserted that the 216 statuses were a SUBSET of the six the
#: module names. `classify` has no `return None` path and every status it can return is already
#: in that set, so the sweep survived every rule change: measured, deleting rule 1 survived the
#: ENTIRE suite, and every clean all-0.6.0 history then printed `1 line(s) predate the chain`
#: at 100 % branch coverage with the requirement citation intact. `HOLDS_TRIVIAL` appeared once
#: in the whole test file — inside the superset that could not fail from its absence.
#:
#: The rejected repair was a `Counter` of the status histogram: it kills all thirteen rules, but
#: it is six hand-written numbers, a lossy digest whose "fix" on any deliberate rule change is
#: to paste new counts. THIS PROJECT'S MOST EXPENSIVE RECURRING LESSON IS THAT A HAND-WRITTEN
#: SCOPE IS WHERE THE DEFECT SITS, so the whole map is compared instead and nothing is counted.
#:
#: TWO ROWS ARE WIDENED, deliberately and visibly. The ADR writes rules 9 and 11 as
#: `agreement = DIFFERS`; in the module each is the `else` of its scope, so it also answers
#: `agreement = NA`. Transcribed literally the table would abstain wherever a line carries a
#: claim and the walk reported no comparison — a state `verify` cannot construct. Widening
#: keeps the transcription TOTAL, which is what R-30 is about, and the cells it covers are
#: named impossible by `test_the_reachable_cells_are_computed_and_the_rest_are_refused` rather
#: than left as a silent difference. How many there are is not written down, here or there.
R25_TABLE = (
    ("0", lambda c, p, a, w, s: c == "GENESIS" and p != "NONE_FIRST", runprov.chain.BROKEN),
    ("1", lambda c, p, a, w, s: p == "NONE_FIRST" and c == "GENESIS", runprov.chain.HOLDS_TRIVIAL),
    ("2", lambda c, p, a, w, s: p == "NONE_FIRST" and c == "DIGEST", runprov.chain.BROKEN),
    (
        "3",
        lambda c, p, a, w, s: p == "NONE_FIRST" and c == "NONE" and w == "UNREADABLE",
        runprov.chain.UNCHECKABLE,
    ),
    ("3b", lambda c, p, a, w, s: p == "NONE_FIRST" and c == "NONE", runprov.chain.UNCHAINED),
    ("4", lambda c, p, a, w, s: c == "NONE" and not s, runprov.chain.UNCHAINED),
    ("5", lambda c, p, a, w, s: c == "NONE" and w == "PRE_CHAIN", runprov.chain.GAP),
    ("6", lambda c, p, a, w, s: c == "NONE" and w == "UNREADABLE", runprov.chain.UNCHECKABLE),
    (
        "7",
        lambda c, p, a, w, s: c == "NONE" and w in ("CAPABLE", "UNSTATED"),
        runprov.chain.UNCLAIMED,
    ),
    ("8", lambda c, p, a, w, s: p == "UNREADABLE" and a == "MATCHES", runprov.chain.HOLDS),
    ("9", lambda c, p, a, w, s: p == "UNREADABLE", runprov.chain.UNCHECKABLE),  # else of R-25/9
    ("10", lambda c, p, a, w, s: a == "MATCHES", runprov.chain.HOLDS),
    ("11", lambda c, p, a, w, s: True, runprov.chain.BROKEN),  # the else of R-25 rule 11
)


def _by_the_adr(cell):
    """The rule of R-25 that decides `cell`, and the status it gives it — first match wins."""
    for rule, applies, status in R25_TABLE:
        if applies(*cell):
            return rule, status
    raise AssertionError(f"R-25 as transcribed decides nothing for {cell}")  # pragma: no cover


def test_the_decision_table_is_total_over_its_own_inputs():
    """ADR-0016 [ADR-0016 R-25] [ADR-0016 R-30] [ADR-0016 R-32]. The table, executed rather
    than read.

    Fifteen of the twenty-six defects in this feature were in one half of it — turning a file's
    partial evidence into one of three words — and that half has 216 input combinations folded
    over a file. I enumerated them by intuition three times, and three times a mutation pass
    came back complete because mutation testing proves the code does what the DESIGN says.

    So the inputs are a closed set and the classifier is total over it. Running the table is
    also what found two wrong cells BEFORE any code existed: a torn predecessor downgrading an
    impossible `GENESIS` claim, and a torn first line reported as "predates the chain" — the
    second being a defect from the previous round, reproduced inside the table written to
    prevent it. Reading the table had not shown either.

    RULE 7'S CELL CHANGED UNDER [ADR-0016 R-32] and this test asserted the old value, which is
    why the change lands here rather than only in the walk: `UNCLAIMED` is a fifth edge status
    and the enumeration of statuses has to grow with it. WHAT MUST NOT CHANGE, and is asserted
    below because it was the rejected remedy: the INPUT space stays at 216 cells. The refused
    fix for G-01 was a fourth `CLAIMS` value — a sentinel written on the unlocked path — which
    takes the table to 288, contradicts R-22's "no claim at all", helps no history already on
    disk, and hands a tail-forger a free BROKEN -> CANNOT_CHECK downgrade for the price of
    typing the word. The status is a property of the JUDGEMENT, so it costs no cells at all.

    AND THE SWEEP THAT SAID ALL THAT HAD NO DISCRIMINATING POWER (Audit G, G-04). It asserted
    that the statuses of all 216 cells were a SUBSET of the ones the module names, which no
    change to any rule can disturb — `classify` has no `return None` path and cannot return a
    status that is not in the set. Measured: of the thirteen rules of R-25, deleting or
    inverting six of them left this test green, and deleting rule 1 left the ENTIRE suite
    green while every clean all-0.6.0 history gained a false `1 line(s) predate the chain`.
    The whole map is now compared against `R25_TABLE`, a transcription of R-25 from the ADR,
    and all thirteen are caught — as is the rule-4/5 swap of G-12, which nothing caught before.
    """
    shipped = {cell: runprov.chain.classify(*cell) for cell in CHAIN_CELLS}
    by_the_adr = {cell: _by_the_adr(cell)[1] for cell in CHAIN_CELLS}
    disagreements = {
        cell: (by_the_adr[cell], shipped[cell])
        for cell in CHAIN_CELLS
        if by_the_adr[cell] != shipped[cell]
    }
    assert not disagreements, (
        f"{len(disagreements)} of {len(CHAIN_CELLS)} cells: the module and ADR-0016 R-25 "
        "disagree. Each entry is (claim, predecessor, agreement, writer, started): "
        f"(the ADR, the module). {disagreements}"
    )

    # No rule of R-25 is dead or shadowed — the transcription is what the module is measured
    # against, so a rule that quietly stopped deciding anything would weaken the measure
    # without failing it.
    assert {_by_the_adr(cell)[0] for cell in CHAIN_CELLS} == {rule for rule, _, _ in R25_TABLE}, (
        "a rule of R-25 decides no cell: it is shadowed by an earlier rule, or dead"
    )

    # EVERY status is produced, and no other. `==`, not `<=`: the subset form was G-04 — it
    # survived every rule change, because a status can only vanish from the left-hand side.
    assert set(shipped.values()) == {
        runprov.chain.HOLDS,
        runprov.chain.HOLDS_TRIVIAL,
        runprov.chain.UNCHAINED,
        runprov.chain.GAP,
        runprov.chain.UNCHECKABLE,
        runprov.chain.UNCLAIMED,
        runprov.chain.BROKEN,
    }, sorted(set(shipped.values()))
    assert len(CHAIN_CELLS) == 216, "the input space moved; the table must move with it"
    assert len(runprov.chain.CLAIMS) == 3, (
        "[ADR-0016 R-32] a fifth STATUS costs no cells; a fourth CLAIM would cost 72 and buy "
        "a tail-forger the downgrade this rule otherwise charges for"
    )

    # THE CELLS THAT DECIDE THE FEATURE, asserted individually rather than left to the sweep.
    # Each is a defect this project actually shipped.
    assert runprov.chain.classify("GENESIS", "READABLE", "DIFFERS", "CAPABLE", True) == (
        runprov.chain.BROKEN
    ), "rule 0: a sentinel is not a digest"
    assert runprov.chain.classify("GENESIS", "UNREADABLE", "DIFFERS", "CAPABLE", True) == (
        runprov.chain.BROKEN
    ), "rule 0 again: tearing a line must not downgrade an impossible claim"
    assert runprov.chain.classify("NONE", "NONE_FIRST", "NA", "UNREADABLE", False) == (
        runprov.chain.UNCHECKABLE
    ), "a torn first line did not 'predate the chain'"
    assert runprov.chain.classify("DIGEST", "UNREADABLE", "MATCHES", "CAPABLE", True) == (
        runprov.chain.HOLDS
    ), "the honest crash: the claim is over the fragment as it sits, and it matches"
    assert runprov.chain.classify("DIGEST", "UNREADABLE", "DIFFERS", "CAPABLE", True) == (
        runprov.chain.UNCHECKABLE
    ), "a later tear and an edit are indistinguishable — never BROKEN, never silent"
    assert runprov.chain.classify("NONE", "READABLE", "NA", "PRE_CHAIN", True) == (
        runprov.chain.GAP
    ), "unverifiable AND fixable"
    assert runprov.chain.classify("NONE", "READABLE", "NA", "CAPABLE", True) == (
        runprov.chain.UNCLAIMED
    ), "[ADR-0016 R-32] a release that can chain wrote no claim: disclosed, never accused"
    assert runprov.chain.classify("NONE", "READABLE", "NA", "UNSTATED", True) == (
        runprov.chain.UNCLAIMED
    ), "[ADR-0016 R-32] and a writer we cannot place is not a forger either"
    assert runprov.chain.classify("NONE", "READABLE", "NA", "CAPABLE", False) == (
        runprov.chain.UNCHAINED
    ), "before the chain started, the same shape is history rather than a finding"


def _reachable_by_construction(cell):
    """Can `verify`'s walk hand `classify` this cell? Read off the walk, not off a list.

    Every clause below is one line of `verify`, and the count of cells that satisfy them is a
    property of the WALK and not of the table — it moves whenever `chained_from` moves. That is
    why nothing here is a number.
    """
    claim, predecessor, agreement, _writer, started = cell
    if predecessor == "NONE_FIRST":
        # `index == 1` is the only source of NONE_FIRST, and it sets `agreement` to NA with it.
        # `chained_from` is still None on the way in, so `started` is whether THIS line claims.
        return agreement == "NA" and started == (claim != "NONE")
    if claim == "NONE":
        return agreement == "NA"  # the walk compares nothing when there is nothing to compare
    # And it always compares when there IS: `agreement` is NA for a claim only at index 1.
    if agreement == "NA":
        return False
    # `chained_from` is assigned BEFORE `classify` is called, so a line that claims has started.
    if not started:
        return False
    # `GENESIS` is a sentinel; `digest_of` returns 64 hex, so the two can never be equal.
    return not (claim == "GENESIS" and agreement == "MATCHES")


def _corpus_line(claim, writer, run, prev=None):
    """One history line of a named shape, for the corpus below.

    `UNREADABLE` is not a separate dimension: a line the parser refuses is both
    `writer = UNREADABLE` and, for its successor, `predecessor = UNREADABLE`, and R-20 still
    recovers its claim from the raw bytes.
    """
    record = {}
    if claim == "GENESIS":
        record["prev"] = runprov.chain.GENESIS
    elif claim == "DIGEST":
        record["prev"] = prev or "b" * 64
    record["schema"] = "runprov.history.v2"
    record["run_id"] = run
    if writer in ("PRE_CHAIN", "CAPABLE"):
        record["tool"] = {"version": "0.5.0" if writer == "PRE_CHAIN" else "0.6.0"}
    if writer != "UNREADABLE":
        return json.dumps(record).encode()
    # A crash truncates the tail of a line, and `prev` is written first (R-19), so the claim
    # survives in the fragment — which is the state R-20 exists for.
    head = b'{"prev": "%s", ' % record["prev"].encode() if "prev" in record else b"{"
    return head + b'"schema": "runprov.histo'


def test_the_reachable_cells_are_computed_and_the_rest_are_refused(tmp_path, monkeypatch):
    """ADR-0016 [ADR-0016 R-25] [ADR-0016 R-30]. Which of the 216 cells the walk can build.

    R-30 says an impossible cell must be DEMONSTRATED impossible and never assumed, because
    assuming is what produced F-07 — R-5's no-`tool` arm had no fixture because every fixture
    happened to carry one. The ADR then asserted the demonstration existed. Audit G, G-14:
    nothing computed it, AND THE NUMBER WAS WRONG BY 31. The paragraph claimed 133 cells were
    structurally impossible and 83 required a verdict; the split is 52 reachable and 164
    impossible, so a repairer implementing R-30 against the document would have edited the
    code until 83 cells were reachable.

    THE LESSON IS NOT A BETTER NUMBER. 52 is a property of the WALK and not of the table: it
    moves whenever `chained_from` moves, so writing it down anywhere — here or in the ADR —
    reproduces the defect one layer along. So neither half of this test contains it. The
    reachable set is derived twice, independently, and the two are compared:

    * ANALYTICALLY, from `verify`'s own construction — `_reachable_by_construction`, whose
      every clause is one line of the walk;
    * BY MEASUREMENT, from an instrumented `classify` driven by `verify` over a corpus of
      every one- and two-line history the shapes below can spell. Two lines saturate it: every
      dimension a third line could vary is already varied by the second.

    Measurement alone would not be enough — an unreached cell and an unreachable one look the
    same — and the derivation alone is a list somebody wrote. Together, each is the other's
    fixture: every cell the derivation calls reachable has a FILE that produces it, and every
    cell it calls impossible is one the corpus never reached.
    """
    reachable = {cell for cell in CHAIN_CELLS if _reachable_by_construction(cell)}
    impossible = [cell for cell in CHAIN_CELLS if cell not in reachable]
    assert reachable and impossible, "a partition with an empty half proves nothing"

    reached = set()
    shipped = runprov.chain.classify

    def watched(*cell):
        reached.add(cell)
        return shipped(*cell)

    monkeypatch.setattr(runprov.chain, "classify", watched)

    firsts = [(c, w) for c in runprov.chain.CLAIMS for w in runprov.chain.WRITERS]
    seconds = [(c, w) for c in (*runprov.chain.CLAIMS, "MATCH") for w in runprov.chain.WRITERS]
    for number, (claim, writer) in enumerate(firsts):
        first = _corpus_line(claim, writer, "one")
        alone = tmp_path / f"one-{number}.jsonl"
        alone.write_bytes(first + b"\n")
        runprov.chain.verify(alone)
        for index, (next_claim, next_writer) in enumerate(seconds):
            follower = _corpus_line(
                "DIGEST" if next_claim == "MATCH" else next_claim,
                next_writer,
                "two",
                prev=runprov.chain.digest_of(first) if next_claim == "MATCH" else None,
            )
            pair = tmp_path / f"two-{number}-{index}.jsonl"
            pair.write_bytes(first + b"\n" + follower + b"\n")
            runprov.chain.verify(pair)

    assert not reached - reachable, (
        "the walk built a cell the derivation calls structurally impossible, so the derivation "
        f"is wrong about `verify`: {sorted(reached - reachable)}"
    )
    assert not reachable - reached, (
        "the derivation calls these cells reachable and no file produces one, so either the "
        f"derivation is wrong or the corpus stopped spelling a shape: {sorted(reachable - reached)}"
    )

    # WHY G-04'S TRANSCRIPTION MAY WIDEN R-25's RULES 9 AND 11 to the `else` of their scope.
    # The cells that widening decides are cells where a line carries a claim and the walk
    # reported no comparison, and every one of them is on the impossible side of this
    # partition — so the widening answers nothing `verify` can ask.
    uncompared_claims = {
        cell
        for cell in CHAIN_CELLS
        if cell[0] != "NONE" and cell[1] != "NONE_FIRST" and cell[2] == "NA"
    }
    assert uncompared_claims and not uncompared_claims & reachable, (
        "a line that claims a predecessor is always compared against it; if that has stopped "
        "being true, R25_TABLE's two widened rows now decide cells the walk really reaches"
    )


def test_the_verdict_is_the_worst_edge_and_nothing_else(tmp_path):
    """ADR-0016 [ADR-0016 R-26] [ADR-0016 R-27]. The fold, and the count.

    Every earlier version assembled the verdict from a hand-picked set of conditions — broken,
    translated, nothing-chained, unattested, stale-writer — and every one of them missed a
    state. A fold over a closed status type cannot. And `attested` counts a status rather than
    subtracting from a total, which is how it came to overcount lines that made no claim and to
    go negative.
    """
    p = tmp_path / "h.jsonl"
    _chain_history(p, 5)
    report = runprov.chain.verify(p)
    assert report.status == runprov.chain.INTACT
    assert report.attested == 4, "five lines, four edges that hold; the first attests nothing"
    assert report.attested == len(report.of(runprov.chain.HOLDS))
    assert report.attested >= 0 and report.attested < report.lines

    # BROKEN dominates everything, including a gap and an uncheckable edge in the same file.
    # THE TWO MUST LAND IN DIFFERENT PLACES, and the first version of this fixture did not:
    # editing line 3 and tearing line 4 produces no BROKEN at all, because the torn line 4 is
    # the only thing that could have accused line 3, and a torn line never accuses. That is the
    # model working — and it is why the edit goes at line 2, whose accuser (line 3) is intact.
    mixed = tmp_path / "mixed.jsonl"
    lines = _chain_history(mixed, 6)
    edited = lines[1].replace(b'"status": "ok"', b'"status": "NO"')
    mixed.write_bytes(b"\n".join([lines[0], edited, *lines[2:4], lines[4][:20], lines[5]]) + b"\n")
    worst = runprov.chain.verify(mixed)
    assert worst.of(runprov.chain.BROKEN) and worst.of(runprov.chain.UNCHECKABLE)
    assert worst.status == runprov.chain.BROKEN, "the worst edge decides, not the most common"


def test_crlf_is_a_per_line_fact_and_cannot_suppress_a_finding(tmp_path):
    """ADR-0016 [ADR-0016 R-28] [ADR-0016 R-21]. Audit F, F-03 — and Audit G, G-02, which
    walked back in through the carve-out F-03's own repair left open.

    The version F-03 replaced tested for `\r\n` ANYWHERE in the file and returned before walking
    a single line, then printed "not tampering" as a statement of fact. Two bytes — one line
    re-terminated — discarded every break in the file and replaced it with an affirmative denial.

    THE PER-LINE REPAIR LEFT THE SAME HOLE ONE SIZE SMALLER. `verify` still pre-empted the
    table for any edge whose PREDECESSOR was translated, and that edge is the only thing that
    ever accuses a line. So one `\r` appended to the line you had just forged turned BROKEN /
    exit 1 into CANNOT_CHECK / exit 2, printed "not tampering", and recommended a
    `.gitattributes` entry that suppresses the finding permanently — and inside a genuine
    `core.autocrlf=true` checkout, where every edge was pre-empted, nothing was detectable at
    all, ever. The cost of the evasion was one byte.

    What closes it: a translated terminator earns the edge ONE extra question — does the claim
    match the predecessor's bytes with the `\r` stripped? A match PROVES the terminator was the
    only change, and the edge is named UNCHECKABLE rather than accused. Anything else is a
    change to the CONTENT, and the table judges it exactly as it judges any other disagreement.
    """
    p = tmp_path / "h.jsonl"
    lines = _chain_history(p, 5)
    forged = lines[2].replace(b'"status": "ok"', b'"status": "FORGED"')
    body = b"\n".join([*lines[:2], forged, *lines[3:]])
    cut = body.index(b"\n")
    p.write_bytes(body[:cut] + b"\r\n" + body[cut + 1 :] + b"\n")

    report = runprov.chain.verify(p)
    assert report.translated == 1, "one line, not the file"
    assert report.of(runprov.chain.BROKEN), "the forgery survives the CRLF byte"
    assert report.status == runprov.chain.BROKEN

    # G-02, with the `\r` where it actually buys the forger something: on the forged line
    # ITSELF, so that the edge which would accuse it is the one sitting behind a translated
    # predecessor. Measured before the fix — BROKEN/exit 1 became CANNOT_CHECK/exit 2.
    evaded = tmp_path / "evaded.jsonl"
    clean_lines = _chain_history(evaded, 5)
    forgery = clean_lines[2].replace(b'"status": "ok"', b'"status": "FORGED"')
    evaded.write_bytes(b"\n".join([*clean_lines[:2], forgery + b"\r", *clean_lines[3:]]) + b"\n")
    got = runprov.chain.verify(evaded)
    assert got.status == runprov.chain.BROKEN, "one `\\r` must not buy a forgery an exit code"
    assert [e.line for e in got.of(runprov.chain.BROKEN)] == [4], (
        "and it is the edge ABOVE the forged line that breaks, as it does without the `\\r`"
    )

    # The same forgery inside a REAL whole-file autocrlf checkout, where EVERY edge is behind a
    # translated predecessor. This is the case the pre-emption made permanently undetectable.
    checkout = tmp_path / "checkout.jsonl"
    co_lines = _chain_history(checkout, 5)
    forgery = co_lines[2].replace(b'"status": "ok"', b'"status": "FORGED"')
    checkout.write_bytes(
        (b"\n".join([*co_lines[:2], forgery, *co_lines[3:]]) + b"\n").replace(b"\n", b"\r\n")
    )
    mixed = runprov.chain.verify(checkout)
    assert mixed.status == runprov.chain.BROKEN, "a checkout is not a place forgeries are safe"
    assert [e.line for e in mixed.of(runprov.chain.BROKEN)] == [4]
    assert [e.line for e in mixed.of(runprov.chain.UNCHECKABLE)] == [2, 3, 5], (
        "the CRLF finding is scoped to the edges that earned it, and the break is not one"
    )

    # And a wholly translated checkout with nothing edited is named, not accused — [ADR-0016
    # R-21] and E-01 must not come back as the price of closing G-02.
    clean = tmp_path / "clean.jsonl"
    _chain_history(clean, 4)
    clean.write_bytes(clean.read_bytes().replace(b"\n", b"\r\n"))
    whole = runprov.chain.verify(clean)
    assert whole.translated == 4 and not whole.of(runprov.chain.BROKEN)
    assert whole.status == runprov.chain.CANNOT_CHECK, "the bytes did change; INTACT would lie"
    page = "\n".join(runprov.chain.render(whole, clean))
    assert "core.autocrlf=true" in page and "-text" in page, page
    assert "not tampering" not in page, (
        "the sentence is a fact about those lines, not a verdict for the file — it has to be "
        "able to stand on the same page as a BROKEN row, which it could not while it denied "
        "tampering outright: that is what it printed, unchanged, over the forged file above"
    )

    # Audit G, G-19. THE SUMMARY REPLACES THE PER-LINE ROWS; IT DOES NOT ACCOMPANY THEM. The
    # `continue` in `render` that does the replacing, and the `wrote="translated"` marker it
    # keys on, were executed by this test and constrained by nothing: removing the `continue`,
    # and separately renaming the marker, both survived the ENTIRE suite. Measured by return
    # code, baseline 0 / g19a 0 / g19b 0.
    #
    # Either mutation puts a row under the summary above for every translated edge, and what
    # that row says after wave 4's rewording is that the line "carries no readable runprov
    # record" — false of a line the parser reads perfectly. The page would then name a git
    # checkout as the cause and contradict it line by line: F-03's self-contradicting
    # diagnostic, one `continue` away, on an ordinary `core.autocrlf=true` clone.
    #
    # THE WITNESS COMES FIRST, because a negative assertion over an empty set proves nothing —
    # and it is what kills the marker mutation, which leaves the rows to be suppressed by a
    # branch that no longer matches.
    marked = [e for e in whole.of(runprov.chain.UNCHECKABLE) if e.wrote == "translated"]
    assert len(marked) == 3, (
        f"three edges sit behind a translated predecessor and are marked as such at "
        f"construction; without the marker there is nothing for the renderer to suppress: "
        f"{[(e.line, e.status, e.wrote) for e in whole.edges]}"
    )
    rendered = runprov.chain.render(whole, clean)
    assert not [line for line in rendered if "COULD NOT CHECK" in line], (
        f"the CRLF summary is the whole finding for these edges. With the per-line rows back, "
        f"this page tells a reader that their checkout translated the endings AND that each of "
        f"those same lines carries no readable runprov record: {rendered}"
    )


def test_the_writer_of_a_line_is_resolved_from_the_run(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-29] [ADR-0016 R-32]. Audit F, F-02 — the miss that cost the most.

    NO RELEASED VERSION writes a `tool` block into a `runprov.start.v1` line, and those are half
    of every history. Reading the line alone makes every one of them `UNSTATED`, which sends it
    to rule 7 — so one ordinary run by a colleague on a released wheel reported BROKEN over a
    file nobody touched. Verified against the real bytes in `tests/corpus/0.5.0`.

    THE UNPARSEABLE-VERSION CASE BELOW ASSERTED BROKEN, AND ITS OWN COMMENT ARGUED AGAINST IT:
    "a distribution that stamps 'nightly' … is not a forger — it is a writer we cannot place".
    The test wrote down the objection and then pinned the behaviour it objects to. Under
    [ADR-0016 R-32] the objection wins, and it is a spec change rather than a bugfix: rule 7's
    row in R-25 now answers `UNCLAIMED` for both `CAPABLE` and `UNSTATED`. Audit G's G-05 is
    the same cell reached without any exotic version string — the BYTE-IDENTICAL 0.5.0 start
    line read `GAP` once its run's completion record arrived and `BROKEN` while the run was
    still going, so the verdict over unchanged bytes depended on whether a process had
    finished, and for a killed run it never does. Resolution from the run still matters and is
    still asserted above: it is the difference between a GAP that names the machine to fix and
    an UNCLAIMED that can only say what it cannot tell you.
    """
    p = tmp_path / "h.jsonl"
    _chain_history(p, 2)
    real = [
        line
        for line in (_repo_root() / "tests/corpus/0.5.0/tree/prov/history.jsonl")
        .read_bytes()
        .split(b"\n")
        if line.strip()
    ][:2]
    assert b'"schema": "runprov.start.v1"' in real[0], "the fixture must be a real start line"
    assert b'"tool"' not in real[0], "and real start lines carry no tool block — the whole point"
    with p.open("ab") as fh:
        fh.write(b"\n".join(real) + b"\n")

    report = runprov.chain.verify(p)
    assert not report.of(runprov.chain.BROKEN), "a real released run is not a forgery"
    assert len(report.of(runprov.chain.GAP)) == 2, "both of its lines are gaps, named by version"
    assert {e.wrote for e in report.of(runprov.chain.GAP)} == {"0.5.0"}
    assert runprov.__main__.main(["chain", str(p)]) == 2
    assert "written by runprov 0.5.0" in capsys.readouterr().out

    # Audit G, G-20. THE KEY IS `run_uid` — this requirement's own word — and it was
    # `run_uid or run_id`. `run_id` is a LABEL the caller chooses, and real histories reuse it:
    # the premise below is read off this repository's own released-wheel corpus rather than
    # argued, and it was confirmed on a live run while this row was applied, where two runs a
    # minute apart both recorded `run_id="adhoc_20260923T141046Z"` under two `run_uid`s. A map
    # keyed on something that does not identify a run lets one run's version answer for another
    # run's lines, and which one answers is whichever record happened to come first.
    rows = [
        json.loads(line)
        for line in (_repo_root() / "tests/corpus/0.5.0/tree/prov/history.jsonl")
        .read_bytes()
        .split(b"\n")
        if line.strip()
    ]
    assert len({r["run_id"] for r in rows}) == 1 and len({r["run_uid"] for r in rows}) == 3, (
        f"the premise: three runs and ONE `run_id` between them — "
        f"{sorted({r['run_id'] for r in rows})}"
    )
    assert runprov.chain._writers(dict(enumerate(rows, start=1))) == {
        r["run_uid"]: "0.5.0" for r in rows if isinstance(r.get("tool"), dict)
    }, "one entry per RUN, each carrying its own version — not one entry for all three"
    assert runprov.chain._writers({1: {"run_id": "job", "tool": {"version": "0.5.0"}}}) == {}, (
        "and a record identified only by that label resolves nothing: the writer is a property "
        "of the RUN. This is the old fallback's only reachable input, and it is not one any "
        "release writes — the `runprov.run.v1` records that predate `run_uid` carry no `tool` "
        "block at all, so no history on disk is resolved differently by this"
    )

    # WHAT IT COSTS, asserted so the loss is on the page and not only in the ADR. A line whose
    # run is named only by a reused label no longer borrows a sibling's version, so it resolves
    # UNSTATED and takes rule 7 — which under [ADR-0016 R-32] is `UNCLAIMED`, exit 2 and a
    # disclosure, where it used to be `GAP`, exit 2 and a machine to upgrade. The exit code is
    # the same; what is given up is an actionable sentence that was only ever as good as the
    # label it was read from.
    labelled = tmp_path / "labelled.jsonl"
    borrowed_sink = runprov.JsonlSink(labelled)
    borrowed_sink.append(
        {"schema": "runprov.history.v2", "run_id": "job", "tool": {"version": "0.6.0"}}
    )
    with labelled.open("ab") as fh:
        fh.write(json.dumps({"schema": "runprov.start.v1", "run_id": "shared"}).encode() + b"\n")
    borrowed_sink.append(
        {"schema": "runprov.history.v2", "run_id": "shared", "tool": {"version": "0.5.0"}}
    )
    borrowed = runprov.chain.verify(labelled)
    assert [e.status for e in borrowed.edges] == [
        runprov.chain.HOLDS_TRIVIAL,
        runprov.chain.UNCLAIMED,
        runprov.chain.HOLDS,
    ], [(e.line, e.status, e.wrote) for e in borrowed.edges]
    assert _chain_exit(labelled) == 2, "the exit code is unchanged; only the sentence is"

    # A VERSION STRING THIS PACKAGE CANNOT PARSE. `tool.version` is written by whoever built
    # the wheel, and a distribution that stamps "nightly" or a git describe is not a forger —
    # it is a writer we cannot place. [ADR-0016 R-32]: unplaceable is not guilty, so the
    # verdict is CANNOT_CHECK. Asserted so the decision is on the page rather than an accident
    # of parsing, exactly as the BROKEN it replaces was.
    unparseable = tmp_path / "nightly.jsonl"
    _chain_history(unparseable, 2)
    with unparseable.open("ab") as fh:
        fh.write(
            json.dumps(
                {"schema": "runprov.history.v2", "run_id": "n", "tool": {"version": "nightly"}}
            ).encode()
            + b"\n"
        )
    assert runprov.chain._writer_of({"tool": {"version": "nightly"}}, {}) == "UNSTATED"
    nightly = runprov.chain.verify(unparseable)
    assert nightly.status == runprov.chain.CANNOT_CHECK
    assert [e.line for e in nightly.of(runprov.chain.UNCLAIMED)] == [3]

    # An unreadable file, a missing one, and an EMPTY one: CANNOT_CHECK, never an exception
    # (R-24's rule one level up — `verify`'s docstring promises it never raises). The empty file
    # is its own branch: `b"".split(b"\n")` is `[b""]`, one empty line that the terminator rule
    # then pops, leaving nothing to walk.
    assert runprov.chain.verify(tmp_path / "absent.jsonl").status == runprov.chain.CANNOT_CHECK
    empty = tmp_path / "empty.jsonl"
    empty.write_bytes(b"")
    assert runprov.chain.verify(empty).lines == 0
    assert runprov.chain.verify(empty).status == runprov.chain.CANNOT_CHECK

    # Audit H, H1-8. WHAT STOOD HERE WAS A HAND-BUILT `Link` WITH A NON-BROKEN STATUS, kept
    # alive by a comment that stated a false reason for it — "the renderer asks every edge".
    # It does not: `_findings`'s only call is `for link in report.of(BROKEN)`, so the arm that
    # answered for any other status was unreachable and the assertion was pinning a contract
    # nothing uses. Both the arm and the assertion are gone, by the rule the module applied to
    # the claimless arm before it: a sentence nothing can print is a sentence nobody maintains.
    # What replaces it is the contract itself, read off the module rather than assumed.
    module = inspect.getsource(runprov.chain)
    assert module.count("link.detail") == 1, "one caller, and the assertion below is about it"
    assert re.findall(
        r"for link in report\.of\((\w+)\):\n\s*out\.append\([^)]*link\.detail", module
    ) == ["BROKEN"], "`detail` is asked only of BROKEN edges, which is why it answers only them"

    # Any JSON shape resolves, and nothing raises (F-05).
    for shape in ("0.5.0", ["0.5.0"], None, 12345):
        odd = tmp_path / f"odd{abs(hash(str(shape)))}.jsonl"
        _chain_history(odd, 2)
        with odd.open("ab") as fh:
            fh.write(json.dumps({"schema": "runprov.history.v2", "tool": shape}).encode() + b"\n")
        # ONE VERDICT, NOT A DISJUNCTION. This asserted `in (BROKEN, CANNOT_CHECK)` while both
        # were reachable here; under [ADR-0016 R-32] every one of these shapes resolves to
        # `UNSTATED` and takes rule 7, so the disjunction went slack and would have survived
        # rule 7 answering either one. Audit G, carried forward from the R-32 repair to G-04.
        report = runprov.chain.verify(odd)
        assert report.status == runprov.chain.CANNOT_CHECK, shape
        assert [e.status for e in report.edges] == [
            runprov.chain.HOLDS_TRIVIAL,
            runprov.chain.HOLDS,
            runprov.chain.UNCLAIMED,
        ], f"a `tool` this package cannot read is a writer it cannot place, never a forger: {shape}"


def test_a_line_that_made_no_claim_is_not_an_accusation(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-32]. Audit G, G-01 and G-05 — one status closes both.

    Rule 7 answered BROKEN for any line carrying no `prev` once the chain had started. Measured
    during adjudication, that caught exactly one thing: a forger who appended a line at the very
    END of a history and did not compute the digest — while the nine-line `sha256sum` recipe for
    computing it is printed in `chain.py`'s own module docstring, so a forger who reads the
    documentation was never caught by it at all. A mid-file splice is caught by rule 11 at the
    NEXT edge, with rule 7 or without it, and both are asserted below.

    What that narrow detection charged was two classes of PERMANENT false accusation over files
    in which every record is present and every byte is as written:

    * **G-01** — an append that could not take the lock (NFS, CIFS, a container without
      `flock`), which [ADR-0016 R-22] REQUIRES to write no claim. Measured: two ordinary locked
      appends followed by four unlocked ones gave BROKEN, four untouched lines accused. That
      scenario is asserted end to end by R-22's own test,
      `test_no_lock_means_no_chain_claim_rather_than_a_false_accusation`.
    * **G-05** — a `runprov.start.v1` line whose run is still going or was killed. The same
      bytes reported GAP once the run's completion record arrived, so the verdict over
      unchanged bytes depended on whether a process had finished, and for a killed run it never
      does. Asserted here, because it has no other home.

    And [ADR-0016 R-13] gives nothing the power to clear a finding, so the only way to remove
    either accusation was to edit the history — the act this feature exists to detect. A
    tamper-detector that cries wolf over correct files is worse than none, because the next
    real break is discounted. Exit 2 still means LOOK AT THIS: nothing becomes silently green,
    and [ADR-0016 R-31]'s acceptance gate is untouched because no new INTACT is produced.
    """
    p = tmp_path / "base.jsonl"
    lines = _chain_history(p, 5)
    unchained = json.dumps(
        {"schema": "runprov.history.v2", "run_id": "x", "tool": {"version": "0.6.0"}}
    ).encode()

    # THE TRADE, measured on these files rather than asserted in prose. What is kept:
    mid = tmp_path / "mid.jsonl"
    mid.write_bytes(b"\n".join([*lines[:2], unchained, *lines[2:]]) + b"\n")
    caught = runprov.chain.verify(mid)
    assert [e.line for e in caught.of(runprov.chain.BROKEN)] == [4], (
        "a mid-file splice is still an accusation, and it always was rule 11's: the line AFTER "
        "the spliced one claims a predecessor that is no longer there"
    )
    assert _chain_exit(mid) == 1
    assert runprov.__main__.main(["chain", str(mid)]) == 1
    accused = capsys.readouterr().out
    assert "BROKEN  line 4 claims its predecessor hashed to" in accused, accused
    # Audit H, H1-4: the break still points at the boundary below line 4, which is what R-10
    # buys. What it no longer does is name a cause — and this file is why the old wording was
    # wrong in a third way the row did not need: the line at 3 here was INSERTED, so "LINE 3 IS
    # WHAT CHANGED" named a line that had not changed because it had never been there.
    assert "LOOK BETWEEN LINES 3 AND 4, NOT AT LINE 4" in accused, accused
    assert "pushed aside by an insertion" in accused, accused
    assert "edited after it was written" in accused, (
        "and the break paragraph still prints. What R-32 gives up is the accusation against a "
        "line that made NO claim; the accusation for a link that disagrees is untouched, and "
        "after this change nothing else in the suite renders one — it reached the page only "
        "through the verdict that is now UNCLAIMED"
    )

    # What is given up, stated as an assertion so the loss is on the page and not only in the
    # ADR: a lazy tail-splice is exit 2 rather than exit 1.
    tail = tmp_path / "tail.jsonl"
    tail.write_bytes(b"\n".join([*lines, unchained]) + b"\n")
    lost = runprov.chain.verify(tail)
    assert [e.line for e in lost.of(runprov.chain.UNCLAIMED)] == [6]
    assert _chain_exit(tail) == 2, "still detected and still on the page; no longer accused"
    assert lost.status != runprov.chain.INTACT, "and no new INTACT is created anywhere"

    # G-05: the BYTE-IDENTICAL real 0.5.0 start line, with and without the completion record
    # that resolves its writer. One verdict, not two.
    real = [
        line
        for line in (_repo_root() / "tests/corpus/0.5.0/tree/prov/history.jsonl")
        .read_bytes()
        .split(b"\n")
        if line.strip()
    ][:2]
    verdicts = {}
    for taken in (1, 2):
        q = tmp_path / f"flight{taken}.jsonl"
        _chain_history(q, 2)
        with q.open("ab") as fh:
            fh.write(b"\n".join(real[:taken]) + b"\n")
        verdicts[taken] = _chain_exit(q)
    assert (tmp_path / "flight1.jsonl").read_bytes().split(b"\n")[2] == (
        tmp_path / "flight2.jsonl"
    ).read_bytes().split(b"\n")[2], "the start line is byte-identical in both files"
    assert verdicts == {1: 2, 2: 2}, (
        f"the same bytes must not get one verdict while a process runs and another after it "
        f"exits — and for a killed run the second never arrives: {verdicts}"
    )

    # THE SENTENCE. It names the innocent causes AND the guilty one without picking between
    # them, because the file cannot tell them apart and saying otherwise would be a guess —
    # AND ONLY THE CAUSES IT CANNOT EXCLUDE ([ADR-0016 R-32], amended after Audit H, H1-10).
    # This line states `0.6.0`, and a 0.6.0 run killed mid-flight writes a CHAINED start line,
    # so a missing completion record cannot be why there is no claim here. Measured through
    # `runprov.Run` and SIGKILL: the start line left behind carries `prev`.
    assert runprov.__main__.main(["chain", str(tail)]) == 2
    page = capsys.readouterr().out
    assert "UNCLAIMED  line 6 carries no chain claim" in page, page
    assert "could not take the file lock" in page, "the first innocent cause, and R-22's own"
    assert "still in flight" not in page, (
        "the line names a chain-capable release, and its own bytes exclude this cause. Naming "
        "a cause the record rules out is the same defect as an accusation, one register quieter"
    )
    assert "inserted by hand" in page, "and the guilty one, which is not hidden either"
    assert "This is not evidence of an edit." in page, page
    assert "upgrade that machine" not in page, (
        "[ADR-0016 R-5]'s sentence, and it is false here twice over: this line names no "
        "machine, and a run still in flight has nothing to upgrade"
    )
    assert "edited after it was written" not in page, "no accusation anywhere on the page"

    # AND THE CLAUSE IS KEPT WHERE IT IS TRUE — an UNSTATED writer, which is G-05's case: a
    # line that names no version and whose run has written no completion record to resolve one.
    # It is scoped, not deleted, and asserting only its absence above would have let a repair
    # that deleted it outright pass.
    unstated = tmp_path / "unstated.jsonl"
    unstated.write_bytes(b"\n".join(lines) + b"\n")
    with unstated.open("ab") as fh:
        fh.write(json.dumps({"schema": "runprov.start.v1", "run_id": "s"}).encode() + b"\n")
    assert runprov.chain._writer_of({"schema": "runprov.start.v1", "run_id": "s"}, {}) == (
        "UNSTATED"
    ), "the cell this half is about, and rule 7 is reached from it as well as from CAPABLE"
    assert [e.line for e in runprov.chain.verify(unstated).of(runprov.chain.UNCLAIMED)] == [6]
    assert runprov.__main__.main(["chain", str(unstated)]) == 2
    quiet = capsys.readouterr().out
    assert "UNCLAIMED  line 6 carries no chain claim" in quiet, quiet
    assert "still in flight has not written its completion record yet" in quiet, quiet
    assert "upgrade that machine" not in quiet, "still rule 5's advice, and still false here"

    # The machine-readable rendering carries the same verdict and the same status, so a reader
    # of one can never see a finding the other does not. E-10's lesson, applied to a new status.
    assert runprov.__main__.main(["chain", str(tail), "--format", "json"]) == 2
    payload = json.loads(capsys.readouterr().out)
    assert payload["status"] == "CANNOT_CHECK"
    assert [e["line"] for e in payload["edges"] if e["status"] == "UNCLAIMED"] == [6]


def test_a_destroyed_record_terminator_is_two_records_and_not_a_tear(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-11] [ADR-0016 R-20] [ADR-0016 R-32]. Audit G, G-03 — the one
    single-byte edit that ever escaped the acceptance gate, and the code half of its repair.

    Overwrite the `\\n` that separates the last two attested lines and NOTHING about the chain
    is disturbed: both records survive byte for byte, the edges on either side still HOLD, and
    the verdict was INTACT with exit 0 — while `log`, `show` and `report` see one unparseable
    line where two runs used to be. The gate could not see it because its loop skipped every
    `\\n`, and the table could not see it because an edge judges the LINK between two lines and
    this is a fact about the bytes of one.

    WHAT DISTINGUISHES IT FROM AN HONEST CRASH IS NOT POSITION AND NOT LENGTH — it is that a
    crash TRUNCATES a line and never CONCATENATES two. A fragment is a PREFIX of one record, so
    it contains no record boundary; a merged line contains one. That is the whole discriminator,
    and it is what lets this be closed without charging a crashed run its exit code, which the
    two remedies proposed for G-03 could not do: both moved the ordinary crash off exit 0 and
    contradicted the fixture above that requires a crash to cost nothing, for ever.

    IT IS CANNOT_CHECK AND NOT BROKEN, deliberately, and not merely out of caution. What the
    two joined records used to say cannot be read back from them, so there is no clause
    [ADR-0016 R-10] could print that would be true of the break. And the state has an innocent
    producer: an `fsck` zero-filling a block it cannot recover turns the `\n` inside that block
    into a NUL, which joins two lines exactly as a hand edit would — G-18's finding, on the
    recovery path this repository's own parent directory is named after. So the true statement
    is the narrow one, and it is the one the page prints: a TRUNCATING crash cannot produce
    this. Exit 2 already means LOOK AT THIS, and [ADR-0016 R-32] is why it stops there.
    """
    p = tmp_path / "h.jsonl"
    _chain_history(p, 4)
    original = p.read_bytes()
    terminators = [i for i, byte in enumerate(original[:-1]) if byte == ord("\n")]
    assert terminators, "the fixture must have an interior terminator to destroy"

    for position in terminators:
        mutated = bytearray(original)
        mutated[position] = ord("X")
        p.write_bytes(bytes(mutated))
        report = runprov.chain.verify(p)
        assert report.merged, (
            f"byte {position} was a record boundary and it is gone; two records are now one "
            f"unreadable line, and this is the edit that exited 0"
        )
        assert not report.of(runprov.chain.BROKEN), (
            "[ADR-0016 R-32] the bytes of the two records cannot be read back, so nothing here "
            "is certain enough to accuse anyone of"
        )
        assert report.status == runprov.chain.CANNOT_CHECK
        assert _chain_exit(p) == 2

    # The page names the cause. A verdict with no reason on it is what [ADR-0016 R-9] forbids.
    assert runprov.__main__.main(["chain", str(p)]) == 2
    page = capsys.readouterr().out
    assert "a record boundary sits inside it" in page, page
    assert "A truncating crash cannot produce this" in page, page
    assert "This is not evidence of an edit." in page, (
        "a zero-filled block joins two lines exactly as a hand edit does (G-18), so the page "
        "must not let a reader infer the edit from the detection"
    )
    assert "edited after it was written" not in page, "detected and disclosed, never accused"

    # And the machine rendering carries the same fact, so neither reader sees less (E-10).
    assert runprov.__main__.main(["chain", str(p), "--format", "json"]) == 2
    payload = json.loads(capsys.readouterr().out)
    assert payload["status"] == "CANNOT_CHECK" and payload["merged"] == list(
        runprov.chain.verify(p).merged
    )

    # THE OTHER HALF, and the reason the narrower discriminators were refused: an honest crash
    # still costs nothing. Every truncation of the newest line — the whole space a tear can
    # leave behind — contains no boundary, so none of them is called a merge.
    crash = tmp_path / "crash.jsonl"
    _chain_history(crash, 4)
    raw = crash.read_bytes()
    cut = raw.rfind(b"\n", 0, len(raw) - 1)
    head, last = raw[: cut + 1], raw[cut + 1 :].rstrip(b"\n")
    for keep in range(len(last)):
        crash.write_bytes(head + last[:keep])
        assert not runprov.chain.verify(crash).merged, (
            f"a {keep}-byte fragment is a PREFIX of one record and carries no boundary; "
            f"calling it a merge is the false CANNOT_CHECK this discriminator exists to avoid"
        )
    crash.write_bytes(head + last[: len(last) // 2])
    assert _chain_exit(crash) == 0, "a crash must not cost a project its gate, for ever"


@pytest.mark.parametrize("shape", ["intact", "torn", "mixed-version", "pre-chain"])
def test_no_single_byte_edit_escapes_the_chain(shape, tmp_path):
    """ADR-0016 [ADR-0016 R-31] [ADR-0016 R-23]. THE ACCEPTANCE GATE, and the only claim here
    that does not depend on my having enumerated the cases correctly.

    Flip every byte the report says is attested, one at a time, and require that the verdict is
    never INTACT. It reasons about nothing. Measured against the code as it stood before the
    decision table: **623 positions in a five-line history, 0.1 seconds, 163 of them left the
    verdict INTACT** — all one defect class, which four reviewers and sixteen mutations had
    taken a day to surface.

    THREE SCOPES WERE HAND-WRITTEN HERE AND TWO WERE WRONG (Audit G, G-03 / G-07 / G-10), which
    is why all three are now DERIVED. They are one repair and not three: fixing any one of them
    exposes the next.

    * WHICH BYTES. The loop used to `continue` on `\\n`. One of the bytes it skipped was the
      only escape that existed: overwrite the terminator of the last attested line and two
      records merge into one unreadable line while the verdict stays INTACT and the exit code
      stays 0. Measured on the shipped fixtures: 453 of 456 positions examined on `intact`,
      zero escapes among them, and an escape at the one position skipped — byte 455, the `\\n`.
      A terminator is a record boundary and is part of what the chain must protect, so nothing
      is skipped now.
    * WHICH SHAPES. Two of the four were already non-INTACT before any flip — `mixed-version`
      was CANNOT_CHECK and `pre-chain` was BROKEN — so `not escaped` was vacuously true and the
      test passed with the mutation replaced by a no-op. A shape whose base verdict is not
      INTACT cannot witness an escape, so the precondition is ASSERTED rather than assumed, and
      the two shapes are built the way an upgrade and a pre-chain history really arrive, oldest
      lines first, rather than by editing a chained file into a shape no writer produces.
    * WHICH REGION. `range(last)` excluded the last line and nothing else, so on the rebuilt
      pre-chain shape it swept the lines that NOTHING attests by design (R-4) and reported 83
      "escapes" that are a disclosed limit rather than defects. The region is now read out of
      the report: a line's bytes are attested if and only if the edge above it HOLDS, which is
      the model's own statement, so the region moves when the model does. The last line is
      still excluded, and not by a subtraction — nothing attests it, which is R-23's limit
      stated on every report rather than hidden here.

    UNCLAIMED cannot silently shrink that region, and the reason is the precondition rather
    than luck: under R-26 an UNCLAIMED edge is decisive, so any shape containing one is
    CANNOT_CHECK and fails the assertion above before a single byte is flipped. The only edge
    statuses a shape reaching the sweep can carry are HOLDS, HOLDS_TRIVIAL and UNCHAINED.

    And the count of what was examined is asserted, because `not escaped` and "nothing was
    examined" print the same word: on a one-line fixture the old loop ran zero times and
    passed, and the gate adds no unique coverage, so the 100 % floor could not notice either.
    """
    p = tmp_path / "h.jsonl"
    if shape == "mixed-version":
        # An in-place upgrade: the release that cannot chain wrote FIRST, and the chain is
        # anchored over it. Appending a 0.5.0 line AFTER the chain is a downgrade, which is a
        # GAP by R-25 rule 5 and can never be INTACT — a shape that cannot witness anything.
        p.write_bytes(
            json.dumps(
                {"schema": "runprov.history.v2", "run_id": "o", "tool": {"version": "0.5.0"}}
            ).encode()
            + b"\n"
        )
    elif shape == "pre-chain":
        # R-4's prefix, written before the feature existed, then chained over by a real run.
        # Prepending to an ALREADY chained file instead makes line 4 claim GENESIS behind a
        # predecessor, which rule 0 calls BROKEN — which is why that fixture was vacuous.
        p.write_bytes(b'{"schema": "runprov.history.v2", "run_id": "old"}\n' * 3)
    _chain_history(p, 4)
    if shape == "torn":
        raw = p.read_bytes()
        cut = raw.rfind(b"\n", 0, len(raw) - 1)
        p.write_bytes(raw[: cut + 1] + raw[cut + 1 :][: len(raw[cut + 1 :]) // 2])
        runprov.JsonlSink(p).append({"schema": "runprov.history.v2", "run_id": "after"})

    original = p.read_bytes()
    before = runprov.chain.verify(p)
    assert before.status == runprov.chain.INTACT, (
        f"{shape}: a shape that is not INTACT to begin with cannot witness an escape, and "
        f"`not escaped` would be vacuously true over it — it is {before.status}"
    )

    # THE REGION, DERIVED: edge n carries line n's claim about line n-1, so line n-1's bytes
    # are attested exactly when that edge HOLDS. The terminator belongs to the line it ends.
    attested = {edge.line - 1 for edge in before.edges if edge.status == runprov.chain.HOLDS}
    positions, at = [], 0
    for number, line in enumerate(original.split(b"\n")[:-1], start=1):
        if number in attested:
            positions.extend(range(at, at + len(line) + 1))
        at += len(line) + 1

    escaped = []
    for position in positions:
        mutated = bytearray(original)
        mutated[position] = ord("X") if mutated[position] != ord("X") else ord("Y")
        p.write_bytes(bytes(mutated))
        if runprov.chain.verify(p).status == runprov.chain.INTACT:
            escaped.append(position)
    p.write_bytes(original)

    assert attested, f"{shape}: the report attests no line at all; there is nothing to protect"
    assert len(positions) == sum(len(original.split(b"\n")[n - 1]) + 1 for n in sorted(attested)), (
        "every byte of every attested line, and its terminator, exactly once"
    )
    assert not escaped, (
        f"{shape}: {len(escaped)} of {len(positions)} attested byte positions can be changed "
        f"with the verdict still INTACT; first at byte {escaped[0] if escaped else None}"
    )


def test_the_chain_reads_the_tail_and_not_the_whole_history(tmp_path):
    """The cost of an append must not grow with the file. Restored after Audit F, F-10.

    THIS TEST HAS BEEN DELETED ONCE, by the hand that wrote it, one day after writing it — in a
    wholesale rewrite of the block it lived in. Its own docstring had said why it exists, and
    the rewrite took it anyway, so the mutation it guards went unguarded until a reviewer
    diffed the old assertions against the new.

    It asserts the COST, not the answer, and that is the point: replacing the chunked backwards
    read with a single whole-file read gives the SAME digest, so no assertion about correctness
    can distinguish them. When a mutation is equivalent, the property worth protecting is not
    the one under test — here it is the read volume, so the read volume is counted.
    """

    class Counting:
        def __init__(self, fh):
            self._fh, self.total = fh, 0

        def seek(self, *a):
            return self._fh.seek(*a)

        def tell(self):
            return self._fh.tell()

        def read(self, n):
            data = self._fh.read(n)
            self.total += len(data)
            return data

    p = tmp_path / "long.jsonl"
    sink = runprov.JsonlSink(p)
    for i in range(400):
        sink.append({"schema": "runprov.history.v2", "run_id": f"r{i}", "pad": "x" * 200})
    size = p.stat().st_size
    assert size > runprov.chain._TAIL_BLOCK * 10, "the fixture must dwarf a single block"

    with p.open("rb") as fh:
        counter = Counting(fh)
        runprov.chain.previous_digest(counter)  # type: ignore[arg-type]
    assert counter.total <= runprov.chain._TAIL_BLOCK * 2, (
        f"read {counter.total} bytes of a {size}-byte history to find its last line; an append "
        f"that reads the whole file is O(n) per run and O(n^2) over a project"
    )


def test_the_chain_does_not_reach_the_record_the_caller_still_holds(tmp_path):
    """ADR-0016 R-17, R-18 at the seam rather than at the outputs. Restored after F-10.

    The sink copies the record before adding `prev`. Mutating the caller's dict instead works
    today — the sidecar happens to be written first — and would start leaking the field into
    sidecars and pins the moment that order changed. R-17/R-18's own test checks the OUTPUTS,
    which is the ordering accident this one exists not to rely on.
    """
    p = tmp_path / "h.jsonl"
    record = {"schema": "runprov.history.v2", "run_id": "r0"}
    before = dict(record)
    runprov.JsonlSink(p).append(record)

    assert record == before, f"append() mutated its caller's record: {record}"
    assert "prev" in json.loads(p.read_text(encoding="utf-8")), "and the file still got it"


def test_chain_uses_the_configured_history_when_none_is_named(tmp_path, monkeypatch, capsys):
    """ADR-0016 [ADR-0016 R-8]. `runprov chain` with no argument. Restored after F-10.

    THE PRIMARY INVOCATION HAD NO TEST. Its test was deleted in the rewrite, and a mutation
    making bare `runprov chain` fail in every configured project survived the whole suite —
    the command's normal use, dead, and green.

    AMENDED FOR G-06, WHICH THIS TEST HELD OPEN. Its closing case configured `run_log=None`
    and asserted exit 2, and its docstring called that "the unusual one". `run_log=None` is
    the DEFAULT — every project that does not name a history explicitly — so the case the
    test called unusual is the documented layout, and it was pinning the defect as correct:
    `log` and `lineage` read `provenance/runs.jsonl` there and `chain` refused to. The
    default layout now asserts exit 0, and a root that genuinely has no history is a separate
    case below, answered where every other missing history is.
    """
    monkeypatch.chdir(tmp_path)
    # G-24(c). A HISTORY WITH A DIRECTORY COMPONENT, because the assertion about how its path
    # is spelled needs a separator to be about anything. The fixture named `h.jsonl`, and a
    # bare filename contains no separator on any platform — so `"\\" not in payload["path"]`
    # was true on Windows for a reason that had nothing to do with the code. Not a hole: the
    # property itself is guarded repo-wide by `test_no_recorded_path_is_spelled_with_a_bare_str`,
    # an AST scan that kills `str(log)` here. This was a FALSE WITNESS, not an uncovered
    # property, and the fix is to make this assertion able to fail rather than to add a guard.
    log = pathlib.Path("prov") / "h.jsonl"  # built with the host's separator, as a caller's is
    (tmp_path / "prov").mkdir()
    _chain_history(tmp_path / log, 3)
    runprov.configure(root=".", run_log=log)

    assert runprov.__main__.main(["chain"]) == 0, "no argument means the project's own history"
    assert "INTACT" in capsys.readouterr().out

    assert runprov.__main__.main(["chain", "--format", "json"]) == 0
    payload = json.loads(capsys.readouterr().out)
    assert payload["schema"] == runprov.chain.SCHEMA == "runprov.chain.v1", (
        "the shape is versioned, per ADR-0017. BOTH, the way every sibling schema is "
        "asserted: the constant, because this line respelled the literal and so pinned one "
        "sentence against its own copy while the payload was free to say anything; and the "
        "value, because a constant compared only against itself pins nothing at all"
    )
    assert payload["attested"] == 2 and payload["lines"] == 3
    assert payload["path"] == "/".join(log.parts), (
        f"POSIX-spelled, so a Windows record reads the same: the components this test "
        f"configured, joined with forward slashes. On Windows `str({log!r})` is "
        f"`prov\\h.jsonl`, and this is the assertion that says so — got {payload['path']!r}"
    )

    # THE DEFAULT LAYOUT, which is what a project that names no history has. No `run_log=`,
    # the history where this package puts it, and the same answer the explicit case gives.
    default = tmp_path / "default"
    (default / "provenance").mkdir(parents=True)
    _chain_history(default / "provenance" / "runs.jsonl", 3)
    monkeypatch.chdir(default)
    runprov.configure(root=".")
    assert runprov.__main__.main(["chain"]) == 0, (
        "G-06. `runprov chain` with no argument, in the layout the README documents, over an "
        "intact history. This read `active().run_log` — `None` here — and exited 2."
    )
    assert "INTACT" in capsys.readouterr().out

    # A root that genuinely has no history. Not a configuration fault: a resolved path with
    # nothing at it, answered by `verify` exactly as a named path with nothing at it is.
    empty = tmp_path / "empty"
    empty.mkdir()
    monkeypatch.chdir(empty)
    runprov.configure(root=".")
    assert runprov.__main__.main(["chain"]) == 2
    assert "no history to read" in capsys.readouterr().out


def test_a_break_names_the_digest_a_reader_can_check_it_against(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-10], the clause nothing asserted. Audit F, F-09.

    R-10's first requirement is that a break names BOTH digests — claimed and computed. The
    test that cited R-10 asserted two OTHER clauses of the sentence, so printing the claimed
    digest where the computed one belongs survived the suite: a self-contradictory message
    asserting the two are equal while reporting them unequal, and no value for the reader to
    run `sha256sum` against. That is the exact failure R-10 exists to buy off.
    """
    p = tmp_path / "h.jsonl"
    lines = _chain_history(p, 4)
    edited = lines[1].replace(b'"status": "ok"', b'"status": "NO"')
    p.write_bytes(b"\n".join([lines[0], edited, *lines[2:]]) + b"\n")

    broken = runprov.chain.verify(p).of(runprov.chain.BROKEN)[0]
    truth = hashlib.sha256(edited).hexdigest()
    assert broken.computed == truth, "the computed digest must be the real one, not a copy"
    assert broken.claimed != broken.computed, "they differ; that is why this is a break"
    assert broken.computed in broken.detail and broken.claimed in broken.detail

    assert runprov.__main__.main(["chain", str(p), "--format", "json"]) == 1
    edges = json.loads(capsys.readouterr().out)["edges"]
    edge = next(e for e in edges if e["status"] == "BROKEN")
    assert edge["computed"] == truth and edge["claimed"] != truth

    # G-22: THE RULE-2 SHAPE, which this test never built. R-10's both-digests clause held
    # for rule 11 and not for rule 2 — the beheaded file's message printed sixteen hex
    # characters and an ellipsis. There is no computed digest at rule 2, because the
    # predecessor the line claims is not in the file, so what R-10 asks for here is the one
    # digest that exists, whole. A 16-character prefix is not a value anyone can paste into
    # `sha256sum`, which is the [ADR-0016 R-12] check the sentence is pointing them at.
    beheaded = tmp_path / "beheaded.jsonl"
    beheaded.write_bytes(b"\n".join(lines[2:]) + b"\n")
    gone = runprov.chain.verify(beheaded).of(runprov.chain.BROKEN)[0]
    assert gone.line == 1 and gone.computed is None, "rule 2: it has no predecessor to hash"
    assert gone.claimed == hashlib.sha256(lines[1]).hexdigest(), "the line it claims is gone"
    assert gone.claimed in gone.detail, "the whole digest, as rule 11's sibling already did"
    assert "…" not in gone.detail, (
        "and no ellipsis. The finding is the INCONSISTENCY between the two BROKEN sentences "
        "rather than a reader who cannot recover: the value is the `prev` field of line 1 in "
        "front of them, and `--format json` emits it whole either way"
    )


def test_a_torn_predecessor_and_a_disagreeing_claim_are_told_apart(tmp_path):
    """ADR-0016 [ADR-0016 R-10] [ADR-0016 R-11] [ADR-0016 R-12] [ADR-0016 R-24]. Audit G, G-13.

    ONE SENTENCE SERVED RULES 6 AND 9, AND THEY HAVE OPPOSITE STRUCTURE. Rule 6 is a line that
    says nothing readable about its predecessor. Rule 9 is a line that says something EXPLICIT
    about its predecessor and disagrees with it. The shared sentence — "nothing readable
    vouches for line N-1" — is true of the first and false of the second, where line N is
    readable, carries a digest claim about N-1, and contradicts the bytes on disk.

    AND IT PRINTED NEITHER DIGEST, so [ADR-0016 R-12]'s by-hand `sha256sum` check was
    impossible at the one edge where a reader most needs it: the edge where the tool itself
    says it cannot decide between a tear and an edit, and hands the reader the decision.

    THE WORDING TRAP, which is why this asserts on two files rather than one. "line N could
    not be read" is FALSE at rule 6: `[1, 2, 3]` is valid JSON that `json.loads` parses
    perfectly and [ADR-0016 R-24] treats as saying nothing, so it reaches rule 6 with the
    parser never having complained. The sentence has to be true of both files, which means
    saying the line carries no readable runprov RECORD.

    THE THIRD CASE WAS FOUND WHILE SPLITTING THE OTHER TWO, and it is asserted here because
    the replacement would otherwise have been printed over it. Rule 3 — a torn FIRST line,
    with chained lines behind it, so the early return in `render` is not taken — reaches the
    same loop, and the shared sentence named "line 0": a line that does not exist. That is
    E-07's own defect, surviving in the renderer after it was fixed in `Link.detail`.
    """
    p = tmp_path / "h.jsonl"
    lines = _chain_history(p, 4)

    # Rule 6 at edge 3 and rule 9 at edge 4. Line 3 loses its leading brace, so the parser
    # refuses it AND [ADR-0016 R-20]'s anchored recovery cannot match: it made no claim.
    torn = tmp_path / "torn.jsonl"
    fragment = lines[2][1:]
    torn.write_bytes(b"\n".join([lines[0], lines[1], fragment, lines[3]]) + b"\n")
    report = runprov.chain.verify(torn)
    assert [e.line for e in report.of(runprov.chain.UNCHECKABLE)] == [3, 4]
    page = runprov.chain.render(report, torn)

    six = next(line for line in page if line.strip().startswith("COULD NOT CHECK  line 3 "))
    assert "line 3 carries no readable runprov record" in six, six
    assert "so it made no claim about line 2" in six, six
    assert "nothing else can vouch for line 2's bytes" in six, six

    nine = next(line for line in page if line.strip().startswith("COULD NOT CHECK  line 4 "))
    assert "nothing readable vouches for line 3" not in nine, (
        "line 4 IS readable, DOES vouch for line 3 explicitly, and disagrees with it. That "
        "is the whole finding, and the old sentence asserted its opposite"
    )
    assert json.loads(lines[3])["prev"] in nine, (
        "[ADR-0016 R-12]: the claimed digest, whole, so the reader can carry the check on"
    )
    assert hashlib.sha256(fragment).hexdigest() in nine, (
        "and the computed one beside it. The two values a reader has to compare by hand are "
        "exactly the two the sentence never printed"
    )

    # [ADR-0016 R-24]: the SAME rule 6, reached by a line the parser accepts.
    listed = tmp_path / "listed.jsonl"
    listed.write_bytes(b"\n".join([lines[0], lines[1], b"[1, 2, 3]", lines[3]]) + b"\n")
    assert json.loads(b"[1, 2, 3]") == [1, 2, 3], "valid JSON, and not a record"
    listed_page = "\n".join(runprov.chain.render(runprov.chain.verify(listed), listed))
    assert "line 3 carries no readable runprov record" in listed_page, listed_page
    assert "could not be read" not in listed_page, (
        "the clause this file falsifies, and the one the obvious rewording reaches for"
    )

    # Rule 3: a torn FIRST line, with the chain still running behind it.
    beheaded = tmp_path / "beheaded.jsonl"
    src = _chain_history(tmp_path / "src.jsonl", 3)
    beheaded.write_bytes(b"\n".join([src[0][:10], src[1], src[2]]) + b"\n")
    first = runprov.chain.verify(beheaded)
    assert first.edges[0].status == runprov.chain.UNCHECKABLE
    assert first.chained_from == 2, "so `render` reaches the loop rather than returning early"
    first_page = "\n".join(runprov.chain.render(first, beheaded))
    assert "line 0" not in first_page, first_page
    assert "line 1 carries no readable runprov record" in first_page, first_page
    assert "it vouched for nothing in any case" in first_page, (
        "the first line attests nothing — that is what HOLDS_TRIVIAL says when it CAN be "
        "read — so losing it puts no other line's bytes in doubt"
    )


def test_a_history_with_nothing_chained_says_what_it_could_not_read(tmp_path, capsys):
    """ADR-0016 [ADR-0016 R-9]. Audit G, G-16.

    `render`'s EARLY RETURN PRINTED THE ONE SENTENCE RULE 3 EXISTS TO PREVENT. Over a torn
    first line in front of a pre-chain history it said "This history was written before the
    chain existed; the next run to append will anchor it" — F-06's wrong message, in the
    renderer, after the table had been amended to stop the walk from saying it. Rule 3 splits
    a torn first line out of `UNCHAINED` precisely because we cannot read what it said, and
    the renderer then said it anyway, because it decided from `chained_from` alone and never
    looked at the edges. It fires on a one-line file that is nothing but a fragment too.

    THE TWO RENDERINGS OF ONE `Report` CONTRADICTED EACH OTHER: `--format json` carried the
    `UNCHECKABLE` edge and `CANNOT_CHECK`, while the text said the file merely predates the
    feature. A reader who believes the text runs the next job and expects to be anchored.

    DELETING THE EARLY RETURN IS WORSE, and that was measured rather than assumed — the
    general header then prints "chained from line None". So the return is KEPT for the file
    it is true of, which is every edge `UNCHAINED`, and every other file gets the findings
    under a header that claims nothing about why nothing is chained.
    """
    pre = [
        json.dumps(
            {"schema": "runprov.history.v2", "run_id": f"p{i}", "tool": {"version": "0.5.0"}}
        ).encode()
        for i in range(5)
    ]
    fragment = _chain_history(tmp_path / "src.jsonl", 1)[0][:10]

    p = tmp_path / "h.jsonl"
    p.write_bytes(b"\n".join([fragment, *pre]) + b"\n")
    report = runprov.chain.verify(p)
    assert report.chained_from is None, "nothing in this file carries a claim"
    assert report.edges[0].status == runprov.chain.UNCHECKABLE, "rule 3: line 1 is torn"
    page = "\n".join(runprov.chain.render(report, p))

    assert "written before the chain existed" not in page, (
        "rule 3 exists to stop exactly this being said about a line nobody can read"
    )
    assert "chained from line None" not in page, page
    assert "6 line(s), none of them chained" in page, page
    assert "5 line(s) predate the chain" in page, page
    assert "line 1 carries no readable runprov record" in page, page
    assert "anchor the file from line 7" in page, (
        "and the anchoring line is NAMED. [ADR-0016 R-7]'s repair closes the fragment with a "
        "newline rather than discarding it, so the next record lands on line 7 and carries "
        "line 6's digest — the fragment stays where it is, counted and unreadable"
    )

    # The two renderings of one report must agree, and they did not.
    assert runprov.__main__.main(["chain", str(p), "--format", "json"]) == 2
    payload = json.loads(capsys.readouterr().out)
    assert payload["status"] == "CANNOT_CHECK"
    assert [e["line"] for e in payload["edges"] if e["status"] == "UNCHECKABLE"] == [1]

    # AND THE SENTENCE IS KEPT where it is true of the whole file: every edge UNCHAINED.
    clean = tmp_path / "clean.jsonl"
    clean.write_bytes(b"\n".join(pre) + b"\n")
    only_pre = runprov.chain.verify(clean)
    assert {e.status for e in only_pre.edges} == {runprov.chain.UNCHAINED}
    kept = "\n".join(runprov.chain.render(only_pre, clean))
    assert "written before the chain existed" in kept, kept


def test_a_claimless_line_is_described_by_who_wrote_it_not_by_where_it_sits(
    tmp_path, capsys, monkeypatch
):
    """ADR-0016 [ADR-0016 R-4] [ADR-0016 R-9] [ADR-0016 R-22] [ADR-0016 R-25].
    Audit H, H1-1, H1-2 and H1-3 — three rows, one guard and ONE ROOT CAUSE.

    R-25 RULE 4 ASSIGNS `UNCHAINED` BY POSITION — `claim = NONE, started = NO` — and never asks
    who wrote the line. That is right for the VERDICT, which is why the status is disclosed and
    never decisive: a claimless line at the front of a file is unverifiable and not fixable
    whoever wrote it. It is wrong for the SENTENCE, which said those lines "predate the chain".

    They need not, and the file says so itself. R-22 makes an append that could not take the
    lock write NO claim at all — NFS, CIFS, a container without `flock` — so a project whose
    early runs landed on such a mount carries a front block of claimless lines stamped with the
    CURRENT release. Three ways that reached the reader:

    * **H1-1** — one unlocked run then one locked one prints `2 line(s) predate the chain` over
      two lines that state `0.6.0`, on an `INTACT`, exit 0 page. The one place in this feature
      where a false sentence sits on a clean bill.
    * **H1-2** — when EVERY line is unlocked, nothing is chained, and `render`'s early return
      said "This history was written before the chain existed; the next run to append will
      anchor it". Both clauses false: the chain existed, and the next append anchors nothing
      while the mount is the same. G-16's defect, through a shape G-16's guard did not exclude.
    * **H1-3** — the same early return DISCARDED `report.unreadable` and `report.merged`, so
      G-03's critical finding — a destroyed record boundary — was invisible in the text while
      `--format json` carried it. The code's own comment already stated the precondition,
      "every edge UNCHAINED, nothing unreadable, nothing merged", and only the first third of
      it was implemented; nothing tested the other two, which is why they could be absent.

    AND BOTH GENUINE CASES MUST READ EXACTLY AS THEY DID, which is the second half of this
    test: a history from 0.5.0 and earlier still says "predate the chain" and still gets the
    early return's sentence. A repair that buys one true sentence with a false one is how this
    feature has already been "fixed" twice.
    """
    real = __import__

    def without_locking(name, *a, **k):
        # BOTH MECHANISMS: `_exclusive` uses `fcntl` on POSIX and `msvcrt` on Windows, and
        # blocking one leaves the other leg asserting the UNLOCKED behaviour of a LOCKED append.
        if name in ("fcntl", "msvcrt"):
            raise ImportError(name)
        return real(name, *a, **k)

    def append(path, tag, version):
        runprov.JsonlSink(path).append(
            {"schema": "runprov.history.v2", "run_id": tag, "tool": {"version": version}}
        )

    # H1-1. AN UNLOCKED FRONT BLOCK, THEN ORDINARY APPENDS.
    mixed = tmp_path / "unlocked_first.jsonl"
    monkeypatch.setattr(builtins, "__import__", without_locking)
    append(mixed, "u0", "0.6.0")
    append(mixed, "u1", "0.6.0")
    monkeypatch.undo()
    append(mixed, "l0", "0.6.0")
    append(mixed, "l1", "0.6.0")
    claims = [("prev" in json.loads(ln)) for ln in mixed.read_bytes().rstrip(b"\n").split(b"\n")]
    assert claims == [False, False, True, True], (
        f"the shape this row is about, and without it the walk never reaches rule 4: {claims}"
    )

    report = runprov.chain.verify(mixed)
    assert [e.status for e in report.edges] == [
        runprov.chain.UNCHAINED,
        runprov.chain.UNCHAINED,
        runprov.chain.HOLDS,
        runprov.chain.HOLDS,
    ], [(e.line, e.status) for e in report.edges]
    assert report.status == runprov.chain.INTACT, (
        "the VERDICT is right and stays right — what was wrong is the sentence wrapped round it"
    )
    assert [e.wrote for e in report.of(runprov.chain.UNCHAINED)] == ["0.6.0", "0.6.0"], (
        "the writer is carried onto UNCHAINED edges; nothing carried one before, which is "
        "exactly why the renderer had nothing to ask and guessed"
    )

    capsys.readouterr()
    assert runprov.__main__.main(["chain", str(mixed)]) == 0
    page = capsys.readouterr().out
    assert "2 line(s) predate the chain" not in page, page
    assert "although runprov 0.6.0 wrote them" in page, page
    assert "0.6.0 can chain" in page, page
    assert "This is not evidence of an edit" in page, "disclosed, and never an accusation"
    assert "upgrade that machine" not in page, (
        "rule 5's advice, and false here: the machine that wrote these lines is current"
    )

    # H1-2. EVERY LINE UNLOCKED, so nothing is chained and the early return is reached.
    everything = tmp_path / "all_unlocked.jsonl"
    monkeypatch.setattr(builtins, "__import__", without_locking)
    for i in range(3):
        append(everything, f"u{i}", "0.6.0")
    monkeypatch.undo()
    loose = runprov.chain.verify(everything)
    assert loose.chained_from is None and {e.status for e in loose.edges} == {
        runprov.chain.UNCHAINED
    }, "the cell G-16's guard let through: every edge UNCHAINED, and none of it pre-chain"
    page = "\n".join(runprov.chain.render(loose, everything))
    assert "written before the chain existed" not in page, page
    assert "although runprov 0.6.0 wrote them" in page, page

    # H1-3. A GENUINE PRE-CHAIN HISTORY WITH A DESTROYED RECORD BOUNDARY. Every edge is
    # UNCHAINED and no writer can chain, so only `merged`/`unreadable` can fail the guard —
    # which is what makes this file, and not H1-2's, the one that tests those two clauses.
    old = [
        json.dumps(
            {"schema": "runprov.history.v2", "run_id": f"p{i}", "tool": {"version": "0.5.0"}}
        ).encode()
        for i in range(3)
    ]
    boundary = tmp_path / "boundary.jsonl"
    raw = b"\n".join(old) + b"\n"
    cut = len(old[0]) + 1 + len(old[1])
    assert raw[cut : cut + 1] == b"\n", "the byte about to be destroyed is the terminator"
    # A lost or zero-filled block, which is how G-03's producer arrives with no forger at all.
    boundary.write_bytes(raw[:cut] + b"\x00" + raw[cut + 1 :])
    joined = runprov.chain.verify(boundary)
    assert joined.merged == (2,) and joined.unreadable == (2,), joined
    assert {e.status for e in joined.edges} == {runprov.chain.UNCHAINED}
    page = "\n".join(runprov.chain.render(joined, boundary))
    assert "written before the chain existed" not in page, page
    assert "a record boundary sits inside it" in page, (
        "G-03 is CRITICAL and the early return dropped it from the text while `--format json` "
        "reported it — the two renderings of one report, disagreeing again"
    )
    assert "2 line(s) predate the chain" in page, (
        "and these lines really do predate it, so that sentence is still the true one"
    )

    # AND `unreadable` ON ITS OWN, because `merged` implies it and a file carrying both cannot
    # tell the two clauses apart — the shape of the mutation that survived this test's first
    # draft. `[1, 2, 3]` is valid JSON that is not an object (R-24), so the parser never
    # complains, `_BOUNDARY` is never consulted, and the line is unreadable with nothing merged.
    lone = tmp_path / "not_an_object.jsonl"
    lone.write_bytes(b"\n".join([old[0], b"[1, 2, 3]", old[2]]) + b"\n")
    odd = runprov.chain.verify(lone)
    assert odd.unreadable == (2,) and odd.merged == (), odd
    assert {e.status for e in odd.edges} == {runprov.chain.UNCHAINED}
    page = "\n".join(runprov.chain.render(odd, lone))
    assert "written before the chain existed" not in page, page
    assert "UNREADABLE  line 2 carries no readable runprov record" in page, (
        "the disclosure the early return dropped, over a file with no destroyed boundary in it"
    )

    # THE GENUINE PRE-CHAIN HISTORY, UNCHANGED, in both of its shapes.
    genuine = tmp_path / "genuine.jsonl"
    genuine.write_bytes(b"\n".join(old) + b"\n")
    kept = "\n".join(runprov.chain.render(runprov.chain.verify(genuine), genuine))
    assert "3 line(s), none of them chained. This history was written before the chain " in kept
    assert "existed; the next run to append will anchor it." in kept, kept

    anchored = tmp_path / "anchored.jsonl"
    anchored.write_bytes(b"\n".join(old) + b"\n")
    append(anchored, "now", "0.6.0")
    after = runprov.chain.verify(anchored)
    assert after.status == runprov.chain.INTACT, "R-4: one append anchors what came before it"
    page = "\n".join(runprov.chain.render(after, anchored))
    assert "3 line(s) predate the chain" in page, page
    assert "although runprov" not in page, (
        "and the new sentence is not printed over lines that genuinely predate the chain"
    )


def test_r31s_shape_list_is_the_one_the_gate_actually_runs():
    """ADR-0016 [ADR-0016 R-31] [ADR-0016 R-15]. The prose and the parametrisation, held equal.

    Audit G, G-15: R-31 named five shapes — intact, torn, unlocked run, mixed-version,
    CRLF-translated — against four that ran. Two it named were never run and one that ran was
    never named, so a reader budgeting risk from the ADR over-credited the gate by two
    confirmations. The wording was corrected in `cbf3f49`; NOTHING KEPT IT CORRECT, which is
    how it drifted in the first place.

    DERIVED FROM BOTH SIDES, never a written list. The requirement's shapes are read out of the
    ADR sentence and the gate's out of the decorator's own AST, so this cannot be satisfied by
    editing a third copy — the failure that `test_every_chain_requirement_has_a_test` was
    rewritten to avoid in G-11, applied to the one other place this project states a set in
    prose and again in code.
    """
    adr = _repo_root() / "docs" / "adr" / "0016-a-history-shows-whether-it-has-been-edited.md"
    if not adr.is_file():  # pragma: no cover - docs ship in the sdist, a bare tree may not
        pytest.skip("ADR-0016 not present")
    # The sentence is a blockquote and wraps, so fold the quote markers and soft breaks away
    # before matching — a line-oriented read is exactly what hid G-23's third site.
    prose = re.sub(r"\n>?[ \t]*", " ", adr.read_text(encoding="utf-8"))
    said = re.search(r"It runs over ([a-z]+) shapes[^:]*:(.+?)\.", prose)
    assert said, "R-31 no longer states the shapes it runs over"
    named = set(re.findall(r"\*\*([a-z-]+)\*\*", said.group(2)))

    source = pathlib.Path(__file__).read_text(encoding="utf-8")
    tree = ast.parse(source)
    run = None
    for node in ast.walk(tree):
        if (
            isinstance(node, ast.FunctionDef)
            and node.name == "test_no_single_byte_edit_escapes_the_chain"
        ):
            for dec in node.decorator_list:
                for arg in getattr(dec, "args", []):
                    if isinstance(arg, ast.List):
                        run = {ast.literal_eval(e) for e in arg.elts}
    assert run, "the acceptance gate is no longer parametrised over shapes"

    assert named == run, (
        f"ADR-0016 R-31 and the acceptance gate disagree about which shapes it runs. "
        f"Named in the ADR and not run: {sorted(named - run)}. "
        f"Run and not named: {sorted(run - named)}. "
        f"Two shapes were removed from the prose for cause — a CRLF-translated line's digest "
        f"cannot match, and under R-32 an unlocked append is UNCLAIMED — so neither can meet "
        f"this gate's asserted INTACT precondition. If a shape is added, add it to both."
    )


def test_no_committed_file_carries_this_machines_identity():
    """Nothing that ships may name the machine it was built on. DERIVED FROM THE HOST.

    `tools/corpus.py`'s own leak scanner covers the corpus TREES, which is where a generated
    record lands — and both leaks found on 2026-09-23 were outside it. **32 files in the
    published 0.5.0 sdist carried the absolute path of the repository** (`command`, `argv[0]`
    and `code.script_file`, which `_normalise` never reached because the scenario script lives
    outside the tree it normalises), and this file itself carried the build host's name in a
    sample of expected output. A PyPI file cannot be replaced, so 0.5.0 keeps both.

    THE SCOPE IS EVERY TRACKED FILE, not a list of likely ones, and the needles are read off
    the RUNNING machine rather than written down: the repository's own absolute path, and this
    host's name. That makes the check true wherever it runs — on CI it asserts CI's paths are
    absent, here it asserts these ones are — and it needs no maintenance when either changes.
    The corpus scanner stays: it can see a leak in a file that is generated and not yet
    committed, which this one cannot.
    """
    root = _repo_root()
    host = platform.node()
    needles = {str(root.resolve()), root.resolve().as_posix()}
    if len(host) >= 4:  # a one- or two-character hostname would match everything
        needles.add(host)

    listed = subprocess.run(
        ["git", "ls-files", "-z"], cwd=root, capture_output=True, text=True, check=False
    )
    if listed.returncode != 0:  # pragma: no cover - a tarball install is not a git checkout
        pytest.skip("not a git checkout")
    tracked = [root / n for n in listed.stdout.split("\0") if n]
    assert len(tracked) > 50, f"only {len(tracked)} tracked files found; the sweep is not sweeping"

    found = []
    for f in tracked:
        try:
            text = f.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue  # a binary fixture is not a leak vector here
        for needle in needles:
            if needle in text:
                found.append(f"{f.relative_to(root).as_posix()}: {needle!r}")
    assert not found, (
        "committed files name the machine they were built on, and a published sdist cannot be "
        f"taken back: {found[:10]}"
    )


def test_every_field_of_the_chain_report_reaches_its_payload(tmp_path):
    """ADR-0017 [ADR-0017 R-1] [ADR-0017 R-2] [ADR-0017 R-9]. DERIVED FROM `_fields`.

    `chain --format json` shipped in 0.6.0 with its emitter in the CLI handler, naming every
    field by hand. Measured before this guard existed: the payload was COMPLETE — `merged`
    (wave 2) and `unreadable` (wave 5) had both been remembered in the second place. **Nothing
    would have said if they had not been**, and a dropped field in a released output is a
    consumer silently missing a finding, not a test going red.

    So the assertion is set equality over the structure's OWN field names, in both directions.
    A field added to `Report` or to `Link` and not carried fails here; a key in the payload that
    answers to no field fails here too, unless it is one of the three named below with its
    reason. A hand-written list of expected keys would be the same defect one layer along.
    """
    history = tmp_path / "h.jsonl"
    sink = runprov.JsonlSink(history)
    for i in range(3):
        sink.append(
            {"schema": "runprov.history.v2", "run_id": f"r{i}", "tool": {"version": "0.6.0"}}
        )
    report = runprov.chain.verify(history)
    body = runprov.chain.payload(report, history)

    # `schema` and `path` identify the answer rather than being part of it (R-5); `status` and
    # `attested` are computed properties, allowed by R-10 because they compute nothing the
    # record does not already hold.
    # `cannot_check` JOINED THIS SET FOR J-01, and this guard is how I learned it had: it failed
    # on the first gate naming the key, alongside the coverage leg. `status` says which verdict;
    # this says which of four routes reached the only verdict that has several. Allowed by R-10
    # for the same reason `status` is — both are read off one fold and compute nothing the
    # record does not already hold.
    named = {"schema", "path", "status", "attested", "cannot_check"}
    assert set(body) - named == set(report._fields), (
        f"the payload and `Report` disagree. Carried but not a field: "
        f"{sorted(set(body) - named - set(report._fields))}. "
        f"A field that reaches no payload: {sorted(set(report._fields) - set(body))}"
    )
    assert "status" in body and "attested" in body, "the computed properties are part of the answer"

    assert body["edges"], "a clean history has edges; this asserts nothing over an empty list"
    # I-08. `could_chain` IS NAMED, not tolerated. It is a computed property rather than a field,
    # so `_fields` does not reach it and the payload adds it — exactly as `status` and `attested`
    # are added above. Naming it here is what makes a FIFTH addition fail this assertion instead
    # of being absorbed: an edge key that is neither a `Link` field nor one of these is a fact
    # invented on the way out.
    link = set(runprov.chain.Link._fields)
    computed = {"could_chain"}
    for edge in body["edges"]:
        assert set(edge) == link | computed, (
            f"an edge and `Link` disagree: carried {sorted(set(edge) - link - computed)}, "
            f"missing {sorted((link | computed) - set(edge))}"
        )
        assert (
            edge["could_chain"]
            is runprov.chain.Link(**{f: edge[f] for f in runprov.chain.Link._fields}).could_chain
        ), (
            "AND IT IS THE STRUCTURE'S OWN ANSWER, not a second computation. M09 was a computed "
            f"field pinned to a constant that passed every KEY check there is: {edge}"
        )

    # R-9: no field is renamed on the way out, so a question asked of the structure is
    # answerable of the payload.
    assert body["lines"] == report.lines and body["chained_from"] == report.chained_from
    assert json.loads(json.dumps(body)) == body, "the payload must survive a JSON round trip"


def _adr_0018_rules() -> dict[str, dict[str, str]]:
    """ADR-0018 R-7's table, read from the ADR. The ONLY list of rule names outside the registry.

    R-5 forbids a second copy of the rule set in the parser, the docs or the tests, so this reads
    the specification rather than restating it. R-7 was a PROSE SENTENCE until 2026-10-02 — *"the
    tree was clean; no unregistered reads; …"* — which no test could derive canonical names from,
    so it became a table. That amendment is what makes R-5 enforceable rather than aspirational.
    """
    adr = (
        _repo_root()
        / "docs"
        / "adr"
        / "0018-a-policy-is-checked-against-the-history-not-remembered.md"
    )
    if not adr.is_file():  # pragma: no cover - docs ship in the sdist, a bare tree may not
        pytest.skip("ADR-0018 not present")
    out: dict[str, dict[str, str]] = {}
    for row in re.finditer(
        r"^\| `(?P<rule>[a-z_]+)` \| (?P<asks>[^|]+) \| (?P<reads>[^|]+) \| (?P<blind>[^|]+) \|$",
        adr.read_text(encoding="utf-8"),
        re.M,
    ):
        out[row["rule"]] = {
            "asks": row["asks"].strip(),
            "reads": row["reads"].strip(),
            "blind": row["blind"].strip(),
        }
    return out


def _record_field_vocabulary(tmp_path, monkeypatch) -> set[str]:
    """Every field a record can carry, as dotted paths, from records REACHING each state.

    R-10 says a rule may only assert over fields that exist. Deciding that from ONE record is too
    strict: `unregistered_reads` is written only when reads were missed, and
    `observation.unregistered_watch_truncated` only when the watch hit its cap — both absent from
    a clean run and both legitimate fields of the schema.

    SO THE VOCABULARY IS THE UNION OVER RECORDS THAT REACH THOSE STATES, built by this package
    rather than declared here. A hand-written field list would be the stale-list pattern one level
    down, and a list of conditional fields is exactly the kind that goes stale silently — the
    field stops being written and the list still names it.

    `WATCH_MAX_PATHS` IS MONKEYPATCHED TO REACH THE CAP. It is 2000, so the truncation state is
    unreachable in a test at full size; the cap is a module constant precisely so it can be moved.
    """
    vocabulary: set[str] = set()
    histories = tmp_path / "vocab"
    histories.mkdir()

    def harvest(log: pathlib.Path) -> None:
        for line in log.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            record = json.loads(line)
            if record.get("schema") == "runprov.start.v1":
                continue
            for key, value in record.items():
                vocabulary.add(key)
                if isinstance(value, dict):
                    vocabulary.update(f"{key}.{inner}" for inner in value)

    #: 1. A CLEAN RUN, with an input and an output.
    clean = histories / "clean.jsonl"
    runprov.configure(root=histories, run_log=clean, auto_steps="off")
    (histories / "in.tsv").write_text("a\n", encoding="utf-8")
    with runprov.Run("clean", {}, provenance=histories / "p1.json") as run:
        run.input(histories / "in.tsv")
        with run.open_output(histories / "out.tsv") as fh:
            fh.write("a\n")
    harvest(clean)

    #: 2. A RUN THAT READ WITHOUT REGISTERING, which is the only way `unregistered_reads` appears.
    missed = histories / "missed.jsonl"
    runprov.configure(root=histories, run_log=missed, auto_steps="off")
    with runprov.Run("missed", {}, provenance=histories / "p2.json"):
        with open(histories / "in.tsv", encoding="utf-8") as fh:
            fh.read()
    harvest(missed)
    assert "unregistered_reads" in vocabulary, (
        "the premise of this fixture: an unregistered read puts the field in the record"
    )

    #: 3. A WATCH THAT HIT ITS CAP, reached by moving the cap rather than opening 2,000 files.
    monkeypatch.setattr(runprov.watch, "WATCH_MAX_PATHS", 1)
    capped = histories / "capped.jsonl"
    runprov.configure(root=histories, run_log=capped, auto_steps="off")
    for name in ("one.tsv", "two.tsv", "three.tsv"):
        (histories / name).write_text("x\n", encoding="utf-8")
    with runprov.Run("capped", {}, provenance=histories / "p3.json"):
        for name in ("one.tsv", "two.tsv", "three.tsv"):
            with open(histories / name, encoding="utf-8") as fh:
                fh.read()
    harvest(capped)

    #: 4. A RUN THAT FAILED, so `failure` is a string rather than null.
    failed = histories / "failed.jsonl"
    runprov.configure(root=histories, run_log=failed, auto_steps="off")
    try:
        with runprov.Run("failed", {}, provenance=histories / "p4.json"):
            raise ValueError("boom")
    except ValueError:
        pass
    harvest(failed)

    #: 5. A RUN THAT CAPTURED AN ENVIRONMENT SNAPSHOT, which is the only way
    #: `environment_snapshot` appears — added for K-19, where `environment_captured` had to start
    #: reading it. `environment` itself is `None` in a history record: `run.py` FLATTENS the block
    #: to this top-level key and `environment.snapshot` exists only in the sidecar, which `gate`
    #: never opens. **That is the half of K-19 a skeptic caught**: the row sent an applier to
    #: `environment["snapshot"]`, which would have read `None` on every record — uninformed and
    #: indistinguishable from satisfied — and this fixture is what makes the right field provable.
    snapped = histories / "snapped.jsonl"
    snapshots = histories / "env"
    snapshots.mkdir()
    runprov.configure(root=histories, run_log=snapped, auto_steps="off", env_snapshot_dir=snapshots)
    with runprov.Run("snapped", {}, provenance=histories / "p5.json"):
        pass
    harvest(snapped)
    return vocabulary


def test_each_rule_reaches_all_three_verdicts_over_the_state_its_row_names(tmp_path):
    """[ADR-0018 R-3] [ADR-0018 R-7] T-34. Every rule's three answers, state by state.

    The derived guards prove the STRUCTURE — that each rule can say `CANNOT_CHECK`, reads only
    real fields, and agrees with its row. They do not prove the verdicts. This does, one state at
    a time, with the state constructed so that exactly one fact distinguishes the three cases.

    CONSTRUCTED RECORDS HERE AND REAL ONES BELOW, deliberately. A constructed record isolates the
    single field under test, which is what makes a three-way comparison legible; the next test
    runs the same rules over records this package actually wrote, which is what stops the
    constructed ones from drifting into a shape the writer never produces.
    """
    met, violated, unknown = (
        runprov.policy.MET,
        runprov.policy.VIOLATED,
        runprov.policy.CANNOT_CHECK,
    )
    stable = tmp_path / "stable.tsv"
    stable.write_text("a\n", encoding="utf-8")
    recorded = runprov.hashing.content_digest(stable)
    cases = {
        "clean_tree": [
            ({"git_status_captured": True, "git_tree_dirty": False}, met),
            ({"git_status_captured": True, "git_tree_dirty": True}, violated),
            #: THE WHOLE POINT: `git_tree_dirty` is False here exactly as in the MET case.
            ({"git_status_captured": False, "git_tree_dirty": False}, unknown),
        ],
        "no_unregistered_reads": [
            ({"observation": {}}, met),
            ({"observation": {}, "unregistered_reads": ["a.tsv"]}, violated),
            ({"observation": {"unregistered_watch_truncated": 7}}, unknown),
            #: A VIOLATION OUTRANGES THE TRUNCATION: knowing part of a list is knowing a breach.
            (
                {"observation": {"unregistered_watch_truncated": 7}, "unregistered_reads": ["a"]},
                violated,
            ),
            ({}, unknown),
        ],
        "outputs_pin_inputs": [
            ({"outputs": [{"path": "o"}], "inputs": [{"path": "i"}]}, met),
            ({"outputs": [{"path": "o"}], "inputs": []}, violated),
            ({"outputs": []}, unknown),
            ({}, unknown),
        ],
        "commit_recorded": [
            ({"git_status_captured": True, "git_commit": "abc123"}, met),
            ({"git_status_captured": True, "git_commit": None}, violated),
            ({"git_status_captured": False, "git_commit": None}, unknown),
        ],
        "environment_captured": [
            ({"observation": {"packages_recorded": "tracked"}, "packages": {"x": "1"}}, met),
            #: A SNAPSHOT THAT NAMES ITS PACKAGE COUNT, which is what every released wheel
            #: from 0.2.0 on wrote and why MET is correct for SIX of the seven [L-11] — 0.1.0
            #: predates ADR-0010, carries no `observation` block and answers CANNOT_CHECK
            #: through the arm above, correctly. The row that was here before carried the MARK
            #: ALONE and answered MET, which is K-19.
            (
                {
                    "observation": {"packages_recorded": "snapshot"},
                    "packages": {},
                    "environment_snapshot": {"n_packages": 2, "sha256": "ab" * 32},
                },
                met,
            ),
            #: THE MARK WITHOUT THE SNAPSHOT [K-19]. `_observed_packages` returns `"snapshot"` on
            #: the mere presence of the key, so a capture that RAISED is marked the same way as
            #: one that worked, and the rule vouched for it over `packages: {}` — which its own
            #: `blind` text calls indistinguishable from nobody having asked.
            (
                {
                    "observation": {"packages_recorded": "snapshot"},
                    "packages": {},
                    "environment_snapshot": {"error": "[Errno 13] Permission denied"},
                },
                unknown,
            ),
            ({"observation": {"packages_recorded": "snapshot"}, "packages": {}}, unknown),
            #: AND A RUN THAT TRACKED PACKAGES *AND* TOOK A SNAPSHOT IS NOT RELYING ON IT, so the
            #: snapshot is not consulted at all: the packages themselves are in the record.
            (
                {
                    "observation": {"packages_recorded": "snapshot"},
                    "packages": {"x": "1"},
                    "environment_snapshot": {"error": "this is not read"},
                },
                met,
            ),
            #: `none` IS AN ANSWER, not an inability: the record positively says nothing was kept.
            ({"observation": {"packages_recorded": "none"}, "packages": {}}, violated),
            ({"observation": {}}, unknown),
            ({}, unknown),
        ],
        "finished_ok": [
            ({"status": "ok"}, met),
            ({"status": "failed", "failure": "ValueError: boom"}, violated),
            #: A STATUS THAT FAILED AND NOTHING TO QUOTE. The verdict is still VIOLATED and the
            #: sentence must not end in a dangling colon — and a record written before the
            #: failure block existed carries a STRING there, which is the row above.
            ({"status": "failed"}, violated),
            #: AND TODAY'S SHAPE, a mapping of `type`, `message` and `traceback`. Interpolating it
            #: whole put an escaped multi-line traceback inside one line of a filed report, found
            #: by rendering the command once by hand rather than by a test.
            (
                {"status": "failed", "failure": {"type": "ValueError", "message": "boom"}},
                violated,
            ),
            #: A START WITH NO ENDING IS NOT A FAILURE — `show`'s INTERRUPTED distinction.
            ({}, unknown),
        ],
        #: THE ONE RULE WHOSE THREE STATES ARE STATES OF THE DISK rather than shapes of a dict,
        #: so the record is constructed and the digest is NOT: it comes from the same function
        #: the writer uses, which is why the MET row cannot pass by agreeing with a literal
        #: somebody typed. A digest typed into a test is a test of the typing.
        "inputs_verify": [
            ({"inputs": [{"path": str(stable), "content_sha256": recorded}]}, met),
            ({"inputs": [{"path": str(stable), "content_sha256": "0" * 64}]}, violated),
            #: GONE IS AN INABILITY, NOT A VIOLATION — R-9's clarification in one row. The file
            #: may have been archived, and accusing the run of changing it would be an
            #: accusation nobody can withdraw from a record.
            (
                {"inputs": [{"path": str(tmp_path / "gone.tsv"), "content_sha256": recorded}]},
                unknown,
            ),
            ({"inputs": []}, unknown),
            ({}, unknown),
        ],
    }
    assert set(cases) == set(runprov.policy.rules()), (
        "every registered rule needs its verdicts asserted here, and only registered ones: "
        f"{sorted(set(cases) ^ set(runprov.policy.rules()))}"
    )
    #: A BARE `Context` CACHES NOTHING, AND THIS IS AN ASSERTION BECAUSE A COMMENT HERE TAUGHT
    #: THE OPPOSITE [K-36]. It justified the fresh context below by saying a shared one *would
    #: serve the VIOLATED row a digest cached by the MET row*. `Context().digests` is `None` and
    #: the cache path guards on it, so the file is read twice either way — and even a shared
    #: `Context(digests={})` would not move these verdicts, because the cache holds the DISK
    #: digest while the two rows differ only in what the RECORD claims.
    #:
    #: **IT MATTERS BECAUSE THE BELIEF IT TAUGHT IS WHAT MAKES K-31 LOOK IMPOSSIBLE.** A reader
    #: who thinks a bare `Context()` memoises cannot see the one shape that really produces a
    #: wrong answer: a cache handed in ALREADY POISONED, which `assess` uses verbatim — zero
    #: files read, an unchanged file reported VIOLATED. The same false belief was in `assess`'s
    #: own comment and in `Context`'s docstring, and this is the third place it lived.
    assert runprov.policy.Context().digests is None, (
        "[K-36] [K-31] a bare `Context` holds no cache at all. The assertion is here rather than "
        "a corrected comment because the comment that was here taught a reader that it does, "
        "which is the belief that hides K-31's poisoned cache"
    )
    for name, rows in cases.items():
        outcomes = set()
        for record, expected in rows:
            #: A FRESH CONTEXT PER CASE — for isolation, and NOT because a shared one would cache
            #: anything. See the assertion above: it would not.
            got = runprov.policy.rules()[name].judge(record, runprov.policy.Context())
            assert got.outcome == expected, (
                f"`{name}` over {record} answered {got.outcome} ({got.reason}), not {expected}"
            )
            if expected != met:
                assert got.reason, f"`{name}` said {expected} without saying why"
            outcomes.add(got.outcome)
        assert outcomes == {met, violated, unknown}, (
            f"[ADR-0018 R-3] `{name}` was not exercised in all three answers here, so one of them "
            f"is unasserted: {sorted(outcomes)}"
        )


def test_the_rules_agree_with_records_this_package_really_wrote(tmp_path, monkeypatch):
    """[ADR-0018 R-7] [ADR-0018 R-10] T-34. The constructed records, checked against real ones.

    A hand-built record asserts against what the test's author believes the writer produces — A-08's
    shape. So the same rules run over the four records `_record_field_vocabulary` builds, and the
    verdicts are asserted against what those states MEAN rather than against a literal.

    THE CAPPED RUN IS THE ONE THAT MATTERS, AND IT TAKES TWO OF THEM. Capping the watch at one
    path while the first file opened is UNREGISTERED gives a record carrying both fields — a known
    violation and a truncation — and the rule answers VIOLATED, because knowing part of a list is
    knowing a breach. **My first version of this test expected CANNOT_CHECK there and the rule was
    right:** the expectation was wrong, not the precedence.

    The state C-06 is actually about needs the opposite order: the one path the watch keeps must be
    a REGISTERED one, so `unregistered_reads` comes out EMPTY while the dropped paths were the
    unregistered ones. Then the empty list means *the watch lost them*, not *none were missed* —
    and only then must the rule refuse to pass. Both are built below, from real runs.
    """
    histories = tmp_path / "real"
    histories.mkdir()
    monkeypatch.setattr(runprov.watch, "WATCH_MAX_PATHS", 1)
    runprov.configure(root=histories, run_log=histories / "h.jsonl", auto_steps="off")
    for name in ("one.tsv", "two.tsv", "three.tsv"):
        (histories / name).write_text("x\n", encoding="utf-8")
    with runprov.Run("capped", {}, provenance=histories / "p.json"):
        for name in ("one.tsv", "two.tsv", "three.tsv"):
            with open(histories / name, encoding="utf-8") as fh:
                fh.read()
    capped = [
        json.loads(line)
        for line in (histories / "h.jsonl").read_text(encoding="utf-8").splitlines()
        if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
    ][-1]
    assert capped["observation"].get("unregistered_watch_truncated"), (
        f"the premise: the cap bit and the record says so: {capped['observation']}"
    )

    assert capped.get("unregistered_reads"), (
        "the premise of THIS fixture: the watch kept one unregistered path before the cap bit, so "
        f"the record names a breach as well as a truncation: {capped}"
    )
    verdict = runprov.policy.rules()["no_unregistered_reads"].judge(
        capped, runprov.policy.Context()
    )
    assert verdict.outcome == runprov.policy.VIOLATED, (
        "a truncated watch that still caught something knows at least one read was missed, so the "
        f"violation outranks the inability: {verdict}"
    )

    # AND THE STATE C-06 IS ABOUT: the kept path is REGISTERED, so the missed list comes out empty
    # while the dropped paths were the unregistered ones. Only the truncation mark separates this
    # from a clean run, which is the whole of why the rule reads it.
    pure = histories / "pure.jsonl"
    runprov.configure(root=histories, run_log=pure, auto_steps="off")
    with runprov.Run("c06", {}, provenance=histories / "p3.json") as run:
        with open(run.input(histories / "one.tsv"), encoding="utf-8") as fh:
            fh.read()
        for name in ("two.tsv", "three.tsv"):
            with open(histories / name, encoding="utf-8") as fh:
                fh.read()
    lost = [
        json.loads(line)
        for line in pure.read_text(encoding="utf-8").splitlines()
        if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
    ][-1]
    assert not lost.get("unregistered_reads"), (
        f"the premise: nothing was RECORDED as missed, because the cap dropped it: {lost}"
    )
    assert lost["observation"].get("unregistered_watch_truncated"), (
        f"and the record says the watch lost paths: {lost['observation']}"
    )
    verdict = runprov.policy.rules()["no_unregistered_reads"].judge(lost, runprov.policy.Context())
    assert verdict.outcome == runprov.policy.CANNOT_CHECK, (
        "[ADR-0018 R-3] an empty `unregistered_reads` after the cap bit cannot mean none were "
        f"missed — this is C-06 as a policy, and a pass here is the vacuous green: {verdict}"
    )
    assert "cap" in (verdict.reason or ""), verdict

    # AND A REAL FAILED RUN, whose status and failure the writer sets rather than this test.
    failed = histories / "failed.jsonl"
    runprov.configure(root=histories, run_log=failed, auto_steps="off")
    try:
        with runprov.Run("boom", {}, provenance=histories / "p2.json"):
            raise ValueError("boom")
    except ValueError:
        pass
    record = [
        json.loads(line)
        for line in failed.read_text(encoding="utf-8").splitlines()
        if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
    ][-1]
    assert record["status"] != "ok", f"the premise: a real failed run: {record['status']}"
    got = runprov.policy.rules()["finished_ok"].judge(record, runprov.policy.Context())
    assert got.outcome == runprov.policy.VIOLATED and "boom" in (got.reason or ""), got

    # AND `assess` OVER THE WHOLE HISTORY, so R-4's count comes from a real selection.
    tally = runprov.policy.assess("finished_ok", [record])
    assert (tally["evaluated"], tally["violated"]) == (1, 1), tally
    assert tally["asked_of_nothing"] is False and tally["reasons"], tally


def test_only_the_writer_of_status_may_default_it(tmp_path, capsys, monkeypatch):
    """THE GATE AND `show` READ A STATUS-LESS RECORD DIFFERENTLY, AND ONE OF THEM INVENTED A
    VERDICT. Audit M, the second row the field-comparison table surfaced. Five sites spelled
    `record.get("status", "ok")` — including the page `show` prints and the entry `log --format
    yaml` writes — while `policy._finished_ok` spelled `record.get("status")` and answered
    CANNOT_CHECK. One history, two answers, chosen by which command the reader typed.

    WHICH DEFAULT IS RIGHT, DECIDED BY WHAT THE RECORD MEANS AND NOT BY THE MAJORITY. The gate's
    is. ADR-0018 R-3 says an unevaluable rule is NEVER a pass, and `_finished_ok`'s own docstring
    adds the other half — *A MISSING STATUS IS NOT A FAILURE* — so absence is neither verdict.
    `_status` in `diff.py` reaches the same answer in its own words (*a missing `status` BLOCKS
    rather than compares*), and `show.py` already states the principle four lines above the line
    that broke it, about the field next door: *a run that PREDATES the field does not know the
    answer, and rendering "clean" for it would be the reassuring lie the flag exists to stop.*
    So every reader now goes through `show.status_of`, which names the third state.

    AND THE STATUS-LESS RECORD IS NOT HYPOTHETICAL, which is worth saying because the row was
    filed as though it were: `runprov.start.v1` carries no `status` AT ALL, and it is three of
    every six lines in all seven released histories. It never reaches either side only because
    `__main__._is_start` drops it in `_load` and `policy` drops it in `_counted` — Taylor's
    ruling of 2026-10-03, recorded in `policy.Assessment.unfinished`. What does reach them is a
    hand-edited history, a line from another tool, and `compare()`, which `_status`'s docstring
    names as *pure and public and fed hand-built mappings*.

    DERIVED, NOT LISTED, AND THE DERIVATION IS THE WRITER'S. The permitted defaults are not a
    set of filenames: they are *whatever module assigns this field*, found by AST, and the
    verdict words are *whatever values that module assigns*, found the same way. A sixth reader
    added next year with a `"ok"` default fails this the day it is written, and a verdict word
    added to the writer is in scope the day it exists.

    WHAT THIS GUARD DOES NOT COVER, SAID RATHER THAN GLOSSED: `export.py`'s RO-Crate
    `actionStatus` is `CompletedActionStatus if rec.get("status") == "ok" else
    FailedActionStatus`, so a status-less record is exported as an ACCUSATION — the opposite
    invention, in a published interchange format a third party reads, and `export.py` two
    paragraphs later carries `runprov:status: null` honestly for the same record. It is not a
    `.get` default, so the rule below does not reach it; it is a filed row and a decision about
    an interchange field rather than something to change in passing. Named here so the next
    reader does not take this test's green as covering it.
    """
    #: THE WRITER AND ITS VOCABULARY, BOTH DERIVED.
    package = pathlib.Path(runprov.__file__).parent
    sources = {m.name: m.read_text(encoding="utf-8") for m in sorted(package.glob("*.py"))}
    assert len(sources) == _PACKAGE_MODULES, (
        f"the walk read {len(sources)} of the package's {_PACKAGE_MODULES} modules: "
        f"{sorted(sources)}"
    )

    def value_of(node, module):
        """A string literal, or a module constant resolved to one. Anything else is not a word."""
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return node.value
        if isinstance(node, ast.Name):
            held = getattr(getattr(runprov, module.removesuffix(".py"), None), node.id, None)
            return held if isinstance(held, str) else None
        return None

    writers = {}
    for name, src in sources.items():
        for node in ast.walk(ast.parse(src, filename=name)):
            assigned = None
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "setdefault"
                and len(node.args) == 2
                and isinstance(node.args[0], ast.Constant)
                and node.args[0].value == "status"
            ):
                assigned = node.args[1]
            elif isinstance(node, ast.Assign) and any(
                isinstance(t, ast.Subscript)
                and isinstance(t.slice, ast.Constant)
                and t.slice.value == "status"
                for t in node.targets
            ):
                assigned = node.value
            word = value_of(assigned, name) if assigned is not None else None
            if word is not None:
                writers.setdefault(name, set()).add(word)

    assert writers == {"run.py": {"ok", "failed", runprov.run.RUNNING_STATUS}}, (
        f"the writer of `status` is not where this thinks, or its vocabulary moved: {writers}. "
        f"This test derives BOTH from the code; if a second module now assigns the field, the "
        f"question of who owns the default has a new answer and this test is the wrong shape."
    )
    (writer,) = writers
    verdicts = writers[writer]

    def verdict_defaults(src, name):
        """Every read of `status` that supplies a verdict word the record did not carry.

        TWO SPELLINGS, NOT ONE [Audit N, guards-5]. This saw only
        `<rec>.get("status", <word>)`, so `rec.get("status") or "ok"` defaulted the field
        invisibly and the docstring's promise — *a sixth reader added next year with a `"ok"`
        default fails this the day it is written* — was false for the spelling its own SIBLING
        guard had been widened to catch IN THE SAME AUDIT. The widening was applied to the
        instance and not to the class.

        AND THE TWO SPELLINGS ARE NOT BEHAVIOURALLY IDENTICAL; `or` IS STRICTLY WORSE.
        `.get("status", "ok")` returns `""` or `None` when the key is PRESENT and empty or null;
        `or "ok"` returns `"ok"` for both. A present-but-null status is real data in this
        project — `export.py` writes `"runprov:status": rec.get("status")` deliberately, and
        `show.status_of`'s own docstring says a hand-edited history or a line from another tool
        can carry `null`. So the `or` spelling invents a verdict for a record that explicitly
        says it has none, which is worse than the shape this already caught.

        THE `branches()` DESCENT IS THE PATH GUARD'S, verbatim in shape: a fallback can hide in
        an `ast.IfExp`'s arms or an `ast.BoolOp`'s operands, so the WORD is looked for in every
        arm rather than in the one expression. `value_of(arm) in verdicts` carries the load — the
        `X or <fallback>` idiom appears at about 97 sites in the package and the key and the word
        together are what make this specific.

        WHAT IT STILL DOES NOT SEE, RECORDED RATHER THAN CLOSED: the TWO-LINE form,
        `status = rec.get("status")` on one line and `verdict = status or "ok"` on the next.
        Neither arm follows a local binding, and `policy.py` and `show.py` are ALREADY split that
        way — both correctly, neither defaulting — so the shape is live in the tree and a reader
        who copied it and added `or "ok"` would pass this. Closing it needs flow analysis of a
        local, which is a different guard; this one closes a spelling.
        """

        def branches(v: ast.expr) -> list[ast.expr]:
            """The arms a fallback can hide in — and no other descent."""
            if isinstance(v, ast.IfExp):
                return [*branches(v.body), *branches(v.orelse)]
            if isinstance(v, ast.BoolOp):
                return [b for x in v.values for b in branches(x)]
            return [v]

        def a_verdict_word(v: ast.expr) -> bool:
            return any(value_of(arm, name) in verdicts for arm in branches(v))

        def reads_status(v: ast.expr, args: int) -> bool:
            return (
                isinstance(v, ast.Call)
                and isinstance(v.func, ast.Attribute)
                and v.func.attr == "get"
                and len(v.args) == args
                and isinstance(v.args[0], ast.Constant)
                and v.args[0].value == "status"
            )

        found = {}
        for node in ast.walk(ast.parse(src, filename=name)):
            if reads_status(node, 2) and a_verdict_word(node.args[1]):
                found[f"{name}:{node.lineno}"] = ast.unparse(node)
            #: THE `or` SPELLING: the first operand reads the field and the last supplies the
            #: word. `Or` only — `X and "ok"` cannot default anything, since it yields the word
            #: exactly when the field was already truthy.
            elif (
                isinstance(node, ast.BoolOp)
                and isinstance(node.op, ast.Or)
                and reads_status(node.values[0], 1)
                and a_verdict_word(node.values[-1])
            ):
                found[f"{name}:{node.lineno}"] = ast.unparse(node)
        return found

    inventing = {}
    for name, src in sources.items():
        if name == writer:
            continue  # the writer may: see the comment at `_append_history`'s projection
        inventing |= verdict_defaults(src, name)
    assert not inventing, (
        f"a READER of `status` defaults it to a verdict the writer writes: {inventing}. A record "
        f"that does not carry the field says nothing, and `show.status_of` is where that is "
        f"named — `policy._finished_ok` answers CANNOT_CHECK for the same record, and two views "
        f"of one run disagreeing is the failure this field's readers exist to prevent."
    )
    # NON-VACUITY, THROUGH THE SAME MATCHER: a probe for each verdict word, so narrowing the
    # derivation or losing an argument condition fails here rather than quietly matching nothing.
    #: AND ONE LINE PER NEW ARM [Audit N, guards-5], exactly as the path guard's probe does. The
    #: positives come first and the negatives after, because the assertion is positional: the
    #: `or` spelling, a fallback behind an `ast.IfExp`, and both at once. The negatives are the
    #: controls that say the arms are specific — a non-verdict default, a read with no default,
    #: the wrong KEY with the `or` spelling, and `and` instead of `or`, which cannot default
    #: anything because it yields the word exactly when the field was already truthy.
    first = sorted(verdicts)[0]
    probe = verdict_defaults(
        "\n".join(f'x = r.get("status", {w!r})' for w in sorted(verdicts))
        + f'\nx = r.get("status") or {first!r}'
        + f'\nx = r.get("status", {first!r} if c else None)'
        + f'\nx = r.get("status") or ({first!r} if c else None)'
        + '\nx = r.get("status")\nx = r.get("status", "?")\nx = r.get("other", "ok")'
        + f'\nx = r.get("other") or {first!r}\nx = r.get("status") and {first!r}\n',
        "<probe>",
    )
    assert sorted(probe) == [f"<probe>:{i}" for i in range(1, len(verdicts) + 4)], (
        f"the scan cannot see its own subject, one line per verdict word and one per arm: {probe}"
    )
    #: AND THE EXEMPTION'S OWN SUBJECT, ASSERTED: `run.py` is skipped above, so if its projection
    #: ever stops carrying that default the skip is covering nothing and should go.
    assert verdict_defaults(sources[writer], writer), (
        f"`{writer}` is exempted here and no longer has a defaulted `status` read, so the "
        f"exemption now hides nothing — delete it rather than leave it unexplained"
    )

    #: AND THE TWO SIDES, ASKED THE SAME QUESTION ABOUT THE SAME RECORD. The structural half
    #: forbids the shape; this half is the agreement itself.
    nameless = {
        "schema": "runprov.history.v2",
        "script": "s",
        "run_uid": "u" * 32,
        "run_id": "r",
        "generation": "(default)",
        "started_utc": "2026-01-01T00:00:00Z",
        "finished_utc": None,
        "command": "python s.py",
        "cwd": str(tmp_path),
    }
    assert "status" not in nameless, "the premise"
    assert runprov.show.status_of(nameless) == runprov.show.UNKNOWN_STATUS
    gate = runprov.policy.rules()["finished_ok"].judge(nameless, runprov.policy.Context())
    assert gate.outcome == runprov.policy.CANNOT_CHECK, (
        f"[ADR-0018 R-3] the gate side of the agreement moved: {gate}"
    )

    #: AND THROUGH THE COMMANDS, which is where the divergence was visible. Measured first,
    #: then asserted: `show --format json`'s project view carries COUNTERS and no `status` key
    #: for the project summary, and `log --format json` passes the record through verbatim and
    #: adds nothing — so the sites that invented `"ok"` were `show <target>`'s view, the artifact
    #: block, `render_yaml`'s entry, `log`'s text page and `show`'s own per-script counters. All
    #: five are below, and each is asserted on the fact the reader actually sees.
    log = tmp_path / "h.jsonl"
    monkeypatch.chdir(tmp_path)

    def page(argv, record):
        log.write_text(json.dumps(record) + "\n", encoding="utf-8")
        runprov.configure(root=tmp_path, run_log=log)
        runprov.__main__.main([*argv, "--log", str(log)])
        return capsys.readouterr().out

    #: THE COUNTERS: a two-bucket tally has no third bucket, so an unknown status increments
    #: NEITHER and `runs` is what says so. `ok: 1` was the reassuring lie; `failed: 1` would be
    #: the opposite overstatement, and counting neither is the only answer the payload can hold
    #: without a new key.
    counted = json.loads(page(["show", "--format", "json"], dict(nameless)))["project"]
    assert [counted["runs"], *[counted["scripts"]["s"][k] for k in ("runs", "ok", "failed")]] == [
        1,
        1,
        0,
        0,
    ], f"a status-less record is counted as a verdict: {counted}"
    recorded = json.loads(page(["show", "--format", "json"], dict(nameless, status="ok")))[
        "project"
    ]
    assert recorded["scripts"]["s"]["ok"] == 1, (
        f"and a RECORDED `ok` must still be counted, or the arm above is uninformed: {recorded}"
    )

    #: THE VIEW THAT CARRIES THE VALUE: `show <target>` and the artifact block both render the
    #: status itself, where the third state is expressible and is the whole answer.
    assert runprov.show.status_of(dict(nameless)) == runprov.show.UNKNOWN_STATUS
    view = runprov.show.run_view(dict(nameless))
    assert view["status"] == runprov.show.UNKNOWN_STATUS, (
        f"`show`'s own view of a status-less record: {view['status']!r}"
    )
    #: AND IT SURVIVES THE PAGE, which is what a reader sees: `render_run` does
    #: `view["status"].upper()` for anything that is not `ok`, so a view with no status at all
    #: used to be a KeyError there and the `"ok"` default is what hid it.
    assert "UNKNOWN" in runprov.show.render_run(view), runprov.show.render_run(view)

    #: AND `log`'s PAGE, which marked such a record `  ` — the mark a recorded success gets.
    #: `!!` now means *not a recorded success*, and the clause below it says which of the two
    #: reasons applies rather than printing `FAILED  ?:` with an empty message.
    text = page(["log"], dict(nameless))
    assert "!!" in text and "NOT RECORDED" in text and "FAILED" not in text, (
        f"`log`'s page either calls a status-less record clean or accuses it of failing: {text}"
    )
    failed = page(["log"], dict(nameless, status="failed", failure={"type": "V", "message": "m"}))
    assert "FAILED     V: m" in failed and "NOT RECORDED" not in failed, (
        f"and a RECORDED failure must still reach the failure clause: {failed}"
    )


def test_the_watch_can_be_switched_off_and_the_rule_says_so_rather_than_pretending(tmp_path):
    """[ADR-0018 R-6] [ADR-0018 R-10] Audit K, K-18. The one row a skeptic recommends NOT fixing
    before release, and this is where the decision is recorded so it stays a decision.

    **THE DEFECT.** `no_unregistered_reads` answers MET for a run whose watch was switched off by
    `warn_unregistered_reads=False` — a documented, package-recommended setting for a step that
    deliberately reads files it does not want recorded. Reproduced: such a run performed a real
    unregistered `open()`, recorded neither `unregistered_reads` nor the truncation mark, kept a
    full `observation` block, and the rule said MET. **This is the rule the whole ADR is built
    around, producing the vacuous green through the most ordinary route there is.** And the
    setting is PROJECT-level, so one step's exemption silences the watch for every run that shares
    the project and the rule says MET over all of them — more ordinary than the row first filed.

    **THE VERDICT IS DELIBERATELY NOT CHANGED, and the reason is measured.** The record carries no
    field saying whether the watch ran, and `observation.unregistered_watch` cannot be
    back-filled: a rule requiring it would turn **every clean pre-0.8.0 history from MET to
    CANNOT_CHECK for ever**, which is worse than the defect — in the one release that is also the
    last chance to add fields. And the same check placed before the violation arm turns a real
    VIOLATED finding into CANNOT_CHECK on all seven corpus histories. So the record field gets its
    own ADR, which is R-10's answer rather than a loosening of it.

    **WHAT LANDED IS THE HONEST HALF, AND THIS IS THE TEST OF IT.** R-6 requires each rule to name
    what it cannot see, so the route is named in the rule's own `blind` text and ADR-0018 no
    longer presents the watch's `except` arm as the only way to reach that state. **The MET is
    asserted here on purpose**: a known limit that nothing records reads exactly like an
    oversight, and the next pass over this code would file it again.
    """
    project = tmp_path / "watchoff"
    project.mkdir()
    (project / "secret.tsv").write_text("data nobody declared\n", encoding="utf-8")
    runprov.configure(
        root=project,
        run_log=project / "h.jsonl",
        auto_steps="off",
        warn_unregistered_reads=False,
    )
    with runprov.Run("sneaky", {}, provenance=project / "p.json"):
        with open(project / "secret.tsv", encoding="utf-8") as fh:
            fh.read()
    record = [
        json.loads(line)
        for line in (project / "h.jsonl").read_text(encoding="utf-8").splitlines()
        if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
    ][-1]

    #: THE STATE, ASSERTED RATHER THAN DESCRIBED. The `observation` block is what makes this rule
    #: evaluable at all, so a record that kept it and still says nothing about the watch is
    #: exactly the shape the rule cannot tell from a clean run.
    assert record.get("observation") is not None, (
        f"the premise: the run still records a full observation block, which is what makes the "
        f"rule think it can answer: {record.get('observation')}"
    )
    assert "unregistered_reads" not in record, (
        f"and nothing of the read reached the record, because the watch was never attached: "
        f"{record.get('unregistered_reads')}"
    )
    assert not record["observation"].get("unregistered_watch_truncated"), record["observation"]

    got = runprov.policy.rules()["no_unregistered_reads"].judge(record, runprov.policy.Context())
    #: AND THE VERDICT IS MET, WHICH IS WRONG AND IS LEFT WRONG ON PURPOSE [K-18]. Asserted so
    #: that the day the record can say whether the watch ran, this line fails and sends whoever
    #: changes it to the paragraph in ADR-0018 that explains why it was waiting.
    assert got.outcome == runprov.policy.MET, (
        f"[K-18] this is the KNOWN limit, recorded rather than hidden: if this rule has started "
        f"answering {got.outcome} here, the record has gained a field saying whether the watch "
        f"ran, and ADR-0018's R-10 amendment is the thing to update next: {got}"
    )

    #: SO R-6 IS WHAT MUST HOLD: the rule's own text names the route. A limit the rule does not
    #: state is a limit a reader of the gate's page never learns.
    blind = runprov.policy.rules()["no_unregistered_reads"].blind
    assert "warn_unregistered_reads=False" in blind, (
        f"[ADR-0018 R-6] a rule that cannot see a state reached by a DOCUMENTED setting must say "
        f"so in its own words — this is the sentence the gate prints under `cannot see`: {blind}"
    )
    assert "PROJECT-level" in blind, (
        f"[ADR-0018 R-6] and that it is project-level, which is what makes one step's exemption "
        f"silence the watch for every run in the history: {blind}"
    )

    #: AND THE ADR NO LONGER PRESENTS THE `except` ARM AS THE ONLY ROUTE. Its paragraph justified
    #: accepting this blind spot on the grounds that the only way in is a branch *"defensive and
    #: believed unreachable"* — which made a supported configuration look impossible. The ADR is
    #: the specification, so the correction belongs there and not only in the code.
    adr = (
        _repo_root()
        / "docs"
        / "adr"
        / "0018-a-policy-is-checked-against-the-history-not-remembered.md"
    ).read_text(encoding="utf-8")
    assert "warn_unregistered_reads=False" in adr, (
        "[ADR-0018 R-6] [ADR-0018 R-10] ADR-0018 states that the watch's `except` arm is the only "
        "route to both fields being unset, and a documented setting reaches the same state. The "
        "paragraph is defective by OMISSION and the omission is the ordinary route"
    )
    #: AND THE README'S THIRD COLUMN IS UNTOUCHED BY THIS, which is why the `blind` text was
    #: APPENDED to rather than rewritten: the README's cell is checked with `startswith`, so the
    #: cheap half of this row really is two edits and costs no third.
    assert blind.startswith("a run whose record carries no `observation` block at all"), blind


def test_environment_captured_reads_the_snapshot_the_record_names_and_opens_no_file(
    tmp_path, monkeypatch
):
    """[ADR-0018 R-3] [ADR-0018 R-7] [ADR-0018 R-9] [ADR-0018 R-10] Audit K, K-19 in its narrow
    form. A `snapshot` mark is not a snapshot.

    **THE DEFECT.** `_observed_packages` returns `"snapshot"` on the mere PRESENCE of the key, and
    a capture that raised stores `{"error": str(exc)}` under it. So a run that printed *WARNING:
    could not write environment snapshot* and recorded no package at all answered **MET**, over
    `packages: {}` — which this rule's own `blind` text calls indistinguishable from nobody having
    asked. An unwritable snapshot directory in CI turns the environment control into a no-op for
    every run after it, which on an accreditation audit is the one control an assessor cares about
    most: *name the software this result was produced with.* Reproduced live with `chmod 500`.

    **THE WIDER FORM OF THIS ROW IS WITHDRAWN, refuted twice and independently.** It claimed the
    rule is MET over the records of every released wheel *"on a document the gate never
    examined"*. Those records carry `environment_snapshot: {path, sha256, n_packages: 2, …}`: the
    count AND the digest are attested in the record, so those runs did record what they ran with
    and MET is correct for them.

    **CORRECTED [L-11]: the withdrawal said *all seven* and it is SIX.** 0.1.0 answers
    CANNOT_CHECK through the no-`observation` arm, correctly: it predates ADR-0010 and never
    reaches the snapshot arms. Measured `0.1.0: CANNOT_CHECK`, `0.2.0 … 0.7.0: MET`. The claim
    moves and the reason does not — `n_packages: 2` is exactly why the other six are stable.

    The row also forbade and prescribed the same read — it cited
    R-9 against opening the snapshot file, when R-9's clarification says *the source* means source
    code and explicitly not the filesystem.

    **AND THE REMEDY AS FILED COULD NEVER HAVE FIRED**, which is the half a skeptic caught: it
    sent an applier to `environment["snapshot"]`, and in a HISTORY record `environment` is `None`
    because the block is flattened to a top-level `environment_snapshot`. `environment.snapshot`
    exists only in the sidecar, which `gate` never opens. A rule reading it would have evaluated
    `None` on every record — a guard that is uninformed looking exactly like one that is
    satisfied, which is this project's own named defect.

    **SO NO FILE IS OPENED, AND THAT IS ASSERTED RATHER THAN CLAIMED**: the verdict is taken, the
    snapshot file is deleted, and the verdict is taken again.
    """
    met, unknown = runprov.policy.MET, runprov.policy.CANNOT_CHECK
    rule = runprov.policy.rules()["environment_captured"]

    def last(log: pathlib.Path):
        return [
            json.loads(line)
            for line in log.read_text(encoding="utf-8").splitlines()
            if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
        ][-1]

    #: 1. A SNAPSHOT THAT WORKED. The positive companion, and it comes first so the failure below
    #: is a comparison against a measured baseline rather than against an expectation.
    good = tmp_path / "good"
    (good / "env").mkdir(parents=True)
    runprov.configure(
        root=good, run_log=good / "h.jsonl", auto_steps="off", env_snapshot_dir=good / "env"
    )
    with runprov.Run("ok", {}, provenance=good / "p.json"):
        pass
    kept = last(good / "h.jsonl")
    assert kept["observation"]["packages_recorded"] == "snapshot", kept
    assert not kept.get("packages"), (
        f"the premise of the whole row: a snapshot run records `packages: {{}}`, which is "
        f"indistinguishable from nobody having asked: {kept.get('packages')}"
    )
    snapshot = kept.get("environment_snapshot") or {}
    assert snapshot.get("n_packages"), (
        f"and the premise of the FIX: the record attests the snapshot's package COUNT, so the "
        f"rule needs no file: {snapshot}"
    )
    assert rule.judge(kept, runprov.policy.Context()).outcome == met, (
        "a run whose snapshot names its packages recorded what it ran with"
    )
    #: AND `environment` ITSELF IS `None` HERE, which is the half of this row that was wrong as
    #: filed: the block is flattened, so the field the remedy named reads `None` on every record.
    assert kept.get("environment") is None, (
        f"[K-19] the remedy as filed read `environment['snapshot']`, which a history record does "
        f"not carry: {kept.get('environment')}"
    )

    #: 2. NO FILE IS OPENED. The snapshot the record names is deleted and the verdict is taken
    #: again — R-9's boundary, asserted rather than asserted-about.
    named = good / snapshot["path"] if not pathlib.Path(snapshot["path"]).is_absolute() else None
    written = sorted((good / "env").glob("*"))
    assert written, f"the premise: a snapshot file really was written: {snapshot}"
    for path in written:
        path.unlink()
    assert rule.judge(kept, runprov.policy.Context()).outcome == met, (
        f"[ADR-0018 R-9] the verdict moved when a file was removed, so this rule is reading the "
        f"snapshot rather than the record that attests it ({named})"
    )

    #: 3. A SNAPSHOT WHOSE WRITE FAILED. Reproduced live with `chmod 500` on the snapshot
    #: directory; here the failure is injected at the one call `run.py` guards, so the record is
    #: still written by this package — `{"error": str(exc)}` is `run.py`'s own except arm — and
    #: the test needs no permission bit a Windows runner cannot provide.
    def refuse(directory):
        raise OSError(13, "Permission denied")

    monkeypatch.setattr(runprov.run, "write_snapshot", refuse)
    bad = tmp_path / "bad"
    (bad / "env").mkdir(parents=True)
    runprov.configure(
        root=bad, run_log=bad / "h.jsonl", auto_steps="off", env_snapshot_dir=bad / "env"
    )
    with runprov.Run("raised", {}, provenance=bad / "p.json"):
        pass
    failed = last(bad / "h.jsonl")
    assert failed["observation"]["packages_recorded"] == "snapshot", (
        f"the premise, and the whole defect: a capture that RAISED is marked exactly as one that "
        f"worked, because the mark comes from the key's presence: {failed['observation']}"
    )
    assert failed["environment_snapshot"].get("error"), (
        f"and the record says so, in a field the gate can read: {failed['environment_snapshot']}"
    )
    assert not failed.get("packages"), failed.get("packages")

    got = rule.judge(failed, runprov.policy.Context())
    assert got.outcome == unknown, (
        f"[K-19] a run that printed *could not write environment snapshot* and recorded no "
        f"package answered {got.outcome} over `packages: {{}}`: {got}"
    )
    assert "could not be written" in (got.reason or ""), got.reason
    assert "Permission denied" in (got.reason or ""), (
        f"[ADR-0018 R-3] and it names the error, or a reader cannot tell this from a bug: "
        f"{got.reason}"
    )


def test_inputs_verify_answers_for_each_declared_entry_and_names_which(tmp_path):
    """[ADR-0018 R-3] [ADR-0018 R-7] [ADR-0018 R-9] T-34. The rule that leaves the record, entry
    by entry.

    Every other rule reads fields. This one reads FILES, which is why R-9 had to be clarified
    before it existed — Taylor's ruling, 2026-10-02: *the source* means source code, not the
    filesystem, so re-hashing a declared input is in scope.

    THE INABILITIES ARE THE SUBSTANCE HERE, not the pass. A gate that reported *the evidence
    matches* for a directory it never walked, for a file it could not open, or for a path that no
    longer exists would be the vacuous green with a laboratory's name on it. Each of those states
    is built from a real path on disk and each must come back `CANNOT_CHECK` **saying which**, so
    a reader is sent to one file rather than to the whole history.
    """
    met, violated, unknown = (
        runprov.policy.MET,
        runprov.policy.VIOLATED,
        runprov.policy.CANNOT_CHECK,
    )
    data = tmp_path / "in.tsv"
    data.write_text("a\n", encoding="utf-8")
    folder = tmp_path / "tree"
    folder.mkdir()
    (folder / "r.fa").write_text(">x\n", encoding="utf-8")
    content = runprov.hashing.content_digest(data)
    raw = runprov.hashing.sha256(data)
    absent = "0" * 64

    #: THE DIRECTORY ENTRY AS THE WRITER REALLY EMITS IT, derived from `describe` and folded the
    #: way `Run.__exit__` folds it, rather than typed out here. **K-20 is the row this replaces
    #: two hand-built rows for:** they asserted `{"kind": "tree"}` and `{"sha256_tree": ...}`,
    #: and this package has never written either — the writer spells the kind `directory` and
    #: folds the tree digest into `sha256`. Both rows passed, the guard they were covering was
    #: dead for every real record, and the comment above them (*"older entries carry
    #: `sha256_tree` without a `kind`"*) was false of 0.1.0 onwards. Measured over all seven
    #: corpus versions: the only `kind` values in any history are `None` and `"directory"`.
    described = runprov.hashing.describe(folder)
    assert described["kind"] == "directory" and described.get("sha256_tree"), (
        f"the premise of this fixture: a directory describes as one, with a tree digest: "
        f"{described}"
    )
    as_recorded = {
        "path": str(folder),
        "sha256": described["sha256_tree"],
        "content_sha256": described.get("content_sha256"),
        "kind": described["kind"],
    }
    assert as_recorded["kind"] != "tree" and "sha256_tree" not in as_recorded, (
        f"and the premise of the ROW: neither thing the old guard tested for is in the entry a "
        f"record carries, which is why it never fired: {as_recorded}"
    )

    #: EACH ROW IS (entry, expected, a phrase the reason must contain). The phrase is asserted
    #: because `CANNOT_CHECK` with the wrong sentence is a finding a reader cannot act on, and
    #: four of these rows answer `CANNOT_CHECK` for four different reasons.
    cases: list[tuple[dict[str, object], str, str | None]] = [
        ({}, unknown, "carries no path"),
        ({"path": str(data)}, unknown, "no digest this rule can take again"),
        #: A DECLARED DIRECTORY IS NOT RE-WALKED, and this is the entry a real record carries.
        #: Exit 2 for a declared directory is INTENDED — Taylor's ruling on K-20, now in R-7's
        #: `CANNOT_CHECK` column — so what is asserted is the SENTENCE: a reader is sent to
        #: `runprov verify`, which re-walks the tree, and not to the OSError arm's *could not be
        #: read: Is a directory*, which reads as a permissions problem and sent them to nothing.
        (as_recorded, unknown, "`runprov verify` re-walks"),
        #: AND AN EXPLICIT `file` KIND IS NOT READ AS A DIRECTORY, which is the other side of
        #: `moved_since`'s test. The writer omits `kind` for the ordinary case; a record carrying
        #: it must not be diverted.
        ({"path": str(data), "kind": "file", "content_sha256": content}, met, None),
        #: `content_digest` RETURNS None FOR ANYTHING IT WILL NOT CANONICALISE, and a digest that
        #: could not be taken is not a disagreement. Inventing one would accuse a path nobody
        #: could hash.
        ({"path": str(folder), "content_sha256": absent}, unknown, "not a file whose"),
        #: AND THE SAME PATH ON THE OTHER KEY TAKES THE OTHER ROUTE: `hashing.sha256` raises on a
        #: directory rather than returning None, so the OSError arm is reached by a state this
        #: test can build on every platform instead of by a permission bit it cannot.
        ({"path": str(folder), "sha256": absent}, unknown, "could not be read"),
        (
            {"path": str(tmp_path / "gone.tsv"), "content_sha256": content},
            unknown,
            "no longer on disk",
        ),
        #: THE V1 SHAPE: an entry carrying only a raw `sha256` is compared with `hashing.sha256`.
        ({"path": str(data), "sha256": raw}, met, None),
        ({"path": str(data), "sha256": absent}, violated, "sha256"),
        ({"path": str(data), "content_sha256": content}, met, None),
        ({"path": str(data), "content_sha256": absent}, violated, "content_sha256"),
    ]
    #: WHAT THE TABLE MUST REACH [K-42]. The twelve rows asserted nothing about what the loop
    #: got to, so a row could be deleted invisibly — PROVED in two stages: neutralising the whole
    #: table left the test passing with only coverage objecting, over 5 lines of 296; then
    #: deleting ONE semantically distinct row left **100% statement and branch coverage and a
    #: green suite**. Its sibling twelve lines up the same file had the remedy
    #: (`outcomes == {met, violated, unknown}`) and this test had none.
    #:
    #: DECLARED HERE AND NOT DERIVED FROM `cases`, because a property computed from the table
    #: cannot notice a row leaving it. A row that answers an inability is identified by its
    #: sentence; a row that answers MET has no sentence, so it is identified by the KEYS it
    #: carried — which is what a MET row is for, since the whole question is which digest key
    #: the entry offers and therefore which one is compared.
    must_reach = {
        (unknown, "carries no path"),
        (unknown, "no digest this rule can take again"),
        (unknown, "`runprov verify` re-walks"),
        (unknown, "not a file whose"),
        (unknown, "could not be read"),
        (unknown, "no longer on disk"),
        (violated, "sha256"),
        (violated, "content_sha256"),
        (met, ("content_sha256", "kind", "path")),
        (met, ("path", "sha256")),
        (met, ("content_sha256", "path")),
    }
    reached = set()
    for entry, expected, phrase in cases:
        got = runprov.policy.rules()["inputs_verify"].judge(
            {"inputs": [entry]}, runprov.policy.Context()
        )
        assert got.outcome == expected, f"{entry} answered {got.outcome} ({got.reason})"
        if phrase is not None:
            assert phrase in (got.reason or ""), (
                f"{entry} answered {expected} with a sentence that does not say why: {got.reason}"
            )
            assert str(entry.get("path", "")) in (got.reason or "") or not entry.get("path"), (
                f"and the sentence must name the file a reader has to go and look at: {got.reason}"
            )
        else:
            assert got.reason is None, f"a MET verdict explains nothing: {got.reason}"
        reached.add((expected, phrase) if phrase else (expected, tuple(sorted(entry))))

    assert reached == must_reach, (
        "[K-42] this table asserted nothing about what the loop reached, so a row could be "
        "deleted with the suite green at 100% coverage. Every row above answers for a state the "
        "rule has to distinguish; if one is gone, the state is unasserted:\n"
        f"  declared and not reached: {sorted(map(str, must_reach - reached))}\n"
        f"  reached and not declared: {sorted(map(str, reached - must_reach))}"
    )
    assert {outcome for outcome, _ in reached} == {met, violated, unknown}, (
        f"[ADR-0018 R-3] all three answers must be exercised here: {sorted(reached)}"
    )

    #: I-02, LIFTED OUT OF THE TABLE AND GIVEN ITS PREMISE [K-42]. It was one row of twelve, and
    #: **deleting that one row left 1 192 passed, 0 failed and `policy.py` at 296/124, 100%
    #: statement AND branch** — measured, which is the whole row. It is the only assertion that
    #: an entry carrying BOTH digests is compared on `content_sha256` ALONE, and the premise is
    #: what makes it a test rather than a leniency: the raw digest in this entry is DELIBERATELY
    #: WRONG, so a rule that consulted it at all would answer VIOLATED here. Equal content
    #: digests mean identical content by this package's own definition, and a file whose line
    #: endings were rewritten is exactly the case the two digests are designed to disagree about
    #: — so if that leniency regressed, such a file would be reported VIOLATED: a false
    #: accusation with nothing red.
    both = {"path": str(data), "content_sha256": content, "sha256": absent}
    assert runprov.hashing.sha256(data) != absent, (
        "the premise: the raw digest this entry carries is NOT the file's, so a rule that "
        "consulted it would be visible rather than merely redundant"
    )
    chosen = runprov.policy._comparable_on(both)
    assert chosen is not None and chosen[:2] == ("content_sha256", content), (
        f"[I-02] an entry carrying both digests is comparable on `content_sha256` and the raw "
        f"one is not consulted: {chosen}"
    )
    i02 = runprov.policy.rules()["inputs_verify"].judge(
        {"inputs": [both]}, runprov.policy.Context()
    )
    assert (i02.outcome, i02.reason) == (met, None), (
        f"[I-02] like for like, and only one key: the content digest matches, so this is MET and "
        f"the wrong raw digest beside it is not a finding: {i02}"
    )

    #: SEVERAL ENTRIES, ONE VERDICT, AND THE COUNT TRAVELS. Nothing is short-circuited on the
    #: first mismatch: a laboratory asks WHICH files no longer match, and a gate naming one and
    #: stopping sends the reader back for a second run to find the next.
    second = tmp_path / "also.tsv"
    second.write_text("b\n", encoding="utf-8")
    both_changed = runprov.policy.rules()["inputs_verify"].judge(
        {
            "inputs": [
                {"path": str(data), "content_sha256": absent},
                {"path": str(second), "content_sha256": absent},
            ]
        },
        runprov.policy.Context(),
    )
    assert both_changed.outcome == violated and "and 1 more" in (both_changed.reason or ""), (
        both_changed
    )

    #: AND A VIOLATION OUTRANKS AN INABILITY WITHIN ONE RUN, as it does across runs in `assess`.
    #: L-81's ordering, one level further down: a changed file is a finding whatever else could
    #: not be examined beside it.
    mixed = runprov.policy.rules()["inputs_verify"].judge(
        {
            "inputs": [
                {"path": str(tmp_path / "gone.tsv"), "content_sha256": content},
                {"path": str(data), "content_sha256": absent},
            ]
        },
        runprov.policy.Context(),
    )
    assert mixed.outcome == violated, (
        f"a changed file is a finding beside an unexaminable one: {mixed}"
    )


def test_inputs_verify_anchors_a_recorded_path_on_the_runs_own_cwd_and_not_the_gates(
    tmp_path, monkeypatch
):
    """[ADR-0018 R-7] [ADR-0018 R-9] Audit K, K-17 and K-20. The answer may not depend on where
    the gate was invoked from.

    **THIS IS THE TEST AND THE CODE CHANGE ASSERTS NOTHING**, which was measured rather than
    assumed: K-17's and K-20's repairs both leave the full suite at rc=0 when injected, so the
    deliverable for each is this file.

    **THE PREMISE THE RULE WAS BUILT ON WAS FALSE.** Its docstring read *the recorded `path` is
    ABSOLUTE, so there is nothing to resolve it against*, and `run.input(p)` records
    `hashing._posix(p)` verbatim — so a relative registration is recorded relative, which is what
    this project's own corpus generator writes and therefore what every released wheel's history
    carries. Resolved against the GATE PROCESS'S working directory, one record answered three
    different ways over files nothing had touched:

    * from the tree it describes:        `2 met, 0 violated, 1 not checked`, exit 2
    * from one directory up:             `0 met, 0 violated, 3 not checked`, exit 2, three
      sentences reading *is no longer on disk* about files that are right there
    * from a project with same-named files: `0 met, 3 violated`, **exit 1 — a false accusation
      naming three files the gate never opened**

    So the anchor is the record's own `cwd`, taken exactly as `hashing.moved_since` takes it, and
    the digest cache is keyed on the RESOLVED path — without which two runs in two projects that
    each declared `data/m.tsv` collide inside one `assess` and the second is reported VIOLATED
    with nothing on disk touched (measured: `1 met, 1 violated`, exit 1).

    **AND K-20 RIDES WITH IT, because K-17's fix alone makes K-20's wrong sentence reachable from
    EVERY working directory** rather than only from the tree itself: before, a gate run from one
    directory up left the declared directory via *is no longer on disk*; resolved correctly it
    reaches the real directory and must say which tool re-walks a tree.

    EVERY RECORD HERE IS WRITTEN BY THIS PACKAGE, not built as a dict. The whole of both rows is
    that two hand-built fixtures asserted shapes no history contains.
    """
    met, unknown = runprov.policy.MET, runprov.policy.CANNOT_CHECK

    def project(name: str, payload: str) -> tuple[pathlib.Path, dict]:
        """One real project: a relative file input, a declared directory, and a real record."""
        root = tmp_path / name
        (root / "data" / "refs").mkdir(parents=True)
        (root / "data" / "m.tsv").write_text(payload, encoding="utf-8")
        (root / "data" / "refs" / "r.fa").write_text(f">{name}\n", encoding="utf-8")
        monkeypatch.chdir(root)
        runprov.configure(root=".", run_log="prov/history.jsonl", auto_steps="off")
        with runprov.Run(name, {}, provenance="prov/p.json") as run:
            #: REGISTERED RELATIVE, which is the spelling `tools/corpus_scenario.py` uses and
            #: therefore the one in all seven committed histories.
            run.input("data/m.tsv")
            run.input("data/refs")
        written = [
            json.loads(line)
            for line in (root / "prov" / "history.jsonl").read_text(encoding="utf-8").splitlines()
            if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
        ]
        assert len(written) == 1, written
        return root, written[0]

    a_root, a = project("projA", "project A's own reference data\n")
    b_root, b = project("projB", "a DIFFERENT project's data under the same name\n")

    #: THE FIXTURE'S OWN STATE, ASSERTED. A fixture whose premise is unchecked can stop reaching
    #: the state it exists for in silence — and in this pair of rows that is not hypothetical:
    #: both of K-20's deleted rows were fixtures asserting a shape the writer never emits.
    entries = {entry["path"]: entry for entry in a["inputs"]}
    assert sorted(entries) == ["data/m.tsv", "data/refs"], (
        f"the premise of K-17: the recorded paths are RELATIVE, verbatim as registered: {entries}"
    )
    #: `str()`, NOT `_posix()` [L-27]. This premise was written while `cwd` was `_posix`-spelled;
    #: that spelling was reverted because `Run._anchor` compares the field with
    #: `str(pathlib.Path.cwd())` as a string, and `_posix` broke 15 tests on the Windows leg. Ask
    #: the same function the writer asks — which is the rule that made this assertion wrong twice,
    #: once in each direction.
    assert a["cwd"] == str(a_root) and b["cwd"] == str(b_root), (
        f"the premise of the fix: the record says which directory those paths are relative TO, "
        f"so no `--root` flag is needed: {a['cwd']} / {b['cwd']}"
    )
    assert entries["data/refs"]["kind"] == "directory", (
        f"the premise of K-20: the writer spells a directory's kind `directory`: {entries}"
    )
    assert "sha256_tree" not in entries["data/refs"] and entries["data/refs"]["sha256"], (
        f"and folds its tree digest into `sha256` — so the old guard's `kind == 'tree' or "
        f"sha256_tree` tested for two things no record carries: {entries['data/refs']}"
    )
    assert (
        a["inputs"][0]["path"] == b["inputs"][0]["path"]
        and entries["data/m.tsv"]["content_sha256"]
        != {e["path"]: e for e in b["inputs"]}["data/m.tsv"]["content_sha256"]
    ), "the premise of the cache half: one spelling, two projects, two different files"

    rule = runprov.policy.rules()["inputs_verify"]
    file_only = {**a, "inputs": [entries["data/m.tsv"]]}

    #: THE THREE WORKING DIRECTORIES OF THE REPRODUCTION, and the answer may not move between
    #: them. `b_root` is the cruel one: it holds a `data/m.tsv` that is a real file with different
    #: bytes, so the unanchored rule does not merely fail to find the file — it finds the WRONG
    #: one and reports a violation of a control that was met.
    for where in (a_root, tmp_path, b_root):
        monkeypatch.chdir(where)
        got = rule.judge(file_only, runprov.policy.Context(digests={}))
        assert got.outcome == met, (
            f"[K-17] the gate was invoked from {where.name} and answered {got.outcome} about a "
            f"file nothing had touched: {got.reason}"
        )

        #: AND THE WHOLE RECORD, directory included: `2 met, 1 not checked` from everywhere,
        #: which is what the corpus measures from inside its own tree today.
        whole = rule.judge(a, runprov.policy.Context(digests={}))
        assert whole.outcome == unknown, f"from {where.name}: {whole}"
        assert "data/refs" in (whole.reason or ""), (
            f"[ADR-0018 R-7] the sentence must name the path a reader goes and looks at: {whole}"
        )
        assert "`runprov verify` re-walks" in (whole.reason or ""), (
            f"[K-20] from {where.name} a declared directory must say which tool re-walks a tree. "
            f"Exit 2 here is intended (Taylor, 2026-10-03) and R-7's column says so; the sentence "
            f"is what the dead guard cost: {whole.reason}"
        )
        for wrong in ("could not be read", "no longer on disk", "data/m.tsv"):
            assert wrong not in (whole.reason or ""), (
                f"[K-17] [K-20] from {where.name} the reason says {wrong!r}, which sends the "
                f"reader to a problem that is not there: {whole.reason}"
            )

    #: THE CACHE HALF, WHICH A READING OF THE FIX WOULD MISS. Two runs, two projects, one
    #: recorded spelling, ONE `assess` — so one cache. Keyed on the spelling, the second run is
    #: answered with the first one's bytes and the tally reads `1 met, 1 violated`.
    monkeypatch.chdir(a_root)
    tally = runprov.policy.assess(
        "inputs_verify",
        [file_only, {**b, "inputs": [{e["path"]: e for e in b["inputs"]}["data/m.tsv"]]}],
    )
    assert (tally["outcome"], tally["met"], tally["violated"], tally["not_checked"]) == (
        met,
        2,
        0,
        0,
    ), f"[K-17] two projects sharing one history, neither file touched: {tally}"

    #: AND THE KEY IS THE RESOLVED PATH, stated rather than inferred from the tally above.
    supplied = runprov.policy.Context(digests={})
    runprov.policy.assess("inputs_verify", [file_only], context=supplied)
    assert list(supplied.digests) == [((a_root / "data" / "m.tsv").as_posix(), "content_sha256")], (
        f"[K-17] the cache holds what was HASHED and not what was spelled: {supplied.digests}"
    )


def test_the_digest_cache_is_one_assess_wide_and_no_wider(tmp_path):
    """[ADR-0018 R-7] T-34. Why the cache lives in a `Context` and not in an `lru_cache`.

    N runs declaring one reference genome is N full reads of it without a cache — the cost
    `verify.check_input` memoises for, and it measured the shape there at 40,000 reads over 20
    files. So `assess` builds one cache and hands it to every verdict it forms.

    **AND THE SAME FACT IS WHAT MAKES IT DANGEROUS, WHICH IS WHAT THIS TEST IS FOR.** A cache
    outliving one `assess` would answer a later question with an earlier run's bytes — a gate
    reporting MET about a file that changed between two calls. So the staleness is demonstrated
    INSIDE one context deliberately, and then a fresh context is shown to catch what the held one
    missed. The cache is a saving within one answer and never a memory between two.
    """
    data = tmp_path / "ref.tsv"
    data.write_text("a\n", encoding="utf-8")
    record = {
        "inputs": [{"path": str(data), "content_sha256": runprov.hashing.content_digest(data)}]
    }
    rule = runprov.policy.rules()["inputs_verify"]

    held = runprov.policy.Context(digests={})
    assert rule.judge(record, held).outcome == runprov.policy.MET
    assert list(held.digests) == [(data.as_posix(), "content_sha256")], (
        "keyed by the RESOLVED path AND the key, because `sha256` and `content_sha256` are two "
        f"quantities taken from the same bytes and a cache that forgot which it held would "
        f"compare one with the "
        f"other: {held.digests}"
    )

    data.write_text("CHANGED\n", encoding="utf-8")
    assert rule.judge(record, held).outcome == runprov.policy.MET, (
        "the premise of the per-call scope, stated as a measurement rather than a worry: inside "
        "ONE context the cached digest is reused, which is the saving and the staleness in the "
        "same sentence"
    )
    assert rule.judge(record, runprov.policy.Context()).outcome == runprov.policy.VIOLATED, (
        "and a context that was not told anything earlier reads the file as it is now"
    )

    #: `assess` BUILDS ITS OWN PER CALL, so neither a stale one nor none at all reaches a rule.
    #: Two identical records here read the file ONCE and both answer about the same bytes.
    tally = runprov.policy.assess("inputs_verify", [record, record])
    assert (tally["outcome"], tally["evaluated"], tally["violated"]) == (
        runprov.policy.VIOLATED,
        2,
        2,
    ), tally
    assert len(tally["reasons"]) == 1, (
        f"one changed file named once, however many runs declared it: {tally['reasons']}"
    )

    #: AND A CALLER THAT SUPPLIES ONE GETS IT USED RATHER THAN REPLACED, which is what makes a
    #: `gate` over many rules able to read each file once instead of once per rule.
    supplied = runprov.policy.Context(digests={})
    runprov.policy.assess("inputs_verify", [record], context=supplied)
    assert list(supplied.digests) == [(data.as_posix(), "content_sha256")], supplied.digests


def test_a_policy_is_json_or_toml_and_the_two_load_to_the_same_thing(tmp_path):
    """[ADR-0018 R-11] T-34. One checked representation, two ways of writing it.

    R-11's table is the constraint and `dependencies = []` is the reason: JSON parses on every
    supported version with nothing installed, TOML needs `tomllib` (3.11+) or the `runprov[toml]`
    extra below it. **So both are accepted and neither is privileged** — and the thing worth
    asserting is not that each parses but that they AGREE, which is R-1's shape one level down.

    AND THE `why` SURVIVES INTO THE STRUCTURE, which is the whole of R-11's substance. A policy's
    rationale is a required field rather than a comment because a comment cannot be checked and
    does not travel: this is the assertion that it travels.
    """
    reason = "ISO 15189 5.5.1: the analysis must be traceable to a known code state"
    as_json = tmp_path / "policy.json"
    as_json.write_text(
        json.dumps({"rules": [{"rule": "clean_tree", "why": reason}]}), encoding="utf-8"
    )
    as_toml = tmp_path / "policy.toml"
    as_toml.write_text(
        f'[[rules]]\nrule = " clean_tree "\nwhy = """{reason}"""\n', encoding="utf-8"
    )

    loaded = runprov.policy.load(as_json)
    assert loaded == {"rules": [{"rule": "clean_tree", "why": reason}]}, loaded
    assert runprov.policy.load(as_toml) == loaded, (
        "[ADR-0018 R-11] the same policy written in the two accepted formats must load to the "
        "same checked structure, or the format decides what the gate does"
    )

    # AND THE AUTHOR'S ORDER IS KEPT, because a policy read back in another order is a document
    # whose diff stops being the evidence that it did not quietly loosen.
    ordered = tmp_path / "ordered.json"
    names = ["finished_ok", "clean_tree", "commit_recorded"]
    ordered.write_text(
        json.dumps({"rules": [{"rule": name, "why": reason} for name in names]}), encoding="utf-8"
    )
    assert [row["rule"] for row in runprov.policy.load(ordered)["rules"]] == names


def test_a_policy_that_cannot_be_used_names_the_file_and_the_fix(tmp_path):
    """[ADR-0018 R-11] [ADR-0018 R-5] T-34. Every refusal is actionable, and none is a traceback.

    *Invalid policy* is not a finding a laboratory can act on. A policy is the document an
    assessor reads the controls out of, so each refusal below names the file, the rule number
    where one applies, and what to change.

    **READ STRICTLY, AND THAT IS THE SUBSTANCE RATHER THAN PEDANTRY.** A key this version does not
    understand is refused instead of ignored: a rule under a mistyped table name is a control its
    author believes is in force and the gate never applies. A control lost to a typo is the exact
    failure this feature exists to prevent, and letting one in through the parser would be a
    bitter way to produce it.
    """
    cases: list[tuple[str, str, str]] = [
        ("broken.json", "{not json", "not valid JSON"),
        ("broken.toml", "[[rules]\nrule = 1", "not valid TOML"),
        ("policy.yaml", "rules: []", "neither a .json nor a .toml"),
        #: AND A NAME WITH NO SUFFIX AT ALL SAYS SO [K-05]. A reader who typed `policy` gets told
        #: what was read, which is this package's standard: a refusal names its own fix.
        #:
        #: **THE ROW'S OTHER HALF IS A CHECK THAT CANNOT FAIL AND IS DELIBERATELY NOT HERE.** It
        #: asked for an assertion that the offending SUFFIX appears in the message — and measured
        #: with the mutation applied (`{suffix or ...}` deleted), `".yaml" in message` is still
        #: **True**, because the interpolated `{path}` already carries the suffix and the loop
        #: below already asserts the path appears. `path.suffix` is a pure function of `path`, so
        #: the clause carries no information the message lacks. Only this half moves, and a
        #: verification that passes with the mutation re-applied proves nothing.
        ("policy", "rules: []", "the name carries no suffix"),
        ("top.json", "[]", "at the top level"),
        (
            "settings.json",
            '{"rules": [{"rule": "clean_tree", "why": "w"}], "strict": true}',
            "does not understand",
        ),
        ("empty.json", '{"rules": []}', "non-empty"),
        ("scalar.json", '{"rules": "clean_tree"}', "non-empty"),
        ("string.json", '{"rules": ["clean_tree"]}', "each rule is a table"),
        (
            "extra.json",
            '{"rules": [{"rule": "clean_tree", "why": "w", "when": "tuesday"}]}',
            "when",
        ),
        ("nameless.json", '{"rules": [{"why": "w"}]}', "does not name a rule"),
        (
            "twice.json",
            '{"rules": [{"rule": "clean_tree", "why": "a"}, {"rule": "clean_tree", "why": "b"}]}',
            "a second time",
        ),
        ("silent.json", '{"rules": [{"rule": "clean_tree", "why": "   "}]}', "carries no `why`"),
    ]
    for name, body, phrase in cases:
        written = tmp_path / name
        written.write_text(body, encoding="utf-8")
        with pytest.raises(runprov.policy.PolicyError) as raised:
            runprov.policy.load(written)
        assert phrase in str(raised.value), f"{name}: {raised.value}"
        assert str(written) in str(raised.value), (
            f"{name}: a refusal that does not name the file sends the reader to look for "
            f"it: {raised.value}"
        )

    # A FILE THAT IS NOT THERE, AND ONE THAT IS NOT TEXT. Both are refusals about the file rather
    # than about its contents, and both have to say which.
    #
    # AND THE OS'S OWN REASON TRAVELS [K-04]. Dropping `exc.strerror` from that refusal leaves
    # *could not be read* with no *No such file or directory* and no *Is a directory*, and this
    # assertion was a phrase match that the mutant satisfied. A user meets this on a mistyped
    # `--policy` on their first run, and a gate that will not start and will not say why is the
    # hardest kind of CI failure to act on.
    #
    # **`strerror` ITSELF IS NOT ASSERTED, AND THAT IS THE ROW'S CORRECTION:** the string is
    # host- and locale-supplied, and the change-verification bar forbids a test to assert on what
    # the host supplies. What is asserted is DERIVED — the prefix, a NON-EMPTY tail after it, and
    # that two different OS failures do not produce the SAME tail. The last clause is what kills
    # a constant put in `strerror`'s place, on every platform and in every language.
    tails = {}
    for label, candidate in (("absent", tmp_path / "absent.json"), ("a directory", tmp_path)):
        with pytest.raises(runprov.policy.PolicyError) as raised:
            runprov.policy.load(candidate)
        said = str(raised.value)
        opening = f"{candidate} could not be read: "
        assert said.startswith(opening), f"{label}: {said!r} does not open with {opening!r}"
        tails[label] = said[len(opening) :].strip()
        assert tails[label], (
            f"[K-04] {label}: the refusal says the file could not be read and not WHY. The OS "
            f"said something and it was dropped: {said!r}"
        )
    assert tails["absent"] != tails["a directory"], (
        f"[K-04] the tail must carry the OS's own reason rather than a constant in its place: "
        f"two different failures produced the same sentence: {tails}"
    )

    raw = tmp_path / "bytes.json"
    raw.write_bytes(b'{"rules": [{"rule": "clean_tree", "why": "\xff\xfe"}]}')
    with pytest.raises(runprov.policy.PolicyError, match="not UTF-8"):
        runprov.policy.load(raw)

    #: AN UNKNOWN RULE IS REPORTED WITH THE NAMES THAT EXIST, DERIVED FROM THE REGISTRY [R-5].
    #: *Unknown rule* on its own sends a reader to the source of a package they installed — and a
    #: hand-typed list of names in this message would be the second copy R-5 forbids.
    mistyped = tmp_path / "mistyped.json"
    mistyped.write_text('{"rules": [{"rule": "clean_trees", "why": "w"}]}', encoding="utf-8")
    with pytest.raises(runprov.policy.PolicyError) as raised:
        runprov.policy.load(mistyped)
    for registered in runprov.policy.rules():
        assert registered in str(raised.value), (
            f"the refusal must name every rule that does exist, and omits {registered}: "
            f"{raised.value}"
        )


def test_a_toml_policy_with_no_parser_names_the_extra_that_supplies_one(tmp_path, monkeypatch):
    """[ADR-0018 R-11] [ADR-0018 R-12] T-34. The 3.10 arm, exercised on this interpreter.

    `tomllib` arrives in 3.11, so on 3.10 a `.toml` policy needs the `runprov[toml]` extra —
    **and `tomli` is an extra and not a dependency, because `dependencies = []` is a property the
    README states.** A `.toml` policy on 3.10 without it is a usage error that names its own fix,
    which is this package's rule everywhere: say what could not be done rather than quietly do
    less of it.

    **THE LOADER IS REPLACED RATHER THAN THE INTERPRETER**, which is why this is a test and not a
    matrix leg. `_toml_parser` goes through `importlib.import_module` precisely so all three arms
    are reachable on one version; a guarded `import` would leave the arm that matters to a 3.10
    user as the one branch only CI could enter, and a branch only CI can enter is a branch whose
    failure nobody reads.
    """
    written = tmp_path / "policy.toml"
    written.write_text('[[rules]]\nrule = "clean_tree"\nwhy = "w"\n', encoding="utf-8")
    real = importlib.import_module

    def nothing_installed(name: str, *args: object, **kwargs: object) -> types.ModuleType:
        if name in ("tomllib", "tomli"):
            raise ModuleNotFoundError(f"No module named {name!r}", name=name)
        return real(name, *args, **kwargs)

    monkeypatch.setattr(importlib, "import_module", nothing_installed)
    with pytest.raises(runprov.policy.PolicyError) as raised:
        runprov.policy.load(written)
    assert "runprov[toml]" in str(raised.value), (
        f"a refusal a user cannot act on is a traceback with better manners: {raised.value}"
    )
    assert ".json" in str(raised.value), (
        "and the other half of the fix is the format that needs nothing installed at all: "
        f"{raised.value}"
    )

    #: AND THE FALLBACK IS WIRED — the 3.10-with-the-extra arm. The stub is a module named
    #: `tomli` carrying the two names this parser uses, and it answers with a policy no file here
    #: contains, so what comes back is proof that the module FOUND was the module USED. A real
    #: parser under the other name would have made this a test of TOML instead, and would have
    #: been unavailable on the one version where the arm matters.
    stub = types.ModuleType("tomli")
    stub.TOMLDecodeError = ValueError
    stub.loads = lambda text: {"rules": [{"rule": "finished_ok", "why": "from the fallback"}]}

    def only_tomli(name: str, *args: object, **kwargs: object) -> types.ModuleType:
        if name == "tomllib":
            raise ModuleNotFoundError("No module named 'tomllib'", name="tomllib")
        if name == "tomli":
            return stub
        return real(name, *args, **kwargs)

    monkeypatch.setattr(importlib, "import_module", only_tomli)
    assert runprov.policy.load(written) == {
        "rules": [{"rule": "finished_ok", "why": "from the fallback"}]
    }, "the parser that was found is the parser that was used"

    #: AND A SYNTAX ERROR FROM THE FALLBACK IS STILL A POLICY ERROR, not a traceback from a module
    #: the user did not know was involved. `TOMLDecodeError` is read off the module that was
    #: found, so the `except` clause names whichever parser is in use.
    stub.loads = lambda text: (_ for _ in ()).throw(stub.TOMLDecodeError("line 1"))
    with pytest.raises(runprov.policy.PolicyError, match="not valid TOML"):
        runprov.policy.load(written)

    #: AND WITH BOTH IMPORTABLE, `tomllib` WINS [K-06]. Reversing `("tomllib", "tomli")` passes
    #: every arm above, because none of them constructs the state where both can be imported —
    #: and on this interpreter `tomli` is absent, so that mutation is IDENTICAL rather than merely
    #: equivalent. The state is ordinary in the wild: `tomli` is a widespread transitive
    #: dependency, and `pytest` itself declares `tomli>=1; python_version < "3.11"` and cannot
    #: start without it there.
    #:
    #: THE CONTRACT IS IN `_toml_parser`'s DOCSTRING AND A DOCSTRING IS NOT A CONTRACT UNTIL
    #: SOMETHING CHECKS IT: on 3.11+ `tomllib` is the standard library and `tomli` is the same
    #: parser under its original name, so *preferring the installed extra would let the version a
    #: user happens to have decide how their policy is parsed*. Behaviourally equivalent while the
    #: two agree — which is the point, because the guard is against the day they do not.
    #:
    #: **BOTH NAMES ARE STUBBED, AND THAT IS DELIBERATE.** Stubbing only `tomli` and letting
    #: `tomllib` import for real would fail on the 3.10 matrix leg, where there is no `tomllib`
    #: at all — a guard only part of the matrix can enter, which is exactly what `_toml_parser`'s
    #: own docstring argues against. The two stubs answer with DIFFERENT policies, so what comes
    #: back names which module was chosen rather than merely that one was.
    from_stdlib = types.ModuleType("tomllib")
    from_stdlib.TOMLDecodeError = ValueError  # type: ignore[attr-defined]
    from_stdlib.loads = lambda text: {  # type: ignore[attr-defined]
        "rules": [{"rule": "clean_tree", "why": "from tomllib"}]
    }
    stub.loads = lambda text: {"rules": [{"rule": "finished_ok", "why": "from tomli"}]}

    def both_installed(name: str, *args: object, **kwargs: object) -> types.ModuleType:
        if name == "tomllib":
            return from_stdlib
        if name == "tomli":
            return stub
        return real(name, *args, **kwargs)

    monkeypatch.setattr(importlib, "import_module", both_installed)
    assert runprov.policy.load(written) == {
        "rules": [{"rule": "clean_tree", "why": "from tomllib"}]
    }, (
        "[K-06] with both parsers importable the STANDARD LIBRARY must be the one used, on every "
        "supported version — otherwise which parser reads a policy depends on what the user "
        "happens to have installed"
    )


def test_the_toml_extra_is_an_extra_and_the_recommendation_says_why():
    """[ADR-0018 R-11] [ADR-0018 R-12] T-34. `dependencies = []` is a promise, not a default.

    The README's first bullet says zero runtime dependencies, and R-11 chose the policy formats
    around it: JSON parses with nothing installed on every supported version. TOML needs a parser,
    so the parser is an EXTRA carrying a marker that keeps it off the versions that ship one.
    **Asserted in the file that decides it**, because a resolver reads `pyproject.toml` and does
    not read an ADR.

    AND R-12's RECOMMENDATION IS CHECKED WITH ITS REASON. *Use 3.12* without *because
    `sys.monitoring` arrives there and the record is thinner below it* is a preference, and a
    preference in a README is the first thing a reader discounts. The floor stays at 3.10:
    dropping a version is its own decision with its own cost and must not be made to win a
    config-format argument.
    """
    pyproject = (_repo_root() / "pyproject.toml").read_text(encoding="utf-8")
    assert re.search(r"^dependencies = \[\]\s*$", pyproject, re.M), (
        "[ADR-0018 R-11] the TOML parser must not have become a runtime dependency; the whole "
        "reason JSON is accepted at all is that it needs nothing installed"
    )
    extra = re.search(r"^toml = \[(.*?)\]\s*$", pyproject, re.M)
    assert extra, "pyproject declares no `toml` extra, so a .toml policy on 3.10 has no fix to name"
    assert "tomli" in extra.group(1), extra.group(1)
    assert "python_version < '3.11'" in extra.group(1), (
        "without the marker the extra installs a duplicate of the standard library on every "
        f"version that already has `tomllib`: {extra.group(1)}"
    )
    #: IN BOTH READMES, DERIVED FROM THE ONE PyPI FREEZES. `README-pypi.md` is the page most
    #: people read first and the only one that cannot be edited after upload, so a recommendation
    #: that lived in the long form alone would be absent exactly where it is read — and
    #: `test_the_two_readmes_open_with_the_same_words` compares the shared opening verbatim, which
    #: is how this was caught rather than noticed.
    name, _ = _pypi_description()
    for readme in ("README.md", name):
        text = (_repo_root() / readme).read_text(encoding="utf-8")
        assert "3.12 or later is recommended" in text, (
            f"[ADR-0018 R-12] {readme} does not carry the recommendation; it must be written "
            "where a user reads it rather than implied by a matrix"
        )
        recommendation = text[text.index("3.12 or later is recommended") :][:400]
        assert "sys.monitoring" in recommendation and "PEP 669" in recommendation, (
            f"[ADR-0018 R-12] and {readme} must carry its reason: a bare version preference is "
            f"the first thing a reader discounts: {recommendation[:200]}"
        )
    assert re.search(r'^requires-python = ">=3\.10"', pyproject, re.M), (
        "[ADR-0018 R-12] the floor stays at 3.10 — the recommendation is a recommendation, and "
        "dropping a version is its own decision with its own cost"
    )


def test_the_rule_set_is_the_registry_and_the_adr_table_agrees_with_it(tmp_path):
    """[ADR-0018 R-5] [ADR-0018 R-7] T-34. The registry is the source; this holds R-7 to it.

    R-5: the rule set is derived from a registry rules register into, **never a hand-typed list in
    the parser, the docs and the tests.** This compares R-7's table with the registry rather than
    carrying a third list of its own.

    **THERE ARE THREE CHECKED STATEMENTS OF THE RULE SET, NOT TWO, AND THIS TEST USED TO SAY TWO
    IN ITS OWN NAME [K-34].** The registry, R-7's table (here) and the README's table, which has
    its own guard — `--help` is a fourth copy and is DERIVED, so it cannot disagree. The name
    said *and nothing else*, the docstring said *exactly two statements*, and the CHANGELOG entry
    said it a third time while naming the README's checked table in the next clause. The count
    was the claim a reviewer would treat as authoritative, so it is corrected in all three places
    — and the CHANGELOG's own hand-typed list of the seven rule names is now labelled as prose
    the registry overrides, because nothing reads it and K-28 is the proof that the unchecked copy
    is the one that rots: the same entry was already one key stale.

    **THE SUBSET DIRECTION IS THE ONE THAT HOLDS TODAY**, and that is deliberate: a rule must not
    exist that the specification never asked for, while rules the specification asks for may still
    be unbuilt. **All seven are now built, so the two sets are equal today — and the assertion
    stays a subset**, because equality is owed to `Accepted` and the ADR is not: R-1, R-2, R-8,
    R-11 and R-12 have no code. A guard tightened to equality the day the last rule registered
    would be measuring the rule set to decide a question about the whole feature.

    **AND EQUALITY IS REQUIRED THE MOMENT THE ADR SAYS `Accepted`** — which makes closing
    condition 1 enforceable instead of remembered. ADR-0017 was marked `Proposed` through the
    release that shipped it; the inverse mistake is flipping a status while requirements are
    unbuilt, and `Accepted` with two rules missing would be exactly that. The guard fails either
    way round, so the status cannot be moved early and cannot be forgotten late.
    """
    del tmp_path
    specified = set(_adr_0018_rules())
    assert len(specified) == 7, (
        f"R-7's table states the opening rule set; this read {len(specified)}: {sorted(specified)}"
    )
    registered = set(runprov.policy.rules())
    assert registered <= specified, (
        "[ADR-0018 R-5] a rule is registered that R-7 does not specify. Either the ADR needs "
        f"amending with its own row, or the rule is not the opening set's: "
        f"{sorted(registered - specified)}"
    )

    adr = (
        _repo_root()
        / "docs"
        / "adr"
        / "0018-a-policy-is-checked-against-the-history-not-remembered.md"
    ).read_text(encoding="utf-8")
    status = re.search(r"\*\*Status:\*\*\s*(\w+)", adr)
    assert status, "ADR-0018 declares no Status"
    if status.group(1).lower() == "accepted":
        assert registered == specified, (
            "[ADR-0018 R-5] ADR-0018 says `Accepted` while R-7's rule set is not built. That is "
            "T-33's defect inverted — a status moved ahead of the code instead of behind it — and "
            f"these rows have no registered rule: {sorted(specified - registered)}"
        )

    # AND EACH REGISTERED RULE AGREES WITH ITS ROW about the fields it reads, so the table cannot
    # document one thing while the code consults another.
    for name, row in _adr_0018_rules().items():
        if name not in registered:
            continue
        got = runprov.policy.rules()[name]
        declared = {field.strip(" `") for field in row["reads"].split(",")}
        assert declared == set(got.reads), (
            f"[ADR-0018 R-7] `{name}` reads {sorted(got.reads)} and its row says {sorted(declared)}"
        )
        assert row["asks"] == got.asks, (
            f"[ADR-0018 R-7] the ADR says `{name}` asks {row['asks']!r} and the rule says "
            f"{got.asks!r}"
        )
        #: AND THE `CANNOT_CHECK` COLUMN, BY THE EQUALITY THE README'S IS ALREADY HELD TO
        #: [L-14]. This column was the one cell of R-7 nothing read, and it had gone wrong on
        #: the arm that matters most: `no_unregistered_reads`'s named only *the watch hit its
        #: cap* and omitted **a run whose record carries no `observation` block at all** — the
        #: rule's FIRST arm, and the one that actually fires on the corpus oracle, where 0.1.0
        #: has no `observation` block at all. The README's table named it correctly, so two
        #: documents agreed and the ADR did not; K-18's repair amended the prose beside this
        #: table and left the row alone, in the same tranche that amended two other rules'
        #: columns.
        #:
        #: THE SAME FORM AS `test_the_readme_rule_table_is_the_registry_and_not_a_copy_of_it`,
        #: deliberately: `blind.split(" — ")[0]` by EQUALITY and never a prefix, because a
        #: prefix admits an empty cell, a one-character cell and another rule's opening words —
        #: four of the seven `blind` texts begin *"a run "*. And it was satisfiable for all
        #: seven before it was asserted: the README's cells already equalled the first clause
        #: exactly, which is what proved the ADR's seven could be set to the same strings.
        assert row["blind"] == got.blind.split(" — ")[0], (
            f"[ADR-0018 R-6] [L-14] R-7's `CANNOT_CHECK when` for `{name}` is not the FIRST "
            f"CLAUSE of the sentence the rule prints, so the specification and the gate document "
            f"different limits.\n  ADR:  {row['blind']}\n  rule: {got.blind.split(' — ')[0]}"
        )


def test_the_readme_names_every_field_of_the_gate_payload(tmp_path):
    """[ADR-0018 R-8] Audit L, L-13. The document a USER reads, held to the payload it describes.

    **THE OMISSION.** `runprov.gate.v1` gained `read_error` (K-23), `unfinished` (K-08) and a
    per-rule `blocked` list (K-10) during Audit K's repairs, and the README — the one document a
    user reads — named none of them. Its payload paragraph listed the per-rule counts and
    stopped. **And ADR-0018's whole justification for the gate greening on a lost run rests on
    that limit being written down**, in prose a person meets, which is this file and not the ADR.

    **THE ROW'S OTHER HALF IS REFUTED AND IS NOT REPAIRED HERE, which is worth more than the
    half that stands.** L-13 also said the README's exit-code paragraph *"teaches the opposite of
    the new contract"*, quoting *one unreadable line is enough to turn a MET gate into exit 2*.
    **Measured: a torn line still gives `CANNOT_CHECK`, exit 2, `unreadable: 1`.** That sentence
    is TRUE and editing it would have introduced the error the row alleged: the row conflated an
    UNREADABLE LINE with an UNFINISHED RUN, and only the second greens. So one sentence was ADDED
    for the unfinished case and none was changed.

    **DERIVED FROM THE PAYLOAD, not a list typed here**, which is what stops the next field
    repeating this: the gate is asked for a real answer and every top-level key of it must appear
    in the README's gate section. `schema` and `exit_code` are named in prose rather than as
    keys, and `rules` and `policy` are the sections themselves, so the assertion is over the keys
    and the section is what is searched.
    """
    policy_file = _policy_file(tmp_path / "p.json", "finished_ok")
    _, log = _gated_history(tmp_path)
    answer = runprov.policy.payload(
        runprov.policy.assessment(
            runprov.policy.load(policy_file),
            [],
            policy_path=str(policy_file),
            history=str(log),
        )
    )

    readme = (_repo_root() / "README.md").read_text(encoding="utf-8")
    heading = "## `runprov gate`: did the recorded runs meet a written policy?"
    assert heading in readme, "the README no longer documents `gate`, so this reads nothing"
    section = readme[readme.index(heading) :]
    section = section[: section.index("\n## ", 1)]

    missing = [key for key in sorted(answer) if f"`{key}`" not in section]
    assert not missing, (
        f"[L-13] `runprov.gate.v1` carries {missing} and the README's `gate` section never names "
        f"them. The README is the document a user reads, and ADR-0018's justification for this "
        f"gate greening on a run that started and never ended rests on that limit being written "
        f"where a person meets it"
    )
    #: AND THE PER-RULE ROW TOO, where `blocked` lives — the list K-10 split out of `reasons` so
    #: that an inability is never rendered as an accusation.
    row_missing = [key for key in sorted(answer["rules"][0]) if f"`{key}`" not in section]
    assert not row_missing, (
        f"[L-13] a rule row of `runprov.gate.v1` carries {row_missing}, unnamed in the README"
    )
    #: AND THE UNFINISHED LIMIT IS STATED, which is the sentence ADR-0018 depends on and the one
    #: thing a field list cannot carry: that this state does NOT move the exit code.
    #: WHITESPACE-NORMALISED, because the README is hard-wrapped and a sentence a reader sees
    #: as one line is two in the file. A guard that can be satisfied by a reflow is a guard
    #: about formatting.
    flowed = " ".join(section.split())
    assert "never ended" in flowed and "does not move the exit code" in flowed, (
        "[L-13] the README names `unfinished` as a field and does not say what it means for the "
        "verdict. A gate that greens on a lost run must say so where a user reads"
    )


def test_every_rule_declares_the_fields_its_judge_actually_reads():
    """[ADR-0018 R-7] [ADR-0018 R-5] Audit L, L-02. The direction nothing checked.

    **THE DEFECT, FOUND TWICE INDEPENDENTLY** — by the cause lens from the repair and by the
    contract lens from R-7's table, arriving from opposite directions. K-17's repair made
    `inputs_verify`'s verdict depend on the record's own `cwd`, the anchor a relative recorded
    path is resolved against, and declared it nowhere: the body read `record.get("cwd")` while
    `reads` said `('inputs',)` and R-7's row said `inputs`. **It sat one commit away from the
    commit that amended both the tuple and the table for `environment_captured`.**

    **AND NOTHING COULD SEE IT, which is the finding rather than the typo.** Every guard over
    `reads` ran in ONE DIRECTION — `reads ⊆ the record's vocabulary`, and `reads` against R-7's
    cell — so a field the tuple names and no body reads was caught and **a field a body reads
    and the tuple omits was invisible.** The consequence is not cosmetic:
    `test_every_registered_rule_can_say_it_could_not_check` strips exactly what `reads` names,
    so an undeclared dependency is one that guard never removes, and R-3's structural proof is
    weaker than it reads for precisely the rule that has one.

    **A LATENT FALSE GREEN IN THE SPECIFICATION LAYER.** No verdict is wrong today, because
    every released history carries `cwd`. A writer that omitted it would silently return this
    rule to resolving against the GATE PROCESS's working directory — K-17's exact symptom — with
    the registry, the ADR table and every guard green.

    **SO THE SECOND DIRECTION IS DERIVED FROM THE JUDGE'S OWN AST**: every `record.get("X")` and
    `record["X"]` in the function's body, held by EQUALITY against the heads of `reads`. Heads,
    because a dotted read like `observation.unregistered_watch_truncated` is a read of
    `observation` as far as the body is concerned, and that is the key a strip removes.

    **ITS LIMIT, STATED, because a guard whose reach is unstated is read as universal.** It sees
    DIRECT reads in the judge's own body: a field consulted through a helper taking the record,
    or through a dynamic key, is outside it. **All seven judges read directly today**, and that
    is the premise this is worth having on — measured before it was trusted, over the whole
    registry: exactly one finding (`inputs_verify` reads undeclared `['cwd']`) and zero false
    positives. A judge that grows a helper will fail here and needs its reads declared, which is
    the right outcome either way.
    """
    registry = runprov.policy.rules()
    assert registry, "the registry is empty, so this looked at nothing"

    def reads_in(judge) -> set[str]:
        source = textwrap.dedent(inspect.getsource(judge))
        tree = ast.parse(source)
        fn = next((n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)), None)
        # NOT a quiet empty result: a walk that located no function reads exactly like a judge
        # that consults nothing, and the two must not look the same.
        assert fn is not None, f"no function body found for {judge!r}"
        assert fn.args.args, f"{fn.name} takes no record to read"
        record = fn.args.args[0].arg
        found: set[str] = set()
        for node in ast.walk(fn):
            if (
                isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "get"
                and isinstance(node.func.value, ast.Name)
                and node.func.value.id == record
                and node.args
                and isinstance(node.args[0], ast.Constant)
                and isinstance(node.args[0].value, str)
            ):
                found.add(node.args[0].value)
            elif (
                isinstance(node, ast.Subscript)
                and isinstance(node.value, ast.Name)
                and node.value.id == record
                and isinstance(node.slice, ast.Constant)
                and isinstance(node.slice.value, str)
            ):
                found.add(node.slice.value)
        return found

    for name, got in registry.items():
        consulted = reads_in(got.judge)
        declared = {field.split(".")[0] for field in got.reads}
        assert consulted, (
            f"`{name}`'s judge reads no field of the record by name, so this guard sees nothing "
            f"of it — if it now consults the record through a helper, say so here"
        )
        assert consulted == declared, (
            f"[ADR-0018 R-7] `{name}`'s judge reads {sorted(consulted)} and declares "
            f"{sorted(declared)}. Undeclared: {sorted(consulted - declared)}; declared and "
            f"unread: {sorted(declared - consulted)}. `reads` is what R-7's table documents and "
            f"what `test_every_registered_rule_can_say_it_could_not_check` strips, so an "
            f"undeclared field is one R-3's structural proof never removes"
        )


def test_no_rule_reads_a_field_the_record_cannot_carry(tmp_path, monkeypatch):
    """[ADR-0018 R-10] T-34. Widened from one clean record to the states that produce each field.

    R-10: a rule may only assert over fields that exist, and if a policy wants a property the
    record does not carry, the answer is a record change with its own ADR — never an inference.

    **THIS REPLACED `test_every_rule_reads_only_fields_a_record_really_carries`, which read ONE
    clean record's top-level keys and was too strict in two directions at once.** It was deleted
    rather than loosened, and the gate is what forced the issue: it stayed in the suite for one
    commit beside this one, and the five new rules made it fail the moment they declared a
    conditional or nested field. Two guards for one requirement, and the narrow one had to go.

    `unregistered_reads` is written only when reads were missed and
    `observation.unregistered_watch_truncated` only when the watch hit its cap — both absent from
    a clean run, both legitimate. And a nested field could not be expressed at all. So the
    vocabulary is now the union over records REACHING each of those states, built by the package,
    and a rule may name a dotted path.
    """
    vocabulary = _record_field_vocabulary(tmp_path, monkeypatch)
    #: EVERY STATE THE FIXTURE SET EXISTS TO REACH, named — including the two only one of its
    #: four runs produces. **The first version of this omitted
    #: `observation.unregistered_watch_truncated`, and a control proved the omission mattered:**
    #: raising `WATCH_MAX_PATHS` so the cap never bites left the capped fixture reaching nothing
    #: and the guard still passed. A fixture whose state is unasserted can stop doing its job in
    #: silence — the fifth time that shape has been found here, and the first inside a guard
    #: written the same hour.
    required = {
        "git_status_captured",
        "git_commit",
        "status",
        "failure",
        "inputs",
        "outputs",
        "packages",
        "unregistered_reads",
        "observation.auto_available",
        "observation.packages_recorded",
        "observation.unregistered_watch_truncated",
        #: K-19. Written only by a run with a snapshot directory configured, which is the fifth
        #: fixture's whole purpose — and named here because a fixture whose state is unasserted
        #: can stop doing its job in silence, which this guard has already been caught by once.
        "environment_snapshot",
    }
    assert required <= vocabulary, (
        "the fixture set did not reach the states it exists for; these fields were never "
        f"produced: {sorted(required - vocabulary)}"
    )
    for name, got in runprov.policy.rules().items():
        unknown = [field for field in got.reads if field not in vocabulary]
        assert not unknown, (
            f"[ADR-0018 R-10] `{name}` reads {unknown}, which no record this package writes "
            f"carries. A policy wanting a property the record lacks needs a RECORD change with "
            f"its own ADR, not a rule that evaluates `None`"
        )


def test_every_registered_rule_can_say_it_could_not_check(tmp_path, monkeypatch):
    """[ADR-0018 R-3] [ADR-0018 R-6] T-34. The requirement made structural, not aspirational.

    R-3: a rule that cannot be evaluated is NEVER a pass. The way that goes wrong is not by
    someone writing `return MET` on an unevaluable run — it is by a rule reading a field that is
    `False` both when the answer is *no* and when nobody looked. `git_tree_dirty` is exactly such
    a field: `False` for a clean tree AND for a run outside a repository, with
    `git_status_captured` the only thing that separates them.

    **SO EVERY RULE MUST BE ABLE TO REACH `CANNOT_CHECK`, and this proves it by construction**
    rather than by reading the rule: each rule is handed a record stripped of the fields it
    declares it reads, and a rule that still answers `MET` or `VIOLATED` there is a rule that
    will call an unexamined run a pass. A rule that can never say *could not check* has
    collapsed R-2's third exit code, which the ADR calls the whole design.

    DERIVED FROM THE REGISTRY, so a rule added on any later day is held to this on the day it is
    added — R-5's reason for the registry existing, applied to the registry's own guard.
    """
    registry = runprov.policy.rules()
    assert registry, "the rule registry is empty, so every assertion below is vacuous"
    #: WHAT A RECORD REALLY CARRIES, DERIVED, AND CALLED ONCE [L-20]. `_record_field_vocabulary`
    #: is a plain function and not a fixture — it builds four histories with this package — so it
    #: is called here rather than taken as a parameter, and once rather than per rule.
    vocabulary = _record_field_vocabulary(tmp_path, monkeypatch)
    carried = {name for name in vocabulary if "." not in name}
    assert len(carried) > 10, f"the vocabulary found {sorted(carried)}, so the check below is thin"
    for name, got in registry.items():
        assert got.reads, f"{name} declares no fields, so this guard cannot strip any"
        #: THE HEAD OF EVERY READ, BECAUSE THE DOTTED HALF OF THIS STRIP WAS A NO-OP [K-26].
        #: `dict.fromkeys(got.reads)` put the LITERAL key
        #: `"observation.unregistered_watch_truncated"` into the record — a key no rule reads at
        #: all — so for the two rules with nested `reads` the CANNOT_CHECK below came from the
        #: `observation` block being absent and never from the strip. The guard that makes R-3
        #: structural was weaker than it looked for exactly the two rules R-6 is about, and it
        #: was written to prevent this class.
        #:
        #: **AND THE CONTROL THE ROW ASKED FOR IS FALSE, which is why this is a HEAD strip and
        #: not a walk into the nested dict.** Measured: a strip that leaves `observation` present
        #: and empty gives `no_unregistered_reads -> MET`, and **MET is the right answer there** —
        #: a run that read nothing unregistered is that rule's ordinary good case. Asserting
        #: CANNOT_CHECK for it would be a guard satisfiable only by breaking the rule. Stripping
        #: the head removes the whole block, which is what *carrying none of the fields it reads*
        #: means, and all seven rules answer CANNOT_CHECK over it.
        stripped = dict.fromkeys(r.split(".")[0] for r in got.reads)
        #: AND THE STRIP IS WHAT IT CLAIMS TO BE, which is the assertion that makes the line
        #: above load-bearing rather than a silent no-op again [K-26]. A CANNOT_CHECK obtained
        #: over a key no record carries proves nothing about the field the rule actually
        #: consults — and that is precisely the state this guard was in.
        #:
        #: **HELD AGAINST WHAT A RECORD CARRIES, NOT AGAINST A SPELLING [L-20].** K-26's own
        #: assertion was *no stripped key contains a dot* — **a TAUTOLOGY over every possible
        #: registry**, because `r.split(".")[0]` can never return a string containing a dot.
        #: It was a tripwire on one spelling of the line above it, not a statement about the
        #: strip, and both dot-free rewrites reintroduce K-26 verbatim with it green:
        #: `r.split(".")[-1]` yields `unregistered_watch_truncated`, a LEAF name, and
        #: `r.replace(".", "__")` yields `observation__unregistered_watch_truncated`. Neither
        #: is a key any record has, so the rule would again answer CANNOT_CHECK because the
        #: `observation` block is absent rather than because anything was stripped. The defect
        #: class is a SEMANTICS and the old assertion was about a SHAPE. This one asks the
        #: question directly, against a vocabulary built by the package from real records,
        #: and it is satisfied by every rule in the registry today.
        unknown = sorted(set(stripped) - carried)
        assert not unknown, (
            f"[L-20] `{name}`'s stripped record carries {unknown}, which no record this package "
            f"writes has. A CANNOT_CHECK obtained over a key that does not exist comes from the "
            f"field's parent being absent, not from the strip — which is K-26 exactly. The keys "
            f"a record really carries: {sorted(carried)}"
        )
        verdict = got.judge(stripped, runprov.policy.Context())
        assert verdict.outcome == runprov.policy.CANNOT_CHECK, (
            f"[ADR-0018 R-3] `{name}` answered {verdict.outcome} over a record carrying none of "
            f"the fields it reads {list(got.reads)}. A rule that cannot say *could not check* "
            "reports an unexamined run as a pass"
        )
        assert verdict.reason, (
            f"`{name}` said CANNOT_CHECK with no reason, which a reader cannot tell from a bug"
        )

    # AND EVERY RULE SAYS WHAT IT CANNOT SEE [R-6], in its own words rather than by omission.
    for name, got in registry.items():
        assert len(got.blind) > 30, (
            f"{name}'s `blind` must be a sentence, not a shrug: {got.blind!r}"
        )
        #: AND ITS FIRST CLAUSE IS NOT EMPTY [L-21]. The README's *cannot answer when* cell is
        #: held to `blind.split(" — ")[0]` by equality, which is what K-39 built to forbid an
        #: empty cell — and a `blind` that OPENS with the separator makes that clause the empty
        #: string, re-admitting the empty cell through the one input shape K-39's repair made
        #: load-bearing. Built and measured: RC=0 before this line. `len(blind) > 30` constrains
        #: the sentence and not the clause, so it cannot stand in for this.
        assert got.blind.split(" — ")[0].strip(), (
            f"[L-21] `{name}`'s `blind` opens with the em-dash separator, so its first clause is "
            f"empty — and that clause is the README's *cannot answer when* cell: {got.blind!r}"
        )
        assert got.asks, f"{name} does not say what it asks"


def test_a_rule_asked_of_nothing_is_not_a_rule_that_passed(tmp_path):
    """[ADR-0018 R-4] T-34. `check`'s A-08 defect, refused one level up.

    *No violations* over a log matching zero runs is not a pass, and the count is what lets a
    caller tell the two apart. `assess` carries `evaluated` beside the outcome and says
    `asked_of_nothing` in words, so neither reading requires arithmetic on three tallies.

    AND THE WORST OUTCOME DECIDES, asserted in both directions: a violation among runs that
    could not all be checked is still a violation, and an unchecked run among passes is not a
    pass. That ordering is the fact R-3 states, so it is tested rather than left to the order
    the implementation happens to use.
    """
    nothing = runprov.policy.assess("clean_tree", [])
    assert nothing["outcome"] == runprov.policy.CANNOT_CHECK, (
        "[ADR-0018 R-4] a rule asked of no runs must not report MET; `no violations` over an "
        f"empty selection is the vacuous green: {nothing}"
    )
    assert nothing["evaluated"] == 0 and nothing["asked_of_nothing"] is True, nothing

    clean = {"git_status_captured": True, "git_tree_dirty": False}
    dirty = {"git_status_captured": True, "git_tree_dirty": True}
    blind = {"git_status_captured": False, "git_tree_dirty": False}

    met = runprov.policy.assess("clean_tree", [clean, clean])
    assert (met["outcome"], met["evaluated"], met["met"]) == (runprov.policy.MET, 2, 2), met
    assert met["reasons"] == [] and met["asked_of_nothing"] is False, met
    assert met["blocked"] == [], met

    #: THE BLIND RUN IS THE POINT: `git_tree_dirty` is False here exactly as in `clean`, and only
    #: the capture mark separates them. A rule reading one field would call this a pass.
    unknown = runprov.policy.assess("clean_tree", [clean, blind])
    assert unknown["outcome"] == runprov.policy.CANNOT_CHECK, (
        "[ADR-0018 R-3] one run whose git status was never captured makes the rule unevaluable "
        "for the selection; a pass here would be a control that passed because nobody "
        f"looked: {unknown}"
    )
    assert (unknown["met"], unknown["not_checked"]) == (1, 1), unknown
    #: AND THE SENTENCE IS IN `blocked`, NOT IN `reasons` [K-10]. This assertion read
    #: `unknown["reasons"]` until the two lists were split, which is the half of that row a
    #: consumer meets: `reasons` was `list[str]` and `len(reasons)` was 1 where `violated` was 0.
    assert unknown["blocked"], "and it says which fact was missing"
    assert unknown["reasons"] == [], (
        f"[K-10] `reasons` is the breaches, and nothing here is a breach: {unknown}"
    )

    #: A VIOLATION OUTRANKS AN INABILITY, which is L-81's ordering in a new command.
    worst = runprov.policy.assess("clean_tree", [clean, blind, dirty])
    assert worst["outcome"] == runprov.policy.VIOLATED, (
        f"a violation among unexaminable runs is still a violation: {worst}"
    )
    assert (worst["met"], worst["violated"], worst["not_checked"]) == (1, 1, 1), worst
    #: AND THE TWO SENTENCES ARE IN THE TWO LISTS, one each, which is the state K-10 was filed
    #: over: both used to sit in `reasons` and both printed under the word `finding`.
    assert len(worst["reasons"]) == 1 and len(worst["blocked"]) == 1, worst
    assert len(worst["reasons"]) == worst["violated"], (
        f"[K-10] `len(reasons)` is now a number a consumer can compare with `violated`: {worst}"
    )


def _gated_history(tmp_path):
    """A real history: one complete run with an input and an output, and one that failed.

    REAL RUNS, NOT HAND-BUILT RECORDS. `status`, `failure` and the input's digests are written by
    this package, so the verdicts below are asserted against what the writer really produces — the
    A-08 shape is a fixture that asserts what its author believed the writer does.
    """
    histories = tmp_path / "gated"
    histories.mkdir()
    log = histories / "h.jsonl"
    runprov.configure(root=histories, run_log=log, auto_steps="off")
    (histories / "in.tsv").write_text("a\n", encoding="utf-8")
    with runprov.Run("good", {}, provenance=histories / "p1.json") as run:
        run.input(histories / "in.tsv")
        with run.open_output(histories / "out.tsv") as fh:
            fh.write("z\n")
    try:
        with runprov.Run("bad", {}, provenance=histories / "p2.json") as run:
            run.input(histories / "in.tsv")
            raise ValueError("boom")
    except ValueError:
        pass
    return histories, log


_WHY = "a control this project states, and states in a file"


def _policy_file(path: pathlib.Path, *names: str) -> pathlib.Path:
    """A policy naming these rules, each with the `why` R-11 requires."""
    path.write_text(
        json.dumps({"rules": [{"rule": name, "why": _WHY} for name in names]}), encoding="utf-8"
    )
    return path


def test_the_gate_answers_three_ways_and_the_exit_code_is_the_verdict(tmp_path, capsys):
    """[ADR-0018 R-1] [ADR-0018 R-2] [ADR-0018 R-8] T-34. The command, in all three outcomes.

    R-2 keeps the existing exit codes: 0 every rule checked and met, 1 a rule violated, **2 a rule
    that could not be checked.** The third is the whole design — a policy engine that cannot tell
    *violated* from *unverifiable* produces the vacuous pass this project has now fixed in five
    places — so all three are reached here over ONE history, with the rule chosen to select the
    state rather than the record edited to force it.

    THE PREMISES ARE ASSERTED BEFORE THE VERDICTS ARE READ OFF THEM. A history written outside a
    repository is what makes `clean_tree` unevaluable, and a run that really failed is what makes
    `finished_ok` violated; a fixture whose name asserts a state it does not contain is a control
    that did not run, which this project has now found five times.

    AND THE EXIT CODE DOES NOT MOVE WITH THE FORMAT [ADR-0017]. `--format json` is a rendering
    choice, not a different question, and a gate that answers differently depending on how it was
    asked to print is a gate nobody can reason about.
    """
    _, log = _gated_history(tmp_path)
    finished = [
        json.loads(line)
        for line in log.read_text(encoding="utf-8").splitlines()
        if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
    ]
    assert len(finished) == 2, finished
    assert not any(record.get("git_status_captured") for record in finished), (
        "the premise of the CANNOT_CHECK case: a history written outside a git repository, so "
        f"`clean_tree` has nothing to read: {[r.get('git_status_captured') for r in finished]}"
    )
    assert [record.get("status") for record in finished].count("ok") == 1, (
        f"the premise of the other two: one run finished and one did not: {finished}"
    )

    cases = {
        0: ("met.json", "inputs_verify", runprov.policy.MET),
        1: ("violated.json", "finished_ok", runprov.policy.VIOLATED),
        2: ("blind.json", "clean_tree", runprov.policy.CANNOT_CHECK),
    }
    for expected, (name, rule, outcome) in cases.items():
        argv = ["gate", "--policy", str(_policy_file(tmp_path / name, rule)), "--log", str(log)]
        capsys.readouterr()
        code = runprov.__main__.main(argv)
        page = capsys.readouterr().out
        assert code == expected, (
            f"[ADR-0018 R-2] a policy of `{rule}` over this history is {outcome}, which is "
            f"exit {expected}; got {code}. Page:\n{page}"
        )
        capsys.readouterr()
        as_json = runprov.__main__.main([*argv, "--format", "json"])
        body = json.loads(capsys.readouterr().out)
        assert as_json == code, (
            "the exit code must not move with the format; the question is the same one asked "
            f"two ways: {rule} gave {code} as text and {as_json} as JSON"
        )

        assert body["schema"] == runprov.policy.SCHEMA == "runprov.gate.v1", (
            "[ADR-0017 R-5] a consumer branches on the schema and not on what it finds, so the "
            f"literal is asserted here as well as named in the README: {body.get('schema')}"
        )
        assert (body["outcome"], body["exit_code"], body["runs"]) == (outcome, code, 2), body
        assert body["rules"][0]["rule"] == rule and len(body["rules"]) == 1, body
        #: THE PAGE AND THE PAYLOAD NAME THE SAME VERDICT AND THE SAME ROUTE TO IT. J-04 is the
        #: row where two renderings of one answer named different routes, each having worked it
        #: out for itself.
        assert f"GATE: {outcome}" in page and rule in page, page
        #: R-11: THE `why` IS IN BOTH, which is the whole reason it is a required field. An
        #: assessor reads why the control exists beside whether it was met.
        assert _WHY in page and body["rules"][0]["why"] == _WHY, (page, body)
        #: R-4: AND SO IS THE COUNT IT WAS EVALUATED AGAINST, in words rather than only in a
        #: field — a reader who has to ask for JSON to see it is a reader who will not ask.
        assert f"{body['rules'][0]['evaluated']} run(s)" in page, page


def test_one_unreadable_line_is_not_a_gate_that_passed(tmp_path, capsys):
    """[ADR-0018 R-2] [ADR-0018 R-3] T-34. The vacuous green, refused one level above the rules.

    A torn line is a run the gate did not examine. Every rule can still be MET over the runs it
    DID see, and reporting that as a pass would be exactly the shape this feature exists to
    catch — so the history not being whole is enough on its own to make the answer exit 2.

    **THE CONTROL RUNS FIRST AND IS THE POINT.** The same policy over the same history exits 0;
    one appended line that is not JSON moves it to 2. Without that pass, a test asserting 2 here
    would be satisfied by a gate that exits 2 for any reason at all, which is how a check comes to
    measure something other than what it names.

    AND THE RULE STILL SAYS MET, asserted, because the two facts must not collapse. *A rule
    failed* and *the history could not all be read* send a reader to completely different places,
    and a gate that reported the second as the first would send them to the wrong one.
    """
    _, log = _gated_history(tmp_path)
    argv = [
        "gate",
        "--policy",
        str(_policy_file(tmp_path / "met.json", "inputs_verify")),
        "--log",
        str(log),
        "--format",
        "json",
    ]
    capsys.readouterr()
    assert runprov.__main__.main(argv) == 0, "the control: this policy is MET over this history"
    before = json.loads(capsys.readouterr().out)
    assert (before["unreadable"], before["cannot_check"]) == (0, None), (
        "[ADR-0017 R-8] `null` is *looked and found none*, and it is what a whole history gets"
    )

    with log.open("a", encoding="utf-8") as fh:
        fh.write("this line is not json\n")
    capsys.readouterr()
    assert runprov.__main__.main(argv) == 2, (
        "[ADR-0018 R-3] a history the gate could not entirely read cannot be reported as met"
    )
    after = json.loads(capsys.readouterr().out)
    assert after["unreadable"] == 1, after
    assert "could not be read" in (after["cannot_check"] or ""), after
    assert after["rules"][0]["outcome"] == runprov.policy.MET, (
        "the RULE is still met over the runs it saw; the GATE cannot be, because the history was "
        f"not whole. Collapsing those two sends a reader to repair a rule that is fine: {after}"
    )


def _breach_and_inability(tmp_path):
    """One history and ONE rule over it, where one run breaches and another cannot be answered.

    `outputs_pin_inputs` selects both states from real runs rather than from an edited record:
    a run that wrote an output and declared no input is a VIOLATION, and a run that recorded no
    output is a CANNOT_CHECK — *there is nothing to ask*. The audit reproduced K-09 and K-10 in
    this one state, and one rule rather than two is what makes it the interesting one: `assess`
    folds the rule to VIOLATED, which is where the unexamined run used to disappear.
    """
    histories = tmp_path / "mixed"
    histories.mkdir()
    log = histories / "m.jsonl"
    runprov.configure(root=histories, run_log=log, auto_steps="off")
    (histories / "in.tsv").write_text("a\n", encoding="utf-8")
    with runprov.Run("gen", {}, provenance=histories / "a.json") as run:
        with run.open_output(histories / "outA.tsv") as fh:
            fh.write("x\n")
    with runprov.Run("look", {}, provenance=histories / "b.json") as run:
        run.input(histories / "in.tsv")
    return log


def test_a_breach_and_an_inability_are_two_lists_and_two_words(tmp_path, capsys):
    """[ADR-0018 R-3] [ADR-0017 R-9] Audit K, K-10. An inability rendered as an accusation.

    **THE DEFECT.** `reasons` merged violations and inabilities into one unlabelled list and the
    page printed every member under the word `finding`. Reproduced: *1 output(s) recorded and no
    input declared for any of them* and *the run recorded no outputs, so there is nothing to ask*
    appeared together, both labelled `finding` — one a breach and one a limit. **That is Audit H's
    "a true verdict wearing a false sentence" in new code**, and ADR-0018 R-3 is precisely that
    the two are different answers.

    **THE HARM IS MEDIUM AND THE ONE-WAY DOOR IS WHAT MAKES IT HIGH.** A person can tell the two
    apart by reading them. A CONSUMER cannot: `reasons` is `list[str]`, so `len(reasons)` was 2
    where `violated` was 1, and `runprov.gate.v1` freezes at upload — after which ADR-0017 R-9
    forbids renaming a field.

    **THE REMEDY SHAPE WAS REFUTED AND REWRITTEN.** The row asked for each `reasons` row to carry
    its own outcome, i.e. `list[dict]`. That is not this project's vocabulary: `diff` keeps an
    incomparability in its OWN FIELD (`blocked`, per ADR-0014) rather than labelling members of
    the differences. So `reasons` narrows to breaches and `blocked` is the second list, under
    ADR-0014's word for the same idea one command over.
    """
    log = _breach_and_inability(tmp_path)
    policy_file = _policy_file(tmp_path / "p.json", "outputs_pin_inputs")
    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
    )
    row = json.loads(capsys.readouterr().out)["rules"][0]

    #: THE PREMISE: one rule, two runs, one of each state — asserted before anything is read off
    #: it, because a fixture that reached only one state would make this test pass vacuously.
    assert (code, row["evaluated"], row["violated"], row["not_checked"]) == (1, 2, 1, 1), row
    assert row["outcome"] == runprov.policy.VIOLATED, row

    #: 1. TWO LISTS, AND EACH COUNT MATCHES ITS OWN LIST. This is the half a consumer meets.
    assert len(row["reasons"]) == row["violated"] == 1, (
        f"[K-10] `len(reasons)` must be a number a consumer can compare with `violated`: {row}"
    )
    assert len(row["blocked"]) == 1, f"[K-10] the inability needs its own field: {row}"
    assert "no input declared" in row["reasons"][0], row["reasons"]
    assert "nothing to ask" in row["blocked"][0], row["blocked"]
    assert row["blocked"][0] not in row["reasons"], (
        f"[K-10] an inability in the breach list is an accusation: {row}"
    )

    #: 2. AND TWO WORDS ON THE PAGE. The payload split is useless to a reader if the page still
    #: calls both a finding — ADR-0017 R-1 is one builder and two views, and this is the view.
    capsys.readouterr()
    assert runprov.__main__.main(["gate", "--policy", str(policy_file), "--log", str(log)]) == 1
    page = capsys.readouterr().out
    #: READ BY LABEL, so the assertion is about which WORD each sentence is printed under rather
    #: than about whether a phrase appears anywhere on the page. The rule's standing `blind` text
    #: contains the same phrase as its inability sentence, so a substring search over the whole
    #: page matches both lines and proves nothing.
    labelled: dict[str, list[str]] = {}
    for line in page.splitlines():
        for label in ("finding", "not checked", "cannot see"):
            if line.strip().startswith(label):
                labelled.setdefault(label, []).append(line.strip()[len(label) :].strip())
    assert labelled.get("finding") == [row["reasons"][0]], (
        f"[ADR-0017 R-1] the page prints the breaches the payload carries: {labelled}"
    )
    assert labelled.get("not checked") == [row["blocked"][0]], (
        f"[K-10] *the run recorded no outputs, so there is nothing to ask* is not a finding "
        f"about anybody, and the page printed it under `finding` beside a real breach: {labelled}"
    )
    #: AND IT IS NOT THE `cannot see` LINE EITHER, which is the rule's STANDING blind spot rather
    #: than what it could not answer about THESE runs. Two facts, two labels.
    assert labelled.get("cannot see") == [row["blind"]], labelled

    #: 3. A CLEAN PASS LEAVES BOTH EMPTY, the positive companion: without it this test would pass
    #: against a `blocked` that is filled unconditionally.
    _, clean = _gated_history(tmp_path)
    capsys.readouterr()
    runprov.__main__.main(
        [
            "gate",
            "--policy",
            str(_policy_file(tmp_path / "clean.json", "inputs_verify")),
            "--log",
            str(clean),
            "--format",
            "json",
        ]
    )
    passed = json.loads(capsys.readouterr().out)["rules"][0]
    assert (passed["outcome"], passed["reasons"], passed["blocked"]) == (
        runprov.policy.MET,
        [],
        [],
    ), passed


def test_an_unchecked_run_reaches_cannot_check_even_when_the_same_rule_is_violated(
    tmp_path, capsys
):
    """[ADR-0018 R-2] [ADR-0018 R-3] [ADR-0017 R-8] Audit K, K-09. The field a consumer is
    pointed at, and the run that vanished from it.

    **THE DEFECT.** Top-level `cannot_check` was `null` over a history where a run was not
    checked, whenever a violation of the SAME RULE outranked it. Reproduced: one rule
    `outputs_pin_inputs`, run A with an output and no input (VIOLATED), run B with no outputs
    (CANNOT_CHECK) — the payload carried `not_checked: 1` and `cannot_check: null` together, and
    exited 1. The property listed only rules whose AGGREGATE outcome was CANNOT_CHECK, and
    `assess` folds this rule to VIOLATED, so the unexamined run disappeared from the one field
    ADR-0017 R-8 points a consumer at.

    **THE PROPERTY'S OWN DOCSTRING CLAIMED TO HANDLE EXACTLY THIS** — *"a VIOLATED gate that
    still could not see everything"* — which is true at the RULE level and false at the RUN
    level. A docstring is not a contract until something checks it, and this is the something.

    **THE CITATION IS ADR-0017 R-8, NOT R-16**, which a skeptic corrected: R-16's table predates
    T-34 and does not list `gate`.

    **AND THE SENTENCE NAMES RUNS.** The old one counted rules and said nothing about how many
    runs each left unanswered, so a reader could not tell *this rule saw nothing at all* from
    *this rule saw all but one*. The severity was cut to medium for a good reason — `not_checked:
    1` sits three lines above the `null` and the page prints *1 not checked* — so what this fixes
    is the SUMMARY, which is the only part a consumer reading one field sees.
    """
    log = _breach_and_inability(tmp_path)
    policy_file = _policy_file(tmp_path / "p.json", "outputs_pin_inputs")
    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
    )
    body = json.loads(capsys.readouterr().out)
    row = body["rules"][0]

    assert (row["outcome"], row["violated"], row["not_checked"]) == (
        runprov.policy.VIOLATED,
        1,
        1,
    ), f"the premise: ONE rule folding to VIOLATED with a run it could not answer for: {row}"

    assert body["cannot_check"] is not None, (
        f"[K-09] `not_checked: {row['not_checked']}` and `cannot_check: null` in one document, "
        f"and R-8 makes null mean *looked and found nothing missing*: {body}"
    )
    assert "outputs_pin_inputs" in body["cannot_check"], body["cannot_check"]
    #: IT NAMES THE RUNS, which the old sentence did not. `1 of 2` is the whole repair of the
    #: wording: a reader can tell a rule that saw nothing from one that saw all but one.
    assert "1 of 2 run(s)" in body["cannot_check"], (
        f"[K-09] the sentence must say how many RUNS went unchecked, not only which rules: "
        f"{body['cannot_check']}"
    )

    #: AND THE VERDICT IS UNTOUCHED. `cannot_check` is independent of `outcome` by design — a
    #: reader repairing the breach has to know the rest was not cleared either — so this must
    #: fix the sentence and move no exit code. Measured zero blast on all seven corpus histories.
    assert (body["outcome"], body["exit_code"], code) == (runprov.policy.VIOLATED, 1, 1), body

    #: THE PAGE SAYS IT TOO, under COULD NOT CHECK, beside a GATE line that still says VIOLATED.
    capsys.readouterr()
    assert runprov.__main__.main(["gate", "--policy", str(policy_file), "--log", str(log)]) == 1
    page = capsys.readouterr().out
    assert "COULD NOT CHECK" in page and "1 of 2 run(s)" in page, page
    assert "GATE: VIOLATED (exit 1)" in page, page

    #: AND A RULE ASKED OF NO RUN AT ALL IS STILL NAMED, which reading `not_checked` alone would
    #: have dropped: over an empty selection every tally is zero, so the count is 0 and
    #: `asked_of_nothing` is the fact. R-4 exists for exactly that state, and a repair that
    #: silenced it would have traded K-09 for the vacuous green one level up.
    capsys.readouterr()
    assert (
        runprov.__main__.main(
            [
                "gate",
                "--policy",
                str(policy_file),
                "--log",
                str(tmp_path / "absent.jsonl"),
                "--format",
                "json",
            ]
        )
        == 2
    )
    empty = json.loads(capsys.readouterr().out)
    assert empty["cannot_check"] and "no run to check" in empty["cannot_check"], (
        f"[ADR-0018 R-4] a rule asked of nothing must stay in the sentence: {empty}"
    )
    assert "outputs_pin_inputs" in empty["cannot_check"], empty["cannot_check"]


def test_the_gates_precedence_is_asserted_over_every_inability_it_can_report(tmp_path, capsys):
    """[ADR-0018 R-2] [ADR-0018 R-3] Audit K, K-01. The ordering the exit code is read from.

    **THE DEFECT.** `Assessment.outcome`'s ordering was unasserted: reversing it so an inability
    outranks a violation passed all 1,196 tests. Verified by hand rather than inferred — a
    history with a failed run AND one torn line answers `VIOLATED` / exit **1** today and
    `CANNOT_CHECK` / exit **2** reversed, over the same file. **The same ordering one level down,
    in `assess`, IS asserted**, so this was exactly the gap between a rule's verdict and the
    gate's, which is where J-01 found its defect one level up. A CI job keys on the exit code,
    and the two readings send a reader to different work: repair a violation, or go and find out
    why a line is unreadable.

    **NOBODY MEETS IT TODAY — the ordering is CORRECT.** You meet it only if someone later edits
    `outcome`, and then silently, which is why the severity was cut to medium and the fix is
    still worth three lines.

    **WRITTEN PARAMETRICALLY OVER THE INABILITY SOURCES, AND THAT IS THE WHOLE POINT.** Over the
    torn-line case alone, a new clause for a new inability can land in the wrong position — inside
    the verdict's own branch, where it fires only when nothing else is wrong — and this test
    would not see it. K-08 and K-23 each added one in the same audit. **So the field set is
    DERIVED from `Assessment` and the complement is declared**: a field added later fails here
    until somebody decides which kind it is, which is the shape that makes `runprov.gate.v1`'s
    freeze survivable.

    **ASSESSMENTS ARE CONSTRUCTED DIRECTLY HERE, which nothing else does.** A property over the
    FIELDS cannot be stated through a history, because reaching one inability means reaching a
    particular state of a file and varying one field at a time is what makes the ordering
    readable. The real-history case is asserted too, below, end to end through the command.
    """
    #: REAL ROWS FROM REAL RUNS, so the verdicts the ordering is applied to are the writer's own.
    _, log = _gated_history(tmp_path)
    records = [
        json.loads(line)
        for line in log.read_text(encoding="utf-8").splitlines()
        if line.strip() and json.loads(line).get("schema") != "runprov.start.v1"
    ]
    good = [r for r in records if r.get("status") == "ok"]
    bad = [r for r in records if r.get("status") != "ok"]
    assert len(good) == 1 and len(bad) == 1, (
        f"the premise: one run passed and one failed: {records}"
    )

    def rows(selection):
        return ({**runprov.policy.assess("finished_ok", selection), "why": _WHY},)

    passing, breaching = rows(good), rows(bad)
    blinded = rows([])
    assert passing[0]["outcome"] == runprov.policy.MET, passing
    assert breaching[0]["outcome"] == runprov.policy.VIOLATED, breaching
    assert blinded[0]["outcome"] == runprov.policy.CANNOT_CHECK, blinded

    #: EVERY FIELD OF `Assessment` IS EITHER A SUBJECT OR AN INABILITY, and the subjects are the
    #: four that say WHAT was assessed. Derived, so a new field is not silently neither.
    facts = set(runprov.policy.Assessment._fields) - {"policy_path", "history", "runs", "rules"}
    #: WHAT EACH INABILITY LOOKS LIKE CLEAN AND BROKEN. Declared rather than derived because no
    #: expression can know it — and the assertion below is what makes the declaration load-bearing.
    inability: dict[str, tuple[object, object]] = {
        "found": (True, False),
        "read_error": (None, "Permission denied"),
        "unreadable": (0, 1),
        "unfinished": (0, 1),
    }
    assert set(inability) == facts, (
        "[K-01] `Assessment` grew or lost a field that is not a subject of the assessment, so it "
        "is an inability the gate can report and this test does not cover it. Adding a field "
        "reaches `runprov.gate.v1` through `_asdict()` with no other guard objecting at all: "
        f"{sorted(set(inability) ^ facts)}"
    )
    #: AND WHICH OF THEM MOVE THE VERDICT. `unfinished` deliberately does NOT — Taylor's ruling
    #: on K-08, because the start line is append-only and reading it here would fail a project's
    #: gate for ever over one power cut. This is where that ruling is pinned: a later change that
    #: quietly put it in `outcome` fails here.
    moves_the_verdict = {"found", "read_error", "unreadable"}
    assert facts - moves_the_verdict == {"unfinished"}, (
        f"[K-08] Taylor's ruling is that `unfinished` is named and never changes the verdict, and "
        f"every other inability does change it: {sorted(facts - moves_the_verdict)}"
    )

    def built(rules, **facts_set):
        #: EVERY FIELD NAMED, so a field added to `Assessment` raises here rather than defaulting
        #: into a state this test never varied. `runs` is nominal: this is a property over the
        #: FIELDS, and the real history below is where a consistent one is asserted.
        base: dict[str, object] = {
            "policy_path": "policy.json",
            "history": str(log),
            "found": True,
            "read_error": None,
            "runs": 1,
            "unreadable": 0,
            "unfinished": 0,
            "rules": rules,
        }
        return runprov.policy.Assessment(**{**base, **facts_set})

    #: THE THREE-WAY ORDERING OVER THE ROWS ALONE, with every fact clean — VIOLATED above
    #: CANNOT_CHECK above MET, which is the half `assess` already asserts one level down.
    assert built(passing).outcome == runprov.policy.MET
    assert built(passing).exit_code == 0 and built(passing).cannot_check is None
    assert built(blinded).outcome == runprov.policy.CANNOT_CHECK
    assert built(blinded).exit_code == 2
    assert built(breaching + blinded).outcome == runprov.policy.VIOLATED, (
        "[ADR-0018 R-2] a violation among rules that could not all be checked is still a "
        "violation — this is the ordering a reversed `outcome` silently inverts"
    )

    for field, (clean, broken) in sorted(inability.items()):
        #: 1. A VIOLATION OUTRANKS IT. K-01's own assertion, now over every source rather than
        #: over the torn line alone.
        beside = built(breaching, **{field: broken})
        assert (beside.outcome, beside.exit_code) == (runprov.policy.VIOLATED, 1), (
            f"[K-01] `{field}` turned a violation into an inability. A CI job keys on the exit "
            f"code, and 1 and 2 send a reader to different work: {beside}"
        )

        #: 2. AND IT IS STILL REPORTED, which is the half a position error hides. `cannot_check`
        #: is independent of `outcome` by design — a reader repairing the violation has to know
        #: the rest was not cleared — so a clause placed inside the verdict's own branch passes
        #: (1) and fails here. **DERIVED rather than matched against a sentence**: the comparison
        #: is with the same assessment carrying the clean value, so each field must ADD something.
        reference = built(breaching, **{field: clean}).cannot_check
        assert reference is None, (
            f"the baseline must be silent for this to mean anything: {reference}"
        )
        assert beside.cannot_check, (
            f"[K-01] [ADR-0017 R-8] `{field}` is set and the gate reports nothing missing, which "
            f"is documented to mean *looked and found nothing*: {beside}"
        )

        #: 3. AND WHAT IT DOES TO AN OTHERWISE CLEAN GATE is the declared table above.
        alone = built(passing, **{field: broken})
        expected = runprov.policy.CANNOT_CHECK if field in moves_the_verdict else runprov.policy.MET
        assert alone.outcome == expected, (
            f"[K-01] over a gate with nothing else wrong, `{field}` must answer {expected}: {alone}"
        )
        assert alone.cannot_check, f"and say so whatever the verdict is: {alone}"

    #: AND THE SAME ORDERING END TO END, over a real history carrying a violation AND a torn line
    #: at once — which is the state K-01 was verified by hand over, and the one a reversed
    #: `outcome` answers exit 2 for.
    policy_file = _policy_file(tmp_path / "ordering.json", "finished_ok")
    with log.open("a", encoding="utf-8") as fh:
        fh.write("this line is not json\n")
    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
    )
    body = json.loads(capsys.readouterr().out)
    #: THE PREMISES, AND `unfinished` IS ONE OF THEM. Built from a history with NO unpaired start
    #: line on purpose: with one, the CANNOT_CHECK a reversed `outcome` produces could come from
    #: K-08's clause instead and this assertion would not be about the ordering at all.
    assert (body["unreadable"], body["unfinished"], body["found"]) == (1, 0, True), body
    assert body["rules"][0]["violated"] == 1, body
    assert (body["outcome"], body["exit_code"], code) == (runprov.policy.VIOLATED, 1, 1), (
        f"[K-01] a failed run and a torn line in one history: the failure is the finding and the "
        f"torn line is reported beside it. Reversed, this answers CANNOT_CHECK and exit 2 over "
        f"the same file: {body}"
    )
    assert body["cannot_check"] and "could not be read" in body["cannot_check"], body


def test_the_gate_page_says_what_the_payload_says_in_the_states_that_are_not_ordinary(
    tmp_path, capsys
):
    """[ADR-0018 R-2] [ADR-0018 R-4] T-34. The page, in the states a happy path never reaches.

    A rendering is only as good as its worst state, and these are the states in which a gate
    report is actually read: the history was not there, and the history was not whole. Each must
    say so **on the page** — a reader who has to ask for JSON to discover that nothing was
    examined is a reader who will not ask, and R-4's count exists precisely so that *no
    violations* cannot be mistaken for *nothing was checked*.

    THE EARLIER TESTS ASSERT THESE STATES THROUGH THE PAYLOAD, which is not the same claim. J-04
    is the row where a page and a payload named different routes to one verdict, and H1-3 the row
    where the text silently dropped findings the JSON carried; a state asserted in one rendering
    only is a state unasserted in the other.
    """
    _, log = _gated_history(tmp_path)
    policy_file = _policy_file(tmp_path / "met.json", "inputs_verify")

    #: 1. THE HISTORY IS NOT THERE. `found` is a field and not an inference from a count, so the
    #: page says NOT FOUND beside the path AND reports that the rule was asked of nothing — two
    #: different facts, and a reader needs the first to know the second is not a project that has
    #: simply recorded nothing yet.
    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(policy_file), "--log", str(tmp_path / "absent.jsonl")]
    )
    page = capsys.readouterr().out
    assert code == 2, page
    assert "(NOT FOUND)" in page, page
    assert "0 run(s) examined" in page and "ASKED OF NOTHING" in page, page
    assert "COULD NOT CHECK" in page and "GATE: CANNOT_CHECK" in page, page

    #: 2. THE HISTORY IS NOT WHOLE, on the page this time. The count of lines that could not be
    #: read is printed where the run count is, because they are the same fact seen from two sides:
    #: this many runs were examined, and this many could not be.
    with log.open("a", encoding="utf-8") as fh:
        fh.write("this line is not json\n")
    capsys.readouterr()
    code = runprov.__main__.main(["gate", "--policy", str(policy_file), "--log", str(log)])
    page = capsys.readouterr().out
    assert code == 2, page
    assert "1 line(s) unreadable" in page, page
    assert "MET" in page and "GATE: CANNOT_CHECK" in page, (
        "the rule is still met over the runs the gate saw, and the gate is not — both on the "
        "page, because a reader sent to repair a rule that is fine has been sent to the wrong "
        f"place:\n{page}"
    )


def test_a_run_that_started_and_never_ended_is_named_and_never_changes_the_verdict(
    tmp_path, capsys
):
    """[ADR-0018 R-3] [ADR-0018 R-7] [ADR-0017 R-8] Audit K, K-08. The critical row, and Taylor's
    ruling on it.

    **THE DEFECT.** A history holding a run that started and never ended passed the gate with
    `outcome: MET`, `exit_code: 0`, `cannot_check: null` — and the in-flight run counted in **no
    field of the payload at all**. Reproduced with a real SIGKILL: a run entered, the process
    killed, the history left holding `runprov.start.v1` with no record. `gate` said
    `1 run / MET / exit 0 / cannot_check None` while `runprov log` said `unfinished: 1` over the
    same file. `_counted` drops every start line, so `finished_ok`'s judge never received a
    statusless line and its own documented `status is None -> CANNOT_CHECK` arm was unreachable
    through the command. **`cannot_check: null` is documented as *looked and found nothing
    missing*, and it was asserting the opposite of what happened.**

    **TAYLOR'S RULING, 2026-10-03: NAME IT, NEVER CHANGE THE VERDICT.** A skeptic implemented the
    row's own remedy — treat `unfinished` in `outcome` exactly as `unreadable` is treated — and
    measured what it costs: after two further SUCCESSFUL runs and after `runprov prune` removed
    the marker, the gate is **still exit 2**. The start line is append-only, so one lost run in a
    project's lifetime pins `gate` at exit 2 for ever in a record nobody can amend, and
    `_finished_ok`'s own docstring already argues against exactly that shape. It also fails the
    gate because another job is merely in progress. So the fact becomes a field and a
    `cannot_check` clause, and `outcome` and `exit_code` never read it.

    **THE RESIDUAL LIMIT IS ASSERTED HERE RATHER THAN LEFT IMPLICIT**: a consumer keying only on
    the exit code still greens over a lost run. That is now the documented contract, and this
    test is where it is written down — so a later change that quietly made the exit code move
    would fail here rather than pass unnoticed.
    """
    histories = tmp_path / "flight"
    histories.mkdir()
    log = histories / "h.jsonl"
    runprov.configure(root=histories, run_log=log, auto_steps="off")
    with runprov.Run("good", {}, provenance=histories / "p1.json"):
        pass
    #: ENTERED AND NOT EXITED, which is the state a SIGKILL leaves behind — the audit reproduced
    #: it with a real `os.kill(os.getpid(), SIGKILL)` and the file on disk is the same shape: a
    #: `runprov.start.v1` line whose `run_uid` never gets a record. Built in process so the suite
    #: needs no subprocess, and released in the `finally` so nothing is left for a later test.
    lost = runprov.Run("lost", {}, provenance=histories / "p2.json")
    lost.__enter__()
    try:
        written = [
            json.loads(line)
            for line in log.read_text(encoding="utf-8").splitlines()
            if line.strip()
        ]
        starts = [r for r in written if r.get("schema") == "runprov.start.v1"]
        ended = {r.get("run_uid") for r in written if r.get("schema") != "runprov.start.v1"}
        unpaired = [r for r in starts if r.get("run_uid") not in ended]
        assert len(unpaired) == 1 and unpaired[0]["script"] == "lost", (
            f"the premise: exactly one run started and has no ending on record: {written}"
        )

        policy_file = _policy_file(tmp_path / "finished.json", "finished_ok")
        capsys.readouterr()
        code = runprov.__main__.main(
            ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
        )
        body = json.loads(capsys.readouterr().out)

        #: 1. IT IS NAMED, in a field and in the sentence. This is the whole of the fix.
        assert body["unfinished"] == 1, (
            f"[K-08] a run started with no ending on record, and the payload counts it in no "
            f"field: {body}"
        )
        assert body["cannot_check"] is not None, (
            "[ADR-0017 R-8] `cannot_check: null` is documented as *looked and found nothing "
            f"missing*, and one run was never examined: {body}"
        )
        assert "started with no ending on record" in body["cannot_check"], body["cannot_check"]
        assert "runprov log" not in body["cannot_check"], (
            "the sentence names the fact, not another command's output"
        )

        #: 2. AND THE VERDICT DOES NOT MOVE. Taylor's ruling, asserted as the thing a later
        #: change must not do: the rule is met over every run the gate examined, and one lost run
        #: must not fail this project's gate for ever over a record nobody can amend.
        assert (body["outcome"], body["exit_code"], code) == (runprov.policy.MET, 0, 0), (
            f"[K-08] Taylor's ruling is NAME IT, NEVER CHANGE THE VERDICT — the start line is "
            f"append-only and `runprov prune` does not clear it, so an `outcome` arm here pins a "
            f"project at exit 2 for ever after one power cut: {body}"
        )
        assert body["runs"] == 1 and body["rules"][0]["evaluated"] == 1, (
            f"and the examined count is unchanged: a start line still reaches no rule, because a "
            f"line carrying no `outputs`, `inputs` or `git_status_captured` makes EVERY rule "
            f"answer CANNOT_CHECK, which is exit 2 by another route: {body}"
        )

        #: 3. THE PAGE SAYS IT TOO, because a state asserted in one rendering is unasserted in
        #: the other — J-04's row, and ADR-0017 R-1 is one builder and two views.
        capsys.readouterr()
        assert runprov.__main__.main(["gate", "--policy", str(policy_file), "--log", str(log)]) == 0
        page = capsys.readouterr().out
        assert "COULD NOT CHECK" in page and "started with no ending on record" in page, page
        assert "GATE: MET (exit 0)" in page, page
    finally:
        lost.__exit__(None, None, None)

    #: 4. AND A WHOLE HISTORY STILL SAYS `null`, which is the positive companion: without it this
    #: test would pass against a clause that fires unconditionally, and *nothing was missing* has
    #: to stay sayable or the field means nothing.
    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
    )
    whole = json.loads(capsys.readouterr().out)
    assert (whole["unfinished"], whole["cannot_check"], code) == (0, None, 0), (
        f"the run that was in flight has ended, so the gate looked and found nothing missing: "
        f"{whole}"
    )


@requires_unreadable_files
def test_a_history_that_cannot_be_read_is_an_answer_and_not_a_traceback(tmp_path, capsys):
    """[ADR-0018 R-2] [ADR-0017 R-15] Audit K, K-23. The third state beside there and not there.

    **THE DEFECT.** A history that exists and cannot be READ raised out of `_gate` uncaught: a
    raw traceback, **zero bytes on stdout**, and **exit 1**. Reproduced with `chmod 000`. Both
    signals are false. R-15 gives silence on stdout one meaning — *the invocation was wrong, this
    command never had a question* — and the invocation HAD a question: a policy that loaded and a
    history it was told to read. And exit 1 is L-81's code for *a rule was checked and your
    controls were violated*, about a file nothing ever opened a line of.

    **ON THIS PROJECT IT IS NOT HYPOTHETICAL.** An EIO from the external drive this repository
    lives on is an `OSError` on the same path, so a failing disk made the gate report a policy
    violation. `show` crashes identically and inherits no handler, but only `gate` reserves exit
    1 for *checked and violated*.

    **IT NEEDS ITS OWN FIELD AND BOTH AVAILABLE REUSES PRINT A FALSE SENTENCE** — which is the
    half of this row a skeptic had to add. `found=False` prints *there is no run history at …*
    about a file that is right there, and collapses the ADR-0017 R-8 distinction `found` exists
    to keep; `unreadable=1` prints *1 line(s) of the history could not be read* about a file
    whose lines were never reached. So `read_error` is a field of its own, and it lands before
    0.8.0 because `runprov.gate.v1` freezes at upload.
    """
    _, log = _gated_history(tmp_path)
    policy_file = _policy_file(tmp_path / "p.json", "finished_ok")

    #: THE ANSWERED STATE FIRST, so the comparison below is against a measured baseline rather
    #: than against an expectation — and so a fixture that had stopped producing a readable
    #: history could not make the unreadable case look like a repair.
    capsys.readouterr()
    assert (
        runprov.__main__.main(
            ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
        )
        == 1
    ), "the premise: this history is readable and holds a run that really failed"
    before = json.loads(capsys.readouterr().out)
    assert (before["found"], before["read_error"]) == (True, None), before

    log.chmod(0o000)
    try:
        capsys.readouterr()
        code = runprov.__main__.main(
            ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
        )
        shown = capsys.readouterr()
        #: 1. IT IS AN ANSWER: a payload on stdout, not a traceback and not silence.
        assert shown.out.strip(), (
            "[ADR-0017 R-15] silence on stdout says the invocation had no question in it, and "
            f"this one had a policy and a history: {shown.err[-300:]}"
        )
        body = json.loads(shown.out)
        #: 2. AND IT IS EXIT 2, NOT 1. L-81: 1 is *checked and violated*.
        assert (code, body["exit_code"], body["outcome"]) == (2, 2, runprov.policy.CANNOT_CHECK), (
            f"[K-23] exit 1 says a control failed, about a file nothing opened: {body}"
        )
        #: 3. THE SENTENCE IS TRUE OF WHAT HAPPENED, which is why neither reuse would do.
        assert body["read_error"], f"[K-23] the failure must be named: {body}"
        assert body["found"] is True, (
            "[ADR-0017 R-8] the history IS there — `found=False` would print *there is no run "
            f"history at …* about a file a reader can see: {body}"
        )
        assert body["unreadable"] == 0, (
            "and no LINE was unreadable: not one was reached, so a count of them would be a "
            f"second false sentence: {body}"
        )
        assert body["cannot_check"] and str(log) in body["cannot_check"], body["cannot_check"]
        assert "could not be read" in body["cannot_check"], body["cannot_check"]
        assert "no run history at" not in body["cannot_check"], (
            f"the two states must not share a sentence: {body['cannot_check']}"
        )
        assert "line(s) of the history could not be read" not in body["cannot_check"], (
            f"nothing opened a line: {body['cannot_check']}"
        )
        #: 4. AND THE DIAGNOSTIC IS ON STDERR, so a caller parses stdout without stripping a line.
        assert "could not be read" in shown.err and str(log) in shown.err, shown.err

        #: 5. THE PAGE IS THE SAME ANSWER [ADR-0017 R-1].
        capsys.readouterr()
        assert runprov.__main__.main(["gate", "--policy", str(policy_file), "--log", str(log)]) == 2
        page = capsys.readouterr().out
        assert "COULD NOT CHECK" in page and "could not be read" in page, page
        assert "(NOT FOUND)" not in page, (
            f"the history is there; NOT FOUND is the other state's word: {page}"
        )
    finally:
        log.chmod(0o644)

    #: AND IT IS NOT PERMANENT, which is the difference from `unfinished` and the reason this one
    #: IS read by `outcome`: the mode is a fact about this invocation, so the next answer is the
    #: ordinary one again.
    capsys.readouterr()
    assert (
        runprov.__main__.main(
            ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
        )
        == 1
    )
    after = json.loads(capsys.readouterr().out)
    assert after == before, f"the same question over the same file answers the same way: {after}"


def test_the_read_error_arm_carries_the_reason_the_os_gave(tmp_path, capsys, monkeypatch):
    """Audit L, L-04. The arm `read_error` lands on had nothing holding what it carries.

    **THE DEFECT.** K-04's derived invariant was applied to the PARSER's refusal and never to
    `_gate`'s `read_error` arm, which has the identical host-supplied `strerror` shape.
    Measured: replace the OS's reason with the constant `"unavailable"` and the suite is
    **1 203 passed, rc=0** — the test above asserts only that the field is TRUTHY, and it
    exercises one failure mode. `runprov.gate.v1` freezes at upload, so the field is about to
    become permanent with nothing asserting it says anything.

    **THE FILED REMEDY WAS *exercise a second OS failure and assert the two tails differ*, and
    it is UNSATISFIABLE IN EITHER ORDER** — which is why this test has a different shape from
    its K-04 sibling. That sibling can compare two tails because `load()` meets two genuinely
    different OS failures, *absent* and *is a directory*. This arm meets one: before L-01's
    repair the unreadable-parent route did not reach it at all, and after L-01 it reaches it
    reporting the SAME `strerror` — *Permission denied*, both times, measured. A pair of tails
    that are equal by construction is a gate that cannot pass.

    **SO THE VALUE IS INJECTED RATHER THAN SUPPLIED BY THE HOST**, which is the
    change-verification bar and the only form that is both discriminating and honest here: the
    test chooses the string, so asserting it is not asserting what the platform or the locale
    happened to say. A constant in `strerror`'s place fails this on every platform and in every
    language, which is exactly what the K-04 tail comparison buys next door.

    **AND THE REAL FAILURE STAYS BESIDE IT.** The two tests above drive this arm from a real
    `chmod(0o000)` — the file's own mode and its parent's — so the wiring is proved live by an
    actual `OSError` from an actual filesystem, and this test proves the reason it carries is
    the reason it was given. Neither alone is enough: a mock can pass over dead wiring, and a
    real failure can pass over a discarded reason.
    """
    _, log = _gated_history(tmp_path)
    policy_file = _policy_file(tmp_path / "p.json", "finished_ok")
    chosen = "a reason this test chose and no OS would ever say"

    def _refuses(*args, **kwargs):
        raise OSError(errno.EIO, chosen)

    #: THE HISTORY IS READABLE AND THE READ IS WHAT FAILS, so the arm under test is reached
    #: through its own route rather than through the probe L-01 wrapped.
    assert log.is_file(), "the premise: the probe succeeds and the read is what raises"
    monkeypatch.setattr(runprov.__main__, "_counted", _refuses)

    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
    )
    shown = capsys.readouterr()
    body = json.loads(shown.out)
    assert (code, body["exit_code"], body["outcome"]) == (2, 2, runprov.policy.CANNOT_CHECK), body
    assert body["read_error"] == chosen, (
        f"[L-04] the OS said why and the field carries something else. A constant in "
        f"`strerror`'s place reaches here unchanged and nothing else in the suite sees it: "
        f"{body['read_error']!r}"
    )
    assert chosen in (body["cannot_check"] or ""), (
        f"[L-04] and it reaches the one sentence a consumer is pointed at: {body['cannot_check']}"
    )
    assert chosen in shown.err, f"[L-04] and the stderr diagnostic: {shown.err!r}"

    #: THE PAGE IS THE SAME ANSWER [ADR-0017 R-1], so the reason is not lost in the rendering
    #: that a person reads rather than parses.
    capsys.readouterr()
    assert runprov.__main__.main(["gate", "--policy", str(policy_file), "--log", str(log)]) == 2
    page = capsys.readouterr().out
    assert chosen in page, f"[L-04] the page drops the reason the payload carries: {page}"


@requires_unreadable_files
def test_a_history_in_an_unreadable_directory_is_the_same_answer(tmp_path, capsys):
    """[ADR-0018 R-2] Audit L, L-01. K-23's repair guarded the READ and not the PROBE.

    **THE HALF THAT SURVIVED.** The `except OSError` went around `list(_counted(...))`, below an
    unguarded `log.is_file()`. `Path.is_file()` swallows ENOENT, ENOTDIR, EBADF and ELOOP and
    nothing else, so **EACCES and EIO propagate out of the probe** — and the test above makes
    the FILE unreadable, which is the half that was fixed. Make the DIRECTORY unreadable and the
    probe is what fails: a raw `PermissionError`, zero bytes on stdout, exit 1, with the history
    sitting there intact. That is K-23's filed evidence verbatim, one `stat()` earlier.

    **AND IT IS THE LIKELIER ROUTE ON THIS HARDWARE**, which is K-23's own motivation: an EIO
    from the external drive this repository lives on is an `OSError` on the same path, and
    `stat()` is on that path. A dying disk reported a controls violation, with a traceback.

    **THE ANSWER MUST BE THE SAME ANSWER**, not a second shape for a second way of failing: the
    history IS there, so `found` stays True, no LINE was reached so `unreadable` stays 0, and
    the finding is `read_error`. The sibling test above asserts exactly this for the file's own
    mode; this one asserts the two routes are indistinguishable from the payload, because they
    are the same fact about the same file.
    """
    _, log = _gated_history(tmp_path)
    policy_file = _policy_file(tmp_path / "p.json", "finished_ok")

    #: THE ANSWERED STATE FIRST, measured rather than expected — the same ordering as the
    #: sibling, and for the same reason: a fixture that had stopped producing a readable history
    #: would otherwise make the unreadable case look like a repair.
    capsys.readouterr()
    assert (
        runprov.__main__.main(
            ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
        )
        == 1
    ), "the premise: this history is readable and holds a run that really failed"
    before = json.loads(capsys.readouterr().out)
    assert (before["found"], before["read_error"], before["unreadable"]) == (True, None, 0), before

    #: THE PARENT, NOT THE FILE. The file's own mode is untouched here, which is what makes this
    #: a different route and not a restatement.
    log.parent.chmod(0o000)
    try:
        capsys.readouterr()
        code = runprov.__main__.main(
            ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
        )
        shown = capsys.readouterr()
        assert shown.out.strip(), (
            "[L-01] the probe raised out of the command: no payload, and exit 1 about a file "
            f"nothing opened: {shown.err[-300:]}"
        )
        body = json.loads(shown.out)
        assert (code, body["exit_code"], body["outcome"]) == (2, 2, runprov.policy.CANNOT_CHECK), (
            f"[L-01] exit 1 says a control failed; a `stat()` that failed is not a control: {body}"
        )
        assert body["read_error"], f"[L-01] the failure must be named: {body}"
        assert body["found"] is True, (
            f"[ADR-0017 R-8] the history is there and intact, and still listed: {body}"
        )
        assert body["unreadable"] == 0, f"not one line was reached, so a count of them lies: {body}"
        assert "could not be read" in (body["cannot_check"] or ""), body["cannot_check"]
        assert "no run history at" not in (body["cannot_check"] or ""), body["cannot_check"]
    finally:
        log.parent.chmod(0o755)

    #: AND NOT PERMANENT: the mode is a fact about this invocation.
    capsys.readouterr()
    assert (
        runprov.__main__.main(
            ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
        )
        == 1
    )
    assert json.loads(capsys.readouterr().out) == before, "the same question answers the same way"


@pytest.mark.parametrize(
    "shape",
    [
        "absent",
        "enotdir",
        pytest.param("eloop", marks=requires_symlinks),
    ],
)
def test_a_path_that_names_nothing_is_not_a_history_that_cannot_be_read(shape, tmp_path, capsys):
    """Audit L, L-01's trap, and it is the reason the PROBE is wrapped rather than rewritten.

    **THE REMEDY AS FILED SAID: *ENOENT keeps `found=False`, any other OSError becomes
    `read_error`*. THAT IS DEFECTIVE**, and the defect is in this test. Three errnos describe a
    path that NAMES NOTHING, not a file that cannot be read:

        ENOENT   nothing at that name
        ENOTDIR  a path component that is not a directory (`plain-file/under`)
        ELOOP    a symlink cycle, which resolves to no file at all

    Enumerate "any OSError but ENOENT" and the last two flip to `found=True` with a
    `read_error` — the gate then says *the history is there and I could not read it* about a
    path that does not exist, which is the exact false sentence `found` exists to prevent, and
    ADR-0017 R-8's distinction collapses in the other direction.

    **THOSE THREE ARE `Path.is_file()`'s OWN IGNORE SET.** So the fix is to let `is_file()`
    answer and wrap it — catching only what it declines to swallow — rather than to re-implement
    its ignore list in a `catch` clause where it can drift. This test is what holds that choice:
    it is green for the wrapped form and red for the enumerated one.

    **The third form — drop the probe and let the read decide — HANGS**, because `open()` on a
    FIFO blocks forever, so it has no test here and must never be written.
    """
    if shape == "absent":
        log = tmp_path / "nowhere.jsonl"
    elif shape == "enotdir":
        plain = tmp_path / "plain"
        plain.write_text("not a directory\n", encoding="utf-8")
        log = plain / "history.jsonl"
    else:
        one, two = tmp_path / "loop-a", tmp_path / "loop-b"
        one.symlink_to(two)
        two.symlink_to(one)
        log = one

    policy_file = _policy_file(tmp_path / "p.json", "finished_ok")
    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(policy_file), "--log", str(log), "--format", "json"]
    )
    shown = capsys.readouterr()
    body = json.loads(shown.out)
    assert (code, body["outcome"]) == (2, runprov.policy.CANNOT_CHECK), body
    assert body["found"] is False, (
        f"[L-01] {shape} names no file, so this is the NOT FOUND state. `found=True` with a "
        f"`read_error` would be the gate reporting an unreadable history that does not "
        f"exist: {body}"
    )
    assert body["read_error"] is None, (
        f"[L-01] {shape}: there is nothing here to have failed to read: {body}"
    )
    assert "no run history at" in (body["cannot_check"] or ""), body["cannot_check"]
    assert "no run history at" in shown.err, shown.err


def test_the_payload_carries_the_policy_and_it_is_a_projection_not_a_second_parse(tmp_path, capsys):
    """[ADR-0018 R-13] T-34. Taylor's ruling, and the question's own answer is the shape.

    **What was established before the ruling:** the payload already contained every field of the
    normalised policy. Each rule row carries `rule` and `why`, which is exactly what `load()`
    returns, so *emit the policy as well* was already true in substance — interleaved with the
    verdicts rather than absent. What the key adds is a SHAPE, not data: the control as a
    separable object, archivable and diffable without being reassembled from the verdicts.

    **SO THE ASSERTION IS EQUALITY WITH THE PARSER'S OWN OUTPUT**, which is the only form that
    cannot be satisfied by a second parse that agrees today. `load()` is asked the same question
    and the two must match exactly — and the rows and the projection must agree field by field,
    so a `why` cannot say one thing in the control and another beside the verdict.

    ADR-0017 R-10 is the rule this shape exists to respect: one builder, two views. H1-6 is the
    row where one fact computed twice disagreed with itself; `matched` is the row where two
    builders invented one name.
    """
    _, log = _gated_history(tmp_path)
    written = _policy_file(tmp_path / "three.json", "finished_ok", "clean_tree", "inputs_verify")
    capsys.readouterr()
    runprov.__main__.main(["gate", "--policy", str(written), "--log", str(log), "--format", "json"])
    body = json.loads(capsys.readouterr().out)

    assert body["policy"] == runprov.policy.load(written), (
        "[ADR-0018 R-13] the payload's `policy` must be the parser's own output, asked the same "
        f"question and answered the same way: {body['policy']}"
    )
    #: AND IT CARRIES NOTHING ELSE. A verdict leaking into the control would make the archived
    #: object a result, which is the one thing it must not be — and `_RULE_KEYS` is what governs
    #: that, the same constant the parser accepts, so the projection cannot name a field a policy
    #: may not carry.
    for entry in body["policy"]["rules"]:
        assert set(entry) == set(runprov.policy._RULE_KEYS), (
            f"[ADR-0018 R-13] the control must be the policy and not the result: {entry}"
        )
    #: THE TWO VIEWS AGREE FIELD BY FIELD, in order. This is the half a consumer would notice:
    #: a `why` that said one thing in the archived control and another beside the verdict.
    assert [e["rule"] for e in body["policy"]["rules"]] == [r["rule"] for r in body["rules"]]
    assert [e["why"] for e in body["policy"]["rules"]] == [r["why"] for r in body["rules"]]
    assert len(body["policy"]["rules"]) == 3, body["policy"]
    #: AND THE ASSESSMENT IT TRAVELLED WITH WAS NOT VACUOUS [K-25] — the premise this test's
    #: three siblings already assert and this one did not. MEASURED: truncating
    #: `_gated_history`'s log to produce zero records fails three of its four consumers and
    #: leaves THIS test green, because the projection is exercised either way.
    #:
    #: **STATED HONESTLY: no regression escapes the suite for want of this line**, since the
    #: siblings go red first. What it buys is that R-13 stops being satisfiable by an assessment
    #: of nothing — the control travelling beside no verdict at all is the archived-evidence
    #: equivalent of the vacuous green, and R-13's whole point is that the control is evidence.
    assert (body["runs"], body["unreadable"]) == (2, 0), (
        f"[K-25] the premise: two real runs, both read — a projection that travelled with a "
        f"vacuous assessment would prove nothing about R-13: {body['runs']}, {body['unreadable']}"
    )


def test_an_assessment_that_applied_no_control_says_so_in_both_properties():
    """[ADR-0018 R-3] T-34. `outcome` and `cannot_check` must agree about every state.

    **THEY DISAGREED ABOUT ONE [K-24]:** `outcome` guarded the no-rules case and `cannot_check`
    did not, so an assessment over a policy naming no rule answered CANNOT_CHECK, `exit_code` 2
    and `cannot_check` **null** — which is documented as *looked and found nothing missing* — with
    a page carrying no reason at all. `Verdict`'s own docstring calls a CANNOT_CHECK with no
    reason *indistinguishable from a bug*.

    **NOT REACHABLE THROUGH THE CLI, AND THAT IS NOT THE DEFENCE.** `_checked` refuses an empty
    `rules` list, so no policy file reaches this state. But `policy` is importable without the CLI
    BY DESIGN — `check`, `verify` and `report` are too — `assessment()` is public, `outcome`
    already treats the state as reachable, and a payload asserting two contradictory things about
    one state is wrong whoever built it.

    CONSTRUCTED DIRECTLY, because a property over a FIELD SET cannot be reached through a history:
    this is the second test in the suite to build an `Assessment` by hand, after K-01's, and it
    names every field for the same reason — a field added later raises here rather than defaulting
    into a state nothing varied.
    """
    empty = runprov.policy.Assessment(
        policy_path="policy.json",
        history="h.jsonl",
        found=True,
        read_error=None,
        runs=2,
        unreadable=0,
        unfinished=0,
        rules=(),
    )
    assert (empty.outcome, empty.exit_code) == (runprov.policy.CANNOT_CHECK, 2), empty
    assert empty.cannot_check, (
        "[K-24] the gate says it could not check and that nothing was missing, in one object: "
        "`cannot_check` is null over an assessment that applied no control at all"
    )
    assert "no rule" in empty.cannot_check, empty.cannot_check
    #: AND THE PAGE CARRIES IT, because a reason that exists only in the payload is a reason the
    #: person reading the report does not get.
    page = "\n".join(runprov.policy.render(empty))
    assert "COULD NOT CHECK" in page and "no control was applied" in page, page
    assert "GATE: CANNOT_CHECK (exit 2)" in page, page

    #: AND A NON-EMPTY POLICY IS UNAFFECTED — the clause fires on the state and not on the shape.
    one = empty._replace(
        rules=({**runprov.policy.assess("finished_ok", [{"status": "ok"}]), "why": _WHY},)
    )
    assert (one.outcome, one.exit_code, one.cannot_check) == (runprov.policy.MET, 0, None), one


def test_a_newline_in_a_record_or_a_policy_cannot_forge_a_line_on_the_page(tmp_path, capsys):
    """[ADR-0018 R-8] T-34. Every field that came from outside this source file is escaped.

    A newline inside one interpolated field forges WHOLE LINES on the page, and the line it
    forges below is `GATE: MET (exit 0)` **inside a VIOLATED report**. The exit code is right and
    the page is not, and a CI log scraped for `GATE:` reads the forged one first.

    **BOTH ROUTES, AND NEITHER IS ADVERSARIAL-ONLY.** A policy's `why` is whatever the laboratory
    wrote, and a paragraph of rationale is the most natural thing to write there — an innocent
    multi-line `why` garbles this page identically. A declared input path is stored verbatim and
    a newline is legal in one on POSIX.

    THE RECORD HALF IS A HISTORY LINE AND NOT A REAL FILE, so this runs on Windows too, where
    such a name cannot exist: `gate` reads the history, and a path does not have to be openable
    for a rule to name it in a sentence.

    THE CODEBASE ALREADY HELD THE FIX AND ITS ARGUMENT. `_render_unreadable` escapes before
    printing because *printing that raw hands the terminal whatever corrupted the file*; the
    transform is `_report.printable` now, because `policy.py` may not import `__main__` —
    `PolicyError`'s own docstring forbids it in those words.

    **AND THE PAYLOAD IS ASSERTED UNESCAPED**, which is the other half of being right:
    `json.dumps` escapes already, and a payload carrying pre-escaped text would hand a consumer a
    string that is not the one in the record.
    """
    forged = "GATE: MET (exit 0)"
    _, log = _gated_history(tmp_path)

    #: OVER THE CONCATENATION OF STDOUT AND STDERR [L-23], because that is what a CI log is.
    #:
    #: K-21's escaping did not cover stderr, and the stderr diagnostic K-23's repair ADDED
    #: forges the very line K-21 exists to prevent: reproduced with a history whose FILENAME
    #: carries a newline, stdout correctly showed **0** forged lines while stderr emitted a bare
    #: `GATE: MET (exit 0)` on its own line — **1** forged line — inside an invocation that
    #: exited 2. The guard's own docstring promised *every field that came from outside this
    #: source file is escaped*, a universal the code did not have, which is the K-31/K-36 defect
    #: class this same tranche fixed.
    #:
    #: **AND L-23's PROPOSED ASSERTION WAS REFUTED: it would be RED ON EVERY CLEAN RUN.** It
    #: asked for *the one-verdict-line assertion applied to `shown.err` as well as the page* —
    #: and a normal invocation puts **ZERO** `GATE:` lines on stderr, because R-4 gives the
    #: answer to stdout. Requiring one there fails every green gate. The TOTAL over both streams
    #: is the form that discriminates: measured **1 on a normal run and 2 on a forged one**, so
    #: it is red exactly when a line has been forged and never otherwise.
    #:
    #: SCOPED TO `--format text`, deliberately: `--format json` is `json.dumps`, which escapes
    #: already, and a payload carrying pre-escaped text would hand a consumer a string that is
    #: not the one in the record.
    def one_verdict_line(shown: pytest.CaptureResult, expected: list[str]) -> None:
        both = shown.out + shown.err
        assert [line for line in both.splitlines() if line.startswith("GATE:")] == expected, (
            "[K-21, L-23] stdout and stderr together must carry exactly ONE verdict line, and "
            "it must be the real one — a forged `GATE:` line is read first by anything scraping "
            "a CI log, and a CI log is one stream:\n" + both
        )
        assert forged not in both.splitlines(), (
            f"[K-21] a line reading exactly {forged!r} was forged:\n{both}"
        )
        assert forged in both, (
            "and the text is still SHOWN to the reader rather than dropped — escaping is not "
            f"censoring:\n{both}"
        )
        assert "\\n" in both, f"the newline must travel as an escape, visibly:\n{both}"

    #: ROUTE ONE: THE POLICY'S OWN `why`, which `--emit-policy` prints too — where it printed
    #: verdicts for a rule the policy does not contain, over runs that command promises never to
    #: read.
    written = tmp_path / "forge.json"
    written.write_text(
        json.dumps({"rules": [{"rule": "finished_ok", "why": f"a complete run\n{forged}"}]}),
        encoding="utf-8",
    )
    capsys.readouterr()
    assert runprov.__main__.main(["gate", "--policy", str(written), "--log", str(log)]) == 1, (
        "the premise: this history holds a failed run, so the gate is VIOLATED"
    )
    one_verdict_line(capsys.readouterr(), ["GATE: VIOLATED (exit 1)"])

    capsys.readouterr()
    assert runprov.__main__.main(["gate", "--policy", str(written), "--emit-policy"]) == 0
    emitted = capsys.readouterr().out
    assert forged not in emitted.splitlines() and forged in emitted, (
        f"[K-21] `--emit-policy` renders the same `why` and must escape it too:\n{emitted}"
    )

    #: ROUTE TWO: A DECLARED INPUT PATH, recorded exactly as it was handed to `run.input`.
    sneaky = f"data/in.tsv\n{forged}"
    with log.open("a", encoding="utf-8") as fh:
        fh.write(
            json.dumps(
                {
                    "schema": runprov.HISTORY_SCHEMA,
                    "run_uid": "forged",
                    "script": "sneak",
                    "status": "ok",
                    "started_utc": "2026-10-03T00:00:00Z",
                    "finished_utc": "2026-10-03T00:00:01Z",
                    "inputs": [{"path": sneaky, "content_sha256": "0" * 64}],
                }
            )
            + "\n"
        )
    verifying = _policy_file(tmp_path / "iv.json", "inputs_verify")
    capsys.readouterr()
    code = runprov.__main__.main(["gate", "--policy", str(verifying), "--log", str(log)])
    shown = capsys.readouterr()
    assert code == 2, (
        f"a declared input that is not on disk is CANNOT_CHECK, not a breach: {shown.out}"
    )
    one_verdict_line(shown, ["GATE: CANNOT_CHECK (exit 2)"])

    #: ROUTE THREE: THE HISTORY'S OWN FILENAME, which reaches no page at all — it reaches the
    #: stderr diagnostic. NO FILE IS CREATED, which is both the point and what makes this run on
    #: every platform: the finding is that there is nothing to read there.
    absent = tmp_path / f"missing\n{forged}\nhistory.jsonl"
    capsys.readouterr()
    assert runprov.__main__.main(["gate", "--policy", str(verifying), "--log", str(absent)]) == 2, (
        "a history that is not there is CANNOT_CHECK"
    )
    one_verdict_line(capsys.readouterr(), ["GATE: CANNOT_CHECK (exit 2)"])

    #: ROUTE FOUR: THE POLICY'S OWN FILENAME, and this is the one L-23's list of three missed —
    #: `gate: {exc}`, where `PolicyError` names the file it could not read. STDOUT IS SILENT
    #: HERE by ADR-0017 R-15 — the policy IS the question, so without one there is nothing to
    #: answer about — which is why the expected total is ZERO rather than one. A list of
    #: diagnostics is the shape L-03 criticises one row earlier; `_diag` is the derivation.
    capsys.readouterr()
    nameless = tmp_path / f"nope\n{forged}\npolicy.json"
    assert runprov.__main__.main(["gate", "--policy", str(nameless), "--log", str(log)]) == 2
    refused = capsys.readouterr()
    assert refused.out == "", f"[ADR-0017 R-15] silence on stdout is the signal: {refused.out!r}"
    one_verdict_line(refused, [])

    #: AND THE PAYLOAD CARRIES THE RECORD'S OWN STRING, newline and all. A consumer comparing it
    #: with the record would not match a page-escaped copy.
    capsys.readouterr()
    runprov.__main__.main(
        ["gate", "--policy", str(verifying), "--log", str(log), "--format", "json"]
    )
    body = json.loads(capsys.readouterr().out)
    said = [reason for row in body["rules"] for reason in row["blocked"]]
    assert any(sneaky in reason for reason in said), (
        f"[ADR-0017 R-1] the payload is not escaped — `json.dumps` already did it, and the string "
        f"a consumer reads must be the one the record holds: {said}"
    )


#: THE FORGERY, and it is one string so that every renderer is attacked with the same one.
#: `\n` forges a whole line; `\r` is the half a line-count oracle cannot see, because it
#: overwrites the line already printed instead of adding one; `\x1b[2K` is a terminal escape
#: that erases it. All three are "not printable and not a space", which is the property.
#:
#: AND A U+00A0, WHICH IS NOT AN ATTACK AT ALL [Audit N, writer-6]. The non-breaking space is
#: the character French typography puts before `:` `;` `!` `?` and that Word and LibreOffice
#: insert on their own, so it is the likeliest thing to arrive in a policy's `why` from a
#: laboratory in Créteil. `printable` escapes it -- `"\xa0".isprintable()` is False -- and that
#: decision was argued in a docstring and held by NOTHING. Putting it HERE is what makes the
#: COUPLING falsifiable: this oracle's own rule is `c.isprintable() or c in " \n"`, so widening
#: production to let the `Zs` category survive turns this property RED on the escaped page
#: instead of being a sentence someone has to remember. Measured both ways: with this character
#: in the fixture and production unchanged the suite is green, and with production widened it
#: fails naming `['\xa0']`; with a fixture that does NOT carry it, the same widening is green.
_FORGED_LINE = "GATE: MET (exit 0)"
_FORGERY = f"\n{_FORGED_LINE}\n\rverdict\xa0: OK\x1b[2K"


#: WHERE THE FORGERY IS PLANTED. A declared list, and it is the ATTACK rather than the check —
#: the check is the property below, which names no field at all. Four kinds of value a page
#: interpolates: a path a run declared, free text a caller wrote, a label the environment
#: supplied, and a failure's own words.
#:
#: `script`, `status`, `run_uid`, the digests and the schema are left ALONE on purpose: they are
#: the keys every recipe looks a run up BY, so forging them would make `diff align genotype`,
#: `show align` and `report out/summarise.tsv` find nothing and the attack would reach no page.
#: `outputs[].path` is left alone for the same reason — it is how `report` joins an artifact to
#: the run that made it.
#:
#: AND THAT REASON IS FALSE FOR `impact` [Audit M, escape-3], which is why it held nothing while
#: `impact.render` was forgeable: `impact` looks a run up BY ITS INPUT BYTES, not by `script`, so
#: a forged `script` reaches its rebuild-order page intact. The clean-name requirement is a fact
#: about the OTHER recipes, not about this exclusion as a whole. The leg that covers it is
#: `test_every_renderer_main_prints_escapes_at_a_chokepoint`'s forged-`script` channel below,
#: which plants the forgery in `script` on a run `impact` and `lineage` both print.
_FORGE_INTO = (
    ("command",),
    ("cwd",),
    ("history_destination",),
    ("code", "project_root"),
    ("code", "git_branch"),
    ("code", "script_file"),
    ("environment", "manager"),
    ("failure", "type"),
    ("failure", "message"),
)


def _forge(record):
    """One record, with the forgery in every field `_FORGE_INTO` names that it carries."""
    for path in _FORGE_INTO:
        node = record
        for key in path[:-1]:
            node = node.get(key) if isinstance(node, dict) else None
            if not isinstance(node, dict):
                break
        else:
            if isinstance(node.get(path[-1]), str):
                node[path[-1]] = f"{node[path[-1]]}{_FORGERY}"
    for entry in record.get("inputs") or []:
        if isinstance(entry.get("path"), str):
            entry["path"] = f"{entry['path']}{_FORGERY}"
    #: DISTINCT PER RUN, so `diff` has something to REPORT. Two runs carrying identical
    #: forged parameters compare `unchanged` and the renderer prints a count rather than the
    #: values — green while the page it renders is forgeable.
    mine = str(record.get("script", "?"))
    record["parameters"] = {f"p{_FORGERY}": f"{mine}{_FORGERY}"}
    record["notes"] = {f"n{_FORGERY}": f"{mine}{_FORGERY}"}
    record["seeds"] = {f"numpy{_FORGERY}": 1}
    obs = record.get("observation")
    if isinstance(obs, dict):
        obs["unregistered_reads"] = [f"sneak.csv{_FORGERY}"]
    return record


def _can_name_a_file_with_a_newline(tmp_path) -> bool:
    """Can a name on THIS filesystem carry the forgery? PROBED, NOT ASKED.

    The same rule as `_can_symlink` and `_chmod_denies_read` at the top of this file:
    `sys.platform == "win32"` is the wrong question, because the answer is a property of the
    filesystem and not of the interpreter. 0x00 to 0x1F are illegal in an NTFS name and legal in
    a POSIX one, so a Windows host refuses this and a Linux host allows it — and an exotic
    mount could do either.

    **A SKIPPED LEG HERE IS CORRECT SCOPING AND NOT A BLIND SPOT**, which is why the legs it
    guards say so where they are added: on a host that cannot hold such a name, the defect
    those legs attack CANNOT EXIST. An artifact file and a source file both have to be
    created for the walk to find them, so the attack has no channel. The legs that need no
    file — a forged `script`, a forged `runprov.start.v1` line, a forged argv argument — are
    unguarded and run everywhere, which is where this family's reachable routes are anyway.
    """
    probe = tmp_path / f"probe{_FORGERY}.txt"
    try:
        probe.write_text("x", encoding="utf-8")
    except (OSError, ValueError):
        return False
    probe.unlink()
    return True


def _forged_history(tmp_path):
    """A REAL tree, written by this package, with the forgery injected into the history after.

    Real runs rather than hand-written records, and the reason is a measurement: a hand-built
    history cannot be POINTED AT by half the recipes. `report` joins an artifact to the run that
    made it through the artifact's own pin, and `verify` re-derives that pin from the file — so
    without real pinned artifacts both commands stop at NO PIN before reaching any field a
    forgery could sit in, and reverting their escaping stayed GREEN. The attack has to reach the
    page it is attacking.

    AND TWO LEGS WERE VACUOUS ANYWAY UNTIL AUDIT M MEASURED THEM, which is the half this
    docstring got wrong by being half-right. `verify` produced a **255-byte refusal page** and
    `check` a **194-byte** one: the artifacts were written with `write_text` and never
    `run.header()` or `run.open_output()`, so `verify` stopped at `NOTHING CHECKED: none
    carries a pin` BEFORE any renderer line ran, and there was no `.py` file under the tree at
    all, so `check` reported `NOTHING WAS CHECKED`. Reverting either renderer's escaping stayed
    green. So the outputs are opened through `open_output`, one input is CHANGED afterwards so
    there is a non-OK status line to print, and an entry point is written for `check` to find.

    THREE CHANNELS THE FIXTURE HAD NONE OF [Audit M, escape-5], and two of the three need no
    file, so they run on every platform:

    * a forged **`script`** on a run that reads `data/m.tsv`, so `impact` and `lineage` print
      it. `_FORGE_INTO` leaves `script` clean on purpose — the other recipes look runs up by
      it — so this is a run written with a forged name rather than a field edited after.
      `impact` looks a run up by its INPUT BYTES, which is why its exclusion did not apply.
    * a **`runprov.start.v1`** line whose `script` is forged, with **no record and no marker
      file**, which is how the in-flight banner reproduces. Invisible to both oracles before
      this: no corpus recipe produces an unfinished run.
    * an artifact **FILENAME** carrying the forgery, and a **`.py`** file whose name does —
      the two POSIX-only legs, each behind the probe above, each with its reason stated there.
      The source file's name must END in `.py` or the walk never sees it.
    """
    root = tmp_path / "forged"
    for sub in ("prov", "data", "out"):
        (root / sub).mkdir(parents=True)
    (root / "data" / "m.tsv").write_text("id\tv\n1\tx\n", encoding="utf-8")
    #: A SECOND INPUT, SO SOMETHING CAN GO STALE WITHOUT MOVING `m.tsv`. `impact data/m.tsv`
    #: finds its runs by that file's CURRENT bytes, so changing `m.tsv` to make `verify`
    #: interesting would make `impact`'s leg vacuous instead. This one is read by `align`
    #: alone and is rewritten at the end.
    (root / "data" / "n.tsv").write_text("id\tw\n1\tq\n", encoding="utf-8")
    log = root / "prov" / "history.jsonl"
    project = runprov.Project(root=root, run_log=log, run_id=lambda: "r", generation=lambda: "g")
    for name in ("align", "genotype", "summarise"):
        with runprov.Run(
            name, project=project, provenance=root / "prov" / f"{name}.prov.json"
        ) as r:
            r.input(root / "data" / "m.tsv")
            if name == "align":
                r.input(root / "data" / "n.tsv")
            #: `open_output`, NOT `output`. It writes the pin, which is what `verify` and
            #: `report` re-derive from the file; without it both stop at NO PIN.
            #: NO SECOND POSITIONAL. `open_output(path, "w")` passes `"w"` as the pin's
            #: COMMENT PREFIX — there is no mode parameter — and a pin anchored behind `w`
            #: instead of `# ` is one `verify` reads as NO PIN. Measured while building this
            #: fixture: four artifacts pinned out of five, and the forged-name leg silent.
            with r.open_output(root / "out" / f"{name}.tsv") as fh:
                fh.write("id\tv\n1\ty\n")
    with contextlib.suppress(ValueError):
        with runprov.Run("boom", project=project, provenance=root / "prov" / "boom.prov.json"):
            raise ValueError("it broke")
    #: A RUN WHOSE SCRIPT NAME IS FORGED AND WHICH READS `m.tsv`, so `impact data/m.tsv` and
    #: `lineage` both print it. `script` is caller-supplied and needs no file, so this leg is
    #: platform-neutral — the only one of escape-1/2/3's channels that is.
    with runprov.Run(
        f"rebuild{_FORGERY}", project=project, provenance=root / "prov" / "rebuild.prov.json"
    ) as r:
        r.input(root / "data" / "m.tsv")
        #: AND IT READS ANOTHER RUN'S OUTPUT, so `lineage` has an EDGE to print. Measured:
        #: without this the forged script reached `impact` and not `lineage` — `lineage` prints
        #: edge lines only, and a run whose inputs are all orphans contributes none, so its leg
        #: was green over a page with no script name on it.
        r.input(root / "out" / "genotype.tsv")
        with r.open_output(root / "out" / "rebuild.tsv") as fh:
            fh.write("id\tv\n1\tz\n")
    #: THE TWO POSIX-ONLY CHANNELS COME BEFORE `measured`, AND THE ORDER IS THE WHOLE
    #: POINT [Audit N, guards-2]. `resources` picks the MOST RECENT run carrying a
    #: measurement, so while the clean `named` run was created after `measured{_FORGERY}`
    #: it won that pick on every host where the probe is TRUE — which is every host the
    #: gate runs on — and `_resources_text` was handed no forged line at all. The leg was
    #: VACUOUS on POSIX and `vacuous` could not say so, because it only inspects names that
    #: are IN `carried` and `resources` interpolates no other field. Measured: a PARTIAL
    #: regression — `printable_lines` on every line but the header, the one line that
    #: interpolates `script` and `run_id` straight off the record — was RC=0 locally and on
    #: SEVEN of the eight matrix jobs, red only on `windows-latest / 3.12`, the one leg where
    #: the probe is false. With these two created FIRST, `measured{_FORGERY}` is the most
    #: recent measured run on BOTH branches, so the probe no longer decides whether a
    #: renderer is attacked.
    if _can_name_a_file_with_a_newline(tmp_path):
        #: THE TWO POSIX-ONLY CHANNELS, behind the probe and for the reason it states: on a
        #: host whose names cannot hold a control character, neither file can be created and
        #: the defect they attack cannot exist. The source file's name must END in `.py`.
        (root / f"flagged\n{_FORGED_LINE}\nx.py").write_text(
            'if __name__ == "__main__":\n    open("data/m.tsv")\n', encoding="utf-8"
        )
        with runprov.Run(
            "named", project=project, provenance=root / "prov" / "named.prov.json"
        ) as r:
            r.input(root / "data" / "n.tsv")
            #: THE NEWLINE ALONE IN THE NAME, AND THE FULL FORGERY WOULD MAKE THIS LEG
            #: VACUOUS — measured, which is the only reason this differs from every other
            #: channel. `_FORGERY` is four lines long, so an artifact whose NAME contains it
            #: gets a sidecar whose first line (`# provenance for: <name>`) spans four lines
            #: and pushes `PIN_ANCHOR` past `PIN_STARTS_WITHIN`: `verify` then reports NO PIN
            #: and never reaches `render_report` at all. With the newline alone the anchor is
            #: on line 4 and the pin reads. The newline is also the right character here — it
            #: is the one that forges a line and the one `_acted_on` cannot see.
            with r.open_output(root / "out" / f"clean.tsv\n{_FORGED_LINE}\nx") as fh:
                fh.write("id\tv\n1\tn\n")

    #: AND ONE RUN WHOSE SCRIPT NAME IS ITSELF FORGED, last in the history. `resources` picks
    #: the most recent run carrying a measurement and interpolates only `script` and `run_id`,
    #: so it is the one renderer the forgery cannot reach through any other field — and leaving
    #: `script` clean everywhere made reverting its escaping GREEN, measured. The lookups the
    #: other recipes use are by `align`, `genotype` and `summarise`, which this does not touch.
    with runprov.Run(
        f"measured{_FORGERY}", project=project, provenance=root / "prov" / "last.prov.json"
    ):
        pass

    #: AN ENTRY POINT FOR `check` TO FIND. Without one the page is `NOTHING WAS CHECKED` and
    #: the renderer's list branches never run — that is the 194-byte vacuous leg.
    (root / "entry.py").write_text(
        'import sys\n\nif __name__ == "__main__":\n    open("data/m.tsv")\n', encoding="utf-8"
    )
    rows = [
        _forge(json.loads(line))
        for line in log.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    #: A `runprov.start.v1` LINE WITH A FORGED `script`, NO RECORD AND NO MARKER FILE. This is
    #: the in-flight banner's channel, and the skeptic's measurement is that it needs no marker
    #: at all: a start with no ending and no marker reads as INTERRUPTED without further
    #: enquiry, which is `_InFlightScan.report`'s own stated rule.
    started = [r for r in rows if r.get("schema") == runprov.run.START_SCHEMA]
    assert started, "the premise: this package writes a start line per run"
    orphan = dict(started[0])
    orphan["script"] = f"interrupted{_FORGERY}"
    orphan["run_uid"] = "0" * 16
    rows.append(orphan)
    log.write_text("".join(json.dumps(r) + "\n" for r in rows), encoding="utf-8")
    #: NO MARKERS AT ALL, so the banner is driven by the history line alone.
    shutil.rmtree(root / "prov" / ".incomplete", ignore_errors=True)
    #: AND NOW SOMETHING IS STALE, so `verify` and `report` print a status line instead of a
    #: refusal. `n.tsv` is read only by `align` and by the forged-filename run.
    (root / "data" / "n.tsv").write_text("id\tw\n1\tCHANGED\n", encoding="utf-8")
    (root / "policy.json").write_text(
        json.dumps(
            {
                "rules": [
                    {"rule": name, "why": f"a control this laboratory states{_FORGERY}"}
                    for name in sorted(runprov.policy.rules())
                ]
            }
        ),
        encoding="utf-8",
    )
    return root


def _acted_on(text: str) -> list[str]:
    """Every character a terminal would ACT on rather than show. The property, in one line."""
    return sorted({repr(c) for c in text if not (c.isprintable() or c in " \n")})


def test_the_non_breaking_spaces_are_escaped_and_the_oracle_says_the_same(tmp_path):
    r"""THE LINE escape-7 DECLINED, AND THE REASON IT WAS DECLINED IS NOW A MEASUREMENT
    [Audit N, writer-6]. The question Audit M handed to this audit: is `printable` escaping
    U+00A0 a decision or an accident?

    It is a decision, and the reason is a COUPLING rather than a preference. `printable`'s
    predicate is `c.isprintable() or c == " "`; the escaping property's oracle `_acted_on` above
    is `c.isprintable() or c in " \n"`. Neither admits U+00A0, because `"\xa0".isprintable()` is
    **False** -- it is `Zs`, a separator, not a printable character. So the two agree, and if
    production were widened to `unicodedata.category(c) == "Zs"` the oracle would start calling a
    legitimate French `why` a forgery.

    **WORDING CORRECTION TO THE ROW:** the RED is latent only behind a widening of `printable`.
    There is nothing red at any revision in the tree, which is a different claim from "the
    recorded reason was wrong" -- the recorded reason was right and unheld. escape-7's control
    PASSED, meaning deleting the paragraph that argued it left the suite green, and that is what
    this closes.

    Two assertions and one coupling, which is all it takes: the behaviour, the other non-breaking
    space French typography uses, and the oracle's agreement. The forgery fixture now carries a
    U+00A0 of its own, so the coupling is also exercised on every page the property renders.
    """
    printable = runprov._report.printable
    assert printable("a\xa0b") == "a\\xa0b", (
        "U+00A0 is escaped, and this is the line Audit M declined to write. It is not an "
        "adversarial character -- it is what Word puts before a colon"
    )
    #: SPELLED AS AN ESCAPE, not as the character: ruff's RUF001 refuses a literal U+202F in
    #: a string because it is indistinguishable from a space on screen -- which is the
    #: property that makes it worth escaping in the first place.
    assert printable("a\u202fb") == "a\\u202fb", "and U+202F, the narrow one, for the same reason"
    assert printable("a b") == "a b", "an ordinary space survives, or every column is unreadable"

    #: THE COUPLING, ASSERTED RATHER THAN DESCRIBED. If production stopped escaping these, the
    #: escaping property's oracle would report them as characters a terminal acts on -- a RED
    #: over a legitimate `why` from a French laboratory, which is exactly why the narrow
    #: predicate was chosen. The two predicates have to move together, and this is what says so.
    assert _acted_on("contrôle\xa0: chaque run") == [repr("\xa0")], (
        "the oracle must consider an UNESCAPED U+00A0 a character a terminal acts on; if it "
        "stops, widening `printable` becomes silently safe and this coupling is gone"
    )
    assert _acted_on(printable("contrôle\xa0: chaque run")) == [], (
        "and the ESCAPED form must satisfy it, or the transform and the oracle disagree"
    )


def test_the_transform_is_imported_from_one_place():
    """`printable` LIVES IN ONE MODULE, derived instead of counted [Audit N, writer-8].

    `_report.printable`'s docstring said *"the nine modules that use it"* and `terminal.py`'s
    comment said *"Nine modules import them"*. Both were wrong in the same direction and both
    were unheld. The number was **ten** when the sentences were written, **eleven** by the time
    an audit measured it, and **ten again** once `run.py`'s redundant site-level call was deleted
    -- stale three times, once inside the tranche that corrected it. Thirteen answers a different
    question: who depends on `_report` at all.

    SO THE NUMBER IS GONE FROM BOTH SENTENCES and this holds the claim they were making, which
    was never the count: **there is one definition and every user imports it from there.** That
    cannot rot, because it is a property of the graph rather than a figure about it.

    **AND ONLY THE SECOND HALF OF THAT WAS EVER CHECKED** [Audit O, guards-11]. A second
    `printable` DEFINED in `terminal.py` was green here -- the *"two spellings of one property"*
    defect the module move was made for, in the test written to hold against it. The first half is
    asserted now: these two names are defined in `_report.py` and nowhere else in the package.

    **A CORRECTION TO THE ROW THAT FILED IT, because the next reader will otherwise trust the
    wrong half:** the row said the second definition stayed harmless *"until something imports it,
    and `elsewhere` would catch that import"*. That is true for `from .terminal import printable`
    and FALSE for `from . import terminal` followed by `terminal.printable(...)`, which `elsewhere`
    never sees because it reads `ImportFrom` names. That is the same recognition hole as guards-2's
    -- a sweep that reads imported NAMES is blind to a module imported as an object -- and it is
    closed here from the other end: there is no second definition for the unseen spelling to
    reach. The practical exposure was always low, because a second definition that BEHAVES
    differently is caught by the escaping property; the uncaught case is a second definition
    nothing uses, which is the one this now forbids outright.

    BY AST AND NOT BY `git grep`, which is not a style preference here: `terminal.py` carries
    `from ._report import printable` INSIDE A COMMENT, explaining that the import would be a
    cycle, so a textual sweep counts the explanation as a use. The bare-print guard learned the
    same lesson about a comment in the same module.
    """
    sources = sorted((REPO / "runprov").glob("*.py"))
    assert len(sources) == _PACKAGE_MODULES, (
        f"the glob found {len(sources)} modules; the package has {_PACKAGE_MODULES}"
    )
    importers: dict[str, set[str]] = {}
    elsewhere: dict[str, str] = {}
    for mod in sources:
        tree = ast.parse(mod.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if not isinstance(node, ast.ImportFrom):
                continue
            wanted = {a.name for a in node.names} & set(_CHOKEPOINTS)
            if not wanted:
                continue
            importers.setdefault(mod.name, set()).update(wanted)
            #: THE WHOLE CLAIM, in one comparison. `.` + `_report` and `runprov._report` are the
            #: same module and both are fine; anything else is a second definition or a
            #: re-export, which is the "two spellings of one property" defect `terminal.py`'s
            #: comment says this repository keeps finding.
            where = (node.module or "").split(".")[-1]
            if where != "_report":
                elsewhere[f"{mod.name}:{node.lineno}"] = f"imports {sorted(wanted)} from {where}"
    assert elsewhere == {}, (
        f"these import the escaping transform from somewhere other than `_report`: {elsewhere}. "
        f"It lives in `_report` because that module imports nothing from the package, which is "
        f"what lets every layer reach it"
    )
    assert "_report.py" not in importers, (
        "`_report` defines them; importing them back into itself would be the cycle that stops "
        "the package coming up"
    )
    #: NON-VACUITY, and derived rather than a floor: the module that OWNS the page-rendering
    #: surface must be among the importers, so a sweep that matched nothing cannot read as clean.
    assert "__main__.py" in importers and importers["__main__.py"] == set(_CHOKEPOINTS), (
        f"`__main__` prints the pages, so it must import both halves of the transform; the "
        f"sweep found {importers.get('__main__.py')} and matched {sorted(importers)}"
    )

    #: AND THE FIRST HALF OF THE CLAIM: ONE DEFINITION, IN `_report.py` [Audit O, guards-11].
    #: A `def` at any depth and a module-level rebind both count, because both make a second
    #: object reachable under the name this package relies on being one function. An import does
    #: NOT count -- `from ._report import printable` is 10 modules doing the right thing, and the
    #: `elsewhere` assertion above is what holds those.
    #:
    #: ONE EQUALITY, BOTH DIRECTIONS, AND THAT IS DELIBERATE: a name that stops being defined at
    #: all fails it, a name defined somewhere else fails it, and a name defined TWICE inside
    #: `_report.py` fails it too, because the sites are a list and not a set. A first draft of
    #: this compared a sorted key list against a numerically rebuilt one and could not pass.
    #:
    #: TWO LIMITS, BOTH MEASURED RATHER THAN GUESSED. A binding made inside a function body is
    #: local to that call and is not a second definition of anything, so it is out of scope. And
    #: the MISSING direction of this equality cannot actually be reached from here: renaming
    #: `printable_lines` in `_report.py` makes the package fail to import and this file reports a
    #: COLLECTION ERROR, RC=2, before any assertion runs -- the same limit the layer table
    #: declares for a module-level defect. What this equality really holds is the direction that
    #: has no other instrument: a SECOND definition, which nothing else in the suite can see.
    defined: dict[str, list[str]] = {}
    for mod in sources:
        tree = ast.parse(mod.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if node.name in _CHOKEPOINTS:
                    defined.setdefault(node.name, []).append(mod.name)
        for node in tree.body:
            rebound = (
                node.targets
                if isinstance(node, ast.Assign)
                else [node.target]
                if isinstance(node, ast.AnnAssign)
                else []
            )
            for target in rebound:
                if isinstance(target, ast.Name) and target.id in _CHOKEPOINTS:
                    defined.setdefault(target.id, []).append(mod.name)
    assert defined == {name: ["_report.py"] for name in _CHOKEPOINTS}, (
        f"the escaping transform must have exactly ONE definition each and it must be in "
        f"`_report.py`; the package defines them at {defined}. A second definition is the `two "
        f"spellings of one property` defect the move into `_report` was made to end, and nothing "
        f"above this line can see it: the importers half only reads what modules IMPORT"
    )


#: THE TWO FUNCTIONS EVERY PAGE MUST REACH. Named here because the derivation below asks
#: which renderers reach one of them, and a renderer is not allowed to be one of them.
_CHOKEPOINTS = ("printable", "printable_lines")

#: THE PAGES THAT ARE MACHINE FORMATS AND MUST NOT BE ESCAPED, with the reason each one is
#: here. `_report.printable`'s docstring states the rule — *THE JSON SIDE IS LEFT ALONE,
#: deliberately: `json.dumps` already escapes, and a payload carrying pre-escaped text would
#: hand a consumer a string that is not the one in the record* — and these are the renderers
#: on the other side of it that `__main__` nevertheless prints to a stream.
#:
#: HELD BY EQUALITY AGAINST THE DERIVATION, not merely listed: the test below asserts every
#: name here is still something `__main__` prints, so an exemption for a function that has
#: been renamed, deleted or stopped being printed fails this file rather than silently
#: covering nothing. Escaping any of them would corrupt the format — `#SBATCH --mem=4096M`
#: and a YAML mapping are read by Slurm, by Kubernetes and by `yaml.safe_load`, not by a
#: person scanning for a verdict.
_SERIALISERS = {
    ("export", "render"): "RO-Crate and PROV-JSON, written through json.dumps",
    ("resources", "render_k8s"): "a Kubernetes manifest, parsed as YAML by kubectl",
    ("resources", "render_slurm"): "an sbatch header, parsed by Slurm",
    ("show", "_yaml_entry"): "one entry of the transformation-log YAML document",
    ("show", "_yaml_header"): "the banner of the same YAML document",
    ("show", "render_yaml"): "`--format yaml`, the machine-readable view",
    #: SNAKEMAKE'S BENCHMARK COLUMNS, header and one row, joined with tabs and read by
    #: Snakemake's own benchmark parser and by every plotting script pointed at that TSV
    #: [Audit N, guards-1]. It is a MACHINE format on the far side of the same line the entry
    #: above states: escaping a cell would hand `pandas.read_csv` a value that is not the one
    #: in the record. It was in NEITHER the derived set nor this table until the derivation was
    #: widened to see a tuple binding, so it was an UNDECLARED exemption — the one shape this
    #: table exists to make impossible. `snakemake_row` interpolates only numbers today, so
    #: there is no live forging channel through it; this is a derivation defect, not a forgery.
    ("resources", "snakemake_row"): "Snakemake's benchmark TSV, parsed by Snakemake itself",
}


#: EVERY FORM PYTHON HAS FOR BINDING A NAME, WITH A DECISION FOR EACH OF THEM, AND AN
#: EXHAUSTIVENESS ASSERTION INSTEAD OF A FLOOR [Audit O, guards-4].
#:
#: The binder below used to read `ast.Assign` and nothing else, and the audit before this one
#: widened it to `Assign` with a TUPLE target. Both are enumerations of binding forms, and
#: `AnnAssign` was a LIVE, UNDECLARED false green: with `prune.render`'s chokepoint removed and
#: its print site written `page: str = prune_mod.render(...)`, the suite was RC=0 with the
#: coverage floor at baseline over a forgeable page in `prune` -- the one renderer no behavioural
#: leg may ever reach, because `prune` DELETES, so `CORPUS_NOT_READERS` excludes it by name and
#: the structural half exists FOR it. The binding forms this package uses today, counted by
#: nearest non-container owner of a `Name(ctx=Store)` across `runprov/`: `Assign` 1 176,
#: `AnnAssign` 300, `For` 248, `comprehension` 226, `AugAssign` 80, `withitem` 18, `NamedExpr` 8.
#: The binder enumerated ONE of those seven, then two.
#:
#: SO THE SHAPE HERE IS NOT A LONGER LIST. It is a decision per owner plus an assertion that
#: EVERY `Name(ctx=Store)` in the file has an owner this table decided about -- so a binding form
#: nobody has thought of turns this RED BY CONSTRUCTION rather than leaving a hole.
#:
#: THIS PARAGRAPH USED TO END *that is the one shape in this family that has never been defeated*,
#: AND THAT IS WITHDRAWN [Audit P, exhaustive-1]. It was defeated, four times, by a clean
#: full-suite false green. An exhaustiveness assertion is only as total as the PRIMITIVE it
#: quantifies over, and choosing that primitive is where the whole of the risk now sits: this one
#: moved the failure from *a member nobody added* to *a primitive nobody questioned*, which is
#: harder to find precisely because the prose above argues the primitive is total. The assertion
#: is still strictly better than the enumeration it replaced -- it closed `AnnAssign`, it can
#: fail, and its derived page set is unchanged -- but it does not close the claim on its own.
#:
#: WHAT `Name(ctx=Store)` IS, AND WHAT IT IS NOT [Audit P, exhaustive-3]. It is every name
#: Python binds through an ASSIGNMENT-LIKE form, and that is strictly narrower than *every name
#: this file binds*. `def`, `class`, `import`, `global` and `nonlocal` bind through their own node
#: types and bind no `Name` at all; `except E as e`, `match`'s capture patterns and a function's
#: parameters carry their name as a plain `str` on the owning node (`ExceptHandler.name`,
#: `MatchAs.name`, `arg.arg`); `del x` is `ctx=Del`; and `d[k] = v` or `o.a = v` put the `Store` on
#: a `Subscript` or an `Attribute`, whose inner `Name` is a `Load`. `globals()[...] = page` and
#: `setattr(o, "page", page)` bind through a call.
#:
#: AN EARLIER VERSION OF THIS PARAGRAPH SAID *none of those can hold a page a renderer returned*,
#: AND THAT WAS FALSE -- it is the premise the whole totality argument rested on. Measured: a
#: `match` capture, a function parameter and an attribute target each bind a page with
#: `Store names: []`, so no `Name(ctx=Store)` exists anywhere and the walk below cannot see them;
#: four such shapes were full-suite FALSE GREENS over a live forgery in `prune.render`. The
#: binding side is therefore NOT the subject of this derivation's claim, and it is not what closes
#: it: THE PRINTED-SIDE `unresolved` ASSERTION AT THE END OF `_printed_renderers` IS. That one
#: quantifies over what this file PRINTS, which is the subject of the claim, so a page bound by a
#: form with no `Name` at all is still red there. The two assertions are deliberately different
#: sentences and both are needed: this one says every assignment-like binding has a decision, that
#: one says every printed expression resolves to something or to a decision.
#:
#: THE FOUR THAT CAN HOLD A RENDERER'S PAGE, each having a `.value` that is the thing bound:
_PAGE_BINDERS = (ast.Assign, ast.AnnAssign, ast.AugAssign, ast.NamedExpr)
#: AND THE FOUR THAT CANNOT, which is a DECISION and not a skip. For three of them the reason is
#: that the form binds a name to an ELEMENT of something rather than to the thing itself, so the
#: renderer that produced the something is not what the name holds. For a `for` loop that is
#: also why the refuted widening of
#: this row failed: `__main__.py` iterates a generator of `(lineno, raw)` pairs feeding a per-item
#: renderer, so for a tuple target the iterable is NOT the page, and treating it as one is a false
#: positive at HEAD naming `__main__._unreadable`. A `for` loop that prints its target IS already
#: read as printing its iterable, by the printed-expression arm further down, which is the place
#: that question can be answered.
#:
#: AND FOR `withitem` THE REASON ABOVE IS FACTUALLY FALSE, SO HERE IS THE REAL ONE [Audit P,
#: exhaustive-2]. `with X as n` does not bind an element of `X`: it binds `X.__enter__()`, which
#: for every context manager that returns itself IS the thing itself. Verified in this very file:
#: of the four `withitem` bindings in `__main__.py`, the two `as run:` sites -- the `with`
#: statements at `:992` and at `:1083`-`:1090` -- hold the object the expression produced, not a
#: part of it. So this was never a form nobody thought of; it is an entry the table decided about,
#: exercised today, whose stated REASON was wrong -- and an exhaustiveness assertion cannot help
#: with a wrong reason, by construction. That is the sharpest limit of this form.
#:
#: THE ENTRY STAYS HERE ANYWAY, AND THE DECISION IS NOW CARRIED BY A MEASUREMENT RATHER THAN BY
#: THAT SENTENCE. Moving `withitem` to `_PAGE_BINDERS` resolved on `context_expr` was measured and
#: it makes the guard WORSE, not better: a `with`-bound name then enters `bound` below, and
#: `bound` is the third of the three decisions that EXCUSE an unresolved printed expression -- so
#: `with contextlib.nullcontext(prune_mod.render(...)) as page:` followed by `print(page)` becomes
#: an excused name and the forgery is GREEN again (measured: RC=0 on that plant with the page
#: forged live on stderr). Left here, the same plant is RED on the printed-side `unresolved`
#: assertion, naming `_forget:1666`. The excuse cannot simply be dropped either: `bound` carries
#: two legitimate sites at HEAD (`_forget`'s `problems` and `_show`'s `head`) and reading it as
#: *no resolvable renderer call anywhere in the value's subtree* is RED AT HEAD on `problems`,
#: which comes from `prune_mod.apply(p)`. So the honest statement is the narrow one: a page bound
#: by a `with` is not resolved to its renderer here, it is REFUSED, and the refusal names the
#: print site rather than the renderer.
#:
#: AND THE WORD "LEGITIMATE" IN THE PARAGRAPH ABOVE WAS WRONG ABOUT BOTH SITES [Audit Q,
#: decision-1]. `_forget`'s `problems` was a LIVE FORGERY -- `prune.apply` interpolated a marker
#: filename into a failure message and returned it raw, reproduced at HEAD in a temp directory
#: with rc=1 and a bare `GATE: MET (exit 0)` line on stderr -- and the red on `problems` that
#: Audit P refused as a false positive was a TRUE POSITIVE. `_show`'s `head` was `__main__`'s
#: own composed line and still forged a bare line from one argv argument at exit 0. Both are
#: fixed in production: `prune.apply` escapes through `printable_lines`, and `_show`'s head is
#: escaped at its emission point -- which is also why `head` is no longer a printed expression
#: this derivation sees at all, so `bound` carries ONE site today, not two.
_NOT_PAGE_BINDERS = (ast.For, ast.AsyncFor, ast.comprehension, ast.withitem)
#: WHAT A TARGET MAY BE WRAPPED IN on the way to its owner. `a, (b, c) = ...` nests.
_TARGET_CONTAINERS = (ast.Tuple, ast.List, ast.Starred)

#: WHICH OF THOSE EIGHT DECISIONS THIS TREE ACTUALLY EXERCISES, MEASURED BY DELETING EACH ONE AND
#: WATCHING WHAT THE ASSERTION BELOW DOES -- because two of them are reasoning rather than
#: measurement and the next reader is entitled to know which:
#:
#: * EXERCISED, each red when its entry is deleted: `Assign`, `AnnAssign` (17 bindings in
#:   `__main__`), `AugAssign` (17), `For` (45), `comprehension` (35), `withitem` (4).
#: * NOT EXERCISED: `AsyncFor` and `NamedExpr`, which occurs 8 times in `runprov/` and not once
#:   inside a `__main__` function. Deleting either leaves this GREEN, so those two entries are
#:   decisions made in ADVANCE. They are kept rather than left out on purpose: both answers are the
#:   obvious ones -- a walrus binds the value of an expression, an `async for` binds an element --
#:   and a red asking a human to write a line whose content is already settled is a red over no
#:   defect.
#:
#: AND `AsyncFor`'S ENTRY WAS NOT MERELY UNEXERCISED -- IT WAS UNREACHABLE UNTIL THIS COMMIT
#: [Audit P, exhaustive-5]. Keeper-verified: `issubclass(ast.AsyncFunctionDef, ast.FunctionDef)` is
#: **False**, and an `async def` body yields **0** `FunctionDef` nodes. The walk below read
#: `FunctionDef` only, and `async for` can occur ONLY inside an `async def` -- so the day one
#: arrived the walk would not have looked at it at all and `unaccounted` would have stayed empty.
#: The entry read to the next reader as *a decision made in advance*, i.e. as covered when it
#: arrives, and it was not. It is reachable NOW: `_printed_renderers`, `local` and
#: `_reaches_a_chokepoint` all walk `(FunctionDef, AsyncFunctionDef)`, which is also what
#: `tests:18646` and the `_CHOKEPOINTS` one-definition sweep above already did -- the file was
#: inconsistent with itself about this, and that inconsistency is how the hole was found.


def _printed_renderers() -> dict[tuple[str, str], set[str]]:
    """Every page `__main__` prints, DERIVED FROM `__main__` BY AST rather than listed.

    THIS EXISTS BECAUSE THE HAND-WRITTEN LIST HAS BEEN WRONG FIVE TIMES. K-21 escaped two
    renderers and named the five it had left; L-03 escaped those five and wrote a property to
    retire the list — and the property's own attack was a declared list of record FIELDS, so
    `verify`, `check`, `impact`, `chain`, `__main__._render_lineage` and `prune` were all
    still forgeable after it. The fifth miss, `prune.render`, was found by running this
    derivation and by nothing else: it is in none of the seven findings of Audit M.

    WHAT COUNTS AS A PAGE: the value of an expression that reaches `print`, a
    `sys.stdout`/`sys.stderr` `write` or `writelines`, or a `for` loop that prints its target
    — resolved through the wrappers a caller puts round a page (`"\\n".join(...)`, `+ "\\n"`,
    a comprehension) and through one local assignment, so `result = report.render(...)`
    followed by `for line in result.lines` resolves to `report.render`.

    **HOW A LOCAL NAME IS RESOLVED, AND WHY IT IS NOT A LIST OF ASSIGNMENT SHAPES ANY MORE**
    [Audit O, guards-4]. The binder read `ast.Assign`, then `Assign` with a tuple target, and
    `AnnAssign` was a live false green behind both: `page: str = prune_mod.render(...)` bound
    nothing, so `print(page)` resolved to nothing and `prune.render` was not in this set at all.
    Every `Name(ctx=Store)` in the file is now walked up to the form that binds it and that form
    must be one the table above decided about; anything else fails the assertion at the end of
    this function. The table and the reasoning are at `_PAGE_BINDERS`.

    WHAT IS EXCLUDED, AND BOTH EXCLUSIONS ARE DERIVED RATHER THAN NAMED:

    * an expression whose subtree calls `.dumps` or `.dump` is a PAYLOAD, not a page. That is
      what keeps `report`, `verify`, `check`, `diff`, `impact`, `chain`, `policy`, `show` and
      `resources` out of this set twice over — each has a `payload()` beside its renderer and
      `__main__` prints it through `json.dumps`.
    * the chokepoint functions themselves. `_diag` is `print(printable(message))` and the
      in-flight banner is `print("\\n".join(printable_lines(out)))`, so both resolve to
      `_report.printable*`; a transform cannot be required to pass through itself.

    An f-string built in `__main__` and printed there is NOT in this set: it is `__main__`'s
    own line and not a module's page. The 51 `print(..., file=sys.stderr)` sites are that
    shape, and Audit M's escape-4 states why they are not routed through one transform.

    **AND THAT EXCLUSION IS A LIVE FORGING SURFACE THAT NOTHING GUARDS** [Audit Q, decision-1,
    the second live forgery]. One of those composed stderr lines -- `_show`'s `head` -- forged a
    bare `GATE: MET (exit 0)` line from ONE argv argument at EXIT 0, reproduced at HEAD with no
    plant and no permission trickery, and it is now escaped at its emission point. NO COUNT IS
    CLAIMED for how many of the other 50 interpolate a value from outside. `_acted_on` whitelists
    `\\n` by construction and the line-count oracle watches only chokepoints, so neither reaches
    them. That is an OPEN row, not a closed one.

    **AND WHAT REACHES `printed` AT ALL IS AN ENUMERATION -- THE HOLE IS FOUR SHAPES WIDE AND IS
    DECLARED HERE AS A CLASS** [Audit Q, decision-4]. The collector below matches `print` by
    LITERAL NAME and `.write`/`.writelines` on an `Attribute` whose attr is `stdout` or `stderr`.
    A page emitted any other way is never examined, never resolved, never excused and never
    refused -- so it is outside the `unresolved` assertion's SUBJECT, which is why that assertion
    and this test's claim are two sentences and not one. Each of these four was proved a live
    forgery at runtime and each is GREEN under every fix considered for this row:

      out = sys.stderr; out.write(render(...) + "\\n")   # a function-local alias
      sys.__stderr__.write(render(...) + "\\n")          # a FOURTH literal spelling, not an alias
      _OUT = sys.stderr   (at MODULE level)              # a hole INSIDE the proposed fix, which
                                                         # walks `ast.walk(fdef)` only
      emit = print; emit(render(...))                    # the print-by-literal-name half

    **THE PROPOSED FIX IS NOT SHIPPED, AND THAT IS THE POINT OF THE ROW.** Widening the collector
    to a `Name` receiver aliased to `sys.stderr` inside the function is not vacuous -- it has a
    reachable positive and goes red over its own plant with no false positive -- but it closes
    1 OF 4, and declaring two escapes where there are at least four is the *"worse than an
    undeclared gap"* shape this series has now filed three times. The class above is declared
    instead; the row stays OPEN.

    **"LATENT" IS STRUCK AS THE ONLY FRAMING.** All 14 `.write`/`.writelines` receivers in
    `__main__` are the literal `sys.stdout` today, so no forgery exists here now -- but the alias
    idiom is ALREADY SHIPPED TWICE in `_report.py`, at `:205` in `_write` and at `:318` in
    `progress_enabled`, both `stream = sys.stderr`. It is house style, one module away.

    **TWO CANDIDATES WERE DISTINGUISHED RATHER THAN LISTED:** `contextlib.redirect_stdout` and a
    rebound `sys.stdout` create NO NEW EMISSION SITE, so they are not members of this class.
    And the emission surface is otherwise fully covered, measured: 83 `print` + 13
    `sys.stdout.write` + 1 `sys.stdout.writelines` = 97 of 97 call sites in `__main__`, with no
    `logging`, `click`, `parser.error`, `atexit`, `__del__` or traceback-hook emitter anywhere in
    it.
    """
    main = _repo_root() / "runprov" / "__main__.py"
    tree = ast.parse(main.read_text(encoding="utf-8"))

    #: `from . import show as show_mod` and `from .verify import render_report`, both of
    #: which `__main__` uses, plus functions defined in `__main__` itself.
    mods: dict[str, str] = {}
    funcs: dict[str, tuple[str, str]] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.level == 1:
            for alias in node.names:
                if node.module is None:
                    mods[alias.asname or alias.name] = alias.name
                else:
                    funcs[alias.asname or alias.name] = (node.module, alias.name)
    local = {
        n.name for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    def resolve(fn: ast.expr) -> tuple[str, str] | None:
        if isinstance(fn, ast.Attribute) and isinstance(fn.value, ast.Name):
            if fn.value.id in mods:
                return (mods[fn.value.id], fn.attr)
        if isinstance(fn, ast.Name):
            if fn.id in funcs:
                return funcs[fn.id]
            if fn.id in local:
                return ("__main__", fn.id)
        return None

    def peel(expr: ast.expr) -> ast.expr:
        """Strip what a caller wraps a page in before printing it."""
        while True:
            if isinstance(expr, ast.BinOp):
                expr = expr.left
            elif (
                isinstance(expr, ast.Call)
                and isinstance(expr.func, ast.Attribute)
                and expr.func.attr == "join"
                and expr.args
            ):
                expr = expr.args[0]
            elif isinstance(expr, (ast.GeneratorExp, ast.ListComp, ast.SetComp)):
                expr = expr.elt
            #: AND ONE ELEMENT OF A PAGE IS STILL THAT PAGE [Audit N, guards-1]. `result[0]`
            #: printed on its own is the same renderer's output as `result`; without this the
            #: tuple widening above would be half a fix, catching the unpacked spelling and
            #: missing the subscripted one. Measured against the tree: the two together ADD
            #: exactly one page and REMOVE none, so this peels nothing that was resolving.
            elif isinstance(expr, ast.Subscript):
                expr = expr.value
            #: A WALRUS IS THE VALUE IT BINDS, AND A `*` UNPACK IS THE THING UNPACKED [Audit P,
            #: exhaustive-4]. `print(page := prune_mod.render(...))` and `print(*render())` both
            #: print what the call returned; without these two lines the binding arm resolved the
            #: walrus correctly and this arm threw the answer away, which was a full-suite false
            #: green over a live forgery -- RC=0 with both coverage discriminators at baseline.
            #: So a RIGHT decision behind an HONEST declaration was still not enough: the
            #: declaration was never where the risk was.
            elif isinstance(expr, (ast.NamedExpr, ast.Starred)):
                expr = expr.value
            else:
                return expr

    def _has_renderer_call(expr: ast.expr) -> bool:
        """Does this expression's subtree hold a call this derivation can RESOLVE to a module?

        **SHIPPED AS A STRICT IMPROVEMENT, NOT AS A CLOSURE, AND THE RESIDUE IS DECLARED BELOW**
        [Audit Q, decision-2 and decision-3]. It closes four measured defeats of `bound` --
        `str(render(...))`, `render(...) if directory else ""`, `[render(...)]` joined and
        `render(...).rstrip()`, each a runtime-proved live forgery that was RC=0 green -- and it
        is what makes `_composed_in_main` below semantic rather than a test of the top node's
        type.

        **AND ITS POLARITY IS INVERTED IN EXACTLY THE WAY `decision-2` NAMES IN `bound`, ONE
        LAYER IN.** `bound` recorded a name whose binding value the derivation FAILED TO RESOLVE
        and called that a demonstration that no renderer produced it. This helper EXCUSES an
        expression whose calls the derivation FAILED TO RESOLVE. Same inversion, same cause: an
        unresolvable call is evidence about this derivation, never about the expression.

        **THE FIVE DEFEATING SHAPES, MEASURED, each a runtime-proved live forgery that is GREEN
        under this helper on three interpreters:**

            renderer = prune_mod.render ; print(f"{renderer(...)}")           # module alias
            renderer = prune_mod.render ; page = renderer(...) ; print(page)  # two steps
            functools.partial(prune_mod.render, p, gone) in an f-string
            getattr(prune_mod, "render")(...) in an f-string
            reg = {"r": prune_mod.render} ; print(f"{reg['r'](...)}")         # a dict lookup

        Two lines of ordinary refactoring defeat it, and the module-level-alias idiom is already
        house style -- `_report.py:205` and `:319` both do it.

        **AND NO AST FORM CLOSES IT, WHICH IS WHY THE RESIDUE IS DECLARED RATHER THAN FIXED.**
        Both exits were measured and both fail:

        * THE SOUND POLARITY CANNOT PASS. Refusing on ANY unresolvable call is RED on **9 of the
          49** composed expressions at HEAD -- the unresolvable callees are `len` x8,
          `report.get` x2, `", ".join`, `repr`, `str`, `picked[0].get` -- and RED on
          `_show:2489`'s own value, whose unresolvable calls are three `len`s. Closing it needs
          an allowlist of SAFE CALLEES over an unbounded set, which is the member list again.
        * A PRODUCER-SIDE DERIVATION CANNOT PASS EITHER, and the skeptic that built it refused
          to claim it: *every function in `runprov/` that interpolates a non-literal and hands
          the string out* finds `prune.apply` with no `__main__` analysis at all, but **83 of 100
          producers do not reach a chokepoint** (record values, digests, filenames, PROV
          identifiers), so it needs an 83-member *"not a page"* table with no second side.

        Both failures have one cause, and `guard-shapes` names it: a write to a log file and a
        write to a stream installed as stderr can be BYTE-IDENTICAL IN THE AST. *"This string
        becomes a line a person reads"* is a RUNTIME property. What holds the five shapes above
        is therefore not here at all: it is
        `test_prune_does_not_forge_a_line_from_a_marker_filename`, which reads the VALUE ON THE
        STREAM and to which all five are visible.
        """
        #: A CHOKEPOINT CALL IS NOT A PAGE, AND THIS CLAUSE ALREADY EXISTED 150 LINES BELOW.
        #: Without it, ESCAPING one of `__main__`'s own composed stderr lines made this
        #: derivation REFUSE it: `printable` resolves, so `_has_renderer_call` said True,
        #: `_composed_in_main` stopped excusing the line and it landed in `unresolved`.
        #: Measured on the 32-site sweep: RED naming all 32, with the census otherwise
        #: unchanged -- the guard punished the repair, which is the opposite of its purpose.
        #: The helper is named for RENDERERS and matched any resolvable call; the `found`
        #: loop below already distinguishes the two with this exact test, keyed to
        #: `_CHOKEPOINTS`, whose members have their own second side in the one-definition
        #: sweep above. So this is the same decision spelled once more, not a new one.
        return any(
            isinstance(n, ast.Call)
            and (where := resolve(n.func)) is not None
            and not (where[0] == "_report" and where[1] in _CHOKEPOINTS)
            for n in ast.walk(expr)
        )

    def binding(value: ast.expr) -> tuple[str, str] | None:
        """What a page-binder's VALUE resolves to, THROUGH A CONDITIONAL EXPRESSION.

        [Audit Q, decision-1.] `gone, problems = (None, []) if dry else prune_mod.apply(p)` in
        `_forget` is how the live forgery stayed invisible: the value is an `IfExp`, not a
        `Call`, so `problems` resolved to nothing, `bound` excused it, and `prune.apply` was not
        in the page set for `unescaped` to ask about. Either arm may be the page, so both are
        asked and the first answer wins.

        **THIS IS A RESOLVER, NOT AN EXCUSE, WHICH IS WHY IT IS NOT THE REFUTED `guards-4`
        SHAPE.** A per-node-type EXCUSE fails silently when it meets a type nobody listed; a
        resolver that fails leaves the expression unresolved and RED. And of the six shapes
        considered for this row it is the only one whose red NAMES THE RENDERER rather than the
        print site.
        """
        if isinstance(value, ast.IfExp):
            return binding(value.body) or binding(value.orelse)
        return resolve(value.func) if isinstance(value, ast.Call) else None

    def serialises(expr: ast.expr) -> bool:
        return any(
            isinstance(n, ast.Call)
            and isinstance(n.func, ast.Attribute)
            and n.func.attr in ("dumps", "dump")
            for n in ast.walk(expr)
        )

    def _composed_in_main(expr: ast.expr) -> bool:
        """Is this `__main__`'s OWN composed line rather than a module's page?

        THE FIRST OF THE THREE DECISIONS THAT EXCUSE AN UNRESOLVED PRINTED EXPRESSION, and it
        is the exclusion this function's docstring ALREADY DECLARES: *an f-string built in
        `__main__` and printed there is NOT in this set: it is `__main__`'s own line and not a
        module's page*, which is the shape of the 51 `print(..., file=sys.stderr)` sites and
        the reason Audit M's escape-4 gives for not routing them through one transform. A
        literal, a tuple of arguments to `print`, and a `x or y` fallback are the same thing.

        **AND IT IS NOT A TEST OF THE TOP NODE'S TYPE ANY MORE** [Audit Q, decision-3]. It was,
        and `print(f"{prune_mod.render(...)}")` -- the most idiomatic emission shape in the file
        -- was therefore excused: full suite RC=0, 1 230 passed, 5 584 / 2 092, 2 missing / 0
        partial over a live forgery, byte-identical to baseline on BOTH discriminators.
        `print(render(...) or "")` likewise. The contrast was ten lines above: `serialises`
        walks the whole subtree, so the payload exclusion was semantic and this one was not.

        **TIGHTENING IT IS FREE AT HEAD, MEASURED: 0 of the 49 composed expressions contain a
        resolvable renderer call**, so the declared 51-stderr-f-string exclusion is untouched.
        It adds no hole of its own -- the shapes that defeat it are the five
        `_has_renderer_call` declares, and not a sixth.
        """
        return isinstance(
            expr, (ast.JoinedStr, ast.Constant, ast.Tuple, ast.BoolOp)
        ) and not _has_renderer_call(expr)

    found: dict[tuple[str, str], set[str]] = {}
    #: EVERY `Name` THIS FILE BINDS AND NO TABLE DECIDED ABOUT. Asserted below, so a binding form
    #: that arrives in a future Python -- or one nobody thought of in this one -- is RED here
    #: instead of silently holding a page nothing checks [Audit O, guards-4].
    unaccounted: dict[str, str] = {}
    #: EVERY PRINTED EXPRESSION THIS DERIVATION COULD NOT RESOLVE AND NO DECISION EXCUSES, WHICH
    #: IS THE ASSERTION THAT QUANTIFIES OVER THE SUBJECT OF THE CLAIM [Audit P, exhaustive-1].
    #: `unaccounted` above says every assignment-like binding has a decision; it does NOT say
    #: every printed page was resolved, and those are different sentences. Measured: 45 printing
    #: shapes were tried against the previous form and `unaccounted` was empty in ALL 45 -- for
    #: the 9 it caught and for all 36 it missed alike -- because a `match` capture, a function
    #: parameter and an attribute target bind a page with no `Name(ctx=Store)` anywhere. Four of
    #: those were clean full-suite false greens over a live forgery in `prune.render`, the one
    #: renderer no behavioural leg may ever reach. This dict is the repair: a page that is PRINTED
    #: and does not resolve is red here whatever bound it, so a page can no longer LEAVE the
    #: derived set silently -- which is the one direction the floor, the `_SERIALISERS` equality
    #: and the `unescaped` complement all structurally miss, because each of them only sees what
    #: is already IN the set.
    unresolved: dict[str, str] = {}
    #: BOTH KINDS OF FUNCTION, because `ast.AsyncFunctionDef` is NOT a subclass of
    #: `ast.FunctionDef` -- so walking one kind made every decision about `async` unreachable
    #: rather than merely unexercised [Audit P, exhaustive-5].
    for fdef in [
        n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
    ]:
        parent: dict[ast.AST, ast.AST] = {}
        for node in ast.walk(fdef):
            for child in ast.iter_child_nodes(node):
                parent[child] = node
        assigned: dict[str, tuple[str, str]] = {}
        #: EVERY NAME A PAGE-BINDER BOUND FROM A VALUE HOLDING NO RESOLVABLE RENDERER CALL
        #: [Audit Q, decision-2]. This sentence read *every name a page-binder bound, whether or
        #: not its value was a renderer call*, which is what the defect WAS: the set was filled
        #: before `resolve` was consulted, so it excused names whose value this derivation merely
        #: failed to read. It is one of the three decisions that excuse an unresolved printed
        #: expression below -- and its remaining weakness is `_has_renderer_call`'s, declared in
        #: full at that helper, because *no resolvable call* is weaker than *no renderer*.
        #:
        #: AND AFTER THIS COMMIT THIS SET IS EMPTY AND THE EXCUSE IS UNEXERCISED. MEASURED, by
        #: the applier, on five interpreters: of the 110 printed expressions, `bound` now carries
        #: ZERO -- `_forget`'s `problems` RESOLVES through `binding`, and `_show`'s `head` is no
        #: longer a printed expression at all, because its emission point was wrapped in
        #: `printable` in the production fix. Deleting `inner.id in bound` outright leaves this
        #: GREEN on 3.10 / 3.11 / 3.12 / 3.13 / 3.14 with the same 23 pages, verified with an AST
        #: control that no `x in bound` comparison survives. So this is now a DECISION MADE IN
        #: ADVANCE, like `AsyncFor` and `NamedExpr` in the table above, and not a load-bearing
        #: excuse: the scope note that called `bound` *"the sharpest thing in this subject"* was
        #: true of the shape it had before these two commits. It is kept rather than deleted
        #: because the shape it decides about is ordinary -- a page-binder whose value is not a
        #: renderer call -- and a red asking a human to re-write a settled answer is a red over
        #: no defect. **The work `_has_renderer_call` does today is in `_composed_in_main`, over
        #: 49 expressions, not here.**
        bound: set[str] = set()
        for node in ast.walk(fdef):
            if not (isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store)):
                continue
            #: UP THROUGH THE CONTAINERS TO THE OWNER, which is what makes a tuple-unpacked
            #: renderer the same as a plainly assigned one [Audit N, guards-1]: every `Name`
            #: element binds to the SAME `(module, function)`, because the call is one call and
            #: each name holds a part of its one answer. `header, row =
            #: resources_mod.snakemake_row(m)` is printed line by line immediately below -- a
            #: shape ALREADY IN THE TREE that this derivation could not see, so the docstring's
            #: *a new page fails the file the day it is written* was false for a print shape
            #: already shipped.
            owner = parent.get(node)
            while isinstance(owner, _TARGET_CONTAINERS):
                owner = parent.get(owner)
            if isinstance(owner, _PAGE_BINDERS):
                value = owner.value
                #: GATED ON THE VALUE, NOT ON THE BINDING [Audit Q, decision-2]. This read
                #: `bound.add(node.id)` unconditionally -- before and regardless of whether
                #: `resolve` answered -- so it recorded a name whose binding value the
                #: derivation FAILED TO RESOLVE while the comment above claims a name
                #: *demonstrably bound from something that is not a renderer call*. Any page
                #: laundered through one unresolvable wrapper was excused, measured over four
                #: shapes at RC=0. `_has_renderer_call`'s own residue is declared at the helper
                #: and is NOT closed: the gate is a strict improvement, not a closure.
                if not _has_renderer_call(value):
                    bound.add(node.id)
                where = binding(value)
                if where:
                    assigned[node.id] = where
            elif not isinstance(owner, _NOT_PAGE_BINDERS):
                unaccounted[f"{fdef.name}:{node.lineno}: {node.id}"] = type(owner).__name__
        printed: list[ast.expr] = []
        #: THE LOOP TARGETS WHOSE ITERABLE WENT INTO `printed`, which is the second of the three
        #: decisions below: the NAME is an element of a page this derivation has already counted,
        #: so it is not a second unresolved page.
        iterated: set[str] = set()
        for node in ast.walk(fdef):
            if isinstance(node, ast.Call):
                if isinstance(node.func, ast.Name) and node.func.id == "print":
                    printed += list(node.args)
                elif (
                    isinstance(node.func, ast.Attribute)
                    and node.func.attr in ("write", "writelines")
                    and isinstance(node.func.value, ast.Attribute)
                    and node.func.value.attr in ("stdout", "stderr")
                ):
                    printed += list(node.args)
            elif isinstance(node, (ast.For, ast.AsyncFor)) and isinstance(node.target, ast.Name):
                body = ast.dump(ast.Module(body=node.body, type_ignores=[]))
                #: AND `stderr` BESIDE `stdout`, WHICH IS WHERE `prune`'S REAL PAGE GOES [Audit P,
                #: exhaustive-6]. This arm read `'print'` or `stdout` and `prune.render`'s one
                #: print site is `print(..., file=sys.stderr)` -- so a `for` loop writing the
                #: page to stderr was not a printed page here at all.
                if f"id='{node.target.id}'" in body and (
                    "'print'" in body or "stdout" in body or "stderr" in body
                ):
                    printed.append(node.iter)
                    iterated.add(node.target.id)
        for expr in printed:
            if serialises(expr):
                continue
            inner = peel(expr)
            where = None
            if isinstance(inner, ast.Call):
                where = resolve(inner.func)
            elif isinstance(inner, ast.Name):
                where = assigned.get(inner.id)
            elif isinstance(inner, ast.Attribute) and isinstance(inner.value, ast.Name):
                where = assigned.get(inner.value.id)
            if where and not (where[0] == "_report" and where[1] in _CHOKEPOINTS):
                found.setdefault(where, set()).add(fdef.name)
            elif where is None and not _composed_in_main(inner):
                excused = isinstance(inner, ast.Name) and (
                    inner.id in iterated or inner.id in bound
                )
                if not excused:
                    unresolved[f"{fdef.name}:{inner.lineno}"] = (
                        f"{type(inner).__name__}: {ast.unparse(inner)[:120]}"
                    )
    #: AND THE THREE EMISSION SPELLINGS MUST STILL EXIST, OR THE ENUMERATION ABOVE HAS STARTED
    #: COVERING NOTHING [Audit Q, decision-4]. The collector is keyed to `print` by literal name
    #: and to `.write`/`.writelines` on `sys.stdout`/`sys.stderr`; that is an exemption-shaped
    #: claim about WHAT THIS MODULE'S EMISSIONS LOOK LIKE, and an exemption whose subject is never
    #: asserted silently starts covering nothing or everything. Measured today: 83 `print`, 13
    #: `sys.std*.write`, 1 `sys.std*.writelines` -- 97 of the 97 emission call sites in
    #: `__main__`, with all 14 `.write`/`.writelines` receivers being the literal `sys.stdout`.
    #: This asserts PRESENCE, not the counts: a count here would rot on every new line printed,
    #: which is the K-37/L-08 defect, while presence going to zero is the only thing that makes
    #: the derivation vacuous. It is asserted BEFORE the two clauses below on purpose -- if an
    #: arm of the collector has gone blind, the right red is *this instrument stopped reading*
    #: and not *this page is unresolved*.
    spellings = {"print": 0, "sys.std*.write": 0, "sys.std*.writelines": 0}
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if isinstance(node.func, ast.Name) and node.func.id == "print":
            spellings["print"] += 1
        elif (
            isinstance(node.func, ast.Attribute)
            and node.func.attr in ("write", "writelines")
            and isinstance(node.func.value, ast.Attribute)
            and node.func.value.attr in ("stdout", "stderr")
        ):
            spellings[f"sys.std*.{node.func.attr}"] += 1
    absent = sorted(name for name, n in spellings.items() if not n)
    assert not absent, (
        f"{absent} no longer occurs anywhere in `__main__.py`, so the arm of this derivation's "
        f"emission collector that matches it is now dead and the pages it used to see are "
        f"invisible -- which looks exactly like a module with fewer pages. Counted: "
        f"{spellings}. Either the spelling really went away, in which case DELETE that arm and "
        f"this entry together rather than leaving an exemption over nothing, or the emission "
        f"moved to a spelling this collector does not match -- which is `decision-4`'s open row "
        f"and the four shapes declared in the docstring above"
    )
    #: THE EXHAUSTIVENESS ASSERTION, WHICH IS WHAT MAKES THE TABLE ABOVE SOMETHING OTHER THAN A
    #: LIST [Audit O, guards-4]. It is the only clause in this family that goes red for a form
    #: nobody anticipated. Measured able to fail: delete `ast.AnnAssign` from `_PAGE_BINDERS`
    #: without adding it to `_NOT_PAGE_BINDERS` and this names 17 bindings in `__main__.py`.
    assert not unaccounted, (
        f"these names are bound by a form neither `_PAGE_BINDERS` nor `_NOT_PAGE_BINDERS` has a "
        f"decision about, so this derivation cannot say whether they hold a page: {unaccounted}. "
        f"Decide: if the form binds the VALUE of an expression, add it to `_PAGE_BINDERS` (it "
        f"must have a `.value`); if it binds an ELEMENT of something, add it to "
        f"`_NOT_PAGE_BINDERS` with the reason. Do not delete this assertion -- it is the only "
        f"thing here that can fail for a binding form nobody has thought of"
    )
    #: AND THE ASSERTION OVER THE SUBJECT OF THE CLAIM, WHICH IS THE ONE THE FOUR FALSE GREENS
    #: NEEDED [Audit P, exhaustive-1]. The claim is *every page `__main__` prints reaches an
    #: escaping chokepoint*; so what must be accounted for is every expression `__main__` PRINTS,
    #: not every name it binds. Those were different sentences and the gap between them held four
    #: measured false greens: `with nullcontext(render()) as page`, `print(page := render())`, a
    #: function PARAMETER, and `case page:` -- each RC=0 on the full suite with both coverage
    #: discriminators at baseline, over a `prune.render` whose chokepoint had been removed.
    #:
    #: THE THREE DECISIONS ABOVE ARE THE WHOLE EXCUSE LIST, and each is a statement about pages
    #: rather than about syntax: `__main__`'s own composed line (`_composed_in_main`), an element
    #: of an iterable this derivation already counted (`iterated`), and a name this function
    #: demonstrably bound from something that is not a renderer call (`bound`). Anything else
    #: printed and unresolved is RED, including a name bound by a form that has no
    #: `Name(ctx=Store)` at all -- which is exactly what `unaccounted` cannot see.
    #:
    #: **AND THE CLAIM AND THE QUANTIFICATION ARE STILL NOT ONE SENTENCE. THEY ARE TWO, AND THEY
    #: DIFFER ON BOTH ENDS** [Audit Q, decision-2/-3/-4]. The candidate sentence this repair was
    #: proposed under -- *every printed expression either resolves to a renderer, or demonstrably
    #: contains no renderer call* -- is false twice over, and both halves were measured:
    #:
    #: * THE SUBJECT DIFFERS. `printed` is collected by an ENUMERATION of emission spellings:
    #:   `print` by literal name, and `.write`/`.writelines` on an `Attribute` whose attr is
    #:   `stdout` or `stderr`. A page written through an aliased stream, through
    #:   `sys.__stderr__.write`, through a MODULE-LEVEL `_OUT = sys.stderr`, or through
    #:   `emit = print` never reaches `printed` at all, so it is never resolved, never excused
    #:   and never refused. That is `decision-4`, the row stays OPEN, and the fix for the other
    #:   three decisions does not touch it.
    #: * THE PREDICATE DIFFERS. *"Demonstrably contains no renderer call"* is not what
    #:   `_has_renderer_call` decides; it decides *"contains no call THIS DERIVATION CAN
    #:   RESOLVE"*, which is a statement about the derivation. Five shapes are declared at that
    #:   helper, each a runtime-proved live forgery that is green under it.
    #:
    #: So this assertion is a strict improvement over what it replaced and it is NOT a closure.
    #: What closes the five shapes is a RUNTIME leg --
    #: `test_prune_does_not_forge_a_line_from_a_marker_filename` -- and not this file's syntax.
    assert not unresolved, (
        f"these expressions are PRINTED by `__main__` and this derivation cannot say which "
        f"renderer produced them, so a page may be leaving this set unseen: {unresolved}. That "
        f"is the failure the assertion above structurally cannot catch: a page can be bound by "
        f"a `match` capture, a parameter, an attribute target or `setattr` with no "
        f"`Name(ctx=Store)` anywhere in the file. Resolve it -- teach `resolve` or `peel` the "
        f"shape -- or, if it really is `__main__`'s own composed line, say so by giving it a "
        f"decision. Do not delete this assertion: it is the only clause here that quantifies "
        f"over what this module PRINTS, which is the subject of this test's claim"
    )
    return found


def _reaches_a_chokepoint(module: str, function: str) -> bool:
    """Does `function` reach `printable` or `printable_lines` WITHIN ITS OWN MODULE?

    ONE HOP IS NOT ENOUGH AND A GREP IS NOT EITHER. `report.render` is what `__main__`
    prints and `report.render_page` is where the transform is applied, so a rule reading only
    the renderer's own body is red for a module that is correct. The call graph inside the
    module is walked instead, to its closure.

    AND THIS IS A STRUCTURAL CHECK, WHICH IS WHY IT IS NOT THE ONLY ONE. It says a page can
    reach the transform; it cannot say the transform was applied to every line, or to the
    right value. That is what the behavioural oracle in
    `test_no_page_this_package_prints_carries_a_character_a_terminal_acts_on` is for, and
    neither is sufficient alone: this one covers renderers no fixture can reach (`prune`
    deletes, so no corpus recipe may point at it), and that one covers the lines.
    """
    path = _repo_root() / "runprov" / f"{module}.py"
    tree = ast.parse(path.read_text(encoding="utf-8"))
    bodies = {
        n.name: n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
    }
    #: Who calls whom, by NAME, inside this one module. A name is enough: the question is
    #: whether the transform is on the path, and two functions with one name in one module
    #: is not a thing Python allows.
    calls: dict[str, set[str]] = {}
    for name, node in bodies.items():
        calls[name] = {
            n.func.id
            for n in ast.walk(node)
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
        }
    seen: set[str] = set()
    todo = [function]
    while todo:
        name = todo.pop()
        if name in seen or name not in calls:
            continue
        seen.add(name)
        if calls[name] & set(_CHOKEPOINTS):
            return True
        todo += sorted(calls[name])
    return False


def test_every_page_main_prints_reaches_an_escaping_chokepoint():
    """[ADR-0018 R-8] Audit M, escape-5. The renderer set is DERIVED, so a new page fails
    the day it is written.

    **THE DEFECT THIS CLOSES IS A CLASS, NOT A SITE.** K-21 escaped two renderers and named
    five more; L-03 escaped those five, wrote the property that was meant to retire the list
    — and attacked it through `_FORGE_INTO`, *a declared list of record fields*. So the list
    moved out of the production code and into the probe, and six renderers stayed forgeable
    behind a green suite: `verify`, `check`, `impact`, `chain`, `__main__._render_lineage`
    and `prune`. **The hand-written list has now been wrong five times, and the fifth —
    `prune.render` — was found by running this derivation and by nothing else.** It is in
    none of Audit M's seven escaping findings, and it forges a bare line on stderr from ONE
    argv argument: `prune --log 'prov\\nGATE: MET (exit 0)\\nx/history.jsonl' --dry-run`, with
    no marker, no history and no file, on every platform.

    **WHY A SIXTH LIST WOULD NOT HAVE HELPED.** The sites are not the fact; what `__main__`
    prints is the fact. So the set is read off `__main__`'s own syntax, the payload side is
    excluded by its own `json.dumps`, and the only names typed here are the SERIALISERS —
    which are held by equality against the derivation, so a stale exemption is red too.

    **THE LIMIT, STATED.** This asserts a page can REACH the transform, not that every line
    went through it. The behavioural half is the property test below, which runs the commands
    against a forged tree and counts lines.

    **AND THE CLAUSE THAT USED TO END THIS PARAGRAPH IS WITHDRAWN** [Audit Q, decision-1]. It
    read *this half is what covers the renderers no fixture may point at: `prune` DELETES, so
    `CORPUS_NOT_READERS` excludes it by name and a behavioural leg for it would mutate its own
    subject.* The premise is true only of a leg pointed at a real directory. Stub `plan` and
    nothing touches the filesystem at all --
    `test_prune_does_not_forge_a_line_from_a_marker_filename` does exactly that, it is
    platform-neutral where the three `_can_name_a_file_with_a_newline` legs are not, and it
    caught the live forgery in `prune.apply` that THIS half was silent about. So the reasoning
    that made this the only possible check was the reason the defect stayed invisible.
    """
    printed = _printed_renderers()
    #: THE FLOOR IS SLACK AND SAYS SO, WHICH IS THE WHOLE OF WHAT IT CLAIMS [Audit N,
    #: guards-1]. Measured today: 22 pages against a floor of 15. The slack is deliberate and
    #: it is not a number anybody should tighten:
    #:
    #: * AN EQUALITY HERE WOULD ROT ON EVERY NEW SUBCOMMAND, which is the K-37/L-08 defect and
    #:   the reason `pyproject`'s coverage figures were DELETED rather than corrected. Seven
    #:   derived guards in this file already fire the day a subcommand is added; an eighth that
    #:   fires because a RENDERER was added says nothing a reviewer needs.
    #: * AND THE FLOOR IS NOT WHAT HOLDS THE SET. `stale` below is an EQUALITY — every name in
    #:   `_SERIALISERS` must still be something `__main__` prints — and `unescaped` is a
    #:   complement over the whole derived set, so a renderer that goes missing from this
    #:   derivation is caught by neither a count nor a list but by the two assertions that
    #:   quantify over it. This one answers one cruder question: has the derivation stopped
    #:   READING `__main__` at all, the way a changed AST or a renamed import would make it.
    assert len(printed) >= 15, (
        f"this derivation found only {len(printed)} pages, which is fewer than the renderers "
        f"this package is known to have — it has stopped reading `__main__`: {sorted(printed)}"
    )

    #: THE EXEMPTIONS ARE HELD BY THE DERIVATION. A serialiser that is renamed, deleted or no
    #: longer printed must be removed from the set rather than left covering nothing.
    stale = sorted(set(_SERIALISERS) - set(printed))
    assert not stale, (
        f"{stale} are named in `_SERIALISERS` and `__main__` no longer prints them. An "
        f"exemption that covers nothing is a hole with a comment over it: delete the entries."
    )

    unescaped = sorted(
        f"{module}.{function}"
        for (module, function) in printed
        if (module, function) not in _SERIALISERS and not _reaches_a_chokepoint(module, function)
    )
    assert not unescaped, (
        f"[Audit M escape-5] {unescaped} build a page `__main__` prints and reach neither "
        f"`printable` nor `printable_lines`. Every field such a page interpolates can forge "
        f"a whole line on it — a newline in one recorded path prints `GATE: MET (exit 0)` as "
        f"its own line inside a report whose real verdict is the opposite. Apply "
        f"`printable_lines` where the renderer emits its lines; if the page is a MACHINE "
        f"format, add it to `_SERIALISERS` with the format and the parser that reads it."
    )


def test_no_page_this_package_prints_carries_a_character_a_terminal_acts_on(
    tmp_path, monkeypatch, capsys
):
    """[ADR-0018 R-8] Audit L, L-03 and L-23. The PROPERTY, because the site list was wrong.

    **WHAT K-21 LEFT.** `printable` had two call sites in the package — `log`'s unreadable-line
    dump and `policy`'s eight interpolations — and **five other renderers were still forgeable**:
    `log`'s own page, `show`, `show <target>`, `report` and `diff`. A newline inside one recorded
    field forges WHOLE LINES, and the line reproduced was `verdict OK` inside a page whose real
    verdict is STALE, from a REAL run with no record editing: one `sys.argv` argument is enough,
    because `command` is built by this package from `sys.argv`.

    **IT IS A WRONG PRINTED RECORD AND NOT A FALSE GREEN**, and the distinction was measured
    rather than assumed: `action.yml` and `.pre-commit-hooks.yaml` read only the exit code and
    never invoke `gate`, there are zero `runprov` invocations in any workflow, zero pipe-to-grep
    hits across every yml/md/py/toml in the tree, and the README's grep examples scrape RECORD
    files. Nothing shipped reads a page for a verdict. The ground is `report.py`'s own docstring
    instead — the page is *for a quality file… printed and filed beside the result*, and *a
    quality document that overstates is worse than none, because it is the version that gets
    cited.*

    **L-03's FILED REMEDY IS REFUTED AND IT REPEATS THE ERROR IT NAMES.** It said *apply
    `printable` in `report._kv`, `show._kv` and `log`'s three f-strings*. `log`'s renderer has
    **ten** append sites interpolating about thirteen fields, not three f-strings; **`diff` is
    omitted although the row names it** and cannot be reached through either `_kv` because it
    imports nothing from the package and builds its lines from its own f-strings; and `_kv` takes
    `value: Any` and is called with ints and lists, so `printable(value)` raises. The remedy that
    criticises a list of eight sites in one module was a list of three sites in three modules.

    **AND ITS ORACLE WAS BLIND TO `\\r`.** *Assert the line count is unchanged* cannot see a
    carriage return, which overwrites the line already printed without adding one — so a forged
    `GATE: MET (exit 0)` can REPLACE the real verdict line and leave the count identical.

    **SO: ESCAPE AT EACH RENDERER'S EMISSION POINT, AND HOLD IT WITH A PROPERTY.** Five
    chokepoints — `__main__._timeline_entry`, `report.render_page`, `show.render_run`,
    `show.render_project_lines`'s `line()` and `diff.render` — plus `__main__._diag` for all four
    of `gate`'s stderr diagnostics. The property names no field and no shape: **no character in
    anything this package prints may be one a terminal acts on rather than shows.** A field added
    to a page later is covered the day it is written, and `\\r` and `\x1b[` are caught by the
    same sentence as `\\n`.

    **THIS DOCSTRING CLAIMED A UNIVERSAL THE CODE DOES NOT HAVE, and Audit M withdrew the
    claim rather than the property.** It read *THE PROPERTY NEEDS NO EXEMPTIONS, which is what
    makes it a universal rather than a rule with excuses.* It has three, and naming them is the
    difference between a guard and a slogan:

    1. **`\n` IS WHITELISTED BY CONSTRUCTION, so `_acted_on` is blind to the forging
       character.** `not (c.isprintable() or c in " \n")` cannot be otherwise — `\n` is the
       page's own separator, and a page made of lines contains them by the thousand. So every
       newline-only forgery in this family reports `acted_on: []`, and the clause below fires
       only on the `\r` and the `\x1b[2K` this fixture plants beside it. That is why the
       SECOND oracle counts lines at the chokepoint instead, and why its floors are what hold
       `verify`, `check`, `impact` and `chain`.
    2. **THE PAYLOAD SIDE IS NOT ESCAPED AND MUST NOT BE** — `_report.printable`'s docstring
       states it, and `_SERIALISERS` above is the list of renderers on the other side of that
       line, held by equality against the derivation.
    3. **TWO LEGS NEED A FILENAME POSIX ALLOWS AND NTFS FORBIDS**, so they sit behind
       `_can_name_a_file_with_a_newline`. On a host that cannot hold such a name the defect
       cannot exist, which makes the skip correct scoping; the probe's own docstring says so,
       and the three channels that need no file run everywhere.

    Measured over the seven released histories, clean: **2 098 lines across twelve recipes,
    zero characters a terminal acts on** — asserted in the corpus test, so that premise is
    re-measured against every released wheel rather than stated here.

    **AND STDOUT AND STDERR ARE ONE STREAM** [L-23]: the concatenation is what this asserts,
    because that is what a CI log is.

    **THE STRUCTURAL HALF IS NEXT DOOR.** `test_every_page_main_prints_reaches_an_escaping_
    chokepoint` derives the renderer set from `__main__` by AST, because this test's own attack
    was a declared list of record FIELDS and that is how six renderers stayed forgeable behind
    it. Neither half is sufficient: this one cannot reach `prune`, which deletes, and that one
    cannot tell whether the transform was applied to every line.
    """
    root = _forged_history(tmp_path)
    monkeypatch.chdir(root)

    #: THE SCOPE IS DERIVED FROM THE PARSER, not typed here — the same table the corpus
    #: recipes use, so a new subcommand fails this file until it is given a recipe or named as
    #: a deliberate omission with its reason.
    commands = _corpus_commands(capsys)
    missing = [c for c in commands if c not in CORPUS_RECIPES and c not in CORPUS_NOT_READERS]
    assert not missing, f"{missing} is not attacked by this test and has no stated exemption"

    #: TEXT, NOT JSON — `--format json` is `json.dumps`, which escapes already and is not what
    #: this is about. `gate`'s corpus recipe asks for JSON for a different reason, so the flag
    #: is dropped here rather than the recipe being written out a second time.
    recipes = {
        name: [a for a in argv if a not in ("--format", "json")]
        for name, argv in CORPUS_RECIPES.items()
    }
    #: TWO MORE PAGES NO RECIPE REACHES: `show <target>`, which is a different renderer from
    #: `show`, and `--emit-policy`, which renders the policy's `why` with no history at all.
    #: THE TARGET IS THE CLEAN NAME, and that is the difference between attacking this page
    #: and attacking the refusal above it: a forged target matches no run, so `show` prints a
    #: *no such run* diagnostic and `render_run` is never called. Reverting its escaping stayed
    #: GREEN until this recipe named a run that exists.
    recipes["show <target>"] = ["show", "align", "--log", "prov/history.jsonl"]
    recipes["gate --emit-policy"] = ["gate", "--policy", "policy.json", "--emit-policy"]
    #: AND TWO MORE AUDIT M FOUND, each reaching a renderer no recipe above touches.
    #:
    #: `verify .` WALKS THE TREE, which is the only way the artifact FILENAME channel reaches
    #: `verify.render_report` — `verify out/align.tsv` names one clean path and can carry
    #: nothing. This is also the page `action.yml` prints inside `::group::runprov verify`.
    #:
    #: `chain <forged argv>` IS ONE ARGUMENT AND NOTHING ELSE, which makes it the most
    #: reachable route in this whole family: no record, no history, no file, every platform.
    #: `chain prov/history.jsonl` cannot carry it, so without this leg `chain.render`'s
    #: escaping had no behavioural guard at all.
    recipes["verify <tree>"] = ["verify", "."]
    recipes["chain <forged argv>"] = ["chain", f"prov/history.jsonl{_FORGERY}"]

    #: THE NEWLINE-AWARE ORACLE, AND IT IS THE ONE THING `_acted_on` CANNOT BE [Audit M].
    #: `_acted_on` whitelists `\n` BY CONSTRUCTION, because `\n` is the page's own separator —
    #: so every newline-only forgery in this family reports `acted_on: []` and the property
    #: above fires only on the `\r` and the `\x1b[` this fixture plants. The forging character
    #: is the one the oracle cannot see.
    #:
    #: SO THE SECOND ORACLE COUNTS LINES AT THE CHOKEPOINT ITSELF. Every renderer hands
    #: `printable_lines` the list of lines it believes it is emitting; a line in that list
    #: containing a newline is a line the page emits that the renderer did not count. The spy
    #: records those, per module and per function, and the assertions below are what make the
    #: legs' LIVENESS an assertion rather than a hope: Audit M found `verify` and `check`
    #: producing 255- and 194-byte REFUSAL pages, so reverting either renderer's escaping was
    #: green, and nothing in this file said otherwise.
    forged_lines: dict[str, int] = {}
    reached: dict[str, set[str]] = {}

    def _spy(original, module, per_line):
        def inner(value):
            lines = list(value) if per_line else [value]
            extra = sum(len(line.split("\n")) - 1 for line in lines)
            if extra:
                #: THE CALLER'S OWN NAME, so the floors below can name a RENDERER rather than a
                #: module. `show`'s page carries the forgery through a dozen fields, so a
                #: module-level count stayed green when the orphan `start.v1` line was taken
                #: out of the fixture and the in-flight banner stopped being rendered at
                #: all — measured, and that banner is the one site escape-4 fixed in
                #: `__main__`.
                where = f"{module}.{sys._getframe(1).f_code.co_name}"
                forged_lines[where] = forged_lines.get(where, 0) + extra
                reached.setdefault(current[0], set()).add(where)
            return original(value)

        return inner

    current = [""]
    #: BOTH CHOKEPOINTS, because the package has two shapes of them and a spy on one is blind
    #: to the other: `policy` escapes PER FIELD with `printable` and would otherwise look like
    #: a leg the forgery never reached.
    for module in [
        m for m in sys.modules.values() if getattr(m, "__name__", "").startswith("runprov")
    ]:
        for chokepoint in _CHOKEPOINTS:
            original = getattr(module, chokepoint, None)
            if original is not None and getattr(original, "__module__", "") == "runprov._report":
                monkeypatch.setattr(
                    module,
                    chokepoint,
                    _spy(original, module.__name__, chokepoint == "printable_lines"),
                )

    carried: list[str] = []
    for name, argv in recipes.items():
        if name in CORPUS_NOT_READERS:  # pragma: no cover - they are not in CORPUS_RECIPES
            continue
        current[0] = name
        runprov.configure(root=".", run_log="prov/history.jsonl")
        capsys.readouterr()
        try:
            code = runprov.__main__.main(list(argv))
        except SystemExit as exc:
            code = exc.code if isinstance(exc.code, int) else 2
        except Exception as exc:
            pytest.fail(f"`runprov {' '.join(argv)}` raised {type(exc).__name__}: {exc}")
        shown = capsys.readouterr()
        both = shown.out + shown.err
        assert code in (0, 1, 2), f"{name} exited {code}"
        assert _acted_on(both) == [], (
            f"[L-03] `{name}` printed {_acted_on(both)} — a character a terminal ACTS on rather "
            f"than shows, so a recorded field can forge or erase a line of this page:\n{both!r}"
        )
        #: THE SEQUENCE A FIELD CONTRIBUTED, WHEREVER IN THE LINE IT BEGINS, and it is first
        #: because it does not depend on the forgery landing at the start of a line.
        #:
        #: AUDIT M FILED THE CLAUSE BELOW AS UNDER-DETECTING — *`report`/`verify`/`check`/
        #: `export` put the forgery mid-line, so `_FORGED_LINE not in splitlines()` never
        #: fires* — AND THAT DID NOT REPRODUCE. `str.splitlines` splits on `\r` as well as on
        #: `\n`, so a mid-line forgery still yields `GATE: MET (exit 0)` as an exact element:
        #: reverting each of the five renderers Audit M added turns the clause below red, every
        #: time, measured. It is kept, and this stronger form is put in front of it rather than
        #: in place of it, because the claim it makes needs no argument about `splitlines`.
        assert f"\n{_FORGED_LINE}\n" not in both, (
            f"[Audit M escape-5] `{name}` let a newline out of a field: the page carries "
            f"{_FORGED_LINE!r} on a line of its own that no renderer counted:\n{both!r}"
        )
        assert _FORGED_LINE not in both.splitlines(), (
            f"[L-03] `{name}` forged a line reading exactly {_FORGED_LINE!r}:\n{both}"
        )
        if _FORGED_LINE in both:
            carried.append(name)

    #: ESCAPING IS NOT CENSORING — AND IT IS A COUPLING BETWEEN TWO MEASUREMENTS THIS TEST
    #: ALREADY TAKES, NOT A FLOOR [Audit N, guards-6]. It was `len(carried) >= 12`, which was
    #: the FIFTH restatement of clause 3 of the docstring and the one Audit M's four-site table
    #: did not list: a constant standing beside the filename exemption rather than derived from
    #: it. **And it held under the probe inversion only because the set LOSES `check` and GAINS
    #: `resources`** — the number was right for the wrong reason, and that coincidence is
    #: precisely what hid the vacuous `resources` leg for a release.
    #:
    #: A SIXTH DECLARED SET WAS REFUTED RATHER THAN SKIPPED. The obvious repair — a set identity
    #: against the probe-derived exemption — was measured and is RED on `windows-latest / 3.12`:
    #: `verify <tree>` is in `filename_only` and still CARRIES on a probe-false host, because its
    #: text arrives through the run's `script`. So the two exemptions are NOT one set seen from
    #: two ends here, and the only identity that passes both branches needs a hand-written
    #: three-name set plus a hand-written subtraction — a SEVENTH restatement.
    #:
    #: SO THE CLAIM IS MADE AS A COUPLING, which is the only property the floor ever wanted: a
    #: command that got the forgery into one of its renderers must SHOW it. That is computed
    #: from `reached` and `carried`, is IDENTICAL on both probe branches, names the offender,
    #: and — unlike a count — CANNOT BE MET BY A MEMBERSHIP SWAP. A renderer that started
    #: dropping the text instead of escaping it leaves its command in `reached` and takes it out
    #: of `carried`, and lands here by name.
    #:
    #: THE CONVERSE HOLDS THE BOOKKEEPING: every renderer `reached` names must be one
    #: `forged_lines` counted. The two are written by one `if extra:` branch in the spy but
    #: keyed differently — `forged_lines` by the renderer, `reached` by `current[0]` — so this
    #: is the assertion that `current[0]` is still being advanced per recipe. Without it a spy
    #: that stopped tracking the command would file every renderer under one stale name and the
    #: inclusion above would still pass.
    reached_renderers = {where for names in reached.values() for where in names}
    assert set(reached) <= set(carried), (
        f"{sorted(set(reached) - set(carried))} handed the forgery to one of their own renderers "
        f"and then did not print it. Escaping is not censoring: the text must still reach the "
        f"reader and only its power to move the cursor may be gone, so a page that printed LESS "
        f"would satisfy the property above while telling the reader less than the record holds. "
        f"Reached: { {k: sorted(v) for k, v in sorted(reached.items())} }; carried: {carried}"
    )
    assert reached_renderers == set(forged_lines), (
        f"the spy's two books disagree: `reached` names {sorted(reached_renderers)} and "
        f"`forged_lines` counted {sorted(forged_lines)}. They are written by one branch and "
        f"keyed differently, so a disagreement means `current[0]` is no longer advanced per "
        f"recipe and every floor below is being measured against the wrong command"
    )

    #: AND THE ATTACK REACHED A RENDERER, PER COMMAND. This is the vacuity assertion the two
    #: 255-byte legs needed: a command whose page is a refusal, or whose fixture lost the file
    #: the walk had to find, plants no newline in any renderer's line list and lands here.
    #: AND THE ATTACK REACHED A RENDERER, PER COMMAND. This is the vacuity assertion the two
    #: refusal pages needed: a command whose page is a refusal, or whose fixture lost the file
    #: the walk had to find, hands no renderer a line with a newline in it and lands here.
    #: Measured at 12 of 12 carriers, so the claim is an equality in all but shape.
    #: TWO LEGS' ONLY NEWLINE CHANNEL IS A FILENAME, and the fixture already puts both
    #: behind `_can_name_a_file_with_a_newline`. THIS ASSERTION DID NOT KNOW THAT, so the
    #: Windows leg of `4b2ac25` went red here naming `verify <tree>`: the docstring above
    #: states that those legs sit behind the probe, and nothing held the statement — a
    #: docstring is not a contract until something checks it, one layer in, in the test
    #: written to retire exactly that shape.
    #:
    #: On a host whose names cannot hold a control character the forged TEXT still reaches
    #: `verify`'s page through the run's `script`, so the name stays in `carried` while no
    #: renderer is ever handed a newline. That is the probe's own *the defect cannot exist
    #: here*, not a vacuous leg. THE EXEMPTION IS EMPTY WHERE THE CHANNEL EXISTS, so it
    #: cannot start covering a real regression on the hosts that can see one.
    filename_only = (
        set() if _can_name_a_file_with_a_newline(tmp_path) else {"verify <tree>", "check"}
    )
    vacuous = sorted(
        name for name in carried if not reached.get(name) and name not in filename_only
    )
    assert not vacuous, (
        f"[Audit M escape-5] {vacuous} printed the forged TEXT but no renderer of theirs was "
        f"ever handed a line with a newline in it, so this leg asserts nothing about the "
        f"escaping it is supposed to be testing. That is how `verify` (255 bytes) and `check` "
        f"(194 bytes) sat here GREEN over refusal pages for a whole release. Reached: "
        f"{ {k: sorted(v) for k, v in sorted(reached.items())} }"
    )

    #: AND THE FOUR RENDERERS AUDIT M ADDED TO THIS FAMILY ARE NAMED, because a floor over the
    #: set can be met without any of them: each of `verify`, `check`, `impact` and `chain` was
    #: forgeable behind a green suite, two of them through a leg that was a refusal page, and
    #: the only thing that distinguishes "escaped" from "never attacked" is a measurement that
    #: the forgery got into THAT module's line list.
    owed = {
        "runprov.verify.render_report",
        "runprov.check.render",
        "runprov.impact.render",
        "runprov.chain.render",
        #: THE IN-FLIGHT BANNER, escape-4's one `__main__` site. It renders only for a run that
        #: STARTED with no ending on record, which no corpus recipe produces and no earlier
        #: fixture had: the orphan `runprov.start.v1` line above is its only channel, and
        #: without this name in the set, deleting that line left the whole file green.
        "runprov.__main__.report",
    }
    #: AND THE SAME PROBE AGAIN, FOR THE THIRD ASSERTION IN THIS TEST THAT NEEDED TELLING.
    #: `verify.render_report` and `check.render` are reachable ONLY through a FILENAME — an
    #: artifact the tree walk finds, and a source file whose name ends in `.py` — so on a host
    #: whose names cannot hold a control character neither renderer can be handed a forged
    #: line, and owing them one is owing something the filesystem forbids. The other three are
    #: platform-neutral by construction (`impact` takes a forged `script`, `chain` takes a
    #: forged argv, the banner takes an orphan `start.v1` line), so the floor keeps its whole
    #: force on Windows for everything that CAN be attacked there.
    #:
    #: THIS IS THE THIRD PLACE IN ONE TEST where the docstring's clause 3 was true and nothing
    #: held it: the fixture gates both channels on the probe, and then `vacuous` and this floor
    #: each assumed they had run. `66f10ca` fixed the first and the Windows leg immediately
    #: named the second. **A claim stated once and relied on in three places is three
    #: unguarded claims**, which is the list-of-sites shape this whole test exists to retire,
    #: appearing inside it for the fourth time.
    filename_channel = {"runprov.verify.render_report", "runprov.check.render"}
    if not _can_name_a_file_with_a_newline(tmp_path):
        owed -= filename_channel
    #: THE TWO EXEMPTIONS MUST AGREE, so neither can be relaxed alone: the commands dropped
    #: from `vacuous` above and the renderers dropped here are the same channel seen from the
    #: two ends, and on a host that CAN hold the name both sets are empty.
    assert bool(filename_only) == bool(filename_channel - owed), (
        f"the two filename-channel exemptions disagree: commands {sorted(filename_only)} but "
        f"renderers {sorted(filename_channel - owed)}. They are one channel seen from two ends"
    )
    assert owed <= set(forged_lines), (
        f"{sorted(owed - set(forged_lines))} were handed no line with a newline in it, so their "
        f"escaping is not held by anything here. Audit M added all five to this family and two "
        f"of them had legs that stopped at a refusal page: `verify` needs an artifact with a "
        f"readable PIN and a non-OK status, `check` needs a `.py` file the walk can find, "
        f"`impact` needs a run whose `script` is forged, `chain` needs a forged argv, and the "
        f"in-flight banner needs an orphan `runprov.start.v1` line. Reached: {forged_lines}"
    )
    #: AND THE FLOOR IS DERIVED FROM THE EXEMPTION, NOT RESTATED BESIDE IT. This is the FOURTH
    #: assertion in this test that depends on clause 3 of the docstring, and the first three
    #: were each found by a separate red leg: `66f10ca` fixed `vacuous`, the next Windows run
    #: named the `owed` floor, and a local simulation that forces the probe to `False` named
    #: this one before any matrix saw it. **So the number is computed from the set that was
    #: actually exempted** — a fifth place to keep in step would have been found the same
    #: expensive way, and a constant restated beside an exemption is the list-of-sites shape
    #: again, inside the test that exists to retire it.
    #: AND THE BASE MOVED 14 -> 15 IN THE COMMIT THAT REORDERED THE FIXTURE [Audit N,
    #: guards-2]. Making `resources` a live leg adds `__main__._resources_text` to this set, so
    #: a base left at 14 would have been slack by one on both branches — and a floor restated
    #: beside a fixture it is measured from is the list-of-sites shape a SIXTH time, created by
    #: the fix for the fifth. Measured after the reorder: 15 renderers where every channel
    #: exists, 13 where the filename channel does not, and `filename_channel - owed` is exactly
    #: the 2 that separates them. The figure is EXACT on both probe branches, not slack.
    floor = 15 - len(filename_channel - owed)
    assert len(forged_lines) >= floor, (
        f"the newline forgery reached a chokepoint in only these renderers: "
        f"{sorted(forged_lines)}. Fifteen is what this fixture measured where every channel "
        f"exists, {floor} is owed on this host, and fewer means a leg has gone quiet."
    )


def test_prune_does_not_forge_a_line_from_a_marker_filename(tmp_path, capsys, monkeypatch):
    r"""[Audit Q, decision-1] `prune.apply`'s failure line, held by the VALUE ON THE STREAM.

    **THIS IS THE LEG THAT HOLDS WHAT THE AST DERIVATION CANNOT.** The structural half next
    door -- `test_every_page_main_prints_reaches_an_escaping_chokepoint` -- resolves printed
    expressions to renderers by syntax, and five ordinary refactorings defeat it while still
    putting the forged bytes on stderr: a module-level alias, a two-step alias,
    `functools.partial`, `getattr(mod, "render")` and a dict lookup. They are declared at
    `_has_renderer_call` and they are all INVISIBLE TO THIS TEST, because this one does not
    read the syntax at all: it runs the command and counts the lines. *"This string becomes a
    line a person reads"* is a runtime property, and no AST-only derivation can hold it.

    **AND THE REASON THIS LEG WAS THOUGHT IMPOSSIBLE WAS TOO STRONG.** `CORPUS_NOT_READERS`
    excludes `prune` because *"prune deletes in-flight markers, and a test that mutates the
    corpus is a test that changes its own subject between runs"*, and the structural half's own
    docstring says *"`prune` DELETES, so a behavioural leg for it would mutate its own
    subject"*. Both are true of a leg pointed at a real directory and neither is true here:
    `plan` is stubbed, so the forged path is CONSTRUCTED AND NEVER CREATED, the directory is
    never made, `unlink` is replaced before it can run, and **nothing touches the filesystem at
    all.** The already-shipped `test_prune_exits_1_when_a_marker_would_not_go` had been
    monkeypatching `unlink` to raise and deleting nothing since before this row was filed.

    **WHICH MAKES IT PLATFORM-NEUTRAL, AND THAT IS STRICTLY BETTER THAN THE THREE EXISTING
    LEGS.** The forgery channel here is a FILENAME, which is the channel `verify` and `check`
    are attacked through -- and those two are gated behind `_can_name_a_file_with_a_newline`,
    so on Windows they are dropped from `owed` and the floor above falls by two. A name that is
    never written to a filesystem needs no filesystem to accept it, so this leg keeps its whole
    force on every leg of the matrix.

    Measured on 3.10 / 3.11 / 3.12 / 3.13 / 3.14, with the import proved and the arrival
    control live: with `prune.apply` returning its messages raw, `rc=1` and one bare forged
    line; with `printable_lines` applied, `rc=1` and zero. The negative control -- the same
    leg with the ordinary name `dead.json` -- is green BOTH ways, so this is not trivially red.
    """
    #: A NAME, NOT A FILE. Legal on POSIX, never created here, and the point of the row: one
    #: newline inside one interpolated field forges a whole line on the page.
    forged = "a\nGATE: MET (exit 0)\nb.json"
    doomed = tmp_path / ".incomplete" / forged
    monkeypatch.setattr(
        runprov.prune,
        "plan",
        lambda directory, **kw: runprov.prune.Plan([doomed], 0, 0, 0, 0, 0, 0),
    )
    monkeypatch.setattr(
        pathlib.Path,
        "unlink",
        lambda self, *a, **k: (_ for _ in ()).throw(PermissionError(13, "denied")),
    )
    code = cli.main(["prune", "--log", str(tmp_path / "runs.jsonl")])
    err = capsys.readouterr().err

    #: THE ARRIVAL CONTROL, FIRST, because every assertion below is vacuous without it and a
    #: behavioural leg whose fixture never reaches the code under test passes forever. It is
    #: deliberately a prefix that survives BOTH outcomes -- escaped or raw -- so it cannot
    #: double as the property and steal its diagnostic.
    assert code == 1 and "could not remove a" in err, (
        f"this leg no longer reaches `prune.apply`'s failure line, so it proves nothing about "
        f"escaping: exit {code}, stderr {err!r}. `plan` must hand back a `remove` entry and "
        f"`unlink` must raise."
    )
    #: THE NAMED DEFECT, BEFORE ANY TOTAL. A bare line reading exactly this is what a CI log
    #: scraped for `GATE:` reads first, and it is the line this whole family exists to stop.
    bare = [n for n, line in enumerate(err.splitlines(), 1) if line == "GATE: MET (exit 0)"]
    assert not bare, (
        f"stderr line(s) {bare} read exactly `GATE: MET (exit 0)` and nothing on the page put "
        f"them there -- they came out of a marker FILENAME interpolated into "
        f"`prune.apply`'s failure message. Apply `printable_lines` where those messages leave "
        f"`apply`; escaping them one f-string at a time is the list of call sites this "
        f"package has had to widen nine times. Page: {err!r}"
    )
    #: AND THE VALUE IS STILL THERE, ESCAPED, which is the other half: a transform that
    #: DELETED the newline would satisfy the clause above and lose the user's filename.
    assert "could not remove a\\nGATE: MET (exit 0)\\nb.json" in err, (
        f"the forged name must survive on the page in its escaped spelling -- the user needs "
        f"to know WHICH file would not go. Page: {err!r}"
    )


def _argument_slots() -> dict[str, dict[str, list[str]]]:
    """Every subcommand argparse declares, and every value-taking slot each one declares.

    BY AST, for the reason `_cli_subcommands` already gives one screen up: the parser is built
    inside `main()`, there is no factory to call, and `_SubParsersAction.choices` is private API
    that has changed shape between versions. The two walks read the same `add_parser` calls, and
    the caller below asserts they agree -- which is what makes a collector that stopped reading
    `add_argument` red as *this instrument stopped reading* rather than green.

    A `store_true`/`store_false` flag is skipped because it takes no value, so there is nothing
    to drive into it. Everything else is a slot, including the ones that take an `int` or a
    `choices` list: argparse refuses those itself and the caller classifies that refusal.
    """
    tree = ast.parse((_repo_root() / "runprov" / "__main__.py").read_text(encoding="utf-8"))
    var2cmd: dict[str, str] = {}
    slots: dict[str, dict[str, list[str]]] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Call):
            call = node.value
            if (
                isinstance(call.func, ast.Attribute)
                and call.func.attr == "add_parser"
                and call.args
                and isinstance(call.args[0], ast.Constant)
            ):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        var2cmd[target.id] = call.args[0].value
                        slots.setdefault(call.args[0].value, {"pos": [], "opt": []})
    for node in ast.walk(tree):
        if not (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "add_argument"
            and isinstance(node.func.value, ast.Name)
        ):
            continue
        cmd = var2cmd.get(node.func.value.id)
        if cmd is None or not node.args or not isinstance(node.args[0], ast.Constant):
            continue
        names = [a.value for a in node.args if isinstance(a, ast.Constant)]
        action = {k.arg: k.value for k in node.keywords}.get("action")
        if isinstance(action, ast.Constant) and str(action.value).startswith("store_"):
            continue
        slots[cmd]["opt" if names[0].startswith("-") else "pos"].append(names[-1])
    return slots


def test_no_command_forges_a_line_from_a_newline_bearing_argument(tmp_path, monkeypatch):
    r"""`__main__`'s OWN composed stderr lines, held by the VALUE ON THE STREAM.

    **THE SURFACE THIS CLOSES, AND IT WAS THE LARGEST KNOWN ONE IN THE PACKAGE.** Audits L and
    M swept the RENDERERS and put `printable_lines` at each chokepoint. `__main__`'s one-off
    diagnostics go through no renderer, so the sweep never reached them: Audit Q patched two of
    them, each found by accident, and left the rest with *no count claimed*. Derived here: of
    the 95 emissions in `__main__.py` that compose a line around a non-literal, 45 are
    `__main__`'s own composed stderr lines and 32 of those interpolate an outside-controlled
    value. 31 of the 32 were reproduced as live forgeries at `49ac301` with no modified file.

    **AND WHAT HOLDS THEM IS NOT THIS FILE'S SYNTAX.** They are escaped ONE CALL SITE AT A TIME,
    which is the shape `printable_lines`' own docstring calls *the thing this repository has had
    to widen nine times* -- and no chokepoint is available, because these templates carry their
    own newlines, so escaping the composed string would collapse each page into one long line.
    So the property is enforced where it lives: this leg RUNS the command and COUNTS THE LINES.
    `test_prune_does_not_forge_a_line_from_a_marker_filename` is the same shape one module over,
    and the reason is the same one `guard-shapes` gives: *"this string becomes a line a person
    reads"* is a RUNTIME property, and no AST-only derivation can hold it.

    **THE CLAIM AND THE QUANTIFICATION, ONE SENTENCE EACH, SO THEY CAN BE COMPARED** [Audit P's
    rule, violated by its own repairs four times out of five]:

      CLAIM: no subcommand puts a bare forged line on a stream it writes, when a
             newline-bearing path is driven into an argument slot it declares.
      QUANT: for every subcommand argparse declares, and every value-taking slot it declares.

    They are the same sentence. **The residue is therefore exactly the channels that are NOT an
    argv path** -- a record field, an exception's `str()`, a policy `why` -- and those are held
    at their 32 emission points, which were reproduced and escaped individually, not here.

    **PLATFORM-NEUTRAL FOR ALL BUT ONE COMMAND, AND THE EXCEPTION IS DERIVED, NOT LISTED.** The
    forged value is always rooted under a REGULAR FILE, so nothing under it can be created on
    any platform. What the ATTACK needs is therefore no filesystem at all -- unlike the three
    legs gated behind `_can_name_a_file_with_a_newline` -- for every command whose arriving
    channel writes nothing. Measured at `1ad4d42` on POSIX: 14 of the 15 are such commands;
    `exec` is not, because it names its sidecar after the command it was handed. The
    quantification below narrows to the derived set on a host that cannot hold the name, and
    asserts that the narrowing is EMPTY on a host that can.

    **THIS PARAGRAPH STATES THE DIRECTION AND DATES THE RATES.** A first draft of it claimed
    15 of 15, which was an instrument artefact: the standalone prototype did not reset
    `project._ACTIVE`, so `exec`'s sidecar was written into the FIRST attempt's directory and
    the per-attempt check for a created name looked in the wrong place. The number moved from
    15 to 14 the moment the reset was added.

    **WHAT IS NOT ASSERTED, AND WHY.** `exec --provenance` and `exec --name` reach
    `__main__.py:1079`, `provenance.parent.mkdir(parents=True, exist_ok=True)`, which raises a
    RAW `FileExistsError` traceback when a path component is a regular file. Reproduced at
    `1ad4d42` with an ordinary name and no newline anywhere, so it is a different defect in a
    different class -- a traceback where this module says *"A MESSAGE, not a traceback"*
    everywhere else -- and it is recorded here rather than widened into. A raise is collected
    and reported in the diagnostics below; it is not the subject.

    Measured over the revert of the 32 escapes: **21 bare forged lines across 12 of the 15
    subcommands, arrival still 15 of 15**, so the vacuity control does not steal the named
    clause's diagnostic. With the escapes: **0 bare lines, and the escaped spelling present for
    15 of 15 against 9 of 15 before** -- so the last clause is a real second half and not a
    restatement.
    """
    sentinel = "GATE: MET (exit 0)"
    slots = _argument_slots()

    #: THE EXEMPTION'S SUBJECT, ASSERTED FIRST AND BY PRESENCE RATHER THAN BY COUNT [Audit Q,
    #: decision-4]. Two independent AST walks read the same `add_parser` calls; if this one ever
    #: stops seeing a subcommand, or sees a subcommand with no slot at all, everything below it
    #: becomes a loop over nothing and passes forever. This is the clause that reds as *this
    #: instrument stopped reading*, and it is before the main clauses for that reason.
    assert set(slots) == set(_cli_subcommands()), (
        f"the two parser walks disagree: this one found {sorted(slots)} and "
        f"`_cli_subcommands` found {sorted(set(_cli_subcommands()))}. They read the same "
        f"`add_parser` calls, so a disagreement means one of them has stopped reading and "
        f"every clause below is quantifying over the wrong set"
    )
    empty = sorted(c for c, s in slots.items() if not s["pos"] and not s["opt"])
    assert not empty, (
        f"{empty} declare no value-taking argument slot, so this leg drives nothing into them "
        f"and asserts nothing about them. Either the subcommand really takes no value -- say so "
        f"here -- or `_argument_slots` has stopped reading `add_argument`"
    )

    bare: dict[str, list[tuple[str, int]]] = {}
    arrived: dict[str, list[str]] = {}
    unwritten: set[str] = set()
    escaped_survived: set[str] = set()
    raises: list[tuple[str, str, str]] = []
    for command, slot in sorted(slots.items()):
        attempts: list[tuple[str, list[str]]] = []
        if slot["pos"]:
            attempts.append((f"pos*{len(slot['pos'])}", [""] * len(slot["pos"])))
        for option in slot["opt"]:
            attempts.append((option, [option, "", *([""] * len(slot["pos"]))]))
        for index, (label, template) in enumerate(attempts):
            #: THE LABEL IS A DIAGNOSTIC SPELLING, NOT A FILENAME, and naming the attempt's
            #: directory after it made this leg UNABLE TO RUN on Windows. `pos*2` is the label for
            #: "this subcommand's two positionals", and `*` is legal in a POSIX name and illegal in
            #: a Windows path, so `mkdir` raised `OSError: [WinError 123]` and the whole leg errored
            #: on `windows-latest` while all five POSIX jobs were green [MATRIX RED AT a846bad, the
            #: commit that introduced this test]. It did not fail there and it did not become a
            #: floor there -- it ASSERTED NOTHING there, which is the worse outcome of the two the
            #: docstring below contemplates. So the name is derived from the attempt's INDEX, which
            #: cannot carry a character any filesystem refuses, and the label still reaches every
            #: diagnostic in this leg unchanged.
            here = tmp_path / f"{command}-{index}"
            here.mkdir(parents=True, exist_ok=True)
            #: A REGULAR FILE, so every path below it is unopenable AND uncreatable on every
            #: platform. That is what makes the forged NAME never reach the filesystem.
            (here / "blocker").write_text("a regular file", encoding="utf-8")
            forged = str(here / "blocker" / f"n1\n{sentinel}\nn2")
            monkeypatch.chdir(here)
            monkeypatch.setattr(runprov.project, "_ACTIVE", None)
            out, err = io.StringIO(), io.StringIO()
            argv = [command, *(forged if a == "" else a for a in template)]
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                try:
                    cli.main(argv)
                except SystemExit:
                    pass
                except BaseException as exc:  # recorded below, and not the subject
                    raises.append((command, label, type(exc).__name__))
            page = f"{err.getvalue()}\n{out.getvalue()}"
            #: ARGPARSE'S OWN REFUSAL IS NOT A LEG. An `int` slot, a `choices` slot and a
            #: positional this attempt did not supply all land here, and counting them as
            #: arrivals would make the control below green over nothing.
            if any(
                refusal in page
                for refusal in ("unrecognized arguments", "invalid choice", "expected one argument")
            ):
                continue
            bare.setdefault(command, []).extend(
                (label, n) for n, line in enumerate(page.split("\n"), 1) if line == sentinel
            )
            if forged in page or forged.replace("\n", "\\n") in page:
                arrived.setdefault(command, []).append(label)
                if not any("\n" in p.name for p in here.rglob("*")):
                    unwritten.add(command)
            if forged.replace("\n", "\\n") in page:
                escaped_survived.add(command)
    bare = {command: hits for command, hits in bare.items() if hits}

    #: THE VACUITY CONTROL, PER COMMAND, BEFORE THE PROPERTY. A behavioural leg whose fixture
    #: never reaches the code under test passes forever, and `guard-shapes` rates that shape
    #: worse than a missing member. It is deliberately satisfied by EITHER spelling -- raw or
    #: escaped -- so it survives the revert and cannot double as the property below.
    #:
    #: **AND THE SUBJECT IS NARROWED FOR ONE HOST CLASS, DERIVED RATHER THAN LISTED.** A first
    #: draft asserted that every arriving channel CREATES NOTHING, and it CANNOT PASS: `exec`
    #: names its sidecar after the command it was given, so all four of its arriving slots write
    #: `provenance/<the forged name>.prov.json` -- measured, with `--name` and `--provenance` not
    #: arriving at all. On a host whose filesystem refuses a control character in a name, that
    #: command cannot be attacked through this door at all, so the quantification is over
    #: `unwritten` there: the commands that arrived through a slot which created nothing. That is
    #: computed from what each attempt ACTUALLY created, so no command is named here.
    #:
    #: **THE EXEMPTION IS EMPTY WHERE THE CHANNEL EXISTS** [Audit M, escape-5's shape], which is
    #: the clause that stops the narrowing from quietly starting to cover a real regression: on a
    #: host that CAN hold the name the expected set is every subcommand, with nothing excused.
    #: Measured at `1ad4d42` on POSIX: 15 of 15 arrived, 14 of 15 through a slot creating
    #: nothing. On Windows this clause is a FLOOR over `unwritten` and not an exhaustiveness
    #: assertion, and that is said here because a docstring is not a contract until something
    #: checks it -- the two clauses below keep their whole force over whatever did arrive.
    holds_a_newline = _can_name_a_file_with_a_newline(tmp_path)
    expected = set(slots) if holds_a_newline else unwritten
    assert holds_a_newline == (expected == set(slots)), (
        f"the narrowing and the probe disagree: the filesystem "
        f"{'can' if holds_a_newline else 'cannot'} "
        f"hold a control character in a name, and the expected set is "
        f"{'' if expected == set(slots) else 'not '}every subcommand. Where the channel exists "
        f"nothing may be excused: expected {sorted(expected)} of {sorted(slots)}"
    )
    never = sorted(expected - set(arrived))
    assert not never, (
        f"{never} never put the forged value on either stream through any slot they declare, "
        f"so this leg asserts nothing about them. Measured at `1ad4d42` on POSIX: 15 of 15 "
        f"arrived, 14 of 15 through a slot that created nothing. Arrived: "
        f"{dict(sorted((k, sorted(v)) for k, v in arrived.items()))}; raises: {raises}"
    )

    #: THE NAMED DEFECT, AND IT NAMES THE COMMAND AND THE SLOT. A bare line reading exactly this
    #: is what a CI log scraped for `GATE:` reads first.
    assert not bare, (
        f"these commands put a line reading exactly `{sentinel}` on a stream, and nothing on "
        f"the page put it there -- it came out of a newline-bearing PATH interpolated into one "
        f"of `__main__`'s own composed diagnostics: "
        f"{dict(sorted(bare.items()))}. Wrap the interpolated value in "
        f"`printable` at the emission point (imported at `__main__.py:78`); escaping the "
        f"composed STRING is not available here, because these templates carry their own "
        f"newlines and `printable` of the whole page collapses it into one line"
    )
    #: AND THE VALUE IS STILL THERE, ESCAPED, PER COMMAND -- the other half, because a transform
    #: that DELETED the newline satisfies the clause above and loses the user's path. Measured
    #: over the revert at 9 of 15, so this is a second measurement and not a restatement.
    #: OVER WHAT ARRIVED, not over every subcommand, for the reason the narrowing above gives:
    #: a command this host cannot attack has no page to carry anything.
    lost = sorted(set(arrived) - escaped_survived)
    assert not lost, (
        f"{lost} no longer show the forged path in its escaped spelling anywhere on their page. "
        f"Escaping is not censoring: the reader needs to know WHICH path, and only its power to "
        f"move the cursor may be gone. Arrived: "
        f"{ {k: sorted(v) for k, v in sorted(arrived.items())} }"
    )


def test_emit_policy_answers_about_the_file_and_opens_no_history(tmp_path, capsys):
    """[ADR-0018 R-14] [ADR-0018 R-11] T-34. The third half of Taylor's ruling.

    Someone who writes TOML needs the machine-readable form to file, and that is a question about
    the FILE rather than about any run. So `--emit-policy` reads the policy through the same
    `load()` the gate uses — **one validation path, so a policy that emits is a policy the gate
    accepts** — and answers about nothing else.

    **THE PROOF THAT NO HISTORY IS READ IS A `--log` THAT DOES NOT EXIST.** Every other state of
    this command exits 2 for that, so an invocation that exits 0 with an absent history is the
    assertion rather than a claim about it. And the flag is ANNOUNCED on stderr rather than
    accepted and ignored: `verify --log` is the sibling that does the same, and a flag that is
    accepted and does nothing is the silent no-op this package refuses everywhere else.

    **0 USABLE, 2 NOT, AND NEVER 1.** A policy cannot carry a finding — it is either a document
    this version can act on or it is not — so L-81's middle code is deliberately absent here.
    """
    reason = "ISO 15189 5.5.1: the analysis must be traceable to a known code state"
    as_toml = tmp_path / "policy.toml"
    as_toml.write_text(f'[[rules]]\nrule = "finished_ok"\nwhy = """{reason}"""\n', encoding="utf-8")
    absent = tmp_path / "there-is-no-history-here.jsonl"

    capsys.readouterr()
    code = runprov.__main__.main(
        [
            "gate",
            "--policy",
            str(as_toml),
            "--emit-policy",
            "--log",
            str(absent),
            "--format",
            "json",
        ]
    )
    shown = capsys.readouterr()
    assert code == 0, (
        "[ADR-0018 R-14] a usable policy is exit 0 even though the history named does not exist, "
        f"which is the assertion that no history was opened: {shown.err}"
    )
    assert not absent.exists(), "the premise: the history named was never there"
    body = json.loads(shown.out)
    assert body["schema"] == runprov.policy.POLICY_SCHEMA == "runprov.policy.v1", (
        "a normalised policy carries no verdict, no count and no history, so it must not wear the "
        f"gate's version: {body.get('schema')}"
    )
    assert body["rules"] == runprov.policy.load(as_toml)["rules"], body
    #: `_posix`, NEVER `str()` — the sixth site in this file to use the one spelling every
    #: recorded path uses, and the one that CAUGHT THIS. `str(WindowsPath(...))` is
    #: `C:\Users\...` while the payload carries `C:/Users/...`, because K-12's rename ran into
    #: `test_no_recorded_path_is_spelled_with_a_bare_str` on the way in and the CODE was made
    #: right. **The test was then left asserting what the HOST supplies**, which is the smell
    #: `FEATURE_WORKFLOW.md` lists tenth — green on Linux and macOS, red on the Windows leg, and
    #: invisible to the local gate. Ask the same function the code asks.
    assert body["policy_path"] == runprov.hashing._posix(as_toml), body
    assert "is not read" in shown.err and str(absent) in shown.err, (
        f"a flag accepted and silently ignored is the no-op this package refuses: {shown.err}"
    )
    #: NO GATE FIELD IS PRESENT, AND THIS IS THE DERIVED COMPLEMENT RATHER THAN A LIST OF THEM
    #: [K-41]. A consumer must not be able to read an outcome — or a history path — off a document
    #: that examined nothing, which is the vacuous green with a schema on it.
    #:
    #: **IT WAS A HAND-TYPED TUPLE OF GATE FIELDS AND THAT FAILS OPEN.** `history` and `policy`
    #: were never in it, and the two fields K-08 and K-23 added — `unfinished` and `read_error` —
    #: widened the gap to four. Measured in a copied tree: leaking each of the four into
    #: `policy_payload` in turn left this test and the whole suite GREEN, four times out of four.
    #: A key SET fails CLOSED, which is the correct bias for a check whose requirement is
    #: *answers about nothing else*, and this one is derived from `load()`'s own return — the
    #: parser's normalised shape — so a policy that grows a key cannot be mistaken for a leak and
    #: a gate field that grows cannot slip in. This project's own rule: derive a check's scope,
    #: never extend the list.
    expected = {"schema", "policy_path"} | set(runprov.policy.load(as_toml))
    assert set(body) == expected, (
        "[ADR-0018 R-14] [ADR-0017 R-8] a normalised policy is the schema, the file it was read "
        "from and the policy's own keys, and nothing else — every other key in the gate payload "
        "is a fact about runs, and this invocation answered about none:\n"
        f"  present and not allowed: {sorted(set(body) - expected)}\n"
        f"  allowed and missing:     {sorted(expected - set(body))}"
    )

    #: THE PAGE SAYS THE SAME AND SAYS IT IS USABLE, rather than leaving that to be inferred from
    #: the absence of an error.
    capsys.readouterr()
    assert runprov.__main__.main(["gate", "--policy", str(as_toml), "--emit-policy"]) == 0
    page = capsys.readouterr().out
    assert "finished_ok" in page and reason in page, page
    assert "No run was examined" in page, page

    #: AND AN UNUSABLE POLICY IS EXIT 2 WITH NOTHING ON STDOUT — the same class as before, because
    #: it is the same `load()`. R-15: silence means the invocation had no question in it.
    broken = tmp_path / "broken.json"
    broken.write_text('{"rules": [{"rule": "clean_tree"}]}', encoding="utf-8")
    capsys.readouterr()
    code = runprov.__main__.main(
        ["gate", "--policy", str(broken), "--emit-policy", "--format", "json"]
    )
    refused = capsys.readouterr()
    assert code == 2, f"a policy with no `why` is not usable: {refused.out}"
    assert not refused.out.strip(), f"[ADR-0017 R-15] and it says nothing on stdout: {refused.out}"
    assert "carries no `why`" in refused.err, refused.err


def test_the_readme_rule_table_is_the_registry_and_not_a_copy_of_it(tmp_path):
    """[ADR-0018 R-5] [ADR-0018 R-6] [ADR-0018 R-7] T-34. The documented rule set, checked.

    R-5 forbids a second list of the rules. A README cannot execute, so the table in it is written
    out — which makes it exactly the kind of copy that goes stale in silence, since nothing fails
    when a help text is wrong. **This is what makes it not a copy:** every registered rule must
    have a row, every row must name a registered rule, and each row's `asks` cell must be the
    rule's own `asks` VERBATIM.

    AND THE THIRD COLUMN MUST BE THE OPENING OF THE RULE'S `blind` TEXT [R-6], not a paraphrase of
    it. A row that summarised what a rule cannot see in a reader's own words would drift from the
    sentence the rule actually prints, and the README would be documenting a different limit from
    the one the gate reports.

    `--help` IS THE OTHER HALF AND IS DERIVED RATHER THAN CHECKED: the `gate` subparser builds its
    epilog from `rules()`, so it cannot disagree.
    """
    del tmp_path
    readme = (_repo_root() / "README.md").read_text(encoding="utf-8")
    heading = "### The rules, and what each one cannot see"
    assert heading in readme, "the README no longer documents the rule set"
    table = readme[readme.index(heading) :].split("\n\n")[1]
    rows = {}
    for line in table.splitlines():
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        if len(cells) == 3 and cells[0].startswith("`"):
            rows[cells[0].strip("`")] = (cells[1], cells[2])
    assert set(rows) == set(runprov.policy.rules()), (
        "[ADR-0018 R-5] the README's table and the registry are two statements of one rule set "
        f"and they disagree: {sorted(set(rows) ^ set(runprov.policy.rules()))}"
    )
    for name, (asks, blind) in rows.items():
        got = runprov.policy.rules()[name]
        assert asks == got.asks, (
            f"[ADR-0018 R-7] the README says `{name}` asks {asks!r} and the rule says {got.asks!r}"
        )
        #: EQUALITY WITH THE FIRST CLAUSE, NOT `startswith` [K-39]. `got.blind.startswith(blind)`
        #: is satisfied by an EMPTY cell — proved by emptying one in a copy: the targeted test
        #: and the full suite both stayed green at 100% branch coverage. It admits a
        #: one-character cell too, and it admits ANOTHER RULE'S prefix: four of the seven `blind`
        #: texts begin *"a run "*, so those cells can be swapped and the README would document a
        #: different limit from the one the gate prints — the stale-doc copy this test exists to
        #: prevent. Measured before the change: all seven cells are already exactly
        #: `blind.split(" — ")[0]`, so the equality costs no README edit.
        #:
        #: **THE EM DASH IS NOW LOAD-BEARING IN EVERY FUTURE `blind`**, and that clause is in
        #: `policy.Rule`'s own docstring, where the author of the next rule reads it.
        assert blind == got.blind.split(" — ")[0], (
            f"[ADR-0018 R-6] the README's `cannot answer when` for `{name}` is not the FIRST "
            f"CLAUSE of the sentence the rule prints, so the two document different limits — and "
            f"an equality here rather than a prefix is the row: a prefix admits an empty cell, a "
            f"truncated one, and another rule's opening words.\n"
            f"  README: {blind}\n  rule:   {got.blind.split(' — ')[0]}"
        )

    # AND THE `--help` EPILOG IS BUILT FROM THE REGISTRY, so the other documented copy cannot
    # disagree at all. Asserted through the parser rather than by reading the source, because what
    # matters is what a user is shown.
    with contextlib.redirect_stdout(io.StringIO()) as shown:
        with pytest.raises(SystemExit):
            runprov.__main__.main(["gate", "--help"])
    helped = shown.getvalue()
    for name, got in runprov.policy.rules().items():
        assert name in helped and got.asks in helped, (
            f"[ADR-0018 R-5] `runprov gate --help` does not name `{name}` and what it asks, so a "
            f"policy's author has no derived list of the names they may use:\n{helped}"
        )


def test_the_rule_registry_refuses_two_rules_under_one_name():
    """[ADR-0018 R-5] T-34. A duplicate name is a silent change of control, so it raises.

    Two rules registered as one name means a policy naming it gets whichever was imported last.
    That is not a crash a user would see; it is a control that quietly became a different control,
    which is the failure this whole ADR is about one level down.
    """
    existing = next(iter(runprov.policy.rules()))
    with pytest.raises(ValueError, match="two rules registered"):
        runprov.policy.rule(existing, asks="x", reads=("status",), blind="y" * 40)(
            lambda record: runprov.policy.Verdict(runprov.policy.MET)
        )
    # AND THE REGISTRY IS UNCHANGED by the refusal — a failed registration must not half-land.
    assert runprov.policy.rules()[existing].asks != "x"

    # IT IS ALSO READ-ONLY: a caller handed the registry cannot edit the rules this project runs.
    with pytest.raises(TypeError):
        runprov.policy.rules()["clean_tree"] = None  # type: ignore[index]


def test_every_gate_requirement_has_a_test():
    r"""ADR-0018's specification is checked, not remembered — ADR-0013's mechanism, fourth use.

    **WRITTEN ONE COMMIT BEFORE THE LAST BUILD COMMIT — and the correction is the lesson, not
    the sentence it replaces [L-16].** This said *written in the last build commit, which is the
    whole lesson of T-33*, and it is false by exactly one commit: this test landed in `b51ad31`
    and R-13 and R-14 arrived in `4550a83` after it, so the set equality below was written
    against twelve requirements and now reads fourteen. **The claim a test makes about its own
    history is the one claim nothing can check**, which is why the fix is to say what the dates
    say rather than to reach for a stronger sentence.

    The substance stands: ADR-0017 named this guard as its row's closing condition and shipped in
    0.7.0 without it, and the backlog note that recorded the omission is the reason this one
    exists while the feature is being finished rather than after an audit asks for it. **A
    closing condition belongs IN the last build commit** — which is one commit later than this,
    and that is the gap the row found.

    **THE CONVENTION WAS CHECKED BEFORE THE REGEX WAS COPIED.** ADR-0017's guard records that
    copying ITS sibling would have found 14 of 16, because R-15 and R-16 bold the whole sentence
    while R-1 … R-14 bold only the number. ADR-0018 has both shapes too — R-11 and R-12 were added
    by Taylor's rulings and bold their whole opening — so the pattern anchors on the number and the
    period at the start of a line and never on the closing bold. Measured when this was written:
    twelve requirements, and a closing-bold pattern finds ten.

    SET EQUALITY, NOT A FLOOR, for the reason G-11 gives: `>= 12` cannot see a requirement deleted
    from the ADR, and a bare `== 12` turns red on a future R-13 whose obvious fix is to bump the
    number. Equality catches a dropped requirement, a mistyped citation, and a test citing
    something the ADR no longer says, in both directions and with no number to maintain.

    CITATIONS ARE READ FROM BEFORE THIS `def`, like all three siblings, so this docstring's own
    mentions of R-11 and R-12 cannot satisfy the requirements it is checking.
    """
    adr = (
        _repo_root()
        / "docs"
        / "adr"
        / "0018-a-policy-is-checked-against-the-history-not-remembered.md"
    )
    if not adr.is_file():  # pragma: no cover - docs ship in the sdist, a bare tree may not
        pytest.skip("ADR-0018 not present")
    text = adr.read_text(encoding="utf-8")
    required = set(re.findall(r"^\*\*(R-\d+)\.", text, re.M))
    assert len(required) > 10, (
        "ADR-0018 declares R-1 through R-10 with the bold closing after the number and R-11 and "
        "R-12 with their whole opening bold. A pattern that finds ten is matching only the first "
        f"convention and is blind to the two requirements Taylor added: {sorted(required)}"
    )
    tests = pathlib.Path(__file__).read_text(encoding="utf-8")
    cited = set(
        re.findall(r"\[ADR-0018 (R-\d+)\]", tests.split("def test_every_gate_requirement")[0])
    )
    assert required == cited, (
        "ADR-0018 and its tests disagree. Requirements the ADR states that no test names: "
        f"{sorted(required - cited, key=lambda s: (len(s), s))}. Requirements the tests cite "
        f"that the ADR no longer states: {sorted(cited - required, key=lambda s: (len(s), s))}"
    )


def test_every_answer_requirement_has_a_test():
    r"""ADR-0017's specification is checked, not remembered — ADR-0013's mechanism, third use.

    **T-33 SHIPPED IN 0.7.0 WITHOUT THIS GUARD, and the backlog had named it as the row's own
    closing condition.** ADR-0016 and ADR-0013 each have one; the ADR whose feature reaches every
    command in the package did not. Coverage was complete on the day it was written — all 16
    requirements cited — which is exactly the state that rots silently.

    **THE SIBLING'S REGEX WOULD HAVE FOUND 14 OF 16, and copying it was the obvious mistake.**
    `test_every_chain_requirement_has_a_test` matches `^\*\*(R-\d+)\.\*\*` — bold closing
    right after the number — which is ADR-0016's convention and ADR-0017's for R-1 … R-14. R-15
    and R-16, both added by later audits, bold the WHOLE requirement sentence: `**R-15. A payload
    is emitted whenever …**`. So a copied guard would have passed while silently ignoring the two
    newest requirements in the document — the scope pattern, in the guard written to stop it, for
    the tenth time in this project. Measured before this test was written: 14 against 16.

    The pattern here therefore requires the number and the period at the start of a line and NOT
    the closing bold, which matches both conventions this ADR uses. A prose reference cannot
    satisfy it: `**R-12 names this structure**` has no period after the number.

    SET EQUALITY, NOT A FLOOR, for the reason G-11 gives on the chain guard: `>= 16` cannot see a
    requirement deleted from the ADR, and `== 16` turns red on a future R-17 whose obvious fix is
    to bump the number. Equality catches a dropped requirement, a mistyped citation, and a test
    citing something the ADR no longer says — in both directions and with no number to maintain.

    CITATIONS ARE READ FROM BEFORE THIS `def`, like both siblings, so this docstring's own
    mentions of R-15 and R-16 cannot satisfy the requirements it is checking.
    """
    adr = (
        _repo_root() / "docs" / "adr" / "0017-one-answer-two-renderings-and-the-table-is-derived.md"
    )
    if not adr.is_file():  # pragma: no cover - docs ship in the sdist, a bare tree may not
        pytest.skip("ADR-0017 not present")
    text = adr.read_text(encoding="utf-8")
    required = set(re.findall(r"^\*\*(R-\d+)\.", text, re.M))
    assert len(required) > 14, (
        "ADR-0017 declares R-1 through R-14 with the bold closing after the number and R-15 "
        "onward with the whole sentence bold. A pattern that finds 14 is matching only the "
        f"first convention and is blind to the newest requirements: {sorted(required)}"
    )
    tests = pathlib.Path(__file__).read_text(encoding="utf-8")
    cited = set(
        re.findall(r"\[ADR-0017 (R-\d+)\]", tests.split("def test_every_answer_requirement")[0])
    )
    assert required == cited, (
        "ADR-0017 and its tests disagree. Requirements the ADR states that no test names: "
        f"{sorted(required - cited, key=lambda s: (len(s), s))}. Requirements the tests cite "
        f"that the ADR no longer states: {sorted(cited - required, key=lambda s: (len(s), s))}"
    )


def test_every_module_that_answers_in_json_cites_adr_0017_where_the_index_guard_looks():
    """[T-33]. The convention `test_every_adr_is_listed_in_the_adr_index` depends on, enforced.

    **THIS IS WHY ADR-0017 STAYED `Proposed` THROUGH ITS OWN RELEASE.** That guard asserts no ADR
    is still proposed while code implements it, and it decides *implements* from a module's TOP
    docstring — deliberately, so a passing mention of a future decision in a mid-file comment is
    not read as an implementation. T-33 cited ADR-0017 in function docstrings and comments across
    ten commands and in **no module docstring**, so `shipped` never contained `0017` and the
    guard had nothing to check. It was not wrong; it was uninformed, which a guard cannot
    distinguish from satisfied.

    THE SET IS DERIVED FROM THE CODE, not listed here: a module that defines a payload schema
    `runprov.<command>.v1` implements this ADR, and `runprov.run.v2` is the RECORD schema and not
    one of them. So a tenth answering command is covered on the day its schema appears, rather
    than on the day somebody remembers this test.

    `log` and `lineage` have no module of their own — their payload schemas live in `__main__.py`
    — which is why that module is in the set too, found by the same pattern.
    """
    #: A PAYLOAD SCHEMA IS ONE WHOSE NAME IS A COMMAND THAT ANSWERS IN JSON, and that set is
    #: derived from the parser by `_cli_json_commands`. The first version of this sweep matched
    #: any `runprov.<x>.vN` with a `(?!run\.)` lookahead and still caught `run.py`, which also
    #: defines `runprov.history.v2` and `runprov.start.v1` — RECORD schemas, not answers.
    #: Excluding one name by hand would have been the stale-list pattern; asking the parser is
    #: not, and a tenth answering command is covered on the day its schema appears.
    commands = _cli_json_commands()
    root = _repo_root() / "runprov"
    answering = set()
    covered: set[str] = set()
    for module in sorted(root.glob("*.py")):
        source = module.read_text(encoding="utf-8")
        named = set(re.findall(r'^[A-Z_]*SCHEMA = "runprov\.([a-z]+)\.v\d+"', source, re.M))
        if named & commands:
            answering.add(module.name)
            covered |= named & commands
    #: A DERIVATION, NOT A FLOOR [L-15]. This was `len(answering) >= 9` — G-11's shape, and it
    #: was already one below the truth: `policy.py` makes TEN modules, and it was in the tree
    #: when the nine was written. A floor cannot distinguish *the scope broke* from *something
    #: was added*, so it says nothing on the day it matters and nothing on the day it is stale.
    #: The question the sweep exists to ask is answerable exactly: **every command the parser
    #: offers `--format json` must be covered by some module's schema constant.** Red the moment
    #: a command answers in JSON with no schema constant — which is the state that let ADR-0017
    #: stay `Proposed` through its own release — instead of two commands later.
    assert covered == commands, (
        f"these commands answer in JSON and no module defines `runprov.<command>.vN` for them: "
        f"{sorted(commands - covered)}. The sweep below reads module docstrings, so a command "
        f"with no schema constant is one this guard cannot see at all. Found "
        f"{sorted(answering)} covering {sorted(covered)}"
    )
    assert "run.py" not in answering, (
        "`run.py` defines the RECORD schemas — `runprov.run.v2`, `runprov.history.v2`, "
        "`runprov.start.v1` — and implements no answer. The first version of this sweep caught "
        "it, because it asked the shape of the string instead of asking the parser"
    )
    missing = []
    for name in sorted(answering):
        doc = ast.get_docstring(ast.parse((root / name).read_text(encoding="utf-8"))) or ""
        if "0017" not in set(re.findall(r"ADR-(\d{4})", doc)):
            missing.append(name)
    assert not missing, (
        "these modules define a `--format json` payload schema and their TOP docstring does not "
        "name ADR-0017, so `test_every_adr_is_listed_in_the_adr_index` cannot tell that the "
        f"decision is built — which is how it stayed `Proposed` through 0.7.0: {missing}"
    )


def test_every_chain_requirement_has_a_test():
    """ADR-0016's specification is checked, not remembered — the ADR-0013 mechanism, reused.

    QUALIFIED BY THE ADR NUMBER, and the first version was not. It matched a bare `[R-n]`
    anywhere before its own `def`, and ADR-0013's guard uses the identical convention several
    thousand lines earlier — so `[R-1]` through `[R-15]` were ALREADY present and satisfied
    fifteen of these requirements for free. Measured in Audit E: all 53 citations stripped from
    the chain block and the guard still passed.

    AND THIS TEST WAS ITSELF DELETED ONCE, on 2026-09-18, when the block it guards was
    rewritten wholesale — taking seven requirements' tests with it while the suite stayed green,
    because the only thing that would have noticed was the thing being removed. A guard that
    lives inside what it guards is a guard that leaves with it. The outer ring is
    `test_every_adr_is_listed_in_the_adr_index`, which fails if an ADR cited by shipped code is
    still marked proposed — but it cannot see a missing requirement test, so what actually
    caught this was counting the citations by hand. That is not a mechanism, and the honest
    statement is that this guard protects the requirements and nothing yet protects this guard.

    AND ITS OWN FLOOR HAD GONE STALE (Audit G, G-11). It read `len(required) >= 24` while
    ADR-0016 reached 32 requirements, so the whole decision table, its acceptance gate and
    R-32 — all of R-25 through R-32 — could be deleted from the specification with this guard
    green. Measured: eight requirement definitions removed, `1 passed`. `not missing` did not
    notice, because a requirement that is gone from the ADR is not a requirement without a
    test; it is a test citing nothing, which is the direction this never checked.

    THE REPLACEMENT CARRIES NO NUMBER. `== 32` was refused: a future R-33 turns it red and the
    obvious edit is to bump it, which is the maintenance trap rather than the guard. Set
    equality catches a deleted requirement AND a mistyped citation, in both directions, and it
    is the same shape ADR-0013's sibling guard now uses — the class rather than the instance.
    """
    adr = _repo_root() / "docs" / "adr" / "0016-a-history-shows-whether-it-has-been-edited.md"
    if not adr.is_file():  # pragma: no cover - docs ship in the sdist, a bare tree may not
        pytest.skip("ADR-0016 not present")
    required = set(re.findall(r"^\*\*(R-\d+)\.\*\*", adr.read_text(encoding="utf-8"), re.M))
    tests = pathlib.Path(__file__).read_text(encoding="utf-8")
    cited = set(
        re.findall(r"\[ADR-0016 (R-\d+)\]", tests.split("def test_every_chain_requirement")[0])
    )
    assert required == cited, (
        "ADR-0016 and its tests disagree. Requirements the ADR states that no test names: "
        f"{sorted(required - cited, key=lambda s: (len(s), s))}. Requirements the tests cite "
        f"that the ADR no longer states: {sorted(cited - required, key=lambda s: (len(s), s))}"
    )


def _bench_module():
    """`tools/bench.py`, loaded the way `_ci_module` loads `ci.py`.

    By spec rather than `from tools import bench`, so this holds the FILE at its path: the step
    in `ci.py` shells out to that path, and a test importing a package module could keep passing
    while the path `ci.py` names had moved.
    """
    spec = importlib.util.spec_from_file_location(
        "_bench_under_test", _repo_root() / "tools" / "bench.py"
    )
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_the_bench_harness_reads_a_return_code_as_only_the_codes_that_mean_something():
    """`tools/bench.py` classifies pytest's exit code, and `5` is the one that matters.

    THE FAILURE THIS HOLDS. A harness that reads any non-zero code as "the guard caught it"
    reports a mutation killed by a suite that NEVER RAN -- `5` is "no tests collected", which a
    `-k` typo produces, and `4` is a usage error, which an interpreter without `pytest-cov`
    produces. Both have happened here: `4` while this file was being written, when a resolved
    virtualenv symlink silently handed pytest to the base interpreter.

    AND A FALSE PASS IS WORSE THAN A FALSE FAILURE, because a pass closes the question. So the
    assertions below are not only that `0` and `1` map correctly -- they are that `4` and `5` map
    to NEITHER verdict, which is the half a `returncode != 0` harness gets wrong.
    """
    bench = _bench_module()
    assert bench.classify(0) == bench.SURVIVED
    assert bench.classify(1) == bench.CAUGHT

    with pytest.raises(bench.Void, match="collected NOTHING"):
        bench.classify(5)
    #: THE PAGE TRAVELS WITH THE REFUSAL. A bare "pytest exited 4" sent this file's author looking
    #: at the wrong tree; pytest's own usage error says exactly what is wrong.
    with pytest.raises(bench.Void, match="unrecognized arguments"):
        bench.classify(4, "ERROR: unrecognized arguments: --cov=runprov")
    for code in (2, 3, 4):
        with pytest.raises(bench.Void, match="ERROR and not a result"):
            bench.classify(code)


def test_the_bench_harness_calls_a_prose_only_edit_no_mutation_at_all():
    """A docstring edit is not a mutation, and a string that is NOT a docstring still is.

    THE MEASURED FAILURE. A plant harness in this repository inserted six import spellings INSIDE
    A DOCSTRING; all six were present in an AST dump, all six read RC=0 against the guard they
    were meant to break, and that nearly refuted a true row. So `executable_difference` compares
    the two trees with every docstring replaced by a fixed marker.

    AND THE SECOND HALF IS WHAT KEEPS IT FROM OVER-REACHING: an ordinary string literal carries
    behaviour -- a message, a format, a marker -- so changing one IS a mutation. A version of
    this that blanked every `Constant` would call the `__main__` stderr sweep's 32 message edits
    "prose" and refuse to measure any of them.
    """
    bench = _bench_module()
    base = 'def f():\n    """Say what f does."""\n    return "a message"\n'
    prose = 'def f():\n    """Say what f does, at greater length."""\n    return "a message"\n'
    behaviour = 'def f():\n    """Say what f does."""\n    return "a different message"\n'
    code = 'def f():\n    """Say what f does."""\n    return "a message".upper()\n'

    assert not bench.executable_difference(base, prose), "a docstring edit is prose"
    assert bench.executable_difference(base, behaviour), "a MESSAGE is behaviour, not prose"
    assert bench.executable_difference(base, code)
    assert not bench.executable_difference(base, base), "a no-op is not a mutation"

    #: THE MODULE DOCSTRING TOO, because that is where the measured plant landed.
    assert not bench.executable_difference('"""One."""\nx = 1\n', '"""Two."""\nx = 1\n')
    assert bench.executable_difference('"""One."""\nx = 1\n', '"""One."""\nx = 2\n')


def test_the_bench_harness_numbers_the_lines_it_changed_in_the_mutant():
    """`changed_lines` is the left-hand side of the executed-statement control.

    NUMBERED IN THE MUTANT, because that is the file coverage reports on. An insertion shifts
    every line below it, so numbering in the ORIGINAL would point the control at the wrong lines
    and it would read a statement the mutation never touched.
    """
    bench = _bench_module()
    assert bench.changed_lines("a\nb\nc\n", "a\nb\nc\n") == set()
    assert bench.changed_lines("a\nb\nc\n", "a\nB\nc\n") == {2}
    #: AN INSERTION, and the number is the NEW line's.
    assert bench.changed_lines("a\nc\n", "a\nb\nc\n") == {2}
    #: A DELETION changes no line IN the mutant, which is why the control also asks whether any
    #: changed line is a statement at all rather than resting on this set being non-empty.
    assert bench.changed_lines("a\nb\nc\n", "a\nc\n") == set()


def test_the_bench_harness_refuses_a_work_root_inside_this_repository(tmp_path):
    """Control 1, and it refuses BEFORE creating anything.

    WHY IT IS FIRST. The suite enumerates its own sources with `REPO.rglob("*.py")`, so a `.py`
    tree inside the repository joins that sweep: on 2026-10-08 four copies at
    `runprov/.audit-scratch/` put 128 stray sources in scope and turned an unrelated test red at
    a green HEAD. A bench run whose trees sit there measures a repository that is not this one.

    AND A CONTROL THAT CREATES THE HAZARD IT REFUSES IS NOT A CONTROL. The first version ran
    after `main()` had already called `work.mkdir()`, so refusing the root still left the
    directory behind; the assertion below is that nothing is created.
    """
    bench = _bench_module()
    root = _repo_root()
    for inside in (root, root / ".bench", root / "tools" / "deeper"):
        with pytest.raises(bench.Void, match="inside the repository"):
            bench._refuse_a_work_root_inside_the_repo(inside)
    assert not (root / ".bench").exists(), "the refusal must not create what it refuses"
    #: AND IT MUST NOT REFUSE AN HONEST ROOT, or the harness cannot be run at all.
    bench._refuse_a_work_root_inside_the_repo(tmp_path)


def test_ci_declares_the_bench_step_and_points_it_at_the_harnesss_own_controls():
    """`ci.py bench` runs `tools/bench.py selfcheck`, and the step is declared.

    THE INSTRUMENT NEEDS A CONTROL, which is why this step exists at all: `bench.py` decides
    whether a guard noticed a deliberate break, and if it stops being able to produce one of its
    verdicts every answer it gives afterwards still LOOKS like an answer. Its six cases assert
    the REASON each fired and not merely the verdict -- two of them passed for the wrong reason
    while printing `ok` the first time they were written.

    NOT IN THE DEFAULT GATE, and that is asserted rather than described: twelve tree copies and
    twelve pytest runs do not belong on every push.
    """
    ci = _ci_module()
    assert "bench" in ci.STEPS, "the step must be reachable as `python ci.py bench`"
    source = inspect.getsource(ci.STEPS["bench"])
    assert "tools" in source and "bench.py" in source and "selfcheck" in source, (
        "the step must shell out to the harness's own selfcheck; it reads:\n" + source
    )
    assert (_repo_root() / "tools" / "bench.py").is_file(), "and that file must be there"

    #: NOT IN THE DEFAULT GATE, READ OFF `__main__`'S OWN DEFAULT RATHER THAN RESTATED. An earlier
    #: draft also asserted `"bench" not in ("lint", "test", "build")`, which is a comparison of
    #: three literals this file wrote: a shape that CANNOT FAIL, and this project refuses those
    #: because they teach a reader that a green here means something it does not.
    default = re.search(r"sys\.argv\[1:\] or \[([^\]]*)\]", inspect.getsource(ci))
    assert default, "`ci.py`'s default step list is not spelled the way this test reads it"
    steps = default.group(1)
    assert "bench" not in steps, f"`bench` must not be a default step; they are {steps}"


def test_exec_says_it_cannot_write_the_sidecar_instead_of_raising(tmp_path, monkeypatch, capsys):
    """`exec` sets up its sidecar's directory OUTSIDE the block that handles the run.

    THE DEFECT, filed by the `__main__` stderr sweep on 2026-10-08 and fixed in the same pass.
    `provenance.parent.mkdir(parents=True, exist_ok=True)` sat above `_exec`'s `try`, so the three
    handlers that exist to turn `UsageError`, `CommandFailedError` and `Terminated` into A LINE AND
    A NUMBER could never see it. Pointing `--provenance` at a path under a REGULAR FILE printed a
    raw Python traceback and exited 1, in the module whose own comments say *"A MESSAGE, not a
    traceback"* three times.

    TWO SPELLINGS FROM ONE LINE, and both are asserted because each is a different `errno` and a
    fix for one need not be a fix for the other: `FileExistsError` [Errno 17] when the parent IS a
    regular file, `NotADirectoryError` [Errno 20] when a path COMPONENT is one.

    NOT THE ESCAPING CLASS, which is why this is its own test and not a case in the sweep's
    runtime leg: it reproduces with an ORDINARY name and no newline anywhere. `--name` reaches the
    same line by the other door, so it is asserted too.

    AND THE SHAPE WAS ALREADY IN THIS FILE -- `_export` does the same `mkdir` inside a `try` with
    the same `cannot write` wording and returns `CANNOT_CHECK`. The last assertion holds the two
    together, so a future change that moves one is told about the other rather than discovering it.
    """
    monkeypatch.chdir(tmp_path)
    runprov.configure(root=tmp_path, run_log=tmp_path / "h.jsonl")
    blocker = tmp_path / "blocker"
    blocker.write_text("a regular file", encoding="utf-8")

    #: THE PARENT IS THE REGULAR FILE -> EEXIST; A COMPONENT IS -> ENOTDIR.
    for destination in (blocker / "p.prov.json", blocker / "under" / "p.prov.json"):
        code = cli.main(["exec", "--provenance", str(destination), "--", "anything"])
        page = capsys.readouterr()
        assert code == cli.CANNOT_CHECK, f"{destination} exited {code}, not could-not-check"
        assert "Traceback (most recent call last)" not in page.err, (
            f"a TRACEBACK, which this module refuses everywhere else:\n{page.err}"
        )
        assert "runprov exec: cannot write" in page.err, page.err
        #: THE DESTINATION IS NAMED. A message that does not say which path failed sends the
        #: reader to guess, and `exec` is usually run from inside a job script nobody is watching.
        assert str(destination) in page.err or "blocker" in page.err, page.err

    #: `--name` REACHES THE SAME LINE, by composing the sidecar under the project root instead.
    monkeypatch.setattr(runprov.project, "_ACTIVE", None)
    runprov.configure(root=blocker, run_log=tmp_path / "h.jsonl")
    code = cli.main(["exec", "--name", "n", "--", "anything"])
    page = capsys.readouterr()
    assert code == cli.CANNOT_CHECK
    assert "Traceback (most recent call last)" not in page.err, page.err
    assert "runprov exec: cannot write" in page.err, page.err

    #: ONE WORDING, TWO CALLERS. `_export` is where this shape already existed; if either stops
    #: saying `cannot write` the other is the place to look, and nothing else said so.
    source = inspect.getsource(cli)
    assert source.count("cannot write") >= 2, (
        "`_exec` and `_export` both answer an unwritable destination with `cannot write`; only "
        f"{source.count('cannot write')} site(s) say it now"
    )


def _matrix_legs(workflow: dict) -> list[dict[str, str]]:
    """Every job GitHub expands the `test` matrix into, `include` semantics and all.

    `include` IS NOT "APPEND". An entry whose list-valued keys match an existing combination
    ADDS PROPERTIES TO IT; one that matches nothing adds a new combination. Here `ubuntu-latest`
    x `3.13` already exists, so the entry carrying `coverage_floor: off` modifies that leg rather
    than making a seventh — and a test that read `include` as three more jobs would compute 9 and
    call the README wrong. The expansion is 4 ubuntu legs plus macOS plus Windows, which is 6.
    """
    matrix = workflow["jobs"]["test"]["strategy"]["matrix"]
    axes = {k: v for k, v in matrix.items() if k != "include" and isinstance(v, list)}
    combos = [dict(zip(axes, values, strict=True)) for values in itertools.product(*axes.values())]
    for extra in matrix.get("include") or []:
        shared = {k: str(v) for k, v in extra.items() if k in axes}
        for combo in combos:
            if all(str(combo.get(k)) == v for k, v in shared.items()):
                combo.update({k: str(v) for k, v in extra.items()})
                break
        else:
            combos.append({k: str(v) for k, v in extra.items()})
    return [{k: str(v) for k, v in c.items()} for c in combos]


def test_the_ci_sections_legs_are_the_legs_the_workflow_ACTUALLY_DECLARES():
    """The README's CI table must name every matrix leg and no others.

    WHY THIS EXISTS, and it is a correction rather than a precaution. On 2026-10-08 that section
    said *"the hosted matrix on **today's** tree | **not run**"* and *"Since 2026-08-13 every
    hosted run has failed … Making the repository public … is the one action that closes this"* —
    while the repository WAS public, `test.yml` triggered on every push, and all eight jobs were
    green. **The paragraph describing a blockage survived the event it predicted**, and the
    shipped README told a reader the matrix had not run. It also still carried a three-row leg
    table (ubuntu/macOS/windows at 769/768/722) from a suite a third the size.

    WHAT THE EXISTING GUARDS COULD NOT SEE.
    `test_the_commits_the_ci_section_names_are_real_and_in_this_history` checks the SHAs are real
    ancestors — and its own docstring says *"what this cannot check … whether those runs were
    green, and how many runs there have been"*. So the shas were honest while the sentences around
    them were not, which is the gap this closes from the local side.

    AND GREENNESS IS STILL NOT CHECKED HERE, deliberately: it lives on GitHub, and a test needing
    the network would be skipped in exactly the environments this section exists to be honest
    about. What IS a local fact is **which legs exist**, and the table claiming a leg the matrix
    does not run — or missing one it does — is the drift that actually happened.

    AN EQUALITY, NOT A FLOOR [Audit P]. A floor is satisfied by a table that names one leg, which
    is how the stale three-row table survived; this fails in both directions, so adding a Python
    version to the matrix without touching the README is red, and so is removing one.
    """
    wf = _repo_root() / ".github/workflows/test.yml"
    if not wf.is_file():  # pragma: no cover - workflows are not in the sdist
        pytest.skip("test.yml not present")
    yaml = pytest.importorskip("yaml")
    section = _readme().split("## What has actually been run", 1)[1].split("\n## ", 1)[0]
    workflow = yaml.safe_load(wf.read_text(encoding="utf-8"))
    legs = _matrix_legs(workflow)

    #: THE OS NAMES AS A READER WRITES THEM. Not a per-leg list: the runner label is
    #: `<platform>-latest` and the prose says the platform, so the mapping is the suffix rule.
    expected = {f"{leg['os'].removesuffix('-latest')} {leg['python']}".lower() for leg in legs}
    #: THE PER-LEG TABLE ONLY, FOUND BY ITS OWN HEADER, and that scoping is a correction. Reading
    #: the whole section let the STATE table satisfy this: deleting the macOS row from the per-leg
    #: table left `| macOS 3.12 | **green at ...** |` above it, `claimed` was unchanged, and the
    #: demonstration came back GREEN over a table with a leg missing. The two tables make different
    #: claims -- greenness per platform, counts per leg -- and the state table groups all four
    #: ubuntu legs into one row, so only this one is per-leg and only this one can be held to the
    #: matrix. Anchored on the header rather than a line number.
    table = section.split("| leg | passed | skipped |", 1)
    assert len(table) == 2, (
        "the CI section has no `| leg | passed | skipped |` table; this guard reads that header "
        "to find the per-leg claims and cannot be satisfied by the state table above it"
    )
    body = table[1].split("\n\n", 1)[0]
    rows = re.findall(r"^\|\s*\**([A-Za-z]+)\s+(3\.\d+)\**\s*\|", body, re.M)
    claimed = {f"{os_.lower()} {py}" for os_, py in rows}
    assert claimed == expected, (
        f"the CI section's leg table and `test.yml`'s matrix disagree. Claimed and not run: "
        f"{sorted(claimed - expected)}. Run and not claimed: {sorted(expected - claimed)}. "
        f"The matrix expands to {len(legs)} test leg(s)"
    )

    #: AND THE JOB TOTAL, which is the legs plus every job that is not the matrix.
    jobs = workflow["jobs"]
    total = len(legs) + len([name for name in jobs if name != "test"])
    #: ENGLISH NUMBER WORDS ARE A CLOSED SET, not a project list — the section writes "eight"
    #: rather than "8" because it is prose. Either spelling satisfies this.
    words = "zero one two three four five six seven eight nine ten eleven twelve".split()
    spelled = words[total] if total < len(words) else str(total)
    assert re.search(rf"\b({total}|{spelled})\b", section, re.I), (
        f"`test.yml` defines {total} job(s) — {len(legs)} test leg(s) plus "
        f"{sorted(n for n in jobs if n != 'test')} — and the CI section says neither "
        f"{total!r} nor {spelled!r}"
    )

    #: NOT VACUOUS: the section must name legs at all, or the equality above is `set() == set()`.
    #: DISTINCT rows, because the state table above the per-leg table names macOS and Windows a
    #: second time, so the raw match count is 8 against 6 legs and asserting on it is a test of
    #: this section's layout rather than of its content.
    assert len(claimed) == len(legs) > 1, (
        f"the section names {len(claimed)} distinct leg(s) for {len(legs)} in the matrix"
    )


def test_every_readme_binding_resolves_and_still_holds():
    """`tools/claims.py`'s registry, gated — the half of it that CAN pass today.

    TWO REGISTRIES, ONE ASSERTION. `_BOUND` reads a module attribute; `_DERIVED` counts something
    about this repository, with the README's own 10% tolerance where the sentence says *about*.
    Both must resolve and both must hold, and the row count is derived from both so adding an
    entry never needs this line edited.

    TWO FAILURES, AND THEY NEED DIFFERENT REPAIRS, which is why the report separates them and so
    does this. A binding naming a constant that no longer exists is a RENAME to follow and the
    run is VOID; a binding whose number no longer matches is a DRIFT and the document is wrong.
    A check that collapsed them would send a reader to edit prose over a renamed attribute.

    WHY THIS IS GATED WHILE THE REPORT IS NOT. These pass today, so a drift is red on the next
    push. The report's other half — the LIST of README lines accounted for by nothing — would be
    red on arrival, and `ci.py`'s own words for that are *"a gate that is red the day it arrives
    is a gate people learn to scroll past"*. Its COUNT is gated, by
    `test_the_unaccounted_claim_count_is_exactly_the_committed_baseline`. No figure is quoted here
    on purpose: this docstring said 139 and the ratchet was built at 126.

    AND THE REGISTRY MUST NOT HOLD THE VALUE. It holds a (sentence, attribute) pair and reads the
    attribute live; a registry caching the number would agree with itself forever. The assertion
    below reads both sides, which is the only arrangement that can fail.

    MEASURED, on the first run of the report: it exited 2 naming `runprov.run` as having no
    `PIN_STARTS_WITHIN` — the constant is in `verify.py`, and `DIRTY_FILES_SHOWN` was in `run.py`
    rather than `__main__.py`. Two of six module paths were wrong, and the VOID path is what said
    so instead of reporting a drift that was not one.
    """
    spec = importlib.util.spec_from_file_location(
        "_claims_under_test", _repo_root() / "tools" / "claims.py"
    )
    claims = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(claims)

    rows = claims.bound_claims((_repo_root() / "README.md").read_text(encoding="utf-8"))
    #: NOT VACUOUS: an empty registry would make every assertion below true.
    #: DERIVED, so adding a binding never needs this line edited: every registry entry must
    #: produce a row, and the registry itself must not be empty. A bare `>= 6` went stale the
    #: moment four suffix-map bindings were added, which is the shape this file keeps finding.
    entries = len(claims._BOUND) + len(claims._DERIVED)
    assert len(rows) == entries >= 6, f"{len(rows)} row(s) from {entries} registry entries"
    drifted = [(what, said, live, why) for what, said, live, why in rows if why != "ok"]
    assert not drifted, "README figures no longer match the constants they describe: " + "; ".join(
        f"{what} says {said} and the code says {live} ({why})" for what, said, live, why in drifted
    )

    #: AND EVERY BOUND SENTENCE IS STILL IN THE DOCUMENT. `bound_claims` reports a missing one as
    #: VACUOUS rather than raising, because a binding to a number the README no longer states is a
    #: decoration — `ci.py`'s `scale_drift` says the same thing for the same reason, and its
    #: docstring names it: *"the thing that must never happen quietly is this check becoming
    #: vacuous"*.
    vacuous = [what for what, said, _live, _why in rows if said is None]
    assert not vacuous, f"these bindings quote sentences the README no longer contains: {vacuous}"


def test_the_claims_report_is_not_in_the_default_gate_and_ci_declares_it():
    """`ci.py claims` exists, runs the report, and is not one of the default steps.

    THE DENOMINATOR IS THE DELIVERABLE AND THE LIST IS NOT A GATE. Before `tools/claims.py` the
    bound README figures were `_SCALE_FIGURES`' two, and nobody knew what they were two OF — a
    numerator over an unknown, which `guard-shapes` calls a floor. The report names the unknown;
    the count of it is held by `docs/claims-baseline.txt`, which IS gated. The number is not
    repeated here, because this docstring held a stale copy of it once already.
    """
    ci = _ci_module()
    assert "claims" in ci.STEPS
    source = inspect.getsource(ci.STEPS["claims"])
    assert "claims.py" in source, source
    assert (_repo_root() / "tools" / "claims.py").is_file()
    default = re.search(r"sys\.argv\[1:\] or \[([^\]]*)\]", inspect.getsource(ci))
    assert default, "`ci.py`'s default step list is not spelled the way this test reads it"
    assert "claims" not in default.group(1), (
        f"a report that is red on arrival must not be a default step; they are {default.group(1)}"
    )


def test_the_unaccounted_claim_count_is_exactly_the_committed_baseline():
    """THE RATCHET, and it is in the default gate while the report above is not.

    `tools/claims.py` reports which README numbers are accounted for by nothing. The LIST cannot
    be a gate -- it is red on arrival, and `ci.py` has the sentence for that: *"a gate that is red
    the day it arrives is a gate people learn to scroll past"*. The COUNT can be, because it is
    green the day it is written. Report, then ratchet, then gate.

    AN EQUALITY, NOT A CEILING, and the direction decides the remedy rather than the verdict. `<=`
    would let the committed number rot upward while real work went unrecorded, and a ratchet that
    never tightens is not a ratchet. So a FALL is as red as a rise, and the message says which:
    down means regenerate the baseline, up means a claim arrived that nothing accounts for.

    TWO RESIDUES, AND THE SUM IS THE HEADLINE. `unaccounted` is what nobody has examined;
    `historical` is what somebody examined and found permanently unverifiable — a bug since
    repaired, another tree, this host, a library not installed. **Recording a reason is not a check
    gained**, so the two are counted apart and their SUM is asserted as well: moving a line from
    one to the other lowers a number and raises another by the same one, and a reader watching
    only the first would read bookkeeping as progress. Only a binding, a test, or a deleted
    sentence moves the sum.

    TWO DIGESTS, BECAUSE ONE COULD NOT ATTRIBUTE — and attribution is the point. The count is a
    property of the DETECTION RULE as much as of the document: tightening `_KINDS` lowers it with
    no work done at all, and a sibling project's first baseline fell 696 -> 335 with about half of
    that being the rule moving. But *adding a binding* also lowers it, and that IS the work. A
    single digest fired *"not comparable"* on both, so honest work tripped the alarm meant for a
    fall nobody earned — and an alarm that fires on good news is one people learn to silence.

    So `detection` (`NUMBER`, the `_KINDS` patterns, `_SUPERSEDED_DECLARES`) makes this REFUSE to
    compare, and `bindings` (`_BOUND` plus `ci.py`'s `_SCALE_FIGURES`) only changes which sentence
    the failure prints. Measured on the way in: 139 -> 126 was twelve lines of rule and one of
    work, and 126 -> 115 was eleven more lines of rule — a widened `exit-code` kind, a
    `file-descriptor` kind, and crediting the two figures `ci.py` already gates.

    AND IT READS THE COUNT FROM THE TOOL, not from a re-implementation here. Re-deriving it would
    only prove this test agrees with itself; the two sides are the committed file and the live
    document, which is the only arrangement that can fail.
    """
    spec = importlib.util.spec_from_file_location(
        "_claims_ratchet", _repo_root() / "tools" / "claims.py"
    )
    claims = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(claims)

    #: EVERY MESSAGE BELOW NAMES `python ci.py claims-baseline`, so this asserts the step exists
    #: and is not a default one. `ci.py surface`'s docstring is the precedent: that file told a
    #: reader to run `python -c "import tests.surface"`, which was not a thing, and *an
    #: instruction that does not run is worse than none, because the reader tries it before
    #: disbelieving it*. A remedy named by a red test is read at the worst possible moment.
    ci = _ci_module()
    assert "claims-baseline" in ci.STEPS, (
        "the failures below tell a reader to run `python ci.py claims-baseline`, and that step "
        f"does not exist. The steps are {sorted(ci.STEPS)}"
    )
    default = re.search(r"sys\.argv\[1:\] or \[([^\]]*)\]", inspect.getsource(ci))
    assert default and "claims-baseline" not in default.group(1), (
        "a step that REWRITES the baseline must never run in the default gate: it would make "
        "every rise green by overwriting the number that was supposed to refuse it"
    )

    committed = claims.read_baseline()
    assert committed is not None, (
        f"{claims.BASELINE.name} is missing, so nothing holds the count. Write it with "
        f"`python ci.py claims-baseline`"
    )
    detection, bindings, recorded_population, recorded, recorded_known = committed

    #: THE DETECTION RULE IS THE ONE THAT MUST REFUSE TO COMPARE. Tightening a `_KINDS` pattern
    #: lowers the count with no work done at all, so a baseline taken under a different detection
    #: rule is not a baseline, it is a different measurement wearing the same name.
    assert detection == claims.detection_digest(), (
        f"the baseline was taken under detection rule {detection} and it is now "
        f"{claims.detection_digest()}, so its {recorded} is NOT comparable with today's count. "
        f"A `_KINDS` or `NUMBER` change moves the number without any claim being bound. "
        f"Re-measure with `python ci.py claims-baseline` and record the move as RULE"
    )

    readme = (_repo_root() / "README.md").read_text(encoding="utf-8")
    population, live, known = claims.counts(readme)

    #: A DEAD HISTORICAL ENTRY IS AN EXCUSE OUTLIVING ITS SUBJECT. An exemption whose sentence has
    #: gone from the README explains nothing and still lowers a number; this file has already
    #: shipped one decoration that checked nothing, and `scale_drift` exists because of another.
    _found, stale = claims.historical_lines(readme)
    assert not stale, (
        "these entries in `_HISTORICAL` no longer match any README line, so each is an exemption "
        "with no subject: " + "; ".join(stale)
    )

    #: AND AN ENTRY MUST BE EXPLAINING SOMETHING. One that lands on a line already bound, already
    #: classified or already superseded reads as work while doing none — the registry would grow
    #: and the number would fall for nothing. Checked by asking what the line would be WITHOUT it.
    credited, _ = claims.bound_lines(readme)
    without = claims.classify(
        readme, credited, claims.superseded_lines(readme), claims.elsewhere_lines(readme)
    )
    otherwise_unaccounted = {int(row.split(":", 1)[0]) for row in without["unaccounted"]}
    idle = sorted(n for n in _found if n not in otherwise_unaccounted)
    assert not idle, (
        f"these `_HISTORICAL` entries explain lines that something else already accounts for, so "
        f"they lower the residue without examining anything: {idle}"
    )

    #: THE POPULATION IS HELD TOO, because the unaccounted figure is a NUMERATOR and a numerator
    #: alone is the floor shape this repository keeps finding. Tightening `NUMBER` drops lines out
    #: of the population entirely: the numerator falls while nothing was accounted for. Measured
    #: on the way in — 113 -> 84 came with 284 -> 267, so seven of those twenty-nine lines simply
    #: stopped carrying a number. Without this assertion that reads exactly like work.
    assert population == recorded_population, (
        f"{population} README line(s) carry a number and the baseline says {recorded_population}. "
        f"The DENOMINATOR moved, so a change in the figure below is not comparable even if the "
        f"digests match. Regenerate with `python ci.py claims-baseline` and say what moved"
    )
    #: NOT VACUOUS: a rule that matched nothing would make the comparison below trivially true,
    #: and a baseline of 0 would agree with it forever.
    assert known == recorded_known, (
        f"{known} README line(s) are recorded as permanently unverifiable and the baseline says "
        f"{recorded_known}. A rise here is a judgement somebody recorded — regenerate with "
        f"`python ci.py claims-baseline` — and a fall means one became checkable, which is the "
        f"direction this list exists to move in"
    )

    #: THE HEADLINE IS THE SUM, because recording a reason is not a check gained. Moving a line
    #: from `unaccounted` to `historical` lowers one number and raises the other by the same one,
    #: and a reader who watched only the first would read bookkeeping as progress.
    assert live + known == recorded + recorded_known, (
        f"the residue is {live + known} line(s) and the baseline says {recorded + recorded_known}. "
        f"Only a binding, a test or a deleted sentence moves this number"
    )

    assert live > 0 and recorded > 0 and population > live, (
        f"live {live} of {population}, baseline {recorded}: a zero, or a population no larger "
        f"than the numerator, means the rule has stopped classifying anything — which reads "
        f"exactly like a document with no unbound claims in it"
    )
    #: AND THE BINDINGS DIGEST ATTRIBUTES THE MOVE, which is the whole reason it is separate.
    #: A fall while the bindings moved is work; a fall while nothing moved is the document losing
    #: a sentence. The test cannot tell a reader which it wants to be — it can tell them which it
    #: IS, and that is the sentence a commit message is supposed to contain.
    bound_moved = bindings != claims.bindings_digest()
    if live < recorded:
        why = (
            "The BINDINGS moved and the detection rule did not, so this fall is WORK: claims were "
            "bound. Regenerate with `python ci.py claims-baseline` and record it as WORK."
            if bound_moved
            else "Nothing in the rule or the bindings moved, so the README itself lost a number. "
            "Regenerate with `python ci.py claims-baseline` and say which sentence went."
        )
    else:
        why = (
            "It went UP: a number arrived in README.md that nothing measures. Bind it in `_BOUND`, "
            "or give it a kind in `_KINDS` WITH its reason — an unexplained exemption is how a gap "
            "hides."
        )
    assert live == recorded, (
        f"the README now has {live} line(s) accounted for by nothing and the committed baseline "
        f"says {recorded}. {why}"
    )


def test_every_collected_test_carries_exactly_one_tier(request):
    """`tests/conftest.py` tiers the suite, and this holds the tiering to the tests that RAN.

    THE TWO SIDES HAVE DIFFERENT SOURCES, which is the only arrangement that can fail. The
    conftest derives a tier from each test's call graph; this reads what **pytest actually
    collected and what markers were actually applied**. A test generated in a loop or built by a
    factory is collected by pytest and is invisible to an AST walk over module-level `def`s — the
    conftest applies NO marker to it on purpose, and this is what notices. Re-deriving the tier
    here instead would only prove the conftest agrees with itself.

    AN UNMARKED TEST MUST BE A RED, NEVER A QUIET `unit`. `unit` is the COMPLEMENT of the other
    three predicates, so the four are total over what the derivation can see; what is not total is
    the derivation's knowledge of the population. A tier that silently absorbed what it could not
    classify would be the floor shape this repository keeps finding — it would say how much was
    tiered and could not say what was missed.

    AND EXACTLY ONE, NOT AT LEAST ONE. Two tiers on one test means the precedence in `_DRIVES`
    stopped being exclusive, and `-m unit` and `-m subprocess` would both return it — so the
    counts would sum past the suite and `-m "not subprocess"` would still run it.
    """
    tiers = {"unit", "api", "cli", "subprocess"}
    wrong: dict[str, list[str]] = {}
    for item in request.session.items:
        got = sorted(tiers & {mark.name for mark in item.iter_markers()})
        if len(got) != 1:
            wrong.setdefault("none" if not got else "+".join(got), []).append(item.name)
    assert not wrong, "every collected test must carry exactly one tier marker; " + "; ".join(
        f"{how}: {len(names)} test(s), e.g. {names[:3]}" for how, names in sorted(wrong.items())
    )

    #: THE MARKERS MUST BE REGISTERED, and this reads the TOML as TEXT because `tomllib` is 3.11+
    #: and this suite runs on 3.10 in the matrix. An unregistered marker is a warning today and an
    #: error under `--strict-markers`, and a `-m` typo should fail rather than run nothing.
    pyproject = (_repo_root() / "pyproject.toml").read_text(encoding="utf-8")
    block = pyproject.split("markers = [", 1)
    assert len(block) == 2, "pyproject.toml no longer registers any pytest markers"
    declared = set(re.findall(r'"(\w+):', block[1].split("]", 1)[0]))
    applied = {mark.name for item in request.session.items for mark in item.iter_markers()}
    #: ONLY THE ONES THIS FILE'S TIERING APPLIES. `parametrize` and `skipif` are pytest's own.
    assert (applied & (tiers | {"repo"})) <= declared, (
        f"these markers are applied but not registered in `pyproject.toml`: "
        f"{sorted((applied & (tiers | {'repo'})) - declared)}"
    )

    #: NON-VACUOUS, AND ONLY ANSWERABLE ON A FULL RUN. Under `-k` or `-m`, `session.items` is the
    #: SELECTED set, so the population clause below would pass over one test. Stated rather than
    #: skipped silently: the clauses above still hold for whatever ran, and `ci.py test` runs all.
    if request.config.getoption("keyword") or request.config.getoption("markexpr"):
        pytest.skip("a filtered run; the population clause needs the whole suite")
    #: COUNTED WITHOUT `collections`, which this module does not import -- one more import for
    #: one tally is a change to the file's head that a reader has to account for.
    counts: dict[str, int] = {}
    for item in request.session.items:
        for tier in tiers & {mark.name for mark in item.iter_markers()}:
            counts[tier] = counts.get(tier, 0) + 1
    assert len(request.session.items) > 1000, (
        f"{len(request.session.items)} items collected; this suite had 1 250 when the tiering "
        f"was written, so either the selection is filtered after all or the suite has shrunk"
    )
    assert len(counts) == len(tiers), (
        f"a tier is EMPTY, which means its predicate has stopped matching anything: {counts}"
    )
    assert sum(counts.values()) == len(request.session.items), (
        f"the tiers sum to {sum(counts.values())} over {len(request.session.items)} items"
    )


def test_the_tiering_hook_gives_every_test_function_exactly_one_tier():
    """The tiering MECHANISM, driven directly, so it does not need a full run to be answerable.

    WHY THIS EXISTS AND WHY IT IS SEPARATE. `test_every_collected_test_carries_exactly_one_tier`
    reads `request.session.items`, which under `-k` or `-m` is the SELECTED set — so under a
    one-test selection it inspects one item, and a hook that had stopped applying tiers at all
    would still satisfy it if that one test happened to land in the `unit` complement.

    MEASURED, and it is why this test is here. Two mutations of `tests/conftest.py` — turning the
    exclusive `break` into `continue`, and dropping the `add_marker` call outright — both came
    back **SURVIVED** against the population test under `-k`. The population test is not wrong;
    it is a check whose strength is the population, and the harness said so plainly. So the
    MECHANISM is held here, over every test function in the module, under any selection.

    THE STUB IS THE POINT. `pytest` is not asked to collect anything: the hook is called with
    items built from the real test functions this module defines, so the population is derived
    from the file and the selection cannot shrink it.
    """
    spec = importlib.util.spec_from_file_location(
        "_conftest_under_test", _repo_root() / "tests" / "conftest.py"
    )
    conftest = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(conftest)

    source = pathlib.Path(__file__).read_text(encoding="utf-8")
    functions = [
        node.name
        for node in ast.parse(source).body
        if isinstance(node, ast.FunctionDef) and node.name.startswith("test_")
    ]
    assert len(functions) > 1000, (
        f"only {len(functions)} test functions found; this sweep is reading the wrong thing"
    )

    class _Named:
        """`__name__` AS AN INSTANCE ATTRIBUTE, and the first version got this wrong.

        `type("_F", (), {"__name__": name})` builds a CLASS, and `cls.__name__` resolves through
        the metaclass descriptor rather than the namespace dict -- so every stub reported `_F`,
        every lookup missed, and the hook applied nothing to any of 1 148. The test failed saying
        so, which is the good case, but a stub that lies about its own name would have been a
        silent SURVIVED had the assertion been any weaker.
        """

        def __init__(self, name: str) -> None:
            self.__name__ = name

    class _Stub:
        """Item-shaped: what the hook reads, and a record of what it applied."""

        def __init__(self, name: str) -> None:
            self.name = name
            self.function = _Named(name)
            self.module = _Named(__file__)
            self.module.__file__ = __file__
            self.marks: list[str] = []

        def add_marker(self, mark: object) -> None:
            self.marks.append(mark.name)

    stubs = [_Stub(name) for name in functions]
    conftest.pytest_collection_modifyitems(stubs)

    tiers = {"unit", "api", "cli", "subprocess"}
    wrong = {s.name: s.marks for s in stubs if len(set(s.marks) & tiers) != 1}
    assert not wrong, (
        f"{len(wrong)} test function(s) did not get exactly one tier from the hook, e.g. "
        f"{dict(list(wrong.items())[:3])}"
    )

    #: AND EVERY TIER IS NON-EMPTY, so a predicate that has stopped matching anything is a red
    #: rather than a quietly larger `unit`. `unit` is the COMPLEMENT, so it absorbs every failure
    #: of the other three silently -- which is the one direction this cannot be allowed to drift.
    got: dict[str, int] = {}
    for stub in stubs:
        for tier in set(stub.marks) & tiers:
            got[tier] = got.get(tier, 0) + 1
    assert set(got) == tiers, f"a tier matched nothing: {got}"
    #: AND `repo` IS APPLIED, which no tier assertion above can see because it is orthogonal.
    assert sum("repo" in s.marks for s in stubs) > 1, "the `repo` marker is never applied"
